		["thunder ridge"] = {
			name = "Monte del Trueno",
			short = "El Monte del Trueno es un desfiladero en el noroeste de Durotar, al suroeste de Orgrimmar. Alberga un bosque de árboles antiguos que crecieron en armonía con los truenagartos que tienen sus guaridas entre ellos.",
			full = "El Monte del Trueno es un desfiladero en el noroeste de Durotar, al suroeste de Orgrimmar. Alberga un bosque de árboles antiguos que crecieron en armonía con los truenagartos que tienen sus guaridas entre ellos.\n\nLa armonía se rompió cuando una explotación maderera humana comenzó a despojar la cresta de sus árboles, enloqueciendo a los lagartos. Rexxar, enviado a recoger cardaluz para Drek'Thar, notó el cambio en las bestias y llevó la noticia a Orgrimmar. Él y Drek'Thar regresaron juntos, encontraron la explotación maderera y se vieron obligados a acabar con los lagartos enloquecidos para evitar un desastre, aunque después Rexxar recogió sus huevos para que Drek'Thar los estudiara.\n\nJaina Valiente, enviada por Thrall para averiguar qué más había perturbado la cresta, descubrió que sus árboles habían sido talados mediante magia demoníaca, obra del Filo Ardiente, que buscaba desestabilizar la región. Un pequeño grupo de sus cultistas, dirigido por Fizzle Darkclaw, acampó allí para sembrar más caos, y Orgnil Escaralma pidió la muerte de Fizzle y su garra como prueba de ello.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Ridge",
		},
		["tiragarde keep"] = {
			name = "Fuerte de Tiragarde",
			short = "El Fuerte de Tiragarde se alza blanco contra la roca roja de la Costa de la Huida, una fortaleza que jamás debió haberse levantado en Durotar.",
			full = "El Fuerte de Tiragarde se alza blanco contra la roca roja de la Costa de la Huida, una fortaleza que jamás debió haberse levantado en Durotar.\n\nFue construido a toda prisa por orden del almirante general Daelin Valiente de Kul Tiras. La Tercera Guerra había terminado con una paz inestable entre Thrall y Lady Jaina Valiente, la propia hija del almirante, pero Daelin no confiaba en ningún orco ni respetaba ninguna tregua firmada en su nombre. Trajo su flota desde Kul Tiras hasta las costas de Durotar y la lanzó contra la Horda, construyendo el Fuerte de Tiragarde como punto de apoyo para la guerra que pretendía terminar. La ofensiva se estrelló contra los orcos, y el fuerte quedó en ruinas con ella.\n\nEl propio Daelin no vivió para verlo reconstruido; murió cuando la Horda, dirigida por Rexxar, asaltó Theramore. Pero antes de zarpar de Kul Tiras había dejado órdenes selladas para el día en que su flota guardara silencio. Cuando no llegó ninguna noticia, esas órdenes salieron a la luz, y el teniente Benedict fue enviado para recuperar las ruinas y continuar la cruzada de su comandante.\n\nAsí, el fuerte vuelve a alzarse, maltrecho pero en pie, una cicatriz reluciente de color equivocado sobre la piedra carmesí.",
			source = "https://warcraft.wiki.gg/wiki/Tiragarde_Keep",
		},
		["torkren farm"] = {
			name = "Granja Tor'kren",
			short = "La Granja Tor'kren se encuentra entre el Monte del Trueno y la cuenca del Furia del Sur, una propiedad modesta que nunca ha dado las ganancias de sus vecinas.",
			full = "La Granja Tor'kren se encuentra entre el Monte del Trueno y la cuenca del Furia del Sur, una propiedad modesta que nunca ha dado las ganancias de sus vecinas. Antes la trabajaban Misha Tor'kren y su hijo Kron, hasta que Kron bajó al Río Furia del Sur a cazar crocoliscos y no volvió a casa. Ahora Misha lleva la granja sola, y pide un collar hecho con dientes de crocolisco para recordarlo.",
			source = "https://warcraft.wiki.gg/wiki/Tor'kren_Farm",
		},
		["valley of trials"] = {
			name = "Valle de los Retos",
			short = "El Valle de los Retos se encuentra amurallado en el sur de Durotar, una hondonada de tierra abrasada donde todo orco joven comienza la vida que la Horda le ha trazado.",
			full = "El Valle de los Retos se encuentra amurallado en el sur de Durotar, una hondonada de tierra abrasada donde todo orco joven comienza la vida que la Horda le ha trazado. A quienes fracasan no se los saca de allí. Se los deja donde caen, para que se cuezan al sol hasta que el desierto termine lo que la prueba empezó.\n\nEn el corazón del valle se encuentra El Cubil, una cueva excavada en la pared del acantilado y equipada con las sencillas comodidades de una vida dedicada al servicio. La cuidan los ancianos, que enseñan a los jóvenes sus vocaciones y los someten a sus pruebas.\n\nAl norte, una modesta serie de cuevas naturales permaneció vacía durante un tiempo en los acantilados. Desde entonces, algo se ha colado en ellas. Ahora los demonios del Filo Ardiente anidan allí y se desbordan hacia el propio valle, y su presencia ha dado peso a viejos rumores de que el Consejo de la Sombra ha logrado afianzarse en la región. Los demonios son débiles, pero no se quedan en sus cuevas, y la corrupción que traen consigo ha comenzado a extenderse más allá de la piedra que antes la contenía.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Trials",
		},
	},
	-- Mulgore: 18 subzones
	[1412] = {
		["baeldun digsite"] = {
			name = "Excavación de Bael'dun",
			short = "La expedición de Bael'dun abrió su cantera en el extremo occidental de Mulgore, clavando sus picos en la ladera de la montaña.",
			full = "La expedición de Bael'dun abrió su cantera en el extremo occidental de Mulgore, clavando sus picos en la ladera de la montaña. Su excavación fue declarada una afrenta a la Madre Tierra, y cuando las palabras no bastaron para hacerlos retroceder, la tribu Pezuña de Sangre se apoderó de las herramientas de los invasores y las destrozó para expulsarlos.\n\nLos enanos siguieron cavando de todos modos, sin hacer caso de las advertencias, y su trabajo imprudente despertó la ira de los espíritus de la tierra. La cantera permanece, una cicatriz abierta en la tierra de Mulgore.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Digsite",
		},
		["bloodhoof village"] = {
			name = "Poblado Pezuña de Sangre",
			short = "El Poblado Pezuña de Sangre se encuentra a orillas del Lago Toro de Piedra, en las llanuras de Mulgore, y lleva el nombre de la tribu que lo habita.",
			full = "El Poblado Pezuña de Sangre se encuentra a orillas del Lago Toro de Piedra, en las llanuras de Mulgore, y lleva el nombre de la tribu que lo habita. Aquí se doma y adiestra a los kodos salvajes de las llanuras, hasta que se vuelven lo bastante mansos para llevar un jinete, y el poblado es conocido por este trabajo tanto como por cualquier otra cosa.\n\nBaine Pezuña de Sangre vigila el poblado y se encarga de su protección. Zarlman Dos Lunas cuida de la vida espiritual de la tribu Pezuña de Sangre; es el anciano que habla en nombre de los ancestros y de la Madre Tierra ante quienes viven allí y quienes están de paso.",
			source = "https://warcraft.wiki.gg/wiki/Bloodhoof_Village",
		},
		["brambleblade ravine"] = {
			name = "Barranco Cortazarza",
			short = "El Barranco Cortazarza se abre en el borde noreste de la Mesa de la Nube Roja, hogar de los jabaespines Erizapúas.",
			full = "El Barranco Cortazarza se abre en el borde noreste de la Mesa de la Nube Roja, hogar de los jabaespines Erizapúas. Al fondo del barranco, en una gran choza, vive su jefe, Cornapunta Mantospina, cuyo liderazgo ha provocado ataques tauren destinados a frenar las incursiones de los jabaespines desde su origen.",
			source = "https://warcraft.wiki.gg/wiki/Brambleblade_Ravine",
		},
		["camp narache"] = {
			name = "Campamento Narache",
			short = "El Campamento Narache se encuentra en el extremo norte de la Mesa de la Nube Roja: un pequeño círculo de tiendas que pertenece a la tribu Viento de Halcón, en el sur de Mulgore.",
			full = "El Campamento Narache se encuentra en el extremo norte de la Mesa de la Nube Roja: un pequeño círculo de tiendas que pertenece a la tribu Viento de Halcón, en el sur de Mulgore. Los bravos heridos descansan en la tienda principal, y alrededor del centro de la aldea los maestros de la tribu forman un círculo silencioso, presentando sus respetos a la Abuela Viento de Halcón.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Narache",
		},
		["golden plains"] = {
			name = "Las Llanuras Doradas",
			short = "Las Llanuras Doradas, una cuenca de hierba verde y ondulante al sureste de Cima del Trueno, son un tesoro de la patria tauren y un preciado terreno de caza.",
			full = "Las Llanuras Doradas, una cuenca de hierba verde y ondulante al sureste de Cima del Trueno, son un tesoro de la patria tauren y un preciado terreno de caza. Grandes manadas de kodos se reúnen aquí para pastar, y se dice que en algún lugar entre la hierba tiene su hogar la famosa Arra'chea.",
			source = "https://warcraft.wiki.gg/wiki/Golden_Plains",
		},
		["kodo rock"] = {
			name = "Roca de los Kodos",
			short = "La Roca de los Kodos se alza discretamente entre el Campamento Narache y el Barranco Cortazarza, y es fácil pasar junto a ella sin notarla a menos que se preste mucha atención, pues solo puede verse de cerca.",
			full = "La Roca de los Kodos se alza discretamente entre el Campamento Narache y el Barranco Cortazarza, y es fácil pasar junto a ella sin notarla a menos que se preste mucha atención, pues solo puede verse de cerca.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Rock",
		},
		["palemane rock"] = {
			name = "Roca Crines Pálidas",
			short = "La Roca Crines Pálidas es una cueva excavada en lo profundo de la ladera de la montaña, en el oeste de Mulgore, hogar de los gnolls de la tribu Crines Pálidas.",
			full = "La Roca Crines Pálidas es una cueva excavada en lo profundo de la ladera de la montaña, en el oeste de Mulgore, hogar de los gnolls de la tribu Crines Pálidas. Ocupan tanto la cueva como un campamento en el exterior, y recurren enseguida a la violencia, abalanzándose sobre cualquiera que se acerque demasiado a su territorio.",
			source = "https://warcraft.wiki.gg/wiki/Palemane_Rock",
		},
		["ravaged caravan"] = {
			name = "Caravana Devastada",
			short = "En la orilla noreste del Lago Toro de Piedra humean los restos de una caravana de Ventura y Cía., que todavía escupen humo negro al cielo de Mulgore.",
			full = "En la orilla noreste del Lago Toro de Piedra humean los restos de una caravana de Ventura y Cía., que todavía escupen humo negro al cielo de Mulgore. Transportaba suministros para la explotación minera del supervisor Saltatuercas cuando los tauren, hartos de que los goblins atravesaran sus tierras, cayeron sobre ella.\n\nLos supervivientes nunca abandonaron los restos. Aún defienden el montículo humeante y su carga chamuscada, rechazando a cualquiera que se acerque.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Caravan",
		},
		["red cloud mesa"] = {
			name = "Mesa de la Nube Roja",
			short = "La Mesa de la Nube Roja es una extensión de llanuras onduladas sobre los altos acantilados del sur de Mulgore, conocida por su belleza tranquila y abierta.",
			full = "La Mesa de la Nube Roja es una extensión de llanuras onduladas sobre los altos acantilados del sur de Mulgore, conocida por su belleza tranquila y abierta. Es aquí donde los jóvenes tauren demuestran su valía, tomando las armas contra los jabaespines Erizapúas, que ocupan el Barranco Cortazarza al noreste.\n\nEl Campamento Narache, situado en el noroeste de la meseta, es el último terreno seguro de la mesa. Desde el cementerio al oeste del campamento, un sendero sube hasta la cima de la Mesa Vistalonga.",
			source = "https://warcraft.wiki.gg/wiki/Red_Cloud_Mesa",
		},
		["red rocks"] = {
			name = "Roca Roja",
			short = "La arenisca roja de Roca Roja se alza en el noreste de Mulgore, un lugar donde el mundo de Cima del Trueno se desvanece y algo más sereno ocupa su lugar.",
			full = "La arenisca roja de Roca Roja se alza en el noreste de Mulgore, un lugar donde el mundo de Cima del Trueno se desvanece y algo más sereno ocupa su lugar. Aquí los tauren entregan a sus muertos honrados a la Madre Tierra y al Padre Cielo por medio de la llama purificadora. No todos los tauren caídos son traídos aquí; solo a los más valerosos se les concede este descanso: los guerreros que fundaron y defendieron Cima del Trueno, los que dieron la vida por sus tribus y sus jefes. También es el lugar al que acuden los jóvenes bravos para completar su paso a la edad adulta, de pie entre las piedras, escuchando las voces de sus ancestros en el viento.\n\nEl carácter sagrado del lugar no lo ha mantenido a salvo. Una banda de jabaespines Erizapúas se abrió paso hasta Roca Roja y profanó la tierra sagrada con su presencia, un acto que despertó una profunda ira entre los tauren de Cima del Trueno, que tanto aprecian este lugar.",
			source = "https://warcraft.wiki.gg/wiki/Red_Rocks",
		},
		["rolling plains"] = {
			name = "Las Llanuras Onduladas",
			short = "Las Llanuras Onduladas se abren al sur del Poblado Pezuña de Sangre y se extienden hacia la frontera de Los Baldíos. Lobos y pumas se mueven entre la hierba junto a kodos y zancaaltas.",
			full = "Las Llanuras Onduladas se abren al sur del Poblado Pezuña de Sangre y se extienden hacia la frontera de Los Baldíos. Lobos y pumas se mueven entre la hierba junto a kodos y zancaaltas.\n\nA diferencia del resto de Mulgore, las llanuras no están cerradas: los batidores centauros han encontrado un paso por aquí y merodean por donde ningún otro centauro se aventura. En la parte oriental se ha asentado un nido de arpías Viento Furioso.",
			source = "https://warcraft.wiki.gg/wiki/Rolling_Plains",
		},
		["stonebull lake"] = {
			name = "Lago Toro de Piedra",
			short = "El Lago Toro de Piedra rodea el Poblado Pezuña de Sangre por tres lados, una larga herradura de agua fresca. Sus aguas rebosan de peces, y en ellas se echan las líneas durante muchas horas tranquilas.",
			full = "El Lago Toro de Piedra rodea el Poblado Pezuña de Sangre por tres lados, una larga herradura de agua fresca. Sus aguas rebosan de peces, y en ellas se echan las líneas durante muchas horas tranquilas. Donde el lago se estrecha, un puente cruza el paso y lleva el camino que une el Poblado Pezuña de Sangre con Cima del Trueno.",
			source = "https://warcraft.wiki.gg/wiki/Stonebull_Lake",
		},
		["thunderhorn water well"] = {
			name = "Pozo Tronacuerno",
			short = "El pozo se encuentra en la hierba abierta de Mulgore, junto al camino del norte entre Cima del Trueno y el Poblado Pezuña de Sangre.",
			full = "El pozo se encuentra en la hierba abierta de Mulgore, junto al camino del norte entre Cima del Trueno y el Poblado Pezuña de Sangre. Ventura y Cía. se apoderó de él en una ocasión, con la esperanza de cortarles el agua a los tauren, pero los tauren los expulsaron y lo recuperaron.",
			source = "https://warcraft.wiki.gg/wiki/Thunderhorn_Water_Well",
		},
		["venture co mine"] = {
			name = "Mina Ventura y Cía.",
			short = "La mina se adentra en los acantilados orientales de Mulgore y tiene tres entradas: la puerta principal a pie, una pared del acantilado y un pequeño campamento maderero más allá.",
			full = "La mina se adentra en los acantilados orientales de Mulgore y tiene tres entradas: la puerta principal a pie, una pared del acantilado y un pequeño campamento maderero más allá. No tiene por qué estar allí. Los tauren negaron a Ventura y Cía. los derechos de explotación minera en su patria, y la compañía simplemente empezó a excavar de todos modos, con el supervisor Saltatuercas al frente de la operación y la junta asesora del magnate Razdunk presionándolo para expandirse aún más hacia la madera, enviando nuevas trituradoras y materiales para un aserradero que se alimentara de los árboles de Mulgore.\n\nLos tauren no dejaron pasar la intrusión. Los batidores encontraron una caravana de suministros mineros que avanzaba escoltada por la orilla norte del Lago Toro de Piedra, cayeron sobre ella y quemaron cuanto pudieron, dejando atrás los restos en la creencia de que el fuego había arruinado todo lo que valía la pena llevarse. No fue así. Más tarde se vio a recuperadores de Ventura y Cía. rebuscando entre las cenizas y recogiendo lo que las llamas habían perdonado.\n\nAquel descubrimiento señaló la mina como objetivo de represalias, una advertencia dirigida a la operación de Saltatuercas por la negativa de la compañía a dejar en paz las tierras tauren.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Mine",
		},
		["wildmane water well"] = {
			name = "Pozo Ferocrín",
			short = "El Pozo Ferocrín se encuentra al norte de Cima del Trueno, el más septentrional de los pozos sagrados de los tauren. Las arpías Viento Furioso se han apoderado del terreno que lo rodea, y el pozo está contaminado, a la espera de ser purificado.",
			full = "El Pozo Ferocrín se encuentra al norte de Cima del Trueno, el más septentrional de los pozos sagrados de los tauren. Las arpías Viento Furioso se han apoderado del terreno que lo rodea, y el pozo está contaminado, a la espera de ser purificado.",
			source = "https://warcraft.wiki.gg/wiki/Wildmane_Water_Well",
		},
		["windfury ridge"] = {
			name = "Cresta Viento Furioso",
			short = "La Cresta Viento Furioso debe su nombre a las arpías que anidan en sus alturas, criaturas feroces que se abalanzan sobre cualquiera que se acerque demasiado, matando o llevándose a los incautos.",
			full = "La Cresta Viento Furioso debe su nombre a las arpías que anidan en sus alturas, criaturas feroces que se abalanzan sobre cualquiera que se acerque demasiado, matando o llevándose a los incautos. Pumas y lobos también merodean por las colinas circundantes.\n\nAun así, los tauren de Cima del Trueno aprecian mucho las brillantes plumas de las arpías, que usan en bodas y banquetes.",
			source = "https://warcraft.wiki.gg/wiki/Windfury_Ridge",
		},
		["winterhoof water well"] = {
			name = "Pozo Pezuña Invernal",
			short = "El Pozo Pezuña Invernal se encuentra en el límite de las Llanuras Onduladas, en el sur de Mulgore. Años después de la Tercera Guerra, Ventura y Cía. se apoderó de él y envenenó sus aguas para cortar el suministro de los tauren.",
			full = "El Pozo Pezuña Invernal se encuentra en el límite de las Llanuras Onduladas, en el sur de Mulgore. Años después de la Tercera Guerra, Ventura y Cía. se apoderó de él y envenenó sus aguas para cortar el suministro de los tauren. Mull Tronacuerno fabrica tótems para purificar la contaminación, pero el pozo aún no está limpio.",
			source = "https://warcraft.wiki.gg/wiki/Winterhoof_Water_Well",
		},
	},
	-- Los Baldíos: 31 subzones
	[1413] = {
		["agamagor"] = {
			name = "Agama'gor",
			short = "Agama'gor se encuentra al norte del camino que va hacia el oeste desde el Campamento Taurajo, una madriguera de espinos reclamada por los jabaespines Erizapúas.",
			full = "Agama'gor se encuentra al norte del camino que va hacia el oeste desde el Campamento Taurajo, una madriguera de espinos reclamada por los jabaespines Erizapúas. Sus muertos dejan fragmentos de sangre seca, objetos que el exiliado Mangletooth valora mucho y por los que ofrece a cambio sus propios y extraños favores.",
			source = "https://warcraft.wiki.gg/wiki/Agama'gor",
		},
		["bael modan"] = {
			name = "Bael Modan",
			short = "La fortaleza de piedra de Bael'dun se alza donde antes había una aldea tauren de la tribu Aguja de Piedra.",
			full = "La fortaleza de piedra de Bael'dun se alza donde antes había una aldea tauren de la tribu Aguja de Piedra. Debajo, los excavadores enanos cavan hacia un antiguo complejo de los titanes, unas instalaciones de investigación enterradas desde antes de que los propios tauren pisaran esta tierra, cuyas reliquias siguen en su mayoría sin reclamar en la oscuridad.\n\nLos enanos llegaron con explosivos y abrieron a voladuras una tierra que la tribu Aguja de Piedra consideraba sagrada. La excavación desgarró la tierra y, con ella, desgarró a los tauren: la mayor parte de la tribu murió o fue expulsada de las tierras que había conservado durante generaciones. Su antigua aldea yace ahora destrozada por las máquinas excavadoras de los enanos. Gann Aguja de Piedra, que todavía recorre los caminos cercanos, intentó resolverlo de jefe a jefe, hablando en lugar de luchar. Los enanos no quisieron renunciar a la excavación. Él pasó de la diplomacia a la guerra, buscando cualquier fuerza que pudiera encontrar para expulsarlos.",
			source = "https://warcraft.wiki.gg/wiki/Bael_Modan",
		},
		["baeldun keep"] = {
			name = "Fortaleza de Bael'dun",
			short = "La Fortaleza de Bael'dun se alza sobre la excavación de Bael Modan, en el sur de Los Baldíos. La comanda el general Trenzado, que defiende la fortaleza y a sus enanos frente a los tauren y los orcos de las llanuras que la rodean.",
			full = "La Fortaleza de Bael'dun se alza sobre la excavación de Bael Modan, en el sur de Los Baldíos. La comanda el general Trenzado, que defiende la fortaleza y a sus enanos frente a los tauren y los orcos de las llanuras que la rodean.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Keep",
		},
		["blackthorn ridge"] = {
			name = "Loma Espina Negra",
			short = "Las espinas abarrotan el valle al norte del Horado Rajacieno, dominado por los jabaespines Crines de Acero. En la loma vive Salmuera, una chamana. Bajo su campamento hay un estanque de agua clara y pura entre las espinas.",
			full = "Las espinas abarrotan el valle al norte del Horado Rajacieno, dominado por los jabaespines Crines de Acero. En la loma vive Salmuera, una chamana. Bajo su campamento hay un estanque de agua clara y pura entre las espinas.",
			source = "https://warcraft.wiki.gg/wiki/Blackthorn_Ridge",
		},
		["boulder lode mine"] = {
			name = "Mina Pedrusco",
			short = "La Mina Pedrusco se encuentra en Los Baldíos; sus túneles están apuntalados con madera orca y adornados con estandartes de la Horda, reliquias descoloridas de quienes abrieron por primera vez estos pozos en la roca.",
			full = "La Mina Pedrusco se encuentra en Los Baldíos; sus túneles están apuntalados con madera orca y adornados con estandartes de la Horda, reliquias descoloridas de quienes abrieron por primera vez estos pozos en la roca. Ese derecho ya no existe. Ventura y Cía. se ha adueñado de la mina, y los goblins pululan por las galerías donde antes trabajaban los orcos.\n\nAl maestro de muelles Vertipeluca le llegó la noticia de que uno de los mineros había abierto una veta y había extraído una esmeralda gigante. El maestro de muelles la deseaba tanto que prometió una parte de las ganancias a quien estuviera dispuesto a entrar y arrebatársela a Ventura y Cía.",
			source = "https://warcraft.wiki.gg/wiki/Boulder_Lode_Mine",
		},
		["bramblescar"] = {
			name = "Rajazarza",
			short = "Los jabaespines Crines de Acero dominan Rajazarza. Al otro lado del camino, en Agama'gor, están los Erizapúas, y entre ambas tribus solo hay guerra.",
			full = "Los jabaespines Crines de Acero dominan Rajazarza. Al otro lado del camino, en Agama'gor, están los Erizapúas, y entre ambas tribus solo hay guerra. Si alguien se acerca demasiado a la guarida de los Crines de Acero, los jabaespines no esperarán a ser provocados.",
			source = "https://warcraft.wiki.gg/wiki/Bramblescar",
		},
		["camp taurajo"] = {
			name = "Campamento Taurajo",
			short = "El Campamento Taurajo se encuentra en Los Baldíos, cerca del paso de montaña que lleva a Mulgore. Ofrece descanso y provisiones a quienes viajan desde el Poblado Pezuña de Sangre antes de seguir hacia la patria tauren.",
			full = "El Campamento Taurajo se encuentra en Los Baldíos, cerca del paso de montaña que lleva a Mulgore. Ofrece descanso y provisiones a quienes viajan desde el Poblado Pezuña de Sangre antes de seguir hacia la patria tauren.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Taurajo",
		},
		["crossroads"] = {
			name = "El Cruce",
			short = "El Cruce se encuentra donde se unen los caminos: la ruta de norte a sur que baja desde el Camino del Oro y el largo camino de este a oeste que va de Trinquete hasta la Sierra Espolón.",
			full = "El Cruce se encuentra donde se unen los caminos: la ruta de norte a sur que baja desde el Camino del Oro y el largo camino de este a oeste que va de Trinquete hasta la Sierra Espolón. Es un lugar que debe su existencia al cruce más que a cualquier cosa construida allí: pocos alojamientos, ninguna gran muralla, solo tiendas, puestos y comerciantes que se gritan unos a otros para vender lo que tienen.\n\nMás allá del límite del asentamiento hay un cementerio, sencillo y silencioso frente al bullicio de la plaza del mercado que queda detrás. Es aquí donde la Horda viene a honrar a sus muertos, del mismo modo que la Colina del Centinela cumple esa función para la Alianza.",
			source = "https://warcraft.wiki.gg/wiki/Crossroads",
		},
		["dreadmist den"] = {
			name = "Cubil Calígine",
			short = "Una oscura niebla roja cubre eternamente la Cima Calígine y la envuelve en penumbra. En su interior, los cultistas del Filo Ardiente ocupan el Cubil Calígine y custodian la Semilla del Demonio, un artefacto que valoran por encima de todo.",
			full = "Una oscura niebla roja cubre eternamente la Cima Calígine y la envuelve en penumbra. En su interior, los cultistas del Filo Ardiente ocupan el Cubil Calígine y custodian la Semilla del Demonio, un artefacto que valoran por encima de todo. La propia niebla parece ocultar su culto demoníaco de miradas ajenas.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Den",
		},
		["dreadmist peak"] = {
			name = "Cima Calígine",
			short = "Al noroeste de El Cruce, la Cima Calígine se alza en Los Baldíos, con su cumbre ahogada en una niebla roja, residuo de una antigua maldición demoníaca.",
			full = "Al noroeste de El Cruce, la Cima Calígine se alza en Los Baldíos, con su cumbre ahogada en una niebla roja, residuo de una antigua maldición demoníaca. Los cultistas del Filo Ardiente se han instalado en su cumbre y custodian la Semilla del Demonio en el Cubil Calígine, más abajo.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Peak",
		},
		["dry hills"] = {
			name = "Las Colinas Áridas",
			short = "Las Colinas Áridas se alzan verdes frente al polvo de Los Baldíos, estribaciones que ascienden hacia Espolón.",
			full = "Las Colinas Áridas se alzan verdes frente al polvo de Los Baldíos, estribaciones que ascienden hacia Espolón. Las arpías Alabruja dominan este terreno y se han vuelto audaces: caen sobre las caravanas a lo largo del tramo norte del Camino del Oro antes de desaparecer de nuevo entre el verdor.",
			source = "https://warcraft.wiki.gg/wiki/Dry_Hills",
		},
		["far watch post"] = {
			name = "Avanzada del Puente",
			short = "La Avanzada del Puente se encuentra justo al oeste del puente que une Durotar con Los Baldíos, y es poco más que una torre de vigilancia, una madriguera orca y una hilera de catapultas, con un corral de lobos y sus dos peones un poco más al sur.",
			full = "La Avanzada del Puente se encuentra justo al oeste del puente que une Durotar con Los Baldíos, y es poco más que una torre de vigilancia, una madriguera orca y una hilera de catapultas, con un corral de lobos y sus dos peones un poco más al sur. No es un destino cómodo, pero sí necesario: protege las caravanas que se dirigen a Durotar y resiste por igual frente a la Alianza y a los jabaespines.",
			source = "https://warcraft.wiki.gg/wiki/Far_Watch_Post",
		},
		["field of giants"] = {
			name = "Tierra de Gigantes",
			short = "La Tierra de Gigantes se extiende por el sur de Los Baldíos, amplia y abierta, donde manadas de truenagartos y kodos se desplazan juntas en cantidades que pocas tierras pueden igualar.",
			full = "La Tierra de Gigantes se extiende por el sur de Los Baldíos, amplia y abierta, donde manadas de truenagartos y kodos se desplazan juntas en cantidades que pocas tierras pueden igualar.\n\nEl tramo sur del Camino del Oro atraviesa estas llanuras, y aquí es menos seguro que en el norte. Antaño había torres de vigilancia a lo largo del camino para proteger a las caravanas que pasaban; ahora están vacías, abandonadas al viento y a la hierba.\n\nLa Horda no ha renunciado a este terreno, aunque su dominio sobre él es débil. En una loma del límite sur de la Tierra de Gigantes vive la chamana Salmuera, lejos de cualquier campamento o cruce de caminos. No muy lejos camina Gann Aguja de Piedra, que alberga un viejo agravio: su tribu fue expulsada de su aldea cuando los enanos llegaron a excavar la tierra en busca de ruinas de los titanes en unas tierras junto a su hogar. Aquella excavación se convirtió en Bael Modan, y Gann no ha olvidado lo que le costó a su pueblo.",
			source = "https://warcraft.wiki.gg/wiki/Field_of_Giants",
		},
		["forgotten pools"] = {
			name = "Las Charcas del Olvido",
			short = "Las Charcas del Olvido se encuentran al norte del camino occidental que sale de El Cruce, y son el más septentrional de los oasis dispersos por el norte de Los Baldíos.",
			full = "Las Charcas del Olvido se encuentran al norte del camino occidental que sale de El Cruce, y son el más septentrional de los oasis dispersos por el norte de Los Baldíos. Sus orillas se mantienen verdes, rodeadas de hongos cargados que no se encuentran en ningún otro lugar, y sus aguas albergan peces descarriados distintos de cualquiera que se pesque en otras partes de Los Baldíos.\n\nLos centauros Kolkar recorren la orilla del agua junto a las tortugas y la fauna que se refugian allí.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Pools",
		},
		["fray island"] = {
			name = "Isla de Batalla",
			short = "La Isla de Batalla es pequeña y árida, y se encuentra frente a la costa oriental de Los Baldíos.",
			full = "La Isla de Batalla es pequeña y árida, y se encuentra frente a la costa oriental de Los Baldíos.\n\nLa isla sirve como campo de entrenamiento para guerreros de todas las razas y credos, reunidos allí bajo el mando de Klannoc Macleod.",
			source = "https://warcraft.wiki.gg/wiki/Fray_Island",
		},
		["gold road"] = {
			name = "Camino del Oro",
			short = "El Camino del Oro se extiende entre la Empalizada de Mor'shan y la Gran Divisoria, y su tramo sur, más allá del puente que marca el cruce, se conoce por separado como el Camino del Oro Sur.",
			full = "El Camino del Oro se extiende entre la Empalizada de Mor'shan y la Gran Divisoria, y su tramo sur, más allá del puente que marca el cruce, se conoce por separado como el Camino del Oro Sur.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Road",
		},
		["groldom farm"] = {
			name = "Granja de Grol'dom",
			short = "La Granja de Grol'dom es una de las granjas porcinas que surgieron en los años posteriores a la fundación de Orgrimmar, y sus corrales sufren constantes incursiones de los saqueadores Crines de Acero.",
			full = "La Granja de Grol'dom es una de las granjas porcinas que surgieron en los años posteriores a la fundación de Orgrimmar, y sus corrales sufren constantes incursiones de los saqueadores Crines de Acero.",
			source = "https://warcraft.wiki.gg/wiki/Grol'dom_Farm",
		},
		["lushwater oasis"] = {
			name = "Oasis Aguaverde",
			short = "El agua se acumula donde la Gran Divisoria se desploma, y las bestias salvajes bajan entre los árboles para beberla. Los centauros Kolkar las esperan entre las raíces y cazan a los animales que se acercan a las charcas.",
			full = "El agua se acumula donde la Gran Divisoria se desploma, y las bestias salvajes bajan entre los árboles para beberla. Los centauros Kolkar las esperan entre las raíces y cazan a los animales que se acercan a las charcas.\n\nBajo el oasis se encuentra la entrada a las Cuevas de los Lamentos, un lugar del que se habla como maldito. Lo que se agita allá abajo no sale a la superficie, pero su nombre aún pende sobre el agua.\n\nLos peces de aquí no se parecen a ningún otro de Los Baldíos.",
			source = "https://warcraft.wiki.gg/wiki/Lushwater_Oasis",
		},
		["merchant coast"] = {
			name = "La Costa Mercante",
			short = "La Costa Mercante debe su nombre al comercio que pasa por ella, ahorrativo y constante, en manos de los goblins de Trinquete.",
			full = "La Costa Mercante debe su nombre al comercio que pasa por ella, ahorrativo y constante, en manos de los goblins de Trinquete.\n\nLa costa sur pertenece a los Filibusteros de los Mares del Sur. Entre ellos está el barón Longavera, que en una ocasión robó un valioso cargamento a Gazlowe y lo enterró antes de que pudieran atraparlo, dejando la fortuna perdida en algún lugar de la orilla.",
			source = "https://warcraft.wiki.gg/wiki/Merchant_Coast",
		},
		["morshan base camp"] = {
			name = "Campamento de Mor'shan",
			short = "El Campamento de Mor'shan se encuentra al sur de la frontera con Vallefresno, cerca de la Empalizada de Mor'shan, y es uno de los mayores enclaves de la Horda en Los Baldíos.",
			full = "El Campamento de Mor'shan se encuentra al sur de la frontera con Vallefresno, cerca de la Empalizada de Mor'shan, y es uno de los mayores enclaves de la Horda en Los Baldíos. Los escoltas Grito de Guerra tienen aquí su base y vigilan el camino que lleva al norte, hacia el bosque en disputa que se extiende más allá.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Base_Camp",
		},
		["morshan rampart"] = {
			name = "La Empalizada de Mor'shan",
			short = "La Empalizada de Mor'shan se alza donde el Camino del Oro sale de Los Baldíos hacia el norte, levantada como muro contra el avance de la Alianza desde Vallefresno.",
			full = "La Empalizada de Mor'shan se alza donde el Camino del Oro sale de Los Baldíos hacia el norte, levantada como muro contra el avance de la Alianza desde Vallefresno. Es una construcción tosca, hecha para la guerra: terraplenes y torres de vigilancia destinados a mantener la línea frente a las fuerzas que presionan desde el norte.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Rampart",
		},
		["raptor grounds"] = {
			name = "Tierras de los Raptores",
			short = "Los raptores solescama que llenan este pequeño valle no se parecen a ningún otro de Los Baldíos. Muestran una astucia antinatural: construyen chozas toscas y fabrican herramientas con garras que no deberían saber nada de oficios.",
			full = "Los raptores solescama que llenan este pequeño valle no se parecen a ningún otro de Los Baldíos. Muestran una astucia antinatural: construyen chozas toscas y fabrican herramientas con garras que no deberían saber nada de oficios.\n\nMás extraña aún es su avidez por todo lo brillante o desconocido, que los ha llevado a asaltar los asentamientos cercanos de la Horda y a llevarse todo lo que les llama la atención.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Grounds",
		},
		["ratchet"] = {
			name = "Trinquete",
			short = "Trinquete se encuentra en la costa oriental de Los Baldíos, un pueblo portuario goblin que mantiene un comercio intenso con Bahía del Botín y el barón Revilgaz, al otro lado del mar.",
			full = "Trinquete se encuentra en la costa oriental de Los Baldíos, un pueblo portuario goblin que mantiene un comercio intenso con Bahía del Botín y el barón Revilgaz, al otro lado del mar. Gazlowe lo fundó con las monedas que Thrall le pagó por construir Orgrimmar, y se llenó de contrabandistas y de todos aquellos a quienes los lugares respetables habían rechazado.\n\nEsa indiferencia estuvo a punto de costarle cara. El culto del Filo Ardiente trabajó en secreto para enfrentar a Orgrimmar y Theramore, provocando incidentes marítimos cerca del puerto de Trinquete que ninguno de los dos bandos entendió como otra cosa que una provocación. Marineros orcos y humanos que habían compartido sus muelles en paz empezaron a pelearse en sus calles, y cuando el matón Muzzlecrank arrestó a los capitanes Klatt y Joq, el Fuerte del Norte lo tomó como prueba de que los orcos se estaban reuniendo para la guerra. Trinquete se convirtió en el punto de reunión de un ejército de la Horda que se preparaba para marchar contra ellos. Solo cuando salió a la luz la mano del Filo Ardiente en el asunto, Thrall suspendió la lucha antes de que comenzara.",
			source = "https://warcraft.wiki.gg/wiki/Ratchet",
		},
		["shrine of the fallen warrior"] = {
			name = "Santuario del Guerrero Caído",
			short = "Un sendero desgastado sube por una colina al oeste de El Cruce y termina en un santuario dedicado a un guerrero caído. No hay ningún nombre tallado allí, ni ningún estandarte lo señala.",
			full = "Un sendero desgastado sube por una colina al oeste de El Cruce y termina en un santuario dedicado a un guerrero caído. No hay ningún nombre tallado allí, ni ningún estandarte lo señala. La colina guarda su silencio, y el sendero que sube por ella es la única señal de que alguien aún lo recuerda.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Fallen_Warrior",
		},
		["sludge fen"] = {
			name = "El Fangal",
			short = "El Pantano de Lodo no siempre fue una herida en la tierra. Antaño albergaba un estanque de agua azul cristalina, antes de que llegara Ventura y Cía. y levantara una plataforma petrolera sobre él.",
			full = "El Pantano de Lodo no siempre fue una herida en la tierra. Antaño albergaba un estanque de agua azul cristalina, antes de que llegara Ventura y Cía. y levantara una plataforma petrolera sobre él. Lo que queda ahora es un lodazal de residuos industriales, explotado bajo la mirada de un supervisor goblin que responde de la operación ante la compañía.\n\nLa plataforma ha atraído rivales tanto como ha contaminado el agua. El Gremio de Manitas de Trinquete, presionado por el director Riddlevox para igualar las nuevas trituradoras de Ventura y Cía., dejó de intentar superarlas en construcción y decidió, en cambio, robar el diseño sin más. El goblin Petardol envió a Wizzlecrank a apoderarse de una de las máquinas del pantano y llevarla a Trinquete. Wizzlecrank solo logró subirse a la trituradora antes de descubrir que no tenía llave para moverla, y se quedó atrapado en territorio enemigo hasta que llegó el rescate y la máquina pudo sacarse caminando delante de las narices de los trabajadores de la compañía.",
			source = "https://warcraft.wiki.gg/wiki/Sludge_Fen",
		},
		["southern gold road"] = {
			name = "Camino del Oro Sur",
			short = "El Camino del Oro Sur debe su nombre a las caravanas que lo recorren.",
			full = "El Camino del Oro Sur debe su nombre a las caravanas que lo recorren. Va desde el Gran Elevador, en el extremo sur de Los Baldíos, hacia el norte hasta el puente que une las dos mitades de Los Baldíos, donde pasa a llamarse simplemente el Camino del Oro.\n\nLos comerciantes llegan por aquí desde muy lejos: desde Gadgetzan en Tanaris, desde Auberdine en Costa Oscura, desde Amparo de la Noche en el norte. Todos siguen el mismo camino, atraídos por el mismo comercio que le dio su nombre.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Gold_Road",
		},
		["southfury river"] = {
			name = "Río Furia del Sur",
			short = "El Furia del Sur nace en lo alto del Monte Hyjal y brota de un lago de montaña en una cascada que cae con estruendo hacia las tierras bajas.",
			full = "El Furia del Sur nace en lo alto del Monte Hyjal y brota de un lago de montaña en una cascada que cae con estruendo hacia las tierras bajas. Desde allí fluye ancho y veloz, partiendo la tierra en dos: marca el lugar donde Vallefresno da paso a Azshara y, más al sur, donde terminan Los Baldíos y comienza Durotar. En su desembocadura, el río se precipita por una última cascada al Mare Magnum, justo al noreste del puerto goblin de Trinquete.\n\nTres puentes lo cruzan a lo largo de su recorrido: uno une Azshara con Vallefresno, otro lleva a los viajeros hasta Orgrimmar y otro une Durotar con Los Baldíos. Justo al norte del que está más al oeste, un solo tramo de agua toca las cuatro tierras a la vez, el único lugar donde se encuentran Vallefresno, Azshara, Durotar y Los Baldíos.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["stagnant oasis"] = {
			name = "El Oasis Estancado",
			short = "El Oasis Estancado es una mancha de agua verde e inmóvil entre la Costa Mercante y el Camino del Oro. Los centauros Kolkar acampan en sus márgenes, y se dice que su presencia y su vigor provienen de las propias aguas estancadas.",
			full = "El Oasis Estancado es una mancha de agua verde e inmóvil entre la Costa Mercante y el Camino del Oro. Los centauros Kolkar acampan en sus márgenes, y se dice que su presencia y su vigor provienen de las propias aguas estancadas. Los kodos que vagan por aquí están debilitados y solos, a diferencia de las grandes manadas de la Tierra de Gigantes, más al sur, y son presas mucho más fáciles. Bajo la superficie nadan peces descarriados, muy apreciados una vez cocinados, mientras que las quijafortes del oasis acechan junto a ellos en el agua turbia.",
			source = "https://warcraft.wiki.gg/wiki/Stagnant_Oasis",
		},
		["thorn hill"] = {
			name = "Colina Espinosa",
			short = "La Colina Espinosa se encuentra en la cara norte de una cumbre entre El Cruce y Durotar, y sus laderas están plagadas de jabaespines de la tribu Crines de Acero.",
			full = "La Colina Espinosa se encuentra en la cara norte de una cumbre entre El Cruce y Durotar, y sus laderas están plagadas de jabaespines de la tribu Crines de Acero. Desde esta altura han atacado a las caravanas de la Horda que atraviesan la región, provocando la ira de quienes protegen los caminos de abajo.",
			source = "https://warcraft.wiki.gg/wiki/Thorn_Hill",
		},
		["tidus stair"] = {
			name = "El Escalón de la Marea",
			short = "El Escalón de la Marea se alza sobre la Costa Mercante como una serie de amplias terrazas de piedra, apiladas como la escalera de un gigante con vistas al agua.",
			full = "El Escalón de la Marea se alza sobre la Costa Mercante como una serie de amplias terrazas de piedra, apiladas como la escalera de un gigante con vistas al agua. Islen Vidente del Agua y Mahren Vidente del Cielo, dos tauren, frecuentan estas cornisas, echando sus líneas al oleaje y hablando con los espíritus que habitan en el agua de abajo.",
			source = "https://warcraft.wiki.gg/wiki/Tidus_Stair",
		},
		["wailing caverns"] = {
			name = "Cuevas de los Lamentos",
			short = "Las Cuevas de los Lamentos deben su nombre al sonido del propio lugar: vapor que brota por las grietas de la roca y recorre la oscuridad en largos gritos lastimeros.",
			full = "Las Cuevas de los Lamentos deben su nombre al sonido del propio lugar: vapor que brota por las grietas de la roca y recorre la oscuridad en largos gritos lastimeros.\n\nFue el druida elfo de la noche Naralex quien las encontró y quien les dio su propósito. Bajo la sabana corrían vías de agua que salían a la superficie en otros lugares como los oasis dispersos de Los Baldíos, y Naralex creía que si unía esas aguas con el propio Sueño Esmeralda, podría devolver aquella vitalidad verde a la tierra reseca de arriba. Condujo a sus discípulos hasta las cuevas y se sumió en meditación, abriéndose como un canal entre el Sueño y el mundo de la vigilia.\n\nEn cambio, la Pesadilla Esmeralda se apoderó de él. Naralex no pudo despertar. A través de su cuerpo dormido y abierto, la corrupción de la Pesadilla se derramó en las cuevas, contaminando las aguas, retorciendo la fauna en extrañas formas descarriadas y llevando a la locura a la mayoría de sus discípulos; los que quedaron se convirtieron en los Druidas del Colmillo.\n\nNaralex aún duerme allí, y los Druidas del Colmillo defienden las cuevas contra cualquiera que intente despertarlo.",
			source = "https://warcraft.wiki.gg/wiki/Wailing_Caverns",
		},
	},
	-- Montañas de Alterac: 5 subzones
	[1416] = {
		["dalaran"] = {
			name = "Dalaran",
			short = "Dalaran se alzó como una ciudad de magos, fundada después de las Guerras Trols por los hechiceros del Imperio de Arathor, y se convirtió en una nación por derecho propio.",
			full = "Dalaran se alzó como una ciudad de magos, fundada después de las Guerras Trols por los hechiceros del Imperio de Arathor, y se convirtió en una nación por derecho propio. Su gente no respondía ante ninguna corona, sino ante el Kirin Tor, el círculo selecto de los hechiceros más poderosos del mundo, gobernado por el Consejo de los Seis. En su corazón se alzaba la Ciudadela Violeta, santuario y refugio de quienes estudiaban lo arcano, y ninguna ciudad fuera de las tierras élficas de Quel'Thalas reunía una concentración tan grande de poder mágico. Incluso los orgullosos magos altos elfos de Quel'Thalas se inclinaban ante la soberanía del Kirin Tor.\n\nEsa soberanía se quebró entre las llamas. Cuando la Plaga atacó Dalaran, su gente fue expulsada de su propio reino, y el mismísimo Archimonde redujo la ciudad a ruinas, dispersando por Azeroth a los miembros supervivientes del Kirin Tor.\n\nLos supervivientes no dejaron que su ciudad siguiera muerta. Regresaron a los escombros y se pusieron a reconstruirla, alzando una enorme cúpula de magia para proteger su corazón destrozado de nuevos daños.",
			source = "https://warcraft.wiki.gg/wiki/Dalaran",
		},
		["dandreds fold"] = {
			name = "Redil de Dandred",
			short = "Una pequeña granja y una mansión se alzan en el extremo occidental de Las Tierras Altas, donde el terreno se une a la Costa de la Neblina y un puerto se abre al Lago Lordamere.",
			full = "Una pequeña granja y una mansión se alzan en el extremo occidental de Las Tierras Altas, donde el terreno se une a la Costa de la Neblina y un puerto se abre al Lago Lordamere.\n\nAquí vive Aliden, y con él su amante Elysa. Ella lleva un collar que perteneció a Taretha Foxton.",
			source = "https://warcraft.wiki.gg/wiki/Dandred's_Fold",
		},
		["lordamere internment camp"] = {
			name = "Campo de Reclusión de Lordamere",
			short = "El Campo de Reclusión de Lordamere se encuentra en una colina sobre el cráter de Dalaran; es el único campo de reclusión levantado en las Montañas de Alterac y está bajo la vigilancia de las fuerzas de Dalaran.",
			full = "El Campo de Reclusión de Lordamere se encuentra en una colina sobre el cráter de Dalaran; es el único campo de reclusión levantado en las Montañas de Alterac y está bajo la vigilancia de las fuerzas de Dalaran.\n\nAquí, de camino a Dalaran, el príncipe Arthas Menethil y Lady Jaina Valiente eludieron en una ocasión las patrullas de guardias y las torres de vigilancia al amparo de la noche para ver a los orcos recluidos en su interior. Lo que vieron los dividió. Jaina contempló a las hembras orcas y a sus crías y sintió que su certeza se desvanecía en duda y remordimiento. Arthas no sintió nada de eso, y sostuvo que los campos eran necesarios de todos modos. Nadie los vio. Se marcharon por donde habían llegado, y el desacuerdo entre ellos se fue con ellos.\n\nLa celadora Belamoore está ahora al mando de la guarnición y estudia los artefactos de sangrita que le trajeron Kegan Darkmar y sus compañeros.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Internment_Camp",
		},
		["ruins of alterac"] = {
			name = "Ruinas de Alterac",
			short = "Muros derrumbados trepan por las laderas de las Montañas de Alterac donde antes se alzaba una ciudad, con su palacio medio en pie, su iglesia y su ayuntamiento hundidos sobre sí mismos y su puerta construida al estilo de la de Ventormenta.",
			full = "Muros derrumbados trepan por las laderas de las Montañas de Alterac donde antes se alzaba una ciudad, con su palacio medio en pie, su iglesia y su ayuntamiento hundidos sobre sí mismos y su puerta construida al estilo de la de Ventormenta.\n\nSu ruina provino de su propio rey. Durante la Segunda Guerra, el rey Aiden Perenolde se convirtió en traidor y se puso del lado de la Horda orca contra sus semejantes humanos. Se descubrió a soldados de Alterac luchando junto a los orcos, y un campo de prisioneros cerca de la ciudad retenía a ciudadanos de Dalaran. Cuando salió a la luz la verdad, los demás reinos humanos marcharon sobre Alterac en represalia. La gente huyó o fue expulsada de sus hogares, y el rey Terenas Menethil II de Lordaeron declaró la ley marcial en la ciudad, derrocó a Perenolde y lo encadenó.\n\nLa ciudad nunca volvió a alzarse. Los ogros Aplastacresta, dirigidos por Mug'thol, se instalaron en las calles vacías y en el palacio, mientras que los restos dispersos del antiguo pueblo de Alterac ocupaban las aldeas de los alrededores. Todavía hay carretas de carne destrozadas cerca de la muralla norte y de la puerta, y los cementerios dentro y fuera de los muros, la granja sepultada por la nieve y las balistas destrozadas entre los escombros siguen tal como quedaron.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Alterac",
		},
		["uplands"] = {
			name = "Las Tierras Altas",
			short = "Las Tierras Altas alimentaron en otro tiempo a un reino. Sus colinas eran el granero de Alterac, con cereales y pastos para la antigua nación.",
			full = "Las Tierras Altas alimentaron en otro tiempo a un reino. Sus colinas eran el granero de Alterac, con cereales y pastos para la antigua nación.\n\nAquella nación se quebró. Las Tierras Altas no pasaron a ninguna corona, sino a la Hermandad, que no domina ningún otro lugar de las montañas con tanta firmeza. El barón Vardus manda entre sus campamentos de aquí, señor de las tierras sobrantes de un reino roto.\n\nEn el extremo occidental se encuentra el Redil de Dandred, un nombre que ha sobrevivido a lo que alguna vez significó.",
			source = "https://warcraft.wiki.gg/wiki/Uplands",
		},
	},
	-- Tierras Altas de Arathi: 19 subzones
	[1417] = {
		["boulderfist hall"] = {
			name = "Sala Puño de Roca",
			short = "La Sala Puño de Roca se encuentra en el sur de las Tierras Altas de Arathi, cerca del Puente Thandol y del Poblado Secacorteza: un montículo de piedra fortificado por manos de ogro.",
			full = "La Sala Puño de Roca se encuentra en el sur de las Tierras Altas de Arathi, cerca del Puente Thandol y del Poblado Secacorteza: un montículo de piedra fortificado por manos de ogro. En la cueva más grande de su interior gobierna Kor'gresh Coldrage, jefe del clan Puño de Roca.\n\nDesde entonces, los ogros se han extendido por las colinas circundantes y han reforzado aún más sus defensas.",
			source = "https://warcraft.wiki.gg/wiki/Boulderfist_Hall",
		},
		["bouldergor"] = {
			name = "Roca'gor",
			short = "Al norte del Castillo de Stromgarde se alza la colina de Roca'gor, quebrada y abrupta. Los ogros Puño de Roca tienen aquí su montículo, y los trols del bosque Secacorteza rondan sus laderas junto a ellos.",
			full = "Al norte del Castillo de Stromgarde se alza la colina de Roca'gor, quebrada y abrupta. Los ogros Puño de Roca tienen aquí su montículo, y los trols del bosque Secacorteza rondan sus laderas junto a ellos. En la cara oriental se alza el Círculo de los Elementos, y justo al sur de la colina hay un par de granjas.",
			source = "https://warcraft.wiki.gg/wiki/Boulder'gor",
		},
		["circle of east binding"] = {
			name = "Círculo de Vínculo Este",
			short = "La Piedra de Vínculo Este vigila las tierras orientales de las Tierras Altas de Arathi, cerca de Sentencia, y marca uno de los Círculos de Vínculo dispersos por la región.",
			full = "La Piedra de Vínculo Este vigila las tierras orientales de las Tierras Altas de Arathi, cerca de Sentencia, y marca uno de los Círculos de Vínculo dispersos por la región. Los elementales de agua aún custodian la piedra, atados al lugar como si cumplieran alguna antigua tarea inacabada.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_East_Binding",
		},
		["circle of inner binding"] = {
			name = "Círculo de Vínculo Interior",
			short = "El Círculo de Vínculo Interior se encuentra en el sur de las Tierras Altas de Arathi, cerca del Castillo de Stromgarde, custodiado por elementales de tierra. Aquí descansa la Piedra de Vínculo Interior, la más poderosa de las piedras.",
			full = "El Círculo de Vínculo Interior se encuentra en el sur de las Tierras Altas de Arathi, cerca del Castillo de Stromgarde, custodiado por elementales de tierra. Aquí descansa la Piedra de Vínculo Interior, la más poderosa de las piedras.\n\nA través de su fragmento, Myzrael encontró la manera de hablar con los mortales.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Inner_Binding",
		},
		["circle of outer binding"] = {
			name = "Círculo de Vínculo Exterior",
			short = "El Círculo de Vínculo Exterior se encuentra cerca del Refugio de la Zaga, en las Tierras Altas de Arathi. En su centro se alza la Piedra de Vínculo Exterior, siempre custodiada por elementales de aire.",
			full = "El Círculo de Vínculo Exterior se encuentra cerca del Refugio de la Zaga, en las Tierras Altas de Arathi. En su centro se alza la Piedra de Vínculo Exterior, siempre custodiada por elementales de aire.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Outer_Binding",
		},
		["circle of west binding"] = {
			name = "Círculo de Vínculo Oeste",
			short = "El Círculo de Vínculo Oeste se encuentra en el oeste de las Tierras Altas de Arathi, cerca de la Muralla de Thoradin. Allí descansa la Piedra de Vínculo Oeste, custodiada por elementales de fuego que nunca la dejan sin vigilancia.",
			full = "El Círculo de Vínculo Oeste se encuentra en el oeste de las Tierras Altas de Arathi, cerca de la Muralla de Thoradin. Allí descansa la Piedra de Vínculo Oeste, custodiada por elementales de fuego que nunca la dejan sin vigilancia.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_West_Binding",
		},
		["dabyries farmstead"] = {
			name = "Granja de Dabyrie",
			short = "En el norte de las Tierras Altas de Arathi se encuentra la Granja de Dabyrie, propiedad de Kenata Dabyrie y sus hijos Fardel y Marcel, ciudadanos de Stromgarde y leales a la Alianza.",
			full = "En el norte de las Tierras Altas de Arathi se encuentra la Granja de Dabyrie, propiedad de Kenata Dabyrie y sus hijos Fardel y Marcel, ciudadanos de Stromgarde y leales a la Alianza. Una milicia vigila los campos, pues la familia tiene enemigos.",
			source = "https://warcraft.wiki.gg/wiki/Dabyrie's_Farmstead",
		},
		["drowned reef"] = {
			name = "El Arrecife Hundido",
			short = "Bajo la bahía frente a la costa sur de las Tierras Altas de Arathi yace una ciudad élfica hundida, antigua y en ruinas. Ya no está vacía: los nagas Espinada la han reclamado, gobernados por el príncipe Nazjak.",
			full = "Bajo la bahía frente a la costa sur de las Tierras Altas de Arathi yace una ciudad élfica hundida, antigua y en ruinas. Ya no está vacía: los nagas Espinada la han reclamado, gobernados por el príncipe Nazjak.\n\nEl arrecife que hay encima se ha tragado muchos barcos, entre ellos El Capricho y el Espíritu de Argénteos. Se dice que los Espinada pueden cambiar las mareas mismas de la bahía, y atraen hacia las rocas a las tripulaciones que creen haber encontrado un puerto seguro en la Cala de Faldir.",
			source = "https://warcraft.wiki.gg/wiki/Drowned_Reef",
		},
		["drywhisker gorge"] = {
			name = "Cañón Mostacho Seco",
			short = "El Cañón Mostacho Seco atraviesa las montañas del este de las Tierras Altas de Arathi, al noreste de Sentencia. Al final se encuentra una cueva, hogar de los kóbolds Mostacho Seco, aliados de los gigantes que comparten estas tierras altas.",
			full = "El Cañón Mostacho Seco atraviesa las montañas del este de las Tierras Altas de Arathi, al noreste de Sentencia. Al final se encuentra una cueva, hogar de los kóbolds Mostacho Seco, aliados de los gigantes que comparten estas tierras altas.\n\nEn lo más profundo, más allá de las madrigueras, descansa un fragmento de piedra en el que está atrapada una parte de la esencia de la princesa Myzrael. Los kóbolds lo custodian con ferocidad, junto con las motas reunidas en las profundidades de la cueva, aunque ninguno de ellos parece saber lo que el fragmento contiene en realidad.",
			source = "https://warcraft.wiki.gg/wiki/Drywhisker_Gorge",
		},
		["faldirs cove"] = {
			name = "Cala de Faldir",
			short = "La Cala de Faldir debe su nombre a Faldir, de quien se dice que marcó este lugar cuando él y sus seguidores partieron.",
			full = "La Cala de Faldir debe su nombre a Faldir, de quien se dice que marcó este lugar cuando él y sus seguidores partieron.\n\nMucho después, los asaltantes Aguasnegras llegaron en busca de un tesoro élfico que, según se decía, yacía en las aguas cercanas. Los capitanes Tripacero y O'Breen llevaron tres barcos a la cala, pero una extraña marea se alzó contra ellos, provocada por los nagas que custodiaban unas ruinas hundidas bajo el arrecife, y dos de los tres barcos se hundieron. Solo El Heraldo llegó a la orilla, y su tripulación quedó atrapada en la bahía, sin poder marcharse hasta que los nagas fueron expulsados y se recuperaron los cuadernos de bitácora de los naufragios de abajo.\n\nMás tarde, dos ingenieros gnomos, el doctor Draxlegauge y el profesor Fiseltor, construyeron un aparato para buscar las gemas élficas que, según se decía, estaban calcificadas en las piedras del Arrecife Hundido.\n\nLa cala aún lleva las cicatrices de aquella historia anegada: arrecife, naufragio y ruina, que hablan de barcos que jamás debieron hundirse y de un tesoro que el mar no ha devuelto.",
			source = "https://warcraft.wiki.gg/wiki/Faldir's_Cove",
		},
		["goshek farm"] = {
			name = "Granja Go'shek",
			short = "La Granja Go'shek se encuentra en el este de las Tierras Altas de Arathi, cerca del Poblado Secacorteza.",
			full = "La Granja Go'shek se encuentra en el este de las Tierras Altas de Arathi, cerca del Poblado Secacorteza. Después de la Tercera Guerra, los Renegados y los orcos de Sentencia se apoderaron de la granja para sus propios fines: los orcos obtenían suministros de ella, y los Renegados convirtieron sus campos y construcciones en un campo de pruebas para una alquimia de naturaleza más oscura.\n\nLos agentes de la Alianza Quae y Kinelory vinieron a investigar lo que ocurría aquí. Con ayuda, abatieron a un mensajero Renegado que se dirigía al Molino Tarren antes de que pudiera entregar su mensaje, y registraron la propia granja, donde encontraron las notas de un tal boticario Jorell. Su investigación apuntaba a algo nuevo y terrible que estaba tomando forma: otra peste en preparación.\n\nAhora los brutos de Sentencia ocupan la granja.",
			source = "https://warcraft.wiki.gg/wiki/Go'Shek_Farm",
		},
		["hammerfall"] = {
			name = "Sentencia",
			short = "El suelo de Sentencia recuerda lo que fue. Después de la Segunda Guerra, la Alianza de Lordaeron construyó aquí uno de sus mayores campos de reclusión, donde encerraba a los orcos capturados tras sus muros.",
			full = "El suelo de Sentencia recuerda lo que fue. Después de la Segunda Guerra, la Alianza de Lordaeron construyó aquí uno de sus mayores campos de reclusión, donde encerraba a los orcos capturados tras sus muros. No siguió siendo una prisión. El Jefe de Guerra Thrall y Orgrim Martillo Maldito dirigieron a la Horda contra el campo para liberar a su pueblo, y en el caos de aquella liberación, mientras Thrall cubría la retirada, un caballero a la carga clavó una lanza en la espalda de Orgrim con tal fuerza que le atravesó la armadura de lado a lado. Martillo Maldito murió allí, en la tierra que había venido a liberar.\n\nDespués de la Tercera Guerra, la Horda regresó a las ruinas y levantó entre ellas una base avanzada, a la que llamó Sentencia en honor al Jefe de Guerra que había caído al tomarla. Se convirtió en algo más que un puesto de avanzada: un refugio para quienes sentían que ya no tenían lugar en el mundo, con sus cabañas de los espíritus, establos, forja y gran salón alzándose donde antes estaban los muros del campo de reclusión.",
			source = "https://warcraft.wiki.gg/wiki/Hammerfall",
		},
		["northfold manor"] = {
			name = "Mansión Redilnorte",
			short = "Tras la caída de Stromgarde, la Mansión Redilnorte pasó a manos de la Hermandad, que la convirtió en un puesto de avanzada en las Tierras Altas de Arathi.",
			full = "Tras la caída de Stromgarde, la Mansión Redilnorte pasó a manos de la Hermandad, que la convirtió en un puesto de avanzada en las Tierras Altas de Arathi.\n\nAquí llegó el chamán trol Tor'gan, atraído por algo extraño en el aire. Siguiéndolo hasta la mansión, encontró los restos de una invocación demoníaca que aún se aferraban al lugar, y al acercarse, su propia sangre comenzó a hervir con una ira que no era del todo suya. En el suelo encontró un amuleto de sangrita, usado para invocar demonios, aunque este había agotado su poder. Sospechando que los tratos de la Hermandad iban más allá del bandidaje, buscó otros amuletos similares para descubrir la verdad sobre sus intenciones.",
			source = "https://warcraft.wiki.gg/wiki/Northfold_Manor",
		},
		["refuge pointe"] = {
			name = "Refugio de la Zaga",
			short = "Cuando la capital de Stromgarde quedó en ruinas durante la Tercera Guerra, la mayor parte de su gente huyó al sur, hacia las Tierras Altas de Arathi. Pero los restos del ejército de Stromgarde no quisieron marcharse con ellos.",
			full = "Cuando la capital de Stromgarde quedó en ruinas durante la Tercera Guerra, la mayor parte de su gente huyó al sur, hacia las Tierras Altas de Arathi. Pero los restos del ejército de Stromgarde no quisieron marcharse con ellos. Se quedaron, decididos a recuperar lo que se había perdido, y fue aquí, en el Refugio de la Zaga, donde resistieron.\n\nEl puesto se convirtió en la sede de la guerra de la Alianza en las Tierras Altas, y sus soldados se empeñaron en recuperar el Castillo de Stromgarde y asegurar todos los recursos que pudieran para la causa de la Alianza. Esa determinación única dejaba poco espacio para cualquier otra cosa. Cuando el Puente Thandol sufrió un duro ataque de los Hierro Negro y sus enanos pidieron ayuda para recuperar Dun Modr y el propio puente, la capitana Nials no pudo prescindir de nadie. Stromgarde había caído, dijo, y hasta que se recuperara, cada espada y cada mano del Refugio de la Zaga pertenecían solo a esa causa. El honor y el deber los ataban a las Tierras Altas, le dijo al mensajero, y Largatrenza el Nefasto tendría que arreglárselas sin ellos.",
			source = "https://warcraft.wiki.gg/wiki/Refuge_Pointe",
		},
		["stromgarde keep"] = {
			name = "Castillo de Stromgarde",
			short = "Stromgarde fue antaño Strom, cuna del primer reino humano y capital del Imperio de Arathor.",
			full = "Stromgarde fue antaño Strom, cuna del primer reino humano y capital del Imperio de Arathor. Cuando la Horda orca llegó a los Reinos del Este, aún era una potencia dentro de la Alianza de Lordaeron, y su nombre seguía sin doblegarse incluso después de la Segunda Guerra.\n\nLa ciudad fue saqueada después de la Tercera Guerra y quedó destrozada. Ahora está dividida en tres: el castillo interior, en manos de la Hermandad; el arruinado distrito de los magos, invadido por los ogros Puño de Roca con la ayuda de los trols Secacorteza; y el último barrio, aún en manos del ejército de Stromgarde, desde donde el príncipe Galen Aterratrols dirige lo que queda de su pueblo.",
			source = "https://warcraft.wiki.gg/wiki/Stromgarde_Keep",
		},
		["thandol span"] = {
			name = "Puente Thandol",
			short = "Dos grandes arcos de piedra salvan la distancia entre Los Humedales y las Tierras Altas de Arathi, levantados por manos enanas y custodiados durante tres generaciones por el linaje Yunquemar.",
			full = "Dos grandes arcos de piedra salvan la distancia entre Los Humedales y las Tierras Altas de Arathi, levantados por manos enanas y custodiados durante tres generaciones por el linaje Yunquemar. Se construyeron después de la guerra de los Tres Martillos, cuando Forjaz quiso mantener la lealtad con sus parientes Martillo Salvaje de Pico Nidal, y los puentes se convirtieron a la vez en camino y en símbolo entre los dos reinos enanos, llevando un comercio que enriqueció a ambos.\n\nLos puentes podían soportar el peso de ejércitos enteros, y en otro tiempo fueron la principal ruta comercial entre enanos y humanos. Fue aquí donde Anduin Lothar expulsó a los últimos restos de la antigua Horda de Lordaeron y los hizo retroceder hasta Khaz Modan, obligándolos a cruzar el puente derrotados.\n\nAhora el puente está marcado por las cicatrices. Una conspiración de los Hierro Negro, urdida por Kam Furiahonda y Balgaras el Hediondo, ha causado graves daños a los puentes, y las fuerzas enanas luchan por conservar lo que queda y recuperar el cercano pueblo de Dun Modr. Muchos enanos han muerto en los combates, entre ellos Sully Balloo, Ebenezer Herrumbra y el hermano de Largatrenza el Nefasto.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thoradins wall"] = {
			name = "Muralla de Thoradin",
			short = "El rey Thoradin levantó esta muralla para contener a los trols Amani, en los días en que Strom era joven y Arathor apenas acababa de reclamar esta tierra para la humanidad.",
			full = "El rey Thoradin levantó esta muralla para contener a los trols Amani, en los días en que Strom era joven y Arathor apenas acababa de reclamar esta tierra para la humanidad. Durante generaciones se mantuvo como un centinela firme, una línea destinada a proteger a la humanidad de las incursiones de los trols.\n\nSiglos después, la muralla sigue en pie, pero muy dañada, con sus piedras rotas y su larga vigilancia reducida a ruinas.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["tower of arathor"] = {
			name = "Torre de Arathor",
			short = "La Torre de Arathor se alza en el distrito de los magos del Castillo de Stromgarde, y lleva el nombre del antiguo Imperio de Arathor, del que el reino heredó su linaje.",
			full = "La Torre de Arathor se alza en el distrito de los magos del Castillo de Stromgarde, y lleva el nombre del antiguo Imperio de Arathor, del que el reino heredó su linaje.\n\nEl archimago Trelane estudió en otro tiempo entre sus muros, y allí construyó una defensa entretejida en la propia torre, latente hasta que una gema encantada la despertara. Cuando la Hermandad y los ogros Puño de Roca cercaron Stromgarde, Trelane intentó defender la torre con su creación, pero no fue suficiente. Huyó de la ciudad, y la torre cayó con ella. Los ogros Puño de Roca se adueñaron del distrito, y el mago ogro Ruul Onestone se instaló en sus salones.\n\nTrelane nunca dejó de pensar en lo que había dejado allí: su filacteria, su orbe y un ágata de ascuas trabajada con su propia mano. Recurrió a su antiguo aprendiz, el archimago Malin, para recuperarlos de los ogros que ahora ocupaban la torre. A Malin le llegó la noticia de que las pertenencias de su viejo maestro habían sido halladas, escondidas en unos cofres dentro de los salones que él había considerado suyos.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Arathor",
		},
		["witherbark village"] = {
			name = "Poblado Secacorteza",
			short = "El Poblado Secacorteza rodea un pequeño lago en el sureste de las Tierras Altas de Arathi, hogar de los trols de la tribu Secacorteza. Detrás del poblado se encuentra una gran caverna donde suelen estar los líderes de la tribu.",
			full = "El Poblado Secacorteza rodea un pequeño lago en el sureste de las Tierras Altas de Arathi, hogar de los trols de la tribu Secacorteza. Detrás del poblado se encuentra una gran caverna donde suelen estar los líderes de la tribu.\n\nLos Secacorteza han hecho causa común con los ogros Puño de Roca cercanos, una alianza dirigida contra Stromgarde y Sentencia. Juntos, trols y ogros ocupan una parte de la propia Stromgarde, arrebatada a sus antiguos amos.\n\nEsa fuerza ha convertido a los Secacorteza en un pueblo marcado, perseguido tanto por la Alianza como por la Horda, que deseaban verlos desaparecer. Entre quienes se opusieron a ese ajuste de cuentas, Nimar el Asesino fue considerado el más peligroso, un guerrero que al morir se llevó consigo a muchos de sus enemigos.",
			source = "https://warcraft.wiki.gg/wiki/Witherbark_Village",
		},
	},
	-- Tierras Inhóspitas: 17 subzones
	[1418] = {
		["agmonds end"] = {
			name = "El Final de Agmond",
			short = "La excavación del centro sur de las Tierras Inhóspitas lleva el nombre del enano que murió allí.",
			full = "La excavación del centro sur de las Tierras Inhóspitas lleva el nombre del enano que murió allí. Agmond vino a romper piedra y encontró a los troggs que ya habían reclamado el terreno; acabaron con él allí mismo, y el lugar quedó abandonado en sus manos.",
			source = "https://warcraft.wiki.gg/wiki/Agmond's_End",
		},
		["angor fortress"] = {
			name = "Fortaleza de Angor",
			short = "Los enanos Hierro Negro tienen en la Fortaleza de Angor su sede en las Tierras Inhóspitas, desde donde dirigen sus excavaciones hacia Uldaman.",
			full = "Los enanos Hierro Negro tienen en la Fortaleza de Angor su sede en las Tierras Inhóspitas, desde donde dirigen sus excavaciones hacia Uldaman.",
			source = "https://warcraft.wiki.gg/wiki/Angor_Fortress",
		},
		["apocryphans rest"] = {
			name = "Descanso de Apócrifo",
			short = "Los huesos del Descanso de Apócrifo se extienden por las Tierras Inhóspitas al sur de Kargath: el esqueleto de un dragón caído, abandonado para blanquearse bajo el calor seco.",
			full = "Los huesos del Descanso de Apócrifo se extienden por las Tierras Inhóspitas al sur de Kargath: el esqueleto de un dragón caído, abandonado para blanquearse bajo el calor seco. Ahora los buitres anidan y cazan entre sus costillas, los únicos que consideran su hogar este enorme cadáver.",
			source = "https://warcraft.wiki.gg/wiki/Apocryphan's_Rest",
		},
		["camp boff"] = {
			name = "Asentamiento Boff",
			short = "El Asentamiento Boff es el campamento del sureste de los ogros Rotapolvo, uno de los cuatro junto con los asentamientos Cagg, Kosh y Wurg. Pocos ogros lo custodian.",
			full = "El Asentamiento Boff es el campamento del sureste de los ogros Rotapolvo, uno de los cuatro junto con los asentamientos Cagg, Kosh y Wurg. Pocos ogros lo custodian.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Boff",
		},
		["camp cagg"] = {
			name = "Asentamiento Cagg",
			short = "El Asentamiento Cagg es uno de los hogares de los ogros Rotapolvo, que comparten ese nombre con otros tres campamentos dispersos por los alrededores.",
			full = "El Asentamiento Cagg es uno de los hogares de los ogros Rotapolvo, que comparten ese nombre con otros tres campamentos dispersos por los alrededores.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Cagg",
		},
		["camp kosh"] = {
			name = "Asentamiento Kosh",
			short = "El Asentamiento Kosh se encuentra en el extremo norte del territorio Rotapolvo y vigila los caminos áridos que serpentean hacia Kargath y bajan hacia la Garganta de Fuego.",
			full = "El Asentamiento Kosh se encuentra en el extremo norte del territorio Rotapolvo y vigila los caminos áridos que serpentean hacia Kargath y bajan hacia la Garganta de Fuego. Las caravanas que cruzan las Tierras Inhóspitas temen este tramo, pues los ogros de Kosh caen sobre ellas por lo que sea que lleven.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Kosh",
		},
		["camp wurg"] = {
			name = "Asentamiento Wurg",
			short = "El Asentamiento Wurg es uno de los hogares de los ogros Rotapolvo, parientes de los ogros de los asentamientos Cagg, Boff y Kosh.",
			full = "El Asentamiento Wurg es uno de los hogares de los ogros Rotapolvo, parientes de los ogros de los asentamientos Cagg, Boff y Kosh.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Wurg",
		},
		["dustbelch grotto"] = {
			name = "Gruta Rotapolvo",
			short = "En el suroeste de las Tierras Inhóspitas se alza un gran montículo de tierra y piedra, ahuecado y reclamado por los ogros Rotapolvo.",
			full = "En el suroeste de las Tierras Inhóspitas se alza un gran montículo de tierra y piedra, ahuecado y reclamado por los ogros Rotapolvo. La Gruta Rotapolvo es su hogar, una madriguera de túneles y cámaras donde el clan ha establecido su guarida en medio de la tierra agrietada y abrasada por el sol que la rodea.",
			source = "https://warcraft.wiki.gg/wiki/Dustbelch_Grotto",
		},
		["dustbowl"] = {
			name = "Terraseca",
			short = "Terraseca se encuentra entre Kargath y el Valle de los Colmillos, una extensión de terreno agrietado y árido en el noroeste de las Tierras Inhóspitas. Coyotes y buitres la recorren, y elementales de roca se agitan entre las piedras.",
			full = "Terraseca se encuentra entre Kargath y el Valle de los Colmillos, una extensión de terreno agrietado y árido en el noroeste de las Tierras Inhóspitas. Coyotes y buitres la recorren, y elementales de roca se agitan entre las piedras. Aquí apenas crecen cactus y unos pocos árboles tenaces. El Asentamiento Wurg se alza en medio de este páramo.",
			source = "https://warcraft.wiki.gg/wiki/Dustbowl",
		},
		["dustwind gulch"] = {
			name = "Barranco Viento Seco",
			short = "Los vientos azotan el Barranco Viento Seco hasta que no queda en pie nada blando, solo piedra y los huesos secos del barranco. Se encuentra al oeste del Barranco Lethlor, un tajo de tierra yerma en las Tierras Inhóspitas donde el polvo nunca se asienta por mucho tiempo.",
			full = "Los vientos azotan el Barranco Viento Seco hasta que no queda en pie nada blando, solo piedra y los huesos secos del barranco. Se encuentra al oeste del Barranco Lethlor, un tajo de tierra yerma en las Tierras Inhóspitas donde el polvo nunca se asienta por mucho tiempo.",
			source = "https://warcraft.wiki.gg/wiki/Dustwind_Gulch",
		},
		["hammertoes digsite"] = {
			name = "Excavación de Piemartillo",
			short = "La Excavación de Piemartillo se encuentra en el norte de las Tierras Inhóspitas, y sus zanjas ya no oyen a los mineros que antes las trabajaban.",
			full = "La Excavación de Piemartillo se encuentra en el norte de las Tierras Inhóspitas, y sus zanjas ya no oyen a los mineros que antes las trabajaban. El propio Piemartillo ha abandonado el lugar, y en su lugar se ha instalado una banda de Hierro Negro, probablemente la misma fuerza que se ha adentrado en Uldaman.",
			source = "https://warcraft.wiki.gg/wiki/Hammertoe's_Digsite",
		},
		["kargath"] = {
			name = "Kargath",
			short = "Kargath se alza solitaria en Khaz Modan, el único puesto que la Horda tiene en esa tierra, y lleva el nombre de Kargath Garrafilada, jefe del clan Mano Destrozada.",
			full = "Kargath se alza solitaria en Khaz Modan, el único puesto que la Horda tiene en esa tierra, y lleva el nombre de Kargath Garrafilada, jefe del clan Mano Destrozada.\n\nPor orden del propio Jefe de Guerra Thrall, la Fuerza Expedicionaria de Kargath sale una y otra vez a las duras Tierras Inhóspitas. Su verdadero propósito es abrir una ruta a través de la Garganta de Fuego hasta la Montaña Roca Negra, para que la Horda pueda atacar a Rend Puño Negro, Jefe de Guerra de la Horda Oscura, en su propio bastión. Ese camino atraviesa tierras que los enanos Hierro Negro consideran suyas, y así la Horda se ha visto de nuevo en guerra con ellos, no por un plan, sino por el simple hecho de la tierra que necesitaba cruzar.\n\nEl otro valor de Kargath es más evidente: es la bisagra entre el norte y el sur, el punto donde el camino que viene de Sentencia y de Entrañas se une al que baja hacia Grom'gol, Bahía del Botín y Rocal.",
			source = "https://warcraft.wiki.gg/wiki/Kargath",
		},
		["lethlor ravine"] = {
			name = "Barranco Lethlor",
			short = "El Barranco Lethlor se abre amplio y escarpado en el este de las Tierras Inhóspitas, con su fondo infestado de crías y dracos del Vuelo Negro.",
			full = "El Barranco Lethlor se abre amplio y escarpado en el este de las Tierras Inhóspitas, con su fondo infestado de crías y dracos del Vuelo Negro. Por todo el barranco se alzan obeliscos cristalinos, extraños y deliberados en medio de la roca y el fuego de dragón.",
			source = "https://warcraft.wiki.gg/wiki/Lethlor_Ravine",
		},
		["makers terrace"] = {
			name = "Bancal del Hacedor",
			short = "Frente a la entrada de Uldaman, la tierra ha sido arrancada en cortes amplios y deliberados, una cicatriz de excavación abierta al cielo.",
			full = "Frente a la entrada de Uldaman, la tierra ha sido arrancada en cortes amplios y deliberados, una cicatriz de excavación abierta al cielo. Ahora los enanos Hierro Negro ocupan la terraza y vigilan las excavaciones y el camino que desciende hacia los lugares sepultados de abajo.",
			source = "https://warcraft.wiki.gg/wiki/Maker's_Terrace",
		},
		["mirage flats"] = {
			name = "Explanada del Espejismo",
			short = "La Explanada del Espejismo se encuentra al este de la Gruta Rotapolvo, en las Tierras Inhóspitas. Poco queda de ella salvo una extensión de tierra de nadie, reclamada solo por buitres gigantes, patriarcas acechadores de las crestas y coyotes rabiosos de los riscos.",
			full = "La Explanada del Espejismo se encuentra al este de la Gruta Rotapolvo, en las Tierras Inhóspitas. Poco queda de ella salvo una extensión de tierra de nadie, reclamada solo por buitres gigantes, patriarcas acechadores de las crestas y coyotes rabiosos de los riscos.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Flats",
		},
		["uldaman"] = {
			name = "Uldaman",
			short = "En lo más profundo de las montañas de Khaz Modan se encuentra Uldaman, una cámara vasta y antigua levantada por los guardianes titánicos en épocas remotas.",
			full = "En lo más profundo de las montañas de Khaz Modan se encuentra Uldaman, una cámara vasta y antigua levantada por los guardianes titánicos en épocas remotas. Los enanos de Forjaz se adentraron en ella antes de la Tercera Guerra, excavando sus cámaras sepultadas, pero desde entonces la cámara ha caído en manos de troggs y de los Hierro Negro, que ahora horadan su piedra en busca de las riquezas terrenales que aún contenga.\n\nUldaman sigue repleta de los vestigios de aquella era forjada por los titanes, y quienes se atreven a adentrarse en sus profundidades aún encuentran artefactos enterrados en ella, que los arqueólogos y aventureros de la Liga de Expedicionarios desentierran poco a poco mientras siguen rebuscando entre las ruinas.",
			source = "https://warcraft.wiki.gg/wiki/Uldaman",
		},
		["valley of fangs"] = {
			name = "Valle de los Colmillos",
			short = "El Valle de los Colmillos se abre estrecho entre dos paredes de piedra en las Tierras Inhóspitas, reclamado por lobos y pumas cuyos dientes dan nombre al lugar.",
			full = "El Valle de los Colmillos se abre estrecho entre dos paredes de piedra en las Tierras Inhóspitas, reclamado por lobos y pumas cuyos dientes dan nombre al lugar.\n\nEn su interior acampa Martek el Exiliado, expulsado del lugar al que alguna vez perteneció, junto con Aparejez y Jazzrik.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Fangs",
		},
	},
	-- Las Tierras Devastadas: 7 subzones
	[1419] = {
		["dark portal"] = {
			name = "El Portal Oscuro",
			short = "La creación del portal fue una traición desde el primer momento. Gul'dan y el mago humano Medivh, este último poseído por el titán oscuro Sargeras, abrieron juntos la grieta.",
			full = "La creación del portal fue una traición desde el primer momento. Gul'dan y el mago humano Medivh, este último poseído por el titán oscuro Sargeras, abrieron juntos la grieta. En Draenor, los canteros orcos que construyeron su marco de piedra fueron asesinados por los brujos para preparar el sello final, y casi todos los prisioneros draenei que aún tenía la Horda fueron llevados a su base y despojados de la vida en un solo instante para darle a Gul'dan el poder de unir los dos mundos. A través de ese portal, la Horda irrumpió en Ventormenta y comenzó la Primera Guerra, y en la guerra que siguió trajo a Azeroth un sinfín de orcos y ogros, mientras los pantanos que lo rodeaban se corrompían hasta convertirse en el páramo rojo como la sangre que más tarde se llamó las Tierras Devastadas.\n\nAl terminar la guerra, el archimago Khadgar y sus compañeros magos destrozaron la estructura en el lado de Azeroth para impedir la retirada de la Horda, con una explosión tan violenta que también destruyó el marco en Draenor. Después, Khadgar levantó el Castillo de Nethergarde para vigilar las ruinas, aunque la grieta entre los mundos nunca llegó a sellarse del todo, y los demonios volverían a atravesarla en los años siguientes.",
			source = "https://warcraft.wiki.gg/wiki/Dark_Portal",
		},
		["dreadmaul post"] = {
			name = "Puesto Machacamiedo",
			short = "El Puesto Machacamiedo es un montículo levantado por el clan de ogros Machacamiedo, que llegaron a Azeroth desde Draenor y nunca se alejaron mucho del Portal Oscuro.",
			full = "El Puesto Machacamiedo es un montículo levantado por el clan de ogros Machacamiedo, que llegaron a Azeroth desde Draenor y nunca se alejaron mucho del Portal Oscuro. Todavía dominan este terreno.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Post",
		},
		["garrison armory"] = {
			name = "Arsenal del Cuartel",
			short = "En el suelo lleno de cicatrices de las Tierras Devastadas, los mineros de la Alianza trabajan en el Arsenal del Cuartel, arrancando minerales de la tierra para el Castillo de Nethergarde.",
			full = "En el suelo lleno de cicatrices de las Tierras Devastadas, los mineros de la Alianza trabajan en el Arsenal del Cuartel, arrancando minerales de la tierra para el Castillo de Nethergarde. Lo que recogen se envía a Ventormenta, y a cambio el castillo recibe los demás suministros que necesita para resistir en ese lugar maldito.",
			source = "https://warcraft.wiki.gg/wiki/Garrison_Armory",
		},
		["nethergarde keep"] = {
			name = "Castillo de Nethergarde",
			short = "El Castillo de Nethergarde se alza sobre un alto risco que domina el único camino que entra en las Tierras Devastadas, y sus muros se levantaron para vigilar una herida en el mundo que nadie quería ver abierta de nuevo.",
			full = "El Castillo de Nethergarde se alza sobre un alto risco que domina el único camino que entra en las Tierras Devastadas, y sus muros se levantaron para vigilar una herida en el mundo que nadie quería ver abierta de nuevo.\n\nEl archimago Khadgar pidió su construcción en los años posteriores a la Segunda Guerra, cuando el primer Portal Oscuro yacía destrozado y las tierras natales de los orcos, al otro lado, se habían marchitado hasta quedar en ruinas. La Alianza de Lordaeron pagó por él, algunos reinos con más gusto que otros, y la Hermandad de los Albañiles lo levantó bajo la dirección de Edwin VanCleef. Después, el Kirin Tor lo guarneció y se esforzó por contener la corrupción que brotaba de la herida del portal y amenazaba con extenderse por las tierras de más allá.\n\nKhadgar siguió siendo su señor hasta que los clanes de Ner'zhul reconstruyeron el Portal Oscuro desde el lado de Draenor y asediaron el castillo. Khadgar y sus compañeros Turalyon, Danath Aterratrols, Alleria Brisaveloz y Kurdran Martillo Salvaje condujeron a la Alianza a través del portal para derrotar allí a la Horda, y luego se quedaron al otro lado para sellarlo, de modo que la ruina de Draenor no los siguiera hasta casa. Durante los veinte años siguientes, el portal permaneció en silencio.",
			source = "https://warcraft.wiki.gg/wiki/Nethergarde_Keep",
		},
		["rise of the defiler"] = {
			name = "Alto de los Rapiñadores",
			short = "El Alto de los Rapiñadores se eleva en medio de las Tierras Devastadas, una extensión escarpada de montaña quebrada. Aquí habita el gran demonio Razelikh, cuya sola presencia basta para dar nombre al lugar.",
			full = "El Alto de los Rapiñadores se eleva en medio de las Tierras Devastadas, una extensión escarpada de montaña quebrada. Aquí habita el gran demonio Razelikh, cuya sola presencia basta para dar nombre al lugar.",
			source = "https://warcraft.wiki.gg/wiki/Rise_of_the_Defiler",
		},
		["serpents coil"] = {
			name = "Serpiente Enroscada",
			short = "La Serpiente Enroscada es un sinuoso sistema de cuevas en el este de las Tierras Devastadas, cuya entrada está marcada por construcciones orcas calcinadas que quedaron de la Segunda Guerra.",
			full = "La Serpiente Enroscada es un sinuoso sistema de cuevas en el este de las Tierras Devastadas, cuya entrada está marcada por construcciones orcas calcinadas que quedaron de la Segunda Guerra. Mucho después de que terminara aquella guerra, las cuevas se convirtieron en refugio de algo más oscuro: cultistas entregados a la adoración de Kirith el Maldito.\n\nEn ese laberinto entró el archimago Allistarj, que puso a trabajar a sus Sombra Jurada desde su interior. Cerca de la entrada, un cofre guarda un amuleto que lleva su nombre.",
			source = "https://warcraft.wiki.gg/wiki/Serpent's_Coil",
		},
		["tainted scar"] = {
			name = "Escara Impía",
			short = "La Escara Impía formó parte en otro tiempo de la Ciénaga Negra, antes de que la corrupción del Portal Oscuro se filtrara en ella y dejara el suelo seco, sin árboles y rojo como la sangre.",
			full = "La Escara Impía formó parte en otro tiempo de la Ciénaga Negra, antes de que la corrupción del Portal Oscuro se filtrara en ella y dejara el suelo seco, sin árboles y rojo como la sangre. Ya no corre agua por allí. Bestias demoníacas merodean por un suelo que ya no recuerda lo que alguna vez creció en él.\n\nTras la batalla del Monte Hyjal, el señor ered'ruin Kazzak retiró a la Escara lo que quedaba de las fuerzas de la Legión Ardiente en Azeroth y la convirtió en su dominio. Puso al frente a su lugarteniente Razelikh el Rapiñador, con el encargo de mantener la tierra bajo control. El propio Kazzak permaneció allí después, y su sola presencia bastaba para señalar la Escara como territorio de la Legión, años después de que Hyjal se librara y se ganara en otra parte.\n\nUn viejo brujo humano, Daio el Decrépito, llegó a la Escara mucho después y se instaló junto a su altar. Allí, entre los demonios que la tierra ya engendraba, practicó sus rituales sin ser molestado y acogió a jóvenes reclutas, enseñándoles las artes infernales en un lugar ya entregado a lo vil.",
			source = "https://warcraft.wiki.gg/wiki/Tainted_Scar",
		},
	},
	-- Claros de Tirisfal: 28 subzones
	[1420] = {
		["agamand family crypt"] = {
			name = "Cripta de la Familia Agamand",
			short = "Al norte de los Molinos de Agamand, los muertos de la familia Agamand descansaban antes en esta cripta. El capitán Dargol, un esbirro de la Plaga, se apoderó del lugar y despertó a todos los cadáveres y espíritus que había en su interior.",
			full = "Al norte de los Molinos de Agamand, los muertos de la familia Agamand descansaban antes en esta cripta. El capitán Dargol, un esbirro de la Plaga, se apoderó del lugar y despertó a todos los cadáveres y espíritus que había en su interior. Ahora el polvo flota espeso en los pasadizos oscuros, y los muertos vengativos atacan a cualquiera que entre sin ser invitado.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Family_Crypt",
		},
		["agamand mills"] = {
			name = "Molinos de Agamand",
			short = "Los molinos de viento de Agamand giraban antaño para una de las familias más ricas de Tirisfal. Cuando la Plaga llegó al norte, Gregor Agamand se negó a huir.",
			full = "Los molinos de viento de Agamand giraban antaño para una de las familias más ricas de Tirisfal. Cuando la Plaga llegó al norte, Gregor Agamand se negó a huir. Fortificó los molinos, los abasteció para resistir un asedio y convenció a los propios trabajadores de la familia de que se quedaran a luchar junto a ellos.\n\nDebería haber resistido. No lo hizo, porque la traición vino de dentro de los muros. Devlin, el hijo menor de los Agamand, se volvió contra su propia sangre y ayudó a la Plaga, y la guarnición no pudo aguantar los asaltos que siguieron. Con el tiempo, la peste acabó igualmente con el resto de la familia, y los Agamand que habían muerto defendiendo su hogar se alzaron de nuevo en él como muertos sin mente.\n\nLos molinos de viento siguen en pie en las tierras altas del norte de Tirisfal, y la familia que los construyó sirve ahora a la misma hueste que la destruyó.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Mills",
		},
		["balnir farmstead"] = {
			name = "Hacienda Balnir",
			short = "La Hacienda Balnir se encuentra al noreste de la capital en ruinas, con sus cercas rotas y sus establos vacíos salvo por los miembros de la Plaga que vagan por ellos.",
			full = "La Hacienda Balnir se encuentra al noreste de la capital en ruinas, con sus cercas rotas y sus establos vacíos salvo por los miembros de la Plaga que vagan por ellos.\n\nLa familia Balnir dirigió en otro tiempo esta tierra, donde criaba los grandes caballos blancos que la casa real de Lordaeron montaba. El día en que cayó la Ciudad Capital, la Plaga llegó a la hacienda y mató a toda la familia, dejando atrás solo su tierra embrujada.\n\nLas bocas de dragón que antes se cuidaban en el jardín de la granja aún crecen silvestres allí, y a los vivos les ha llegado la noticia de que la corrupción de las Tierras de la Peste puede haberse infiltrado en ellas. Los miembros de la Plaga que logran pasar el Baluarte se reúnen en gran número alrededor de la granja en ruinas.",
			source = "https://warcraft.wiki.gg/wiki/Balnir_Farmstead",
		},
		["brightwater lake"] = {
			name = "Lago Aguasclaras",
			short = "El Lago Aguasclaras se encuentra al noreste de Rémol, y en el centro de sus aguas hay una gran isla donde ahora se alza el Refugio de Gunther.",
			full = "El Lago Aguasclaras se encuentra al noreste de Rémol, y en el centro de sus aguas hay una gran isla donde ahora se alza el Refugio de Gunther.",
			source = "https://warcraft.wiki.gg/wiki/Brightwater_Lake",
		},
		["brill"] = {
			name = "Rémol",
			short = "Rémol fue en otro tiempo un pueblo corriente del reino de Lordaeron, en manos de la familia Barov, y los Agamand tenían una mansión propia dentro de sus límites.",
			full = "Rémol fue en otro tiempo un pueblo corriente del reino de Lordaeron, en manos de la familia Barov, y los Agamand tenían una mansión propia dentro de sus límites. Su normalidad terminó el día en que llegó Kel'Thuzad. Todavía era un hombre vivo entonces, y el nigromante eligió Rémol como el lugar donde probar por primera vez la peste de la no-muerte, y el éxito de aquella infestación fue tan completo que lo animó a presionar al Rey Exánime para lanzar antes de tiempo la invasión de Lordaeron. Los muertos de los Claros de Tirisfal eran más de los que la tierra podía enterrar como es debido; el gran cementerio fuera de los muros de Rémol es la respuesta a ese excedente. Los propios defensores del pueblo no pudieron conservarlo, y los supervivientes que quedaron huyeron para unirse al príncipe Arthas Menethil mientras perseguía el origen de la corrupción que asolaba el norte.\n\nRémol no permaneció en silencio. Años después, los Renegados lo reclamaron, y el magistrado Sevren gobierna ahora lo que la peste se llevó. Aquí también perduran viejos rencores: Coleman Farthing, que antes estuvo al servicio de la familia Agamand, aún busca sus restos, huesos que no se entregan por piedad, sino como venganza por una muerte de la que los culpa.",
			source = "https://warcraft.wiki.gg/wiki/Brill",
		},
		["brill town hall"] = {
			name = "Concejo de Rémol",
			short = "El Concejo es la construcción más destacada de Rémol. Desde su estrado, el magistrado Sevren habla en nombre del pueblo y asigna sus tareas a los muertos de Tirisfal.",
			full = "El Concejo es la construcción más destacada de Rémol. Desde su estrado, el magistrado Sevren habla en nombre del pueblo y asigna sus tareas a los muertos de Tirisfal. Pocos salones como este están en manos de los Renegados en ningún otro lugar, prueba de lo firmemente que Rémol les pertenece.",
			source = "https://warcraft.wiki.gg/wiki/Brill_Town_Hall",
		},
		["bulwark"] = {
			name = "El Baluarte",
			short = "El Baluarte se alza donde los Claros de Tirisfal se unen a las Tierras de la Peste del Oeste, la línea que los Renegados defienden contra la Plaga, que todavía se concentra al este.",
			full = "El Baluarte se alza donde los Claros de Tirisfal se unen a las Tierras de la Peste del Oeste, la línea que los Renegados defienden contra la Plaga, que todavía se concentra al este. Aquí, los defensores Renegados y El Alba Argenta han dejado de lado sus diferencias frente a ese enemigo común, vigilando juntos la frontera y enviando combatientes hacia el este para atacar a los esbirros del Rey Exánime.\n\nA diferencia del resto de Tirisfal, este tramo no se parece en absoluto a los Claros: una niebla de peste flota sobre él y tiñe el cielo del mismo gris amarillento y enfermizo que el de las Tierras de la Peste del Oeste que se extienden más allá.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["cold hearth manor"] = {
			name = "Mansión Fríogar",
			short = "La Mansión Fríogar se ganó en otro tiempo su nombre por el calor de su hogar y la riqueza de sus campos. La Peste de la no-muerte acabó con eso.",
			full = "La Mansión Fríogar se ganó en otro tiempo su nombre por el calor de su hogar y la riqueza de sus campos. La Peste de la no-muerte acabó con eso. Todos los que vivían o trabajaban aquí murieron por la enfermedad, y la tierra generosa se volvió estéril, con sus hileras invadidas por muertos sin mente de la Plaga que aún se arrastran por ellas.\n\nLos Renegados se apoderaron de la casa de labranza y tratan desde allí con los viajeros del camino cercano.",
			source = "https://warcraft.wiki.gg/wiki/Cold_Hearth_Manor",
		},
		["crusader outpost"] = {
			name = "Avanzada de los Cruzados",
			short = "Una torre de exploración se alza en las colinas orientales de los Claros de Tirisfal, en manos de la Cruzada Escarlata.",
			full = "Una torre de exploración se alza en las colinas orientales de los Claros de Tirisfal, en manos de la Cruzada Escarlata. Desde su altura vigilan el camino que baja hacia el sur a través de los claros, listos para flanquear a cualquier fuerza que se atreva a marchar sobre el Monasterio Escarlata, más allá. El capitán Vachon está al mando aquí.",
			source = "https://warcraft.wiki.gg/wiki/Crusader_Outpost",
		},
		["deathknell"] = {
			name = "Camposanto",
			short = "Camposanto se encuentra en un valle estrecho y bien custodiado, y es aquí donde los Renegados recién alzados abren por primera vez los ojos al mundo que se les ha dado.",
			full = "Camposanto se encuentra en un valle estrecho y bien custodiado, y es aquí donde los Renegados recién alzados abren por primera vez los ojos al mundo que se les ha dado.\n\nA diferencia de los demás dominios de los no-muertos rebeldes de la Reina alma en pena, que conservaron los nombres que tenían cuando eran pueblos de vivos, Camposanto recibió un nombre completamente nuevo, acorde con lo que ocurre allí y no con lo que antes había. Hoy nadie recuerda por qué.\n\nSobrevivir aquí es una lucha diaria, y el oro es lo más escaso de todo. Al noroeste de la aldea hay una mina rica en metal, pero ha sido invadida por arañas, y los muertos de Camposanto salen una y otra vez a intentar despejarla para que por fin pueda explotarse el mineral que hay debajo. Los guardias de la muerte de élite vigilan los bordes del valle, lo único que se interpone entre los frágiles nuevos muertos y la Plaga y la Cruzada Escarlata, que acabarían con ellos por segunda vez.",
			source = "https://warcraft.wiki.gg/wiki/Deathknell",
		},
		["faols rest"] = {
			name = "Tumba de Faol",
			short = "Al suroeste del Monasterio Escarlata, en el este de los Claros de Tirisfal, se encuentra una parcela de tierra que antes cuidaban los dolientes: la Tumba de Faol, sepultura del arzobispo Alonsus Faol.",
			full = "Al suroeste del Monasterio Escarlata, en el este de los Claros de Tirisfal, se encuentra una parcela de tierra que antes cuidaban los dolientes: la Tumba de Faol, sepultura del arzobispo Alonsus Faol.\n\nFaol fue venerado en vida, y su muerte, algún tiempo antes de la llegada de la Plaga, atrajo a los dolientes a este lugar.\n\nYa nadie visita la tumba que dejó. Los dolientes que antes acudían se han ido, y la parcela yace descuidada y casi olvidada.",
			source = "https://warcraft.wiki.gg/wiki/Faol's_Rest",
		},
		["gallows end tavern"] = {
			name = "Mesón La Horca",
			short = "El Mesón La Horca se encuentra en Rémol, y su nombre es un eco sombrío del pueblo al que sirve.",
			full = "El Mesón La Horca se encuentra en Rémol, y su nombre es un eco sombrío del pueblo al que sirve. Bajo su suelo, los sótanos no guardan barriles dignos de mención: allí se retiene a un zelote Escarlata capturado y a un enano montaraz, prisioneros de los Renegados.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_End_Tavern",
		},
		["garrens haunt"] = {
			name = "Granja de Garren",
			short = "La Granja de Garren fue en otro tiempo una próspera hacienda en el norte de los Claros de Tirisfal, con campos amplios y silos llenos. La Peste de la no-muerte acabó con eso.",
			full = "La Granja de Garren fue en otro tiempo una próspera hacienda en el norte de los Claros de Tirisfal, con campos amplios y silos llenos. La Peste de la no-muerte acabó con eso. Cuando la Plaga arrasó la región durante la Purga de Lordaeron, Garren y su familia fueron masacrados en su propio hogar, y la tierra misma se volvió gris y sin vida alrededor de su casa en ruinas.\n\nLo que sigue en pie fue reclamado por los gnolls Putrepellejo, dirigidos por Ojo de cresa, que se apoderaron de la casa y del granero y atacaban sin dudarlo a cualquiera que se acercara demasiado.\n\nLa granja nunca se recuperó. Sigue abandonada, con sus campos vacíos y su familia desaparecida, y solo quedan los gnolls para responder por quién la ocupa ahora.",
			source = "https://warcraft.wiki.gg/wiki/Garren's_Haunt",
		},
		["gunthers retreat"] = {
			name = "Refugio de Gunther",
			short = "En una isla del Lago Aguasclaras se encuentra el Refugio de Gunther, reclamado por el exánime Renegado Gunther Arcanus y sus esbirros zombis.",
			full = "En una isla del Lago Aguasclaras se encuentra el Refugio de Gunther, reclamado por el exánime Renegado Gunther Arcanus y sus esbirros zombis. Frente a su orilla suroeste, en un islote desnudo y sin nombre, hay una extraña señal conocida solo como la Mesa de cena de Lillith.",
			source = "https://warcraft.wiki.gg/wiki/Gunther's_Retreat",
		},
		["night webs hollow"] = {
			name = "Hoya Nocturácnidas",
			short = "La Hoya Nocturácnidas es un pequeño valle atravesado por una antigua mina de oro, ambos reclamados por las arañas. Las crías vagan por la hondonada abierta, mientras que las arañas nocturácnidas adultas ocupan los túneles más oscuros de la mina.",
			full = "La Hoya Nocturácnidas es un pequeño valle atravesado por una antigua mina de oro, ambos reclamados por las arañas. Las crías vagan por la hondonada abierta, mientras que las arañas nocturácnidas adultas ocupan los túneles más oscuros de la mina.\n\nLos Renegados recién alzados vienen aquí a poner a prueba lo que sus cuerpos aún pueden hacer, abatiendo a las arañas jóvenes del exterior antes de atreverse con la propia mina.\n\nEn su rincón más profundo se encuentra la matriarca nocturácnida, madre del enjambre que hay sobre ella.",
			source = "https://warcraft.wiki.gg/wiki/Night_Web's_Hollow",
		},
		["nightmare vale"] = {
			name = "Vega Pesadilla",
			short = "Al oeste de la Atalaya Escarlata, en los Claros de Tirisfal, se extiende un valle arruinado. Sus árboles se han marchitado, y los canes oscuros y los enormes murciélagos vampiro han devorado la fauna que antes vivía entre ellos.",
			full = "Al oeste de la Atalaya Escarlata, en los Claros de Tirisfal, se extiende un valle arruinado. Sus árboles se han marchitado, y los canes oscuros y los enormes murciélagos vampiro han devorado la fauna que antes vivía entre ellos. Entre estos cazadores vuela Ressan el Aguijoneador, un raro murciélago blanco distinto de los demás.",
			source = "https://warcraft.wiki.gg/wiki/Nightmare_Vale",
		},
		["north coast"] = {
			name = "La Costa Norte",
			short = "La Costa Norte se extiende donde los Claros de Tirisfal se unen al Mare Magnum, ahora entregada a los múrlocs y a las criaturas del agua.",
			full = "La Costa Norte se extiende donde los Claros de Tirisfal se unen al Mare Magnum, ahora entregada a los múrlocs y a las criaturas del agua. Desde la Peste de la no-muerte, la orilla se ha vuelto oscura y fría, y la marea deja criaturas marinas muertas pudriéndose al borde del agua.",
			source = "https://warcraft.wiki.gg/wiki/North_Coast",
		},
		["ruins of lordaeron"] = {
			name = "Ruinas de Lordaeron",
			short = "Sobre la ciudad sepultada, el palacio de Lordaeron sigue en pie, con sus salones abiertos al cielo y sus jardines en ruinas. Aquí murió el gran reino de la Alianza, y aquí sus fantasmas nunca se han ido del todo.",
			full = "Sobre la ciudad sepultada, el palacio de Lordaeron sigue en pie, con sus salones abiertos al cielo y sus jardines en ruinas. Aquí murió el gran reino de la Alianza, y aquí sus fantasmas nunca se han ido del todo.\n\nFue Arthas Menethil quien le puso fin. El príncipe regresó a casa al frente de un ejército alzado contra su propio pueblo, recibido a través de estas puertas con campanas y vítores antes de que nadie comprendiera en qué se había convertido. Encontró a su padre, el rey Terenas, esperándolo en la sala del trono, y lo mató allí mismo. De pie sobre el cuerpo, pronunció palabras que aún resuenan en esa sala para quien se detenga en ella: que el reino caería, y que de sus cenizas surgiría un nuevo orden que sacudiría el mundo. No fue una amenaza vana. En cuestión de días, la ciudad y su gente fueron masacradas, y Lordaeron pasó a pertenecer a la Plaga.\n\nSe dice que quien recorre aún el patio puede oír lo que la piedra recuerda: voces apagadas, el tañido de las campanas de bienvenida, un murmullo en la sala del trono que nunca termina de apagarse. Quienes pueden ver más allá del velo dicen que los ciudadanos de Lordaeron aún caminan por allí, sin saber que su reino ya no existe.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
		["scarlet monastery"] = {
			name = "Monasterio Escarlata",
			short = "Bajo la Cruzada, el Viejo Monasterio se convirtió en cuartel y prisión. La inquisidora Melenablanca y Renault Mograine establecieron allí su sede, y su capilla se convirtió en un lugar de juicio además de oración.",
			full = "Bajo la Cruzada, el Viejo Monasterio se convirtió en cuartel y prisión. La inquisidora Melenablanca y Renault Mograine establecieron allí su sede, y su capilla se convirtió en un lugar de juicio además de oración.\n\nAntes de ser una fortaleza, el Viejo Monasterio era una catedral de la Iglesia de la Luz Sagrada, llena de bibliotecas donde se formaban los paladines. El propio Alexandros Mograine pasó allí meses en su juventud, rezando y estudiando antes de empuñar jamás una espada.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Monastery",
		},
		["scarlet watch post"] = {
			name = "Atalaya Escarlata",
			short = "La Atalaya Escarlata monta guardia para proteger el acceso que el Monasterio Escarlata no puede defender por sí solo. El capitán Melrache está al mando aquí, y defiende el puesto contra cualquiera que pretenda atacar sin ser visto el flanco expuesto del monasterio.",
			full = "La Atalaya Escarlata monta guardia para proteger el acceso que el Monasterio Escarlata no puede defender por sí solo. El capitán Melrache está al mando aquí, y defiende el puesto contra cualquiera que pretenda atacar sin ser visto el flanco expuesto del monasterio.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Watch_Post",
		},
		["shadow grave"] = {
			name = "Sepulcro Sombrío",
			short = "El Sepulcro Sombrío se alza en lo alto de la pendiente, dentro de las tumbas de Camposanto, entre las montañas de Tirisfal. Un sendero desgastado baja serpenteando desde su entrada hasta Camposanto.",
			full = "El Sepulcro Sombrío se alza en lo alto de la pendiente, dentro de las tumbas de Camposanto, entre las montañas de Tirisfal. Un sendero desgastado baja serpenteando desde su entrada hasta Camposanto.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Grave",
		},
		["solliden farmstead"] = {
			name = "Hacienda Solliden",
			short = "Los campos de calabazas de Solliden son uno de los pocos trozos de tierra de Tirisfal donde la antigua vida no ha sido devorada por la peste ni por la no-muerte.",
			full = "Los campos de calabazas de Solliden son uno de los pocos trozos de tierra de Tirisfal donde la antigua vida no ha sido devorada por la peste ni por la no-muerte. Mientras la región a su alrededor ha caído ante la Plaga y luego ante los Renegados que surgieron de ella, los granjeros de aquí siguen trabajando sus hileras, protegidos bajo la vigilancia de la Cruzada Escarlata desde la cercana Empalizada Escarlata.\n\nEsa protección ha convertido a Solliden en una rareza. Los granjeros no confían en nadie que no sea Escarlata: rechazan a los Renegados como abominaciones de la peste que casi acabó con ellos, y también desconfían de la Alianza, cuyos estandartes podrían arrastrarlos a una guerra de la que hasta ahora se han librado por ser pequeños y estar olvidados.\n\nEs esa tranquilidad lo que los Renegados no pueden dejar en paz. El guardia de la muerte Simmer vigila Solliden no por lo que es ahora, sino por lo que podría llegar a ser: hoy, granjeros pacíficos; mañana, arrendatarios armados de la Alianza, un punto de apoyo en tierras que los Renegados pretenden conservar.",
			source = "https://warcraft.wiki.gg/wiki/Solliden_Farmstead",
		},
		["stillwater pond"] = {
			name = "Charca Aguaserena",
			short = "Antes de la peste, la Charca Aguaserena era un lugar donde los vivos podían ser jóvenes.",
			full = "Antes de la peste, la Charca Aguaserena era un lugar donde los vivos podían ser jóvenes. Las familias de los claros venían a comer al aire libre en sus orillas, y los niños demasiado pequeños para atreverse con las aguas más profundas del Lago Aguasclaras aprendían a nadar aquí.\n\nAhora esa agua es gris. Los peces bajo la superficie son solo huesos que siguen nadando, como si nadie les hubiera dicho que se detuvieran. No-muertos errantes y bestias salvajes recorren la orilla, y el can oscuro Bayne merodea al borde del agua, alimentándose de todo lo que sea lo bastante incauto como para quedarse.\n\nPara cuando los Renegados empezaron a levantar Rémol de sus ruinas, los guerreros Escarlata ya patrullaban la orilla de Aguaserena.",
			source = "https://warcraft.wiki.gg/wiki/Stillwater_Pond",
		},
		["terrace of repose"] = {
			name = "Bancal del Reposo",
			short = "Justo al norte del Monasterio Escarlata se extiende un terreno que la peste nunca ha tocado. Aquí crecen setos verdes, y una fuente mana agua clara en lugar de estancada, a diferencia del resto de los Claros de Tirisfal.",
			full = "Justo al norte del Monasterio Escarlata se extiende un terreno que la peste nunca ha tocado. Aquí crecen setos verdes, y una fuente mana agua clara en lugar de estancada, a diferencia del resto de los Claros de Tirisfal. La Cruzada Escarlata lo cuida y mantiene con vida esta pequeña terraza como prueba de que algo limpio aún puede perdurar en medio de la plaga.",
			source = "https://warcraft.wiki.gg/wiki/Terrace_of_Repose",
		},
		["venomweb vale"] = {
			name = "Vega Venerácnidas",
			short = "La Vega Venerácnidas fue verde en otro tiempo, llena de ciervos y conejos, antes de convertirse en lo que es ahora: un valle invadido por arañas venenosas, dirigidas por la rara y letal Sri'skulk, cuyas telarañas han sustituido a la hierba y han dado nombre a la vega.",
			full = "La Vega Venerácnidas fue verde en otro tiempo, llena de ciervos y conejos, antes de convertirse en lo que es ahora: un valle invadido por arañas venenosas, dirigidas por la rara y letal Sri'skulk, cuyas telarañas han sustituido a la hierba y han dado nombre a la vega. Los canes oscuros merodean por el norte, cerca del Campamento Escarlata, en manos del teniente Sanders.",
			source = "https://warcraft.wiki.gg/wiki/Venomweb_Vale",
		},
		["whispering gardens"] = {
			name = "Jardines de los Susurros",
			short = "En la colina al sur del Monasterio Escarlata se libró en otro tiempo una batalla entre los hombres que llegarían a ser la Cruzada Escarlata y una hueste de la Plaga.",
			full = "En la colina al sur del Monasterio Escarlata se libró en otro tiempo una batalla entre los hombres que llegarían a ser la Cruzada Escarlata y una hueste de la Plaga. Muchos cayeron en ambos bandos. Al anochecer, sus espíritus aún permanecen allí, murmurando como débiles susurros entre las piedras silenciosas del jardín.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Gardens",
		},
		["whispering shore"] = {
			name = "Costa Murmurante",
			short = "La Costa Murmurante se encuentra en el oeste de los Claros de Tirisfal, al norte de la Hacienda Solliden. Los pescadores apreciaban antes sus aguas tranquilas y su pesca constante.",
			full = "La Costa Murmurante se encuentra en el oeste de los Claros de Tirisfal, al norte de la Hacienda Solliden. Los pescadores apreciaban antes sus aguas tranquilas y su pesca constante.\n\nEsa abundancia desapareció. Los múrlocs han invadido la costa y caen sobre cualquiera que se acerque, y el agua se ha vuelto fría y oscura.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Shore",
		},
	},
	-- Bosque de Argénteos: 22 subzones
	[1421] = {
		["ambermill"] = {
			name = "Molino Ámbar",
			short = "Molino Ámbar fue en otro tiempo un pueblo maderero sin importancia que talaba árboles al suroeste del Lago Lordamere, en el Bosque de Argénteos.",
			full = "Molino Ámbar fue en otro tiempo un pueblo maderero sin importancia que talaba árboles al suroeste del Lago Lordamere, en el Bosque de Argénteos.\n\nLa Plaga y la Legión Ardiente cambiaron el valor del pueblo. El Kirin Tor de Dalaran, que se reconstruía tras su propia ruina, ocupó el pueblo, y durante un tiempo Molino Ámbar se convirtió en algo que nunca había sido: un foco de verdadera resistencia humana en el Bosque de Argénteos, sostenido por la hechicería de Dalaran.\n\nLos Renegados no han dejado eso sin vigilancia. Sus mortacechadores han sabido, gracias a un prisionero, que los magos guardan allí documentos relacionados con la situación de la propia Dalaran. Los molinos, los establos y el ayuntamiento siguen en manos del Kirin Tor, mientras los espías actúan contra ellos desde las sombras del bosque.",
			source = "https://warcraft.wiki.gg/wiki/Ambermill",
		},
		["berens peril"] = {
			name = "El Desafío de Beren",
			short = "En las colinas al suroeste de Molino Ámbar se encuentra El Desafío de Beren.",
			full = "En las colinas al suroeste de Molino Ámbar se encuentra El Desafío de Beren. Años después de la Tercera Guerra, los exploradores Renegados informaron al sacerdote de las sombras Allister de que los no-muertos se habían reunido allí en secreto, concentrándose para atacar El Sepulcro. Los no-muertos servían al nigromante Thule Corvozarpa, que había elegido el lugar para reunir a sus sirvientes sin ser visto, lo bastante cerca para amenazar El Sepulcro y lo bastante lejos del camino para pasar desapercibido.",
			source = "https://warcraft.wiki.gg/wiki/Beren's_Peril",
		},
		["dawning isles"] = {
			name = "Islas del Alba",
			short = "Las Islas del Alba se alzaban antaño suaves y bajas sobre las aguas cristalinas del Lago Lordamere, cayos tranquilos a los que no llegaban los problemas. La Peste de la no-muerte cambió eso.",
			full = "Las Islas del Alba se alzaban antaño suaves y bajas sobre las aguas cristalinas del Lago Lordamere, cayos tranquilos a los que no llegaban los problemas. La Peste de la no-muerte cambió eso. Sus árboles enfermaron, y los múrlocs y las bestias del pantano invadieron los islotes. Las bestias del pantano ya no están, pero los múrlocs Anca Vil se reprodujeron sin control y ahora dominan por completo las islas.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Isles",
		},
		["dead field"] = {
			name = "El Campo Muerto",
			short = "El Campo Muerto yace abandonado en el norte del Bosque de Argénteos, con sus campos podridos y sus antiguos ocupantes olvidados.",
			full = "El Campo Muerto yace abandonado en el norte del Bosque de Argénteos, con sus campos podridos y sus antiguos ocupantes olvidados. Lo que se sabe es quién lo ha reclamado desde entonces: los gnolls Putrepellejo, al servicio de la Plaga, que han convertido la granja en ruinas en su base, y su número crece de una manera que sugiere que aquí todavía se prepara algún asalto.\n\nLos Renegados han atacado la granja más de una vez, con la esperanza de derrotar a los gnolls antes de que puedan actuar. Todos los intentos han fracasado. Cada vez que los Putrepellejo se ven amenazados, un alma en pena responde a su llamada: un espíritu llamado Latipesadilla que manda a los gnolls como si fueran suyos y aparece de la nada para defenderlos.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Field",
		},
		["decrepit ferry"] = {
			name = "El Viejo Embarcadero",
			short = "El Viejo Embarcadero llevaba antaño el comercio hasta la Isla de Fenris, donde un señor y su familia tenían su mansión, y pagaban al barquero unas pocas monedas por viaje.",
			full = "El Viejo Embarcadero llevaba antaño el comercio hasta la Isla de Fenris, donde un señor y su familia tenían su mansión, y pagaban al barquero unas pocas monedas por viaje.\n\nEntonces la Plaga cayó sobre Lordaeron. El barquero murió allí mismo, en su trabajo, y su transbordador quedó destrozado.\n\nAhora necrófagos, guerreros esqueléticos y gnolls Putrepellejo rondan los muelles en ruinas, y el paso está abandonado, peligroso para cualquiera que no sea fuerte.",
			source = "https://warcraft.wiki.gg/wiki/Decrepit_Ferry",
		},
		["deep elem mine"] = {
			name = "Mina de Elem",
			short = "La Mina de Elem se encuentra en el Bosque de Argénteos. Arugal dejó que su magia se extendiera por ella, y los huargen convirtieron la mina en su guarida, dirigidos por Grimson el Pálido, que fue su capataz.",
			full = "La Mina de Elem se encuentra en el Bosque de Argénteos. Arugal dejó que su magia se extendiera por ella, y los huargen convirtieron la mina en su guarida, dirigidos por Grimson el Pálido, que fue su capataz.\n\nDalar Tejealba buscaba la muerte de Grimson para que los Renegados pudieran reclamar la mina como un recurso propio, en nombre de Varimathras.",
			source = "https://warcraft.wiki.gg/wiki/Deep_Elem_Mine",
		},
		["fenris isle"] = {
			name = "Isla de Fenris",
			short = "La Isla de Fenris se encuentra en medio del Lago Lordamere, una pieza de un anillo roto de tierra firme que comparte con las Islas del Alba, y se considera, de manera aproximada, parte del Bosque de Argénteos.",
			full = "La Isla de Fenris se encuentra en medio del Lago Lordamere, una pieza de un anillo roto de tierra firme que comparte con las Islas del Alba, y se considera, de manera aproximada, parte del Bosque de Argénteos.\n\nAntes de la Tercera Guerra, la isla albergaba el Castillo de Fenris, un puesto militar de Lordaeron. Cuando la Plaga arrasó la tierra, el castillo cayó. Su gente huyó o murió allí mismo, y la isla quedó vacía.\n\nEn ese vacío llegaron los gnolls Putrepellejo, que tomaron el castillo abandonado como guarida. Su amo era Thule Corvozarpa, recordado como traicionero incluso entre los gnolls, que gobierna a los Putrepellejo y, a través de ellos, toda la Isla de Fenris, y que controla el castillo que reclamó y, además, el cercano Viejo Embarcadero.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Isle",
		},
		["fenris keep"] = {
			name = "Castillo de Fenris",
			short = "El Castillo de Fenris se alza en el centro del Lago Lordamere, sobre la Isla de Fenris, en el Bosque de Argénteos, y en otro tiempo albergó a una parte considerable del ejército de Lordaeron.",
			full = "El Castillo de Fenris se alza en el centro del Lago Lordamere, sobre la Isla de Fenris, en el Bosque de Argénteos, y en otro tiempo albergó a una parte considerable del ejército de Lordaeron.\n\nCuando la Plaga arrasó la tierra, el castillo cayó con ella. Entre sus ruinas llegó Thule Corvozarpa, un joven mago que había pertenecido al Kirin Tor, se unió a la Plaga y sometió a su voluntad a los gnolls de la isla, convirtiéndolos en los Putrepellejo. Con esa tribu a sus espaldas, se hizo amo del Castillo de Fenris, y los Putrepellejo caen sobre cualquiera que se acerque a su amo.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Keep",
		},
		["greymane wall"] = {
			name = "La Muralla de Cringris",
			short = "El rey Genn Cringris levantó su muralla antes de la Tercera Guerra, harto del oro de Gilneas gastado en los campos de reclusión de orcos y agotado por las disputas que dividían a los reyes de la Alianza de Lordaeron.",
			full = "El rey Genn Cringris levantó su muralla antes de la Tercera Guerra, harto del oro de Gilneas gastado en los campos de reclusión de orcos y agotado por las disputas que dividían a los reyes de la Alianza de Lordaeron. Encerró a su reino en sí mismo y aisló Gilneas de Lordaeron y del mundo más allá de las montañas.\n\nLa muralla resistió la Peste de la no-muerte, pero a un precio. Mientras la Plaga arrasaba Lordaeron, los refugiados huyeron al sur y acamparon frente a las puertas, y durante años las puertas no se abrieron. Los refugiados murieron allí, sin respuesta.",
			source = "https://warcraft.wiki.gg/wiki/Greymane_Wall",
		},
		["ivar patch"] = {
			name = "Los Dominios de Ivar",
			short = "Los Dominios de Ivar fueron en otro tiempo una granja que valía la pena tener, con hileras cargadas de calabazas y una casa llena de peones que trabajaban los campos para un hombre llamado Ivar.",
			full = "Los Dominios de Ivar fueron en otro tiempo una granja que valía la pena tener, con hileras cargadas de calabazas y una casa llena de peones que trabajaban los campos para un hombre llamado Ivar. Era un buen sustento, hasta que la Peste de la no-muerte cayó sobre Lordaeron y se lo arrebató.\n\nIvar no se limitó a morir. Se alzó, y también su familia, y también todos los peones que habían trabajado su tierra, convertidos en necrófagos putrefactos que ahora atacan a cualquiera que se acerque. El propio Ivar se alzó como algo peor, y hoy se le recuerda como Ivar el Hediondo.\n\nTres mortacechadores enviados al norte para evaluar el peligro fueron sorprendidos aquí por los necrófagos, e Ivar el Hediondo hirió a uno de ellos, Quinn Yorick, antes de que Quinn y su pariente Rane se atrincheraran dentro de la vieja casa de Ivar.",
			source = "https://warcraft.wiki.gg/wiki/Ivar_Patch",
		},
		["lordamere lake"] = {
			name = "Lago Lordamere",
			short = "El Lago Lordamere se extiende bajo la sombra de reinos que alguna vez tuvieron su hogar en sus orillas.",
			full = "El Lago Lordamere se extiende bajo la sombra de reinos que alguna vez tuvieron su hogar en sus orillas. Lordaeron se alzó en su orilla norte, y es muy probable que el lago tomara su nombre de aquella gran ciudad, que a su vez debía el suyo al viejo Lordain. Dalaran y Alterac también prosperaron alrededor de sus aguas en los días en que la Alianza de Lordaeron unía a los reinos humanos.\n\nAquella época terminó, y lo que queda es una frontera. El lago se encuentra ahora entre los dominios Renegados de los Claros de Tirisfal y del Bosque de Argénteos y las disputadas Montañas de Alterac, separando a los muertos de los vivos.\n\nEn su centro se encuentra la Isla de Fenris, cuyo castillo está en manos de los gnolls Putrepellejo bajo el mando de Thule Corvozarpa.\n\nAl este de la Isla de Fenris, entre las pequeñas Islas del Alba, los múrlocs Anca Vil han impuesto su dominio y las han invadido por completo.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Lake",
		},
		["maldens orchard"] = {
			name = "Huerta de Malden",
			short = "Los árboles de la Huerta de Malden se han vuelto oscuros y perennes, con sus frutos colgando sin recoger temporada tras temporada. El propio Malden se fue hace mucho, expulsado de su hogar cuando la Plaga cayó sobre Lordaeron.",
			full = "Los árboles de la Huerta de Malden se han vuelto oscuros y perennes, con sus frutos colgando sin recoger temporada tras temporada. El propio Malden se fue hace mucho, expulsado de su hogar cuando la Plaga cayó sobre Lordaeron.\n\nAhora la huerta pertenece a los huargos, que tienen sus guaridas en gran número entre los árboles y alrededor de la única cabaña pequeña que sigue en pie. Fue ahí donde entró el mortacechador Erland McKree, enviado a explorar la huerta durante un reconocimiento del norte del bosque. Los huargos lo acorralaron antes de que avanzara mucho, y se atrincheró dentro de la cabaña abandonada, donde quedó atrapado durante días, hasta que otros agentes Renegados lo ayudaron a escapar y volver con sus compañeros, que lo esperaban.",
			source = "https://warcraft.wiki.gg/wiki/Malden's_Orchard",
		},
		["north tides hollow"] = {
			name = "Cuenca Mareanorte",
			short = "La Cuenca Mareanorte se encuentra justo al norte de El Sepulcro, en el Bosque de Argénteos. Es una de las muchas guaridas de los huargen Furia Lunar, sirvientes del archimago Arugal.",
			full = "La Cuenca Mareanorte se encuentra justo al norte de El Sepulcro, en el Bosque de Argénteos. Es una de las muchas guaridas de los huargen Furia Lunar, sirvientes del archimago Arugal. Aquí levantan campamentos toscos, sin nada más que lo mínimo e indispensable para sobrevivir, refugio suficiente para criaturas que viven de sus dientes y su fuerza.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Hollow",
		},
		["north tides run"] = {
			name = "Cala Mareanorte",
			short = "La costa noroeste del Bosque de Argénteos, donde la playa se une al frío Mare Magnum, lleva el nombre de Cala Mareanorte.",
			full = "La costa noroeste del Bosque de Argénteos, donde la playa se une al frío Mare Magnum, lleva el nombre de Cala Mareanorte. Medio hundido en las aguas poco profundas yace un barco roto de la Horda, con el casco asentado en el oleaje, la señal más destacada de este tramo de costa.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Run",
		},
		["olsens farthing"] = {
			name = "Finca de Olsen",
			short = "La Finca de Olsen se alzaba antaño al borde de las rutas comerciales que atravesaban el Bosque de Argénteos, una granja en funcionamiento cuyos campos alimentaban al tráfico que pasaba por allí.",
			full = "La Finca de Olsen se alzaba antaño al borde de las rutas comerciales que atravesaban el Bosque de Argénteos, una granja en funcionamiento cuyos campos alimentaban al tráfico que pasaba por allí.\n\nLa Tercera Guerra acabó con eso. En pocos años, la granja quedó en ruinas.",
			source = "https://warcraft.wiki.gg/wiki/Olsen's_Farthing",
		},
		["pyrewood village"] = {
			name = "Aldea Piroleña",
			short = "La Aldea Piroleña se encuentra en el límite del Bosque de Argénteos, un grupo apiñado de humanos que sobrevivieron a la primera llegada de la Plaga durante la Tercera Guerra.",
			full = "La Aldea Piroleña se encuentra en el límite del Bosque de Argénteos, un grupo apiñado de humanos que sobrevivieron a la primera llegada de la Plaga durante la Tercera Guerra. Al norte se alza un castillo que antes pertenecía al barón Filargenta, custodiado por el paladín comandante Springvale y la Mano de Plata. Filargenta y sus hombres fueron masacrados por los huargen del archimago Arugal, que se apoderó del castillo y lo rebautizó como Castillo de Colmillo Oscuro. Desde allí, Arugal volvió su locura contra la propia Piroleña y maldijo a su gente para que cada noche se convierta en huargen Furia Lunar babeantes, que despedazan a cualquiera que se cruce en su camino, solo para despertar de nuevo como humanos al amanecer.\n\nA pesar de ello, la aldea sigue abriendo sus puertas a los viajeros durante el día, y su gente sigue atada a la maldición que Arugal les impuso, sin que se vea un final.",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Village",
		},
		["sepulcher"] = {
			name = "El Sepulcro",
			short = "El Sepulcro se encuentra sobre la costa de Lordaeron, en las colinas occidentales del Bosque de Argénteos, donde un camino atravesaba antes un sencillo cementerio cuyas criptas no señalaban nada más que un lugar de descanso para los muertos.",
			full = "El Sepulcro se encuentra sobre la costa de Lordaeron, en las colinas occidentales del Bosque de Argénteos, donde un camino atravesaba antes un sencillo cementerio cuyas criptas no señalaban nada más que un lugar de descanso para los muertos.\n\nDespués de la Tercera Guerra, los Renegados tomaron el viejo cementerio y lo convirtieron en una base de operaciones, transformando un lugar construido para los muertos en uno al servicio de los no-muertos.\n\nLa decisión nació de la necesidad. Los huargen merodeaban por el sur, la Plaga aún dominaba terreno al este y el Kirin Tor vigilaba desde el sureste. Rodeados casi por todos lados, los Renegados encontraron en El Sepulcro uno de los pocos lugares de Argénteos donde la Horda podía estar a salvo.",
			source = "https://warcraft.wiki.gg/wiki/Sepulcher",
		},
		["shadowfang keep"] = {
			name = "Castillo de Colmillo Oscuro",
			short = "El Castillo de Colmillo Oscuro se alza sobre un alto risco que domina la Aldea Piroleña. Perteneció en otro tiempo al barón Filargenta, un señor de Gilneas, hasta que la Plaga cayó sobre Lordaeron y el archimago real Arugal buscó la manera de detenerla.",
			full = "El Castillo de Colmillo Oscuro se alza sobre un alto risco que domina la Aldea Piroleña. Perteneció en otro tiempo al barón Filargenta, un señor de Gilneas, hasta que la Plaga cayó sobre Lordaeron y el archimago real Arugal buscó la manera de detenerla. Basándose en las investigaciones del mago Ur, y con la bendición del rey Genn Cringris pero en contra del consejo del Kirin Tor, Arugal invocó a los huargen. Estos hicieron retroceder la marea de no-muertos, y luego se volvieron contra la propia Gilneas, destrozando la Muralla de Cringris antes de correr libres por Argénteos. Cayeron sobre el castillo y mataron al barón Filargenta y a toda su casa.\n\nArugal, destrozado por lo que había desatado, no huyó de ello. Llamó a los huargen sus hijos, se apoderó del castillo y lo rebautizó como Colmillo Oscuro. En comunión con un amo al que servía en el Culto del Lobo, extendió la maldición por el bosque, hasta que la propia Aldea Piroleña quedó transformada: su gente era humana de día y bestias de noche, gobernada por un consejo que solo respondía ante él.",
			source = "https://warcraft.wiki.gg/wiki/Shadowfang_Keep",
		},
		["shining strand"] = {
			name = "La Playa Plateada",
			short = "La Playa Plateada se extiende a lo largo del Lago Lordamere, desde la capital de Lordaeron en el norte hasta las escarpadas colinas que separan el Bosque de Argénteos de las Montañas de Alterac.",
			full = "La Playa Plateada se extiende a lo largo del Lago Lordamere, desde la capital de Lordaeron en el norte hasta las escarpadas colinas que separan el Bosque de Argénteos de las Montañas de Alterac.\n\nLa tribu de múrlocs Anca Vil ha llenado la playa de asentamientos, y los viajeros que no conocen la orilla han aprendido a temerla. El difunto boticario Berard escribió en su diario sobre un objeto raro que podía obtenerse de los Anca Vil, un tumor endurecido, y especuló que podría servir para crear una nueva peste.",
			source = "https://warcraft.wiki.gg/wiki/Shining_Strand",
		},
		["skittering dark"] = {
			name = "Penumbra de las Celerácnidas",
			short = "La mina conocida como la Oscuridad Correteante ha sido reclamada por las arañas Skitterweb, cuyas telarañas cubren vigas rotas y herramientas oxidadas.",
			full = "La mina conocida como la Oscuridad Correteante ha sido reclamada por las arañas Skitterweb, cuyas telarañas cubren vigas rotas y herramientas oxidadas. En lo más profundo se oculta la matriarca Skitterweb, una araña que ha crecido hasta volverse monstruosa y que gobierna el enjambre desde una oscuridad que nunca abandona. Afuera, la rara Krethis la Tejesombras acecha a veces sola entre las rocas.\n\nEl suelo está sembrado de capullos que envuelven a huargen, huargos y osos, además de orcos arrastrados desde un naufragio en la costa, al oeste.",
			source = "https://warcraft.wiki.gg/wiki/Skittering_Dark",
		},
		["south tides run"] = {
			name = "Cala Mareasur",
			short = "La Cala Mareasur se extiende a lo largo de la costa suroeste del Bosque de Argénteos, donde la tierra se une al Mare Magnum.",
			full = "La Cala Mareasur se extiende a lo largo de la costa suroeste del Bosque de Argénteos, donde la tierra se une al Mare Magnum.",
			source = "https://warcraft.wiki.gg/wiki/South_Tide's_Run",
		},
		["valgans field"] = {
			name = "Campo de Valgan",
			short = "El Campo de Valgan se encuentra entre las granjas desoladas del norte del Bosque de Argénteos, al oeste de la Playa Plateada y al norte de un pequeño río.",
			full = "El Campo de Valgan se encuentra entre las granjas desoladas del norte del Bosque de Argénteos, al oeste de la Playa Plateada y al norte de un pequeño río. Debe su nombre a un granjero que murió o fue expulsado de la tierra cuando la Plaga arrasó Argénteos. En sus mejores días, la granja tenía vistas al Lago Lordamere, un paisaje digno de la fama que tuvo alguna vez.\n\nAhora la granja está vacía, una ruina de lo que fue, aunque de vez en cuando puede verse a Latipesadilla rondando el lugar.",
			source = "https://warcraft.wiki.gg/wiki/Valgan's_Field",
		},
	},
	-- Tierras de la Peste del Oeste: 18 subzones
	[1422] = {
		["bulwark"] = {
			name = "El Baluarte",
			short = "El Baluarte se alza donde los Claros de Tirisfal se unen a las Tierras de la Peste del Oeste, la línea que los Renegados defienden contra la Plaga, que todavía se concentra al este.",
			full = "El Baluarte se alza donde los Claros de Tirisfal se unen a las Tierras de la Peste del Oeste, la línea que los Renegados defienden contra la Plaga, que todavía se concentra al este. Aquí, los defensores Renegados y El Alba Argenta han dejado de lado sus diferencias frente a ese enemigo común, vigilando juntos la frontera y enviando combatientes hacia el este para atacar a los esbirros del Rey Exánime.\n\nA diferencia del resto de Tirisfal, este tramo no se parece en absoluto a los Claros. Una niebla de peste flota sobre él y tiñe el cielo del mismo gris amarillento y enfermizo que el de las Tierras de la Peste del Oeste que se extienden más allá.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["caer darrow"] = {
			name = "Castel Darrow",
			short = "En la isla del Lago Darrowmere se alzaba una fortaleza levantada por manos humanas hace mucho tiempo, que albergaba una antigua piedra rúnica de los altos elfos.",
			full = "En la isla del Lago Darrowmere se alzaba una fortaleza levantada por manos humanas hace mucho tiempo, que albergaba una antigua piedra rúnica de los altos elfos. Durante la Segunda Guerra, la Horda invadió la isla y saqueó el castillo, y despedazó la piedra rúnica para forjar los Altares de la Tempestad, a través de los cuales Gul'dan infundió magia en los ogros de su Horda.\n\nEl castillo fue reconstruido y se convirtió en la sede de la Casa Barov. A medida que los años se encaminaban hacia la guerra, los Barov temieron perder lo que habían construido durante décadas, y cerraron un trato con Kel'Thuzad, señor del Culto de los Malditos. Bajo la mansión, las catacumbas se convirtieron en Scholomance, una escuela de nigromancia, y los propios sirvientes de la familia fueron entregados como sujetos para una peste de no-muerte. En medio año, la enfermedad se desató y mató a todos los habitantes de la isla. Sus víctimas no se limitaron a morir: se alzaron como fantasmas, condenados a revivir sus últimos momentos, y todavía hoy recorren los salones en ruinas de Castel Darrow.",
			source = "https://warcraft.wiki.gg/wiki/Caer_Darrow",
		},
		["chillwind camp"] = {
			name = "Campamento del Orvallo",
			short = "El Campamento del Orvallo se encuentra en la puerta sur de las Tierras de la Peste del Oeste, donde las montañas de Alterac dan paso a la tierra envenenada. Es el último lugar donde un viajero de la Alianza puede detenerse y seguir llamando limpia a la tierra.",
			full = "El Campamento del Orvallo se encuentra en la puerta sur de las Tierras de la Peste del Oeste, donde las montañas de Alterac dan paso a la tierra envenenada. Es el último lugar donde un viajero de la Alianza puede detenerse y seguir llamando limpia a la tierra.\n\nLo ocupa un pequeño contingente de El Alba Argenta, con apenas un puñado de tropas y especialistas. Lo que al campamento le falta en número lo compensa con audacia: su gente libra una guerra de guerrillas contra el bastión de la Plaga en Andorhal y contra los calderos de la peste que siembran la muerte en la tierra, y depende de mercenarios dispuestos a golpear y desaparecer en lugar de defender un terreno que no pueden conservar.\n\nLord Grisillo Quiebrasombras envió aquí a prometedores jóvenes Caballeros de la Mano de Plata para que se unieran al comandante Ashlam Puñovalor contra la Plaga en la región.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Camp",
		},
		["dalsons tears"] = {
			name = "Lágrimas de Dalson",
			short = "La Huerta de Dalson dio fruto en otro tiempo para una familia que le dio su nombre. Ahora los árboles se alzan en las Tierras de la Peste del Oeste bajo un nombre que recuerda el dolor en lugar de la cosecha: Lágrimas de Dalson.",
			full = "La Huerta de Dalson dio fruto en otro tiempo para una familia que le dio su nombre. Ahora los árboles se alzan en las Tierras de la Peste del Oeste bajo un nombre que recuerda el dolor en lugar de la cosecha: Lágrimas de Dalson.\n\nLa Plaga se apoderó de la granja y la convirtió en una herida en la tierra. En su centro colocaron un gran caldero que no ha parado desde entonces, escupiendo enfermedad al aire, custodiado por el señor del caldero Malvinious y los muertos infectados que le sirven.\n\nLos Dalson nunca se marcharon. La señora Dalson aún recorre la propiedad, un esqueleto errante que deambula por la tierra que cuidaba cuando era mujer. Su marido no murió a su lado. Lo encerraron en la letrina y lo dejaron allí, y en lo que se convirtió en aquella oscuridad cerrada ya no era un hombre, sino un necrófago.",
			source = "https://warcraft.wiki.gg/wiki/Dalson's_Tears",
		},
		["darrowmere lake"] = {
			name = "Lago Darrowmere",
			short = "Las aguas de Darrowmere aún guardan el recuerdo de la Segunda Guerra, cuando el lago estaba lleno de velas.",
			full = "Las aguas de Darrowmere aún guardan el recuerdo de la Segunda Guerra, cuando el lago estaba lleno de velas. La mayoría de los barcos que anclaron aquí llevaban los colores de la flota Valiente, y antes del incendio de Quel'Thalas, el almirante general envió varios de ellos a través de estas aguas para llevar a Turalyon, Alleria Brisaveloz y su ejército hacia Stratholme. Turalyon consideró seguir navegando hasta la propia Quel'Thalas, pero Alleria le advirtió que los elfos jamás permitirían que barcos humanos remontaran su río, y así la flota puso rumbo a Stratholme. Fue en esta misma guerra cuando Zul'jin y su banda fueron obligados a retroceder hasta las orillas del lago y el caudillo trol fue capturado.\n\nEn el centro del lago se alza el pueblo isleño de Castel Darrow, ahora vacío, que antes pertenecía a la Casa Barov. Bajo las piedras del pueblo yace Scholomance, donde el Culto de los Malditos trabaja entre sus no-muertos, una oscuridad que reposa bajo la quietud anegada de la isla.",
			source = "https://warcraft.wiki.gg/wiki/Darrowmere_Lake",
		},
		["felstone field"] = {
			name = "Campo de Piedramácula",
			short = "El Campo de Piedramácula alimentó en otro tiempo a los vivos. Eso terminó cuando la Plaga llegó y no permitió que volviera a ser una granja.",
			full = "El Campo de Piedramácula alimentó en otro tiempo a los vivos. Eso terminó cuando la Plaga llegó y no permitió que volviera a ser una granja.\n\nEn el corazón del campo, la Plaga colocó un gran caldero que no ha dejado de trabajar desde entonces. De él brota vapor sin pausa, cargado de enfermedad. El señor del caldero Bilemaw lo custodia, con hechiceros esqueléticos, desolladores esqueléticos y necrófagos babeantes a su lado, para que nada vivo pueda acercarse y salir limpio.\n\nEn la esquina noreste aún se alza la vieja casa, y Janice Piedra Mácula sigue allí, rondando la tierra que antes daba las cosechas de su familia.",
			source = "https://warcraft.wiki.gg/wiki/Felstone_Field",
		},
		["gahrrons withering"] = {
			name = "Gangrena de Gahrron",
			short = "La granja del extremo oriental de las Tierras de la Peste del Oeste perteneció en otro tiempo a Del Gahrron, y en sus mejores días se la conocía como el Renacer de Gahrron, un lugar de siembra y crecimiento.",
			full = "La granja del extremo oriental de las Tierras de la Peste del Oeste perteneció en otro tiempo a Del Gahrron, y en sus mejores días se la conocía como el Renacer de Gahrron, un lugar de siembra y crecimiento. Ahora allí no crece nada. La Plaga se apoderó de los campos y colocó un gran caldero en su centro, y el caldero nunca deja de trabajar, escupiendo al aire un vapor cargado de enfermedad hasta que el propio suelo parece enfermar. El señor del caldero Soulwrath lo custodia junto con otros oficiales de la Plaga, y los vapores han despertado cosas que no deberían caminar: visiones inquietantes que flotan entre las hileras en ruinas, muertes lastimeras y espectros hambrientos que no responden ante más amo que su hambre.",
			source = "https://warcraft.wiki.gg/wiki/Gahrron's_Withering",
		},
		["hearthglen"] = {
			name = "Vega del Amparo",
			short = "Vega del Amparo se alza al norte de Andorhal, con sus murallas cerradas alrededor de un castillo, una torre de magos, un molino y una mina, la viva imagen del orden en una región arruinada.",
			full = "Vega del Amparo se alza al norte de Andorhal, con sus murallas cerradas alrededor de un castillo, una torre de magos, un molino y una mina, la viva imagen del orden en una región arruinada. Durante años mantuvo ese orden bajo el mando de Tirion Vadín, señor de Mardenholde, hasta que este ayudó al orco Eitrigg y fue desterrado por traición. Con el tiempo, su hijo Taelan ocupó su lugar como señor de Mardenholde.\n\nMás tarde, Vega del Amparo dio refugio a los restos de la Orden de la Mano de Plata, que aceptaron la oferta de asilo de Taelan tras la caída de la Ciudad Capital. Desde sus murallas, los paladines obtuvieron victorias en los años siguientes, hasta que la orden se corrompió y se convirtió en la Cruzada Escarlata, que tomó el pueblo para sí.",
			source = "https://warcraft.wiki.gg/wiki/Hearthglen",
		},
		["mardenholde keep"] = {
			name = "Fortaleza de Mardenholde",
			short = "La Fortaleza de Mardenholde se alza en el corazón de Vega del Amparo desde antes de lo que recuerdan la mayoría de quienes recorren sus salones, y sus muros permanecieron intactos incluso en los días más oscuros de la invasión orca de Lordaeron.",
			full = "La Fortaleza de Mardenholde se alza en el corazón de Vega del Amparo desde antes de lo que recuerdan la mayoría de quienes recorren sus salones, y sus muros permanecieron intactos incluso en los días más oscuros de la invasión orca de Lordaeron. Durante años fue la sede de Tirion Vadín, y allí, en una sala de consejo presidida por una gran mesa de roble y un mapa que representaba Vega del Amparo hasta su camino más pequeño, el paladín se reunía con sus consejeros para tratar los asuntos del reino. Acusado de traición por ayudar al orco Eitrigg, Tirion fue excomulgado y desterrado, y con el tiempo Mardenholde pasó a su propio hijo, Taelan.\n\nTras la Purga de Lordaeron, Taelan dio un hogar en Vega del Amparo a los Caballeros de la Mano de Plata que habían sobrevivido. Entre estos muros llegó la noticia de que Alexandros Mograine había muerto, y la sospecha de traición dividió a la orden: Maxwell Neófitus se llevó a sus seguidores para fundar El Alba Argenta, mientras que quienes se quedaron adoptaron el nombre de Cruzada Escarlata, y Mardenholde se convirtió en su bastión, con Taelan elevado a alto señor.",
			source = "https://warcraft.wiki.gg/wiki/Mardenholde_Keep",
		},
		["northridge lumber camp"] = {
			name = "Aserradero Crestanorte",
			short = "El Aserradero Crestanorte se encuentra en el norte de las Tierras de la Peste del Oeste, cerca de Vega del Amparo, con sus laderas desnudas por la tala de la Cruzada Escarlata.",
			full = "El Aserradero Crestanorte se encuentra en el norte de las Tierras de la Peste del Oeste, cerca de Vega del Amparo, con sus laderas desnudas por la tala de la Cruzada Escarlata. La Cruzada explota el aserradero para obtener madera, un suministro que tanto la Alianza como la Horda tienen motivos para querer ver arruinado.\n\nAntes de la Tercera Guerra, el aserradero pertenecía a la familia de Nathaniel Dumah, que trabajó la tierra hasta que la guerra y la peste la expulsaron. La familia de Mickey Levine también trabajó aquí en otro tiempo.",
			source = "https://warcraft.wiki.gg/wiki/Northridge_Lumber_Camp",
		},
		["ruins of andorhal"] = {
			name = "Ruinas de Andorhal",
			short = "Andorhal yace en ruinas en el corazón de las Tierras de la Peste del Oeste, con sus casas destrozadas y esparcidas por el terreno abierto.",
			full = "Andorhal yace en ruinas en el corazón de las Tierras de la Peste del Oeste, con sus casas destrozadas y esparcidas por el terreno abierto. Lo que queda está en manos de Araj el Invocador, un exánime de considerable poder, y de los muertos que le sirven: necrófagos que se arrastran entre las piedras caídas, esqueletos que montan guardia donde antes lo hacían los guardias, almas en pena cuyos gritos resuenan sobre las ruinas y abominaciones que avanzan pesadamente entre los restos de las casas.\n\nAraj permanece en el centro de todo, presidiendo una ciudad que nunca volvió a levantarse.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Andorhal",
		},
		["scholomance"] = {
			name = "Scholomance",
			short = "Sobre una elevación que domina la ciudad abandonada de Castel Darrow se alza la mansión que fue antaño la sede de la Casa Barov, una familia cuyo alcance se extendía desde Castel Darrow hasta Rémol, Costasur y el Molino Tarren.",
			full = "Sobre una elevación que domina la ciudad abandonada de Castel Darrow se alza la mansión que fue antaño la sede de la Casa Barov, una familia cuyo alcance se extendía desde Castel Darrow hasta Rémol, Costasur y el Molino Tarren. Durante décadas gobernaron con comodidad, pero a medida que los años se encaminaban hacia la guerra, los Barov se volvieron amargados y codiciosos, sin querer que la muerte acabara con lo que habían construido. Así que cerraron un trato con Kel'Thuzad, señor del Culto de los Malditos, para conservar su fortuna y sus tierras más allá del tiempo de una vida mortal.\n\nEn seis meses, el castillo se había podrido hasta convertirse en algo completamente distinto. Los acólitos del Culto estudiaban el arte del nigromante mientras los propios sirvientes de la familia eran entregados como experimentos vivientes para una peste de no-muerte. Antes de que Uther el Iluminado pudiera realizar una visita programada a la mansión, una enfermedad engendrada en sus salones se desató sobre la propia Castel Darrow. No dejó a nadie con vida, y condenó a sus víctimas a vagar después como fantasmas.\n\nLos propios Barov se alzaron de nuevo como no-muertos, todavía atados a los salones que habían vendido. Ahora el nigromante mortal, el maestro oscuro Gandling, ejerce como director, tras suceder a Araj el Invocador, quien a su vez había sucedido a Kel'Thuzad.",
			source = "https://warcraft.wiki.gg/wiki/Scholomance",
		},
		["sorrow hill"] = {
			name = "Colina de las Penas",
			short = "La Colina de las Penas sirvió a Andorhal en tiempos más apacibles como lugar para los muertos del pueblo, ricos y pobres por igual, enterrados bajo criptas y lápidas sencillas.",
			full = "La Colina de las Penas sirvió a Andorhal en tiempos más apacibles como lugar para los muertos del pueblo, ricos y pobres por igual, enterrados bajo criptas y lápidas sencillas. Esa paz terminó cuando llegó la Peste de la no-muerte. Mientras la Plaga se lanzaba una y otra vez contra Andorhal, la colina se llenó más rápido de lo que podía contener: tumbas apresuradas y sin nombre todavía marcan el suelo donde cayeron los defensores. Con el tiempo, los supervivientes dejaron por completo de enterrar a sus muertos, temerosos de que la peste alzara a sus seres queridos contra ellos, y cavaron una fosa común al sur del cementerio para quemar los cuerpos.\n\nEl último acto del pueblo fue el más triste. Cuando Arthas abatió a lord Uther, los habitantes que quedaban en Andorhal levantaron una gran tumba en lo alto de la colina y depositaron en ella el cuerpo destrozado del paladín antes de abandonar su hogar para siempre. Algunos dicen que la colina debe su nombre solo a esa tumba.\n\nLos calderos de la peste cercanos no perdonaron a los propios muertos de la colina. Soldados y vecinos se alzaron de sus parcelas y montan guardia sobre las tumbas que antes ocuparon.",
			source = "https://warcraft.wiki.gg/wiki/Sorrow_Hill",
		},
		["thondroril river"] = {
			name = "Río Thondroril",
			short = "El Río Thondroril separa las Tierras de la Peste del Oeste de las del Este. Nace muy al norte, cerca del Túnel Terroarácnido, y fluye hacia el sur hasta desembocar en el Lago Darrowmere, y continúa más allá como el río Darrowmere.",
			full = "El Río Thondroril separa las Tierras de la Peste del Oeste de las del Este. Nace muy al norte, cerca del Túnel Terroarácnido, y fluye hacia el sur hasta desembocar en el Lago Darrowmere, y continúa más allá como el río Darrowmere.\n\nSus orillas pertenecen a la plaga. Gusanos y murciélagos vampiro abarrotan el suelo húmedo, osos de la peste y arañas acechan en las aguas poco profundas, y las quijafortes se esconden donde la corriente se calma.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["uthers tomb"] = {
			name = "Tumba de Uther",
			short = "La Tumba de Uther se alza en la Colina de las Penas, el único lugar de las Tierras de la Peste del Oeste donde la Luz aún resiste frente a la agonía de la tierra.",
			full = "La Tumba de Uther se alza en la Colina de las Penas, el único lugar de las Tierras de la Peste del Oeste donde la Luz aún resiste frente a la agonía de la tierra.\n\nUther el Iluminado defendió en otro tiempo Andorhal contra la Plaga, junto al sabio Truthbearer y a Ballador el Brillante, con los Caballeros de la Mano de Plata a sus espaldas. Fue Arthas Menethil quien puso fin a aquella resistencia, al lanzar su ejército de no-muertos contra la ciudad y abatir a Truthbearer, a Ballador y al propio Uther.\n\nLo que Arthas dejó atrás, lo recogieron los propios soldados de Uther. Llevaron su cuerpo al sur de las ruinas de Andorhal y levantaron una tumba sobre él. Su lápida lo muestra tal como era en vida, con un tomo de la Luz en una mano y su martillo de guerra en la otra, y con unas palabras grabadas en lengua común en la piedra que hay delante.\n\nEl sumo sacerdote Thel'danis aún cuida la tumba, como su custodio y guardián. La sepultura es sagrada para quienes siguen la Luz, uno de los pocos lugares de las Tierras de la Peste donde esa devoción todavía significa algo.",
			source = "https://warcraft.wiki.gg/wiki/Uther's_Tomb",
		},
		["weeping cave"] = {
			name = "La Cueva del Llanto",
			short = "La Cueva del Llanto se encuentra al oeste del Río Thondroril, y sus huecos están llenos de bestias del pantano y de cienos engendrados por la tierra apestada. Colosos putrefactos y horrores en descomposición se arrastran por la oscuridad.",
			full = "La Cueva del Llanto se encuentra al oeste del Río Thondroril, y sus huecos están llenos de bestias del pantano y de cienos engendrados por la tierra apestada. Colosos putrefactos y horrores en descomposición se arrastran por la oscuridad. Se dice que más adentro aún, un elemental llamado el Pellejo sale a la superficie en raras ocasiones, algo extraño e inquietante de ver.",
			source = "https://warcraft.wiki.gg/wiki/Weeping_Cave",
		},
		["writhing haunt"] = {
			name = "El Tormento",
			short = "El Tormento fue en otro tiempo tierra de cultivo, trabajada para el sustento de los vivos. Ese propósito desapareció.",
			full = "El Tormento fue en otro tiempo tierra de cultivo, trabajada para el sustento de los vivos. Ese propósito desapareció. La Plaga se apoderó de los campos y colocó en su centro un gran caldero que no ha dejado de trabajar desde entonces: un chorro constante de vapor cargado de enfermedad que se extiende por los surcos donde antes crecían las cosechas.\n\nEl caldero no está desprotegido. El señor del caldero Razarch monta guardia sobre él, con necrófagos putrefactos, necrófagos gélidos y zombis fétidos moviéndose a su alrededor, atados al lugar como sus guardianes.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Haunt",
		},
	},
	-- Tierras de la Peste del Este: 28 subzones
	[1423] = {
		["blackwood lake"] = {
			name = "Lago del Bosque Negro",
			short = "Las aguas del Lago del Bosque Negro están inmundas, infestadas de elementales de agua corruptos que se enroscan en la turbiedad. Los antiguos anales de Villa Darrow afirman que el fondo del lago guarda la cabeza de Horgus el Devastador, hundida en algún lugar de esa oscuridad.",
			full = "Las aguas del Lago del Bosque Negro están inmundas, infestadas de elementales de agua corruptos que se enroscan en la turbiedad. Los antiguos anales de Villa Darrow afirman que el fondo del lago guarda la cabeza de Horgus el Devastador, hundida en algún lugar de esa oscuridad.\n\nAntes de la peste, aquí se alzaba un pueblo llamado Bosque Negro, hogar del gran mariscal Othmar Garithos. Hoy no queda nada de él, salvo el lago que lleva su nombre.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Lake",
		},
		["browman mill"] = {
			name = "Molino Cejifrente",
			short = "Stephen Cejifrente cortaba antaño madera en el molino al norte de la Capilla de la Esperanza de la Luz. La Plaga lo mató como a todos los que tocó la peste, y luego lo alzó como un necrófago atado a su servicio.",
			full = "Stephen Cejifrente cortaba antaño madera en el molino al norte de la Capilla de la Esperanza de la Luz. La Plaga lo mató como a todos los que tocó la peste, y luego lo alzó como un necrófago atado a su servicio. Nunca se marchó. Ahora monta guardia dentro de los muros que antes le pertenecían.\n\nEl molino está lleno de esqueletos, almas en pena y abominaciones, más guarnición que ruina, y nada en él invita a nadie a quedarse.",
			source = "https://warcraft.wiki.gg/wiki/Browman_Mill",
		},
		["corins crossing"] = {
			name = "Cruce de Corin",
			short = "El Cruce de Corin se encuentra donde se unen los caminos hacia Andorhal, Villa Darrow, Stratholme y la Mano de Tyr, entre la Cicatriz Purulenta y el Lago Mereldar.",
			full = "El Cruce de Corin se encuentra donde se unen los caminos hacia Andorhal, Villa Darrow, Stratholme y la Mano de Tyr, entre la Cicatriz Purulenta y el Lago Mereldar. En otro tiempo fue un pueblo corriente de cruce de caminos, con un ayuntamiento y una herrería.\n\nAhora la Plaga llena por completo sus calles, y entre los muertos se mueven cosas que no pueden verse en absoluto: los sirvientes invisibles, que ven a través del sigilo como si no existiera. No hay ningún camino discreto para atravesar el Cruce de Corin.",
			source = "https://warcraft.wiki.gg/wiki/Corin's_Crossing",
		},
		["crown guard tower"] = {
			name = "Torre de la Corona",
			short = "La Torre de la Corona vigila las Tierras de la Peste del Este como una de sus torres de exploración. La invasión de Lordaeron por parte de la Plaga arrasó la región, y la torre aún lleva sus cicatrices, un testigo silencioso de las tierras muertas.",
			full = "La Torre de la Corona vigila las Tierras de la Peste del Este como una de sus torres de exploración. La invasión de Lordaeron por parte de la Plaga arrasó la región, y la torre aún lleva sus cicatrices, un testigo silencioso de las tierras muertas.",
			source = "https://warcraft.wiki.gg/wiki/Crown_Guard_Tower",
		},
		["darrowshire"] = {
			name = "Villa Darrow",
			short = "Villa Darrow fue en otro tiempo una aldea con entidad propia, hasta que la Tercera Guerra llevó a la Plaga hasta sus puertas. Un señor necrófago llamado Horgus el Devastador dirigió el asalto, junto al caballero de la Muerte Marduk Pozonegro.",
			full = "Villa Darrow fue en otro tiempo una aldea con entidad propia, hasta que la Tercera Guerra llevó a la Plaga hasta sus puertas. Un señor necrófago llamado Horgus el Devastador dirigió el asalto, junto al caballero de la Muerte Marduk Pozonegro. Al principio, los defensores de la aldea resistieron con cierto éxito, pero la marea cambió, y al final todos ellos fueron masacrados.\n\nSu muerte no acabó con ellos. Los caídos se alzaron de nuevo como necrófagos, atados al servicio de la misma Plaga que los había matado, con sus espíritus atrapados dentro de la carne podrida que una vez fue suya.\n\nLa propia Villa Darrow está ahora silenciosa y destrozada, vacía salvo por fantasmas y recuerdos.",
			source = "https://warcraft.wiki.gg/wiki/Darrowshire",
		},
		["eastwall gate"] = {
			name = "Puerta de la Muralla del Este",
			short = "La Puerta de la Muralla del Este es la entrada lateral a Stratholme, y da directamente a la Plaza del Anciano, cerca de la Capilla de Alonsus, donde Aurius tiene su puesto.",
			full = "La Puerta de la Muralla del Este es la entrada lateral a Stratholme, y da directamente a la Plaza del Anciano, cerca de la Capilla de Alonsus, donde Aurius tiene su puesto.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Gate",
		},
		["eastwall tower"] = {
			name = "Torre de la Muralla del Este",
			short = "La Torre de la Muralla del Este se alza en las Tierras de la Peste del Este, una torre de exploración que antaño vigilaba estas tierras para Lordaeron. La Plaga arrasó el reino, y la torre aún lleva sus cicatrices, vigilando tierras muertas.",
			full = "La Torre de la Muralla del Este se alza en las Tierras de la Peste del Este, una torre de exploración que antaño vigilaba estas tierras para Lordaeron. La Plaga arrasó el reino, y la torre aún lleva sus cicatrices, vigilando tierras muertas.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Tower",
		},
		["fungal vale"] = {
			name = "Cuenca Fungal",
			short = "Al norte de la Hacienda de Marris y de la Torre de la Corona se encuentra el Valle Fungal, un terreno que se ha vuelto de un morado oscuro bajo una bruma turbia.",
			full = "Al norte de la Hacienda de Marris y de la Torre de la Corona se encuentra el Valle Fungal, un terreno que se ha vuelto de un morado oscuro bajo una bruma turbia. Aquí la Peste de la no-muerte ha arraigado con más fuerza que en ningún otro lugar, y la Plaga y el Culto de los Malditos se mueven libremente por la corrupción, considerando la hondonada completamente suya.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Vale",
		},
		["infectis scar"] = {
			name = "La Cicatriz Purulenta",
			short = "Cerca del Cruce de Corin, la espada rúnica del caballero de la Muerte Marduk Pozonegro se hizo añicos contra el escudo de un capitán enano. Se quedó con la empuñadura y arrojó a un lado la hoja destrozada, considerándola inútil.",
			full = "Cerca del Cruce de Corin, la espada rúnica del caballero de la Muerte Marduk Pozonegro se hizo añicos contra el escudo de un capitán enano. Se quedó con la empuñadura y arrojó a un lado la hoja destrozada, considerándola inútil. Pero la hoja se hundió en la tierra, y el suelo se abrió bajo ella y se llenó de agua oscura.\n\nLo que queda es antinatural de principio a fin, a diferencia de la cercana Cicatriz Pestilente, que no es más que un desfiladero natural.",
			source = "https://warcraft.wiki.gg/wiki/Infectis_Scar",
		},
		["lake mereldar"] = {
			name = "Lago Mereldar",
			short = "Las aguas del Lago Mereldar, al sur del Cruce de Corin, están cargadas de peste, y bajo su superficie se mueven elementales de agua corruptos.",
			full = "Las aguas del Lago Mereldar, al sur del Cruce de Corin, están cargadas de peste, y bajo su superficie se mueven elementales de agua corruptos. En su orilla se alzan las ruinas de una vieja casa, además de una choza y un transbordador que antes servían a una granja ahora abandonada.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mereldar",
		},
		["lights hope chapel"] = {
			name = "Capilla de la Esperanza de la Luz",
			short = "Bajo las montañas al este de las Tierras de la Peste se alza una capilla mucho más antigua que la ruina que la rodea, uno de los lugares sagrados más antiguos y venerados que la Iglesia de la Luz Sagrada llegó a levantar.",
			full = "Bajo las montañas al este de las Tierras de la Peste se alza una capilla mucho más antigua que la ruina que la rodea, uno de los lugares sagrados más antiguos y venerados que la Iglesia de la Luz Sagrada llegó a levantar.\n\nLos paladines que no quisieron seguir el camino que tomaba la Cruzada Escarlata se retiraron a las Tierras de la Peste del Este e hicieron de esta capilla su base, llamándose a sí mismos El Alba Argenta. Lord Raymond George los dirigió primero; cuando murió, lord Maxwell Neófitus ocupó su lugar. A diferencia de la Cruzada Escarlata, no rechazaban a nadie por su raza.\n\nAunque El Alba Argenta se mantiene apartada de la Cruzada Escarlata, la capilla sigue siendo terreno neutral donde ambas aún se reúnen para hablar entre sí.",
			source = "https://warcraft.wiki.gg/wiki/Light's_Hope_Chapel",
		},
		["marris stead"] = {
			name = "Hacienda de Marris",
			short = "La Hacienda de Marris se encuentra sobre una loma baja que domina el camino principal de la región, una granja que perteneció en otro tiempo a Nathanos Marris.",
			full = "La Hacienda de Marris se encuentra sobre una loma baja que domina el camino principal de la región, una granja que perteneció en otro tiempo a Nathanos Marris. Su primo Stephon vivió aquí durante un tiempo, y se sabía que Sylvanas Brisaveloz visitaba a Nathanos bajo este techo.\n\nLiberado por la Reina alma en pena después de que ella alzara a los Renegados en Entrañas, Nathanos regresó al hogar que había perdido y, por orden suya, volvió a hacerlo suyo. Desde aquí reclutó soldados de la Horda para luchar contra la Plaga y la Cruzada Escarlata que aún infestaban las Tierras de la Peste, y reunió reliquias de la batalla de Villa Darrow, que guardaba en la hacienda por motivos que no contó a nadie.",
			source = "https://warcraft.wiki.gg/wiki/Marris_Stead",
		},
		["mazraalor"] = {
			name = "Mazra'Alor",
			short = "En el corazón de Zul'Mashar se alza Mazra'Alor, un zigurat de piedra apilada que domina las tierras en ruinas que lo rodean.",
			full = "En el corazón de Zul'Mashar se alza Mazra'Alor, un zigurat de piedra apilada que domina las tierras en ruinas que lo rodean. La tribu Mossflayer aún lo ocupa, y sus cazadores de las sombras vigilan desde sus alturas el asentamiento trol que hay debajo.",
			source = "https://warcraft.wiki.gg/wiki/Mazra'Alor",
		},
		["northdale"] = {
			name = "Vallenorte",
			short = "Vallenorte es un pueblo en ruinas al norte de la Capilla de la Esperanza de la Luz, en el límite de Quel'Thalas. Aquí, Taelan Vadín renunció a la Orden de la Mano de Plata por la Cruzada Escarlata.",
			full = "Vallenorte es un pueblo en ruinas al norte de la Capilla de la Esperanza de la Luz, en el límite de Quel'Thalas. Aquí, Taelan Vadín renunció a la Orden de la Mano de Plata por la Cruzada Escarlata.\n\nAhora las almas en pena y los vigilantes invisibles rondan los restos. El lago cercano alberga elementales de agua corruptos. No queda nada vivo.",
			source = "https://warcraft.wiki.gg/wiki/Northdale",
		},
		["northpass tower"] = {
			name = "Torre del Paso Norte",
			short = "La Torre del Paso Norte es la más septentrional de las torres de vigilancia de las Tierras de la Peste del Este, y señala el camino hacia las Tierras Fantasma de Quel'Thalas.",
			full = "La Torre del Paso Norte es la más septentrional de las torres de vigilancia de las Tierras de la Peste del Este, y señala el camino hacia las Tierras Fantasma de Quel'Thalas. La Plaga arrasó Lordaeron, y la torre aún lleva sus cicatrices.",
			source = "https://warcraft.wiki.gg/wiki/Northpass_Tower",
		},
		["noxious glade"] = {
			name = "El Claro Ponzoñoso",
			short = "El Claro Ponzoñoso se encuentra en lo alto de una colina al norte de la Capilla de la Esperanza de la Luz, más contaminado por la plaga que el resto de las Tierras de la Peste que lo rodean.",
			full = "El Claro Ponzoñoso se encuentra en lo alto de una colina al norte de la Capilla de la Esperanza de la Luz, más contaminado por la plaga que el resto de las Tierras de la Peste que lo rodean. El aire es denso y de un verde enfermizo, y el suelo se ha teñido de un morado oscuro donde nada verde puede crecer.\n\nLa Plaga ha hecho suyo el claro: un caldero de la peste, un matadero y algunos zigurats se alzan sobre la tierra envenenada, y las criaturas de la Plaga se mueven por él en gran número.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Glade",
		},
		["pestilent scar"] = {
			name = "Cicatriz Pestilente",
			short = "La Cicatriz Pestilente es un profundo desfiladero en las asoladas Tierras de la Peste del Este, probablemente un lago que se secó cuando golpeó la Peste de la no-muerte.",
			full = "La Cicatriz Pestilente es un profundo desfiladero en las asoladas Tierras de la Peste del Este, probablemente un lago que se secó cuando golpeó la Peste de la no-muerte. Ahora está casi seco, una herida en la tierra, y sus profundidades son el hogar de cienos nacidos de la antigua corrupción.",
			source = "https://warcraft.wiki.gg/wiki/Pestilent_Scar",
		},
		["plaguewood"] = {
			name = "Bosque de la Peste",
			short = "Los árboles al sur de Stratholme se alzaban en otro tiempo verdes y tranquilos, un bosque no muy distinto del Bosque de Elwynn, con una pequeña aldea enclavada cerca del arco de piedra de su linde.",
			full = "Los árboles al sur de Stratholme se alzaban en otro tiempo verdes y tranquilos, un bosque no muy distinto del Bosque de Elwynn, con una pequeña aldea enclavada cerca del arco de piedra de su linde. Fue aquí donde el sargento Morigan, un soldado de Lordaeron nacido en aquella aldea, notó por primera vez que el grano envenenado de Andorhal estaba corrompiendo la tierra, cuando Kel'Thuzad comenzó su obra. Su advertencia llegó demasiado tarde para el reino, y el mismo camino que él vigilaba fue el que más tarde recorrió el príncipe Arthas en su camino hacia Stratholme.\n\nLo que quedó después ya no era un bosque. El suelo mismo se volvió esponjoso bajo los pies, y los hongos y las setas crecieron hasta alcanzar el tamaño de árboles, alzándose sobre lo que quedaba del antiguo bosque. Exhalan un gas de color pardo oscuro no muy distinto de los vapores que brotan de los calderos de la peste de la Plaga, aunque nadie puede asegurar si los hongos simplemente crecen en suelo envenenado o si la Plaga los cultiva para propagar aún más su enfermedad. Fue por esta transformación que el bosque recibió su nuevo nombre.",
			source = "https://warcraft.wiki.gg/wiki/Plaguewood",
		},
		["quellithien lodge"] = {
			name = "Refugio Quel'Lithien",
			short = "El Refugio Quel'Lithien era un campamento de los Errantes cerca de Quel'Thalas, un lugar cálido y acogedor. Así lo recordaba Lor'themar Theron de sus propias visitas, cuando lo recibían con afecto los compatriotas que lo consideraban su hogar.",
			full = "El Refugio Quel'Lithien era un campamento de los Errantes cerca de Quel'Thalas, un lugar cálido y acogedor. Así lo recordaba Lor'themar Theron de sus propias visitas, cuando lo recibían con afecto los compatriotas que lo consideraban su hogar. El refugio albergó en otro tiempo varios documentos élficos, algunos relacionados con la familia real y con el general forestal de Lunargenta. Para la época de la Segunda Guerra, Renthar Hawkspear dirigía allí a los cazadores.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Lithien_Lodge",
		},
		["scarlet base camp"] = {
			name = "Campamento Base Escarlata",
			short = "En la orilla oriental del Lago Mereldar, no lejos del bastión religioso de la Mano de Tyr, el Campamento Base Escarlata se alza tras sus barricadas, con sus defensas reforzadas contra lo que pueda venir.",
			full = "En la orilla oriental del Lago Mereldar, no lejos del bastión religioso de la Mano de Tyr, el Campamento Base Escarlata se alza tras sus barricadas, con sus defensas reforzadas contra lo que pueda venir.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Base_Camp",
		},
		["scarlet basilica"] = {
			name = "La Basílica Escarlata",
			short = "La Basílica Escarlata se alza dentro de la Mano de Tyr, la sede principal de la fe de la Cruzada Escarlata, vinculada a la abadía cercana y al lejano Monasterio Escarlata de los Claros de Tirisfal.",
			full = "La Basílica Escarlata se alza dentro de la Mano de Tyr, la sede principal de la fe de la Cruzada Escarlata, vinculada a la abadía cercana y al lejano Monasterio Escarlata de los Claros de Tirisfal. El señor cruzado Valdemar la dirige, con una devoción absoluta a la causa de la Cruzada.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Basilica",
		},
		["stratholme"] = {
			name = "Stratholme",
			short = "La ruina de Stratholme comenzó con el grano. Los cargamentos procedentes de Andorhal, infectados en secreto por el Culto de los Malditos, se hornearon en forma de pan y fueron comidos por una población que nunca supo que se estaba muriendo.",
			full = "La ruina de Stratholme comenzó con el grano. Los cargamentos procedentes de Andorhal, infectados en secreto por el Culto de los Malditos, se hornearon en forma de pan y fueron comidos por una población que nunca supo que se estaba muriendo. El príncipe Arthas Menethil llegó con Uther el Iluminado y Jaina Valiente y encontró que la peste ya se estaba propagando. Convencido de que la única misericordia que quedaba era una muerte limpia en lugar de una lenta transformación en muertos vivientes, Arthas ordenó incendiar la ciudad. Uther y Jaina se negaron y retiraron a sus hombres. Arthas no. El fuego arrasó las calles, y casi todas las almas de Stratholme murieron antes de que el señor del terror Mal'Ganis, a quien Arthas había venido a matar, se escabullera riendo y dejara al príncipe quemando lo que quedaba.\n\nNo fue suficiente. Los muertos se alzaron de todos modos, y la ciudad se convirtió en la capital de la Plaga en Lordaeron, gobernada primero por el exánime Kel'Thuzad y después por el caballero de la Muerte barón Osahendido.\n\nStratholme sigue ardiendo.",
			source = "https://warcraft.wiki.gg/wiki/Stratholme",
		},
		["terrordale"] = {
			name = "Valle del Terror",
			short = "El Valle del Terror se encuentra en el límite del Bosque de la Peste, con sus calles vacías y entregadas a la Plaga y a los animales apestados. Solo el mercader Augustus el Agraciado y el cazador de fantasmas Egan permanecen aún entre las ruinas.",
			full = "El Valle del Terror se encuentra en el límite del Bosque de la Peste, con sus calles vacías y entregadas a la Plaga y a los animales apestados. Solo el mercader Augustus el Agraciado y el cazador de fantasmas Egan permanecen aún entre las ruinas.\n\nEl pueblo está embrujado. Los espíritus recorren sus callejuelas, y en ciertos lugares el propio Valle del Terror parece tambalearse, con el mundo físico cediendo bajo el peso del reino que hay más allá, como si el suelo recordara algún viejo tormento que no puede soltar.\n\nFue esta inquietud la que atrajo a lord Grisillo Quiebrasombras, que vio en los espíritus una prueba adecuada para los paladines que buscaban demostrar que eran dignos de juicio y sacrificio, un paso para ganarse los corceles reservados a los verdaderamente merecedores. No se sabe qué fueron los espíritus en vida, solo que su tormento era lo bastante real como para deformar el pueblo a su alrededor.",
			source = "https://warcraft.wiki.gg/wiki/Terrordale",
		},
		["terrorweb tunnel"] = {
			name = "Túnel Terroarácnido",
			short = "El túnel atraviesa la montaña al noroeste del Valle del Terror y se extiende hacia el sur hasta llegar al Río Thondroril.",
			full = "El túnel atraviesa la montaña al noroeste del Valle del Terror y se extiende hacia el sur hasta llegar al Río Thondroril. Los malignos de cripta nerubianos abarrotan todo el pasaje, y entre ellos acecha algo peor: un sobrestante nerubiano, mucho más letal que sus congéneres.\n\nEn la boca del túnel, junto al río, Tirion Vadín monta guardia, enfrentando la oscuridad del pasaje desde la luz del exterior.",
			source = "https://warcraft.wiki.gg/wiki/Terrorweb_Tunnel",
		},
		["thondroril river"] = {
			name = "Río Thondroril",
			short = "El Río Thondroril separa las Tierras de la Peste del Oeste de las del Este. Nace muy al norte, cerca del Túnel Terroarácnido, y fluye hacia el sur hasta desembocar en el Lago Darrowmere, y continúa más allá como el río Darrowmere.",
			full = "El Río Thondroril separa las Tierras de la Peste del Oeste de las del Este. Nace muy al norte, cerca del Túnel Terroarácnido, y fluye hacia el sur hasta desembocar en el Lago Darrowmere, y continúa más allá como el río Darrowmere.\n\nSus orillas pertenecen a la plaga. Gusanos y murciélagos vampiro abarrotan el suelo húmedo, osos de la peste y arañas acechan en las aguas poco profundas, y las quijafortes se esconden donde la corriente se calma.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["tyrs hand"] = {
			name = "Mano de Tyr",
			short = "La Mano de Tyr es una ciudad humana fortificada, uno de los últimos reductos de los vivos contra la Plaga en la región.",
			full = "La Mano de Tyr es una ciudad humana fortificada, uno de los últimos reductos de los vivos contra la Plaga en la región. Sus alrededores están en mucho mejor estado que el resto de las Tierras de la Peste, aunque los árboles y la vegetación siguen pudriéndose.\n\nLa ciudad es uno de los lugares sagrados más antiguos y venerados de la Iglesia de la Luz, construida casi por completo a base de iglesias y coronada por la Basílica Escarlata y la abadía fortificada.\n\nCuando llegó la Plaga y los Bosques del Este se convirtieron en las Tierras de la Peste, la Mano de Tyr no cayó. Bajo el mando de lord Valdemar resistió asaltos diarios, protegida primero por los Caballeros de la Mano de Plata y después por la Cruzada Escarlata, y enviaba suministros y refuerzos a otros dominios Escarlata, mientras recibía informes diarios desde Stratholme traídos por mensajeros que tenían que abrirse paso a través de caminos plagados de peste.",
			source = "https://warcraft.wiki.gg/wiki/Tyr's_Hand",
		},
		["undercroft"] = {
			name = "La Subgranja",
			short = "La Subgranja es una cripta en el suroeste de las Tierras de la Peste del Este, hogar de trols no-muertos dirigidos por Zaeldarr el Marginado, un trol atroz alzado de entre los muertos.",
			full = "La Subgranja es una cripta en el suroeste de las Tierras de la Peste del Este, hogar de trols no-muertos dirigidos por Zaeldarr el Marginado, un trol atroz alzado de entre los muertos. Desde aquí asalta la fosa de tumbas de El Alba Argenta en la Capilla de la Esperanza de la Luz, robando cuerpos para sí.",
			source = "https://warcraft.wiki.gg/wiki/Undercroft",
		},
		["zulmashar"] = {
			name = "Zul'Mashar",
			short = "Zul'Mashar fue en otro tiempo la capital de la tribu Mossflayer, trols del bosque del noreste de las Tierras de la Peste del Este.",
			full = "Zul'Mashar fue en otro tiempo la capital de la tribu Mossflayer, trols del bosque del noreste de las Tierras de la Peste del Este. Las largas guerras contra los humanos de Lordaeron dejaron las tierras de la tribu en desorden, y la peste de la no-muerte que siguió trajo una ruina aún más profunda. La ciudad que antes gobernaba aquí es ahora una sombra de su antigua gloria.\n\nSu zigurat, Mazra'Alor, aún se alza en el corazón de la ciudad, ahora en manos del señor de la guerra Thresh'jin y de Zul'Brin Warpbranch. Pero la propia gente de los Mossflayer está siendo transformada en secreto por la peste, y Zul'Mashar corre el peligro de convertirse en nada más que un bastión de los no-muertos.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Mashar",
		},
	},
	-- Laderas de Trabalomas: 29 subzones
	[1424] = {
		["azurelode mine"] = {
			name = "Mina Azur",
			short = "La Mina Azur se encuentra en el extremo suroeste de las Laderas de Trabalomas, y su colina se consideraba parte de Gilneas antes de que se alzara la Muralla de Cringris y aislara al reino del mundo.",
			full = "La Mina Azur se encuentra en el extremo suroeste de las Laderas de Trabalomas, y su colina se consideraba parte de Gilneas antes de que se alzara la Muralla de Cringris y aislara al reino del mundo.\n\nLa mina pertenece a la Alianza; la trabajan mineros bajo la vigilancia de guardias, y su hierro abastece los arsenales de la Alianza.",
			source = "https://warcraft.wiki.gg/wiki/Azurelode_Mine",
		},
		["chillwind point"] = {
			name = "Alto del Orvallo",
			short = "El Alto del Orvallo debe su nombre al viento helado que baja de las Tierras de la Peste del Oeste y se encauza por el barranco de abajo. La elevación está coronada por una antigua ruina trol, lo único que queda de quienes la levantaron.",
			full = "El Alto del Orvallo debe su nombre al viento helado que baja de las Tierras de la Peste del Oeste y se encauza por el barranco de abajo. La elevación está coronada por una antigua ruina trol, lo único que queda de quienes la levantaron. El paso perteneció en otro tiempo al reino de Lordaeron. Ahora el trol de la selva Bath'rah el Vigía del viento vive en la ruina.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Point",
		},
		["corrahns dagger"] = {
			name = "Daga de Corrahn",
			short = "La Daga de Corrahn es el segundo de los cuatro dedos de Trabalomas. La Hermandad domina esta colina.",
			full = "La Daga de Corrahn es el segundo de los cuatro dedos de Trabalomas. La Hermandad domina esta colina.",
			source = "https://warcraft.wiki.gg/wiki/Corrahn's_Dagger",
		},
		["crushridge hold"] = {
			name = "Dominios de los Aplastacresta",
			short = "Los Dominios de los Aplastacresta se alzan cerca de las Ruinas de Alterac, una cueva excavada en un montículo de tierra.",
			full = "Los Dominios de los Aplastacresta se alzan cerca de las Ruinas de Alterac, una cueva excavada en un montículo de tierra. A su alrededor, los ogros Aplastacresta han levantado sus campamentos, numerosos y de carácter brutal, y dominan las laderas que se alzan sobre la ciudad en ruinas.",
			source = "https://warcraft.wiki.gg/wiki/Crushridge_Hold",
		},
		["darrow hill"] = {
			name = "Colinas de Darrow",
			short = "Las Colinas de Darrow se encuentran en el norte de las Laderas de Trabalomas, bajo La Punta.",
			full = "Las Colinas de Darrow se encuentran en el norte de las Laderas de Trabalomas, bajo La Punta. Los pumas y los ciervos recorren sus campos abiertos, y dentro de las Cuevas de la Ladera los yetis han establecido su guarida, entre vetas de granito de Alterac que atraviesan la roca.",
			source = "https://warcraft.wiki.gg/wiki/Darrow_Hill",
		},
		["dun garok"] = {
			name = "Dun Garok",
			short = "Dun Garok se alza en las colinas de las Laderas de Trabalomas, una fortaleza enana bajo el mando del capitán Ferrocolina.",
			full = "Dun Garok se alza en las colinas de las Laderas de Trabalomas, una fortaleza enana bajo el mando del capitán Ferrocolina. Su guarnición protege a los humanos de Trabalomas y vigila la Mina Azur, una presencia que los Renegados no soportan, pues han ofrecido oro a quien logre colarse en la fortaleza y pasar a sus enanos por la espada.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Garok",
		},
		["durnholde keep"] = {
			name = "Castillo de Durnholde",
			short = "El Castillo de Durnholde se alza en ruinas al este del Molino Tarren, con sus barracones y su torre de magos hundidos sobre sí mismos y su arena en silencio.",
			full = "El Castillo de Durnholde se alza en ruinas al este del Molino Tarren, con sus barracones y su torre de magos hundidos sobre sí mismos y su arena en silencio. En otro tiempo fue la sede del sistema de reclusión de orcos levantado después de la Segunda Guerra, gobernado por el teniente general Aedelas Lodonegro, un borracho ensimismado que utilizaba el campo para su propio ascenso.\n\nFue Lodonegro quien encontró a un bebé orco entre los cuerpos de sus padres asesinados y lo llevó al castillo, donde le puso el nombre de Thrall. El niño fue criado y educado allí, amamantado por una mujer humana cuya hija, Taretha Foxton, se hizo muy cercana a él. Lodonegro golpeó al muchacho y lo hizo pelear en la arena durante años, aprovechando su fuerza para ascender de rango. Taretha le escribía en secreto, y él le respondía, hasta que al fin le dijo que pensaba escapar. Ella creó la distracción que le permitió escabullirse, se reunió con él al otro lado de los muros y le dio provisiones antes de que partiera.\n\nÉl regresó, años después, al frente de los orcos libres que había reunido. Thrall sitió Durnholde, mató a Lodonegro en combate singular e invocó al Espíritu de la Tierra para arrasar por completo la fortaleza. Lo que queda ha atraído desde entonces a la Hermandad, que reclama estas ruinas como propias.",
			source = "https://warcraft.wiki.gg/wiki/Durnholde_Keep",
		},
		["eastern strand"] = {
			name = "Playa del Este",
			short = "La Playa del Este se extiende a lo largo de la costa sureste de las Laderas de Trabalomas, y su contraparte se encuentra más al oeste, en la misma orilla.",
			full = "La Playa del Este se extiende a lo largo de la costa sureste de las Laderas de Trabalomas, y su contraparte se encuentra más al oeste, en la misma orilla. Esta franja de arena pertenece a los nagas Espinada, que dominan las playas y las aguas poco profundas que hay más allá.",
			source = "https://warcraft.wiki.gg/wiki/Eastern_Strand",
		},
		["gallows corner"] = {
			name = "Camino de la Horca",
			short = "En el Camino de la Horca, donde se unen los caminos de las Montañas de Alterac cerca de los salones en ruinas de Alterac, una torre de exploración se alza rota y vacía.",
			full = "En el Camino de la Horca, donde se unen los caminos de las Montañas de Alterac cerca de los salones en ruinas de Alterac, una torre de exploración se alza rota y vacía. Ahora los ogros Aplastacresta dominan el cruce y merodean entre las piedras que rodean los restos de la torre, y nada más se mueve allí.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_Corner",
		},
		["gavins naze"] = {
			name = "Saliente de Gavin",
			short = "El Saliente de Gavin es la última de las cuatro colinas de Trabalomas, y la más vigilada.",
			full = "El Saliente de Gavin es la última de las cuatro colinas de Trabalomas, y la más vigilada.\n\nLos pumas recorren esta colina, y entre ellos está Araga, que se distingue por su pelaje poco común.",
			source = "https://warcraft.wiki.gg/wiki/Gavin's_Naze",
		},
		["growless cave"] = {
			name = "Caverna Estrecha",
			short = "En las Montañas de Alterac, una cueva da refugio a los yetis de montaña, y a menudo puede encontrarse a Skhowl justo en su entrada.",
			full = "En las Montañas de Alterac, una cueva da refugio a los yetis de montaña, y a menudo puede encontrarse a Skhowl justo en su entrada. En lo más profundo se alza la Llama de Uzel, una pira levantada por el humano Helcular para el ritual que lo convertiría en un exánime. La carne quemada sobre ella atrae a la entrada al poderoso yeti Faucehielo.",
			source = "https://warcraft.wiki.gg/wiki/Growless_Cave",
		},
		["headland"] = {
			name = "La Punta",
			short = "La Punta es uno de los dedos de tierra que se extienden a lo largo de Trabalomas.",
			full = "La Punta es uno de los dedos de tierra que se extienden a lo largo de Trabalomas.\n\nAquí, en la ladera del acantilado, Araga descansa entre sus cachorros.",
			source = "https://warcraft.wiki.gg/wiki/Headland",
		},
		["hillsbrad fields"] = {
			name = "Campos de Trabalomas",
			short = "Los Campos de Trabalomas se extienden fértiles y cultivados por el oeste de las Laderas de Trabalomas, y alimentan a Costasur y, además, al pueblo de Trabalomas.",
			full = "Los Campos de Trabalomas se extienden fértiles y cultivados por el oeste de las Laderas de Trabalomas, y alimentan a Costasur y, además, al pueblo de Trabalomas. Huertos de manzanos, campos de calabazas y ganado que pasta cubren la tierra, y la gente del pueblo aún trabaja la Mina Azur.\n\nAl comienzo de la Segunda Guerra, Martillo Maldito dirigió sus ejércitos contra Trabalomas y ordenó destruirla en un espectáculo atroz que debía servir de advertencia a los reinos humanos. Fue reconstruida después de la guerra y sigue habitada, uno de los pocos rincones del antiguo Lordaeron que no quedó en ruinas ni fue absorbido por la Cruzada Escarlata; sus guardias aún visten el tabardo de su reino, y el magistrado Ladoquemado gobierna desde el ayuntamiento con el Consejo de Trabalomas y el escribano Horrace Whitesteed a su lado.\n\nAhora los campos vuelven a estar amenazados, esta vez por las fuerzas de la suma ejecutora Darthalia en el Molino Tarren. Campesinos y granjeros soportan los ataques, pero muchos devuelven el golpe a los no-muertos con emboscadas propias, armados por el herrero Verringtan y sus aprendices.",
			source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Fields",
		},
		["misty shore"] = {
			name = "Costa de la Neblina",
			short = "La Costa de la Neblina se extiende a lo largo del Lago Lordamere, entre el Redil de Dandred y Dalaran. Las tortugas avanzan lentamente por sus aguas poco profundas.",
			full = "La Costa de la Neblina se extiende a lo largo del Lago Lordamere, entre el Redil de Dandred y Dalaran. Las tortugas avanzan lentamente por sus aguas poco profundas.\n\nDos miembros de la Cruzada Escarlata ocupan esta costa y caen sobre cualquiera que se acerque demasiado, como si el propio terreno necesitara vigilancia.\n\nAl otro lado del agua pueden verse las Islas del Alba, con el Castillo de Fenris asomando tenuemente, sombrío, entre la niebla.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Shore",
		},
		["nethander stead"] = {
			name = "Granja Nethander",
			short = "La Granja Nethander se encuentra justo al este de Costasur, con sus campos abandonados hace mucho e invadidos por los gnolls Morrobarro, el único lugar donde se encuentra a su tribu.",
			full = "La Granja Nethander se encuentra justo al este de Costasur, con sus campos abandonados hace mucho e invadidos por los gnolls Morrobarro, el único lugar donde se encuentra a su tribu. Allí crecen silvestres unos hongos blancos gigantes llamados flores de morrobarro, que antaño buscaba el boticario Lydon para su letal elixir de agonía.",
			source = "https://warcraft.wiki.gg/wiki/Nethander_Stead",
		},
		["purgation isle"] = {
			name = "Isla del Purgatorio",
			short = "Una espiral de piedra se alza al sur de la costa de Trabalomas, coronada por un cementerio y los restos rotos de una torre de exploración. Antes de la Primera Guerra, la Isla del Purgatorio pertenecía a Kul Tiras.",
			full = "Una espiral de piedra se alza al sur de la costa de Trabalomas, coronada por un cementerio y los restos rotos de una torre de exploración. Antes de la Primera Guerra, la Isla del Purgatorio pertenecía a Kul Tiras.\n\nLo que ocurrió después es incierto, pero los muertos no descansan. Decenas de espíritus recorren la isla, humanos y enanos, paladines y sacerdotes, monjes y magos, almas condenadas atadas a sus piedras.",
			source = "https://warcraft.wiki.gg/wiki/Purgation_Isle",
		},
		["ravenholdt manor"] = {
			name = "Mansión Ravenholdt",
			short = "La Mansión Ravenholdt se mantiene apartada del mundo a propósito.",
			full = "La Mansión Ravenholdt se mantiene apartada del mundo a propósito. Solo se llega a ella por un sendero estrecho y sinuoso que sube desde una meseta al noroeste del Castillo de Durnholde, serpenteando entre las montañas y por una pequeña cueva antes de abrirse a los terrenos de la mansión, así que no es un lugar con el que uno se tope por casualidad. Los forasteros no son bienvenidos aquí, y quienes sirven a lord Jorach Ravenholdt se aseguran de que así siga siendo.\n\nLa mansión es propiedad suya, con techos anaranjados al antiguo estilo de Alterac, cuyo reino dominaba estas tierras antes de la Primera Guerra.\n\nEn los años transcurridos desde entonces, la Hermandad ha rondado esta parte de las tierras altas, y Ravenholdt ha resistido esa plaga tras su sendero oculto y sus puertas custodiadas.",
			source = "https://warcraft.wiki.gg/wiki/Ravenholdt_Manor",
		},
		["slaughter hollow"] = {
			name = "Cuenca de la Matanza",
			short = "En lo profundo de las Montañas de Alterac, los ogros Aplastacresta han hecho su hogar en la Cuenca de la Matanza, un montículo hundido entre las colinas.",
			full = "En lo profundo de las Montañas de Alterac, los ogros Aplastacresta han hecho su hogar en la Cuenca de la Matanza, un montículo hundido entre las colinas. Poco más se sabe del lugar aparte de los ogros que lo ocupan, pero el nombre por sí solo dice lo que le espera a cualquiera que se acerque demasiado.",
			source = "https://warcraft.wiki.gg/wiki/Slaughter_Hollow",
		},
		["soferas naze"] = {
			name = "Saliente de Sofera",
			short = "El Saliente de Sofera se alza como uno de los cuatro dedos de Trabalomas. La Hermandad domina la colina y vigila el terreno de abajo.",
			full = "El Saliente de Sofera se alza como uno de los cuatro dedos de Trabalomas. La Hermandad domina la colina y vigila el terreno de abajo.",
			source = "https://warcraft.wiki.gg/wiki/Sofera's_Naze",
		},
		["southpoint tower"] = {
			name = "Torre Austral",
			short = "La Torre Austral se alza en el extremo occidental de las Laderas de Trabalomas, justo al sur del camino que continúa hacia el Bosque de Argénteos.",
			full = "La Torre Austral se alza en el extremo occidental de las Laderas de Trabalomas, justo al sur del camino que continúa hacia el Bosque de Argénteos. La mampostería es vieja y está agrietada, un puesto de exploración abandonado a la ruina, aunque la torre en sí nunca fue derribada en los combates que pasaron por aquí. Cerca, sin nombre, otra torre se alza entre el Molino Tarren y Costasur, también a salvo de la destrucción que arrasó el resto de las laderas.",
			source = "https://warcraft.wiki.gg/wiki/Southpoint_Tower",
		},
		["strahnbrad"] = {
			name = "Strahnbrad",
			short = "Strahnbrad se encuentra en las estribaciones del noreste de las Montañas de Alterac, con su ayuntamiento y su herrería ahora vacíos.",
			full = "Strahnbrad se encuentra en las estribaciones del noreste de las Montañas de Alterac, con su ayuntamiento y su herrería ahora vacíos. En otro tiempo perteneció al Reino de Alterac, y después de la Segunda Guerra pasó a manos de Lordaeron.\n\nLa ruina del pueblo comenzó poco antes de la Tercera Guerra, cuando los orcos Roca Negra cayeron sobre él para llevarse esclavos que sacrificar a la Legión Ardiente. Strahnbrad solo contaba con un puñado de soldados de infantería para defenderlo, pero la noticia llegó a tiempo a los Caballeros de la Mano de Plata. Uther el Iluminado se adelantó para intentar frenar el ataque, mientras el príncipe Arthas Menethil era enviado a defender el propio pueblo. Arthas no llegó a tiempo. Dean, Joe, Mike, Scott y muchos otros murieron antes de que él alcanzara Strahnbrad, y los defensores que quedaban se unieron a él para derrotar a los orcos y matar al capataz de esclavos que había dirigido el ataque. La Alianza se impuso en el campo de batalla, pero la gente de Strahnbrad ya no estaba.\n\nMás tarde, la Hermandad se apoderó del pueblo en ruinas y lo utilizó como bastión para reclamar las Montañas de Alterac, y mantuvo prisionero al orco Gol'dir en una de sus celdas, obligándolo a trabajar como esclavo para acarrear y cavar.",
			source = "https://warcraft.wiki.gg/wiki/Strahnbrad",
		},
		["tarren mill"] = {
			name = "Molino Tarren",
			short = "El Molino Tarren fue en otro tiempo un sencillo pueblo de Lordaeron entre las praderas al pie de las Montañas de Alterac.",
			full = "El Molino Tarren fue en otro tiempo un sencillo pueblo de Lordaeron entre las praderas al pie de las Montañas de Alterac. En los primeros días de la Segunda Guerra, unos arqueros altos elfos de Lunargenta, enviados al sur para ver con sus propios ojos la amenaza orca, cayeron en una emboscada cerca del pueblo y fueron arrastrados a un campo de prisioneros cercano. El rey Terenas envió soldados de la Alianza para liberarlos, y el rescate tuvo éxito. Fue ese éxito el que llevó al Consejo de Lunargenta a unir los ejércitos de Quel'Thalas a la Alianza de Lordaeron.\n\nEl Molino Tarren no siguió en manos humanas. Con el tiempo, los Renegados lo tomaron, y lo dejaron como dejaron sus otros dominios: una iglesia, unas cuantas casas dispersas, huertos podridos, todo en pie pero nada entero. Desde aquí, los Renegados libran su guerra contra las fuerzas de la Alianza de Costasur y Dun Garok, y el terreno entre el Molino Tarren y Costasur se ha vuelto célebre por las escaramuzas incesantes entre ambos pueblos, sin que ninguno pueda doblegar al otro.",
			source = "https://warcraft.wiki.gg/wiki/Tarren_Mill",
		},
		["thoradins wall"] = {
			name = "Muralla de Thoradin",
			short = "El rey Thoradin levantó esta muralla para contener a los trols Amani, en los días en que Strom era joven y Arathor apenas acababa de reclamar esta tierra para la humanidad.",
			full = "El rey Thoradin levantó esta muralla para contener a los trols Amani, en los días en que Strom era joven y Arathor apenas acababa de reclamar esta tierra para la humanidad. Durante generaciones se mantuvo como un centinela firme, una línea que ninguna horda trol podía cruzar.\n\nSiglos después, sigue en pie, pero muy dañada, con sus piedras rotas y su larga vigilancia reducida a ruinas.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["western strand"] = {
			name = "Playa del Oeste",
			short = "La Playa del Oeste se encuentra en la costa suroeste de las Laderas de Trabalomas. Los múrlocs Rompeanca han levantado pequeños campamentos a lo largo de su orilla, y Andy Murgole patrulla estas aguas, vigilando la costa donde habitan.",
			full = "La Playa del Oeste se encuentra en la costa suroeste de las Laderas de Trabalomas. Los múrlocs Rompeanca han levantado pequeños campamentos a lo largo de su orilla, y Andy Murgole patrulla estas aguas, vigilando la costa donde habitan.",
			source = "https://warcraft.wiki.gg/wiki/Western_Strand",
		},
	},
	-- Tierras del Interior: 20 subzones
	[1425] = {
		["aerie peak"] = {
			name = "Pico Nidal",
			short = "Los enanos Martillo Salvaje no eligieron primero las Tierras del Interior.",
			full = "Los enanos Martillo Salvaje no eligieron primero las Tierras del Interior. Su hogar era Grim Batol, en las profundidades de la montaña, hasta que terminó la guerra de los Tres Martillos y los enanos regresaron para encontrar su fortaleza envenenada por la muerte de Modgud. Grim Batol no podía volver a habitarse. Así que los Martillo Salvaje construyeron de nuevo aquí, sobre la ladera de la montaña en lugar de dentro de ella, pues tras los horrores de la lucha en los túneles contra los enanos Hierro Negro no estaban dispuestos a volver a enterrarse en la piedra. El Nidal está abierto al cielo por culpa de aquella guerra.\n\nFue desde aquí donde Kurdran Martillo Salvaje dirigió a sus jinetes de grifo contra las fuerzas orcas enviadas a atacar las Tierras del Interior como maniobra de distracción, mientras el verdadero ejército de la Horda avanzaba sobre Quel'Thalas. Las fuerzas de Anduin Lothar acudieron en su ayuda y contribuyeron a expulsar a los orcos y a los trols del bosque de las tierras de los Martillo Salvaje, y por ello Kurdran comprometió a su clan con la Alianza.\n\nFalstad Martillo Salvaje, que quedó como gran señor feudal cuando Kurdran no regresó, aún gobierna el Nidal. Los trols del bosque de las Tierras del Interior, que llaman a los Martillo Salvaje intrusos en su tierra ancestral, siguen atacando los nidos de grifos, mientras que los altos elfos de Quel'Danil siguen siendo aliados de los enanos contra ese mismo enemigo.",
			source = "https://warcraft.wiki.gg/wiki/Aerie_Peak",
		},
		["agolwatha"] = {
			name = "Agol'watha",
			short = "Las piedras de Agol'watha son más antiguas que los trols que las consideraron sagradas por última vez; se levantaron como templo del Imperio Amani antes de que ese imperio cayera.",
			full = "Las piedras de Agol'watha son más antiguas que los trols que las consideraron sagradas por última vez; se levantaron como templo del Imperio Amani antes de que ese imperio cayera. Los trols Vilrama que llegaron después reclamaron la ruina como propia. Ahora el templo ha sido invadido por lodos animados que llenan sus patios destrozados.",
			source = "https://warcraft.wiki.gg/wiki/Agol'watha",
		},
		["altar of zul"] = {
			name = "El Altar de Zul",
			short = "El Altar de Zul se alza en las Tierras del Interior, levantado por los trols del bosque Vilrama para sus antiguos ritos. Qiaga la Vigilante monta guardia en lo alto de las piedras, custodia del poder que el altar aún pueda conservar.",
			full = "El Altar de Zul se alza en las Tierras del Interior, levantado por los trols del bosque Vilrama para sus antiguos ritos. Qiaga la Vigilante monta guardia en lo alto de las piedras, custodia del poder que el altar aún pueda conservar.",
			source = "https://warcraft.wiki.gg/wiki/Altar_of_Zul",
		},
		["bogens ledge"] = {
			name = "Arrecife de Bogen",
			short = "El Arrecife de Bogen es una cueva en el suroeste de las Tierras del Interior.",
			full = "El Arrecife de Bogen es una cueva en el suroeste de las Tierras del Interior.",
			source = "https://warcraft.wiki.gg/wiki/Bogen's_Ledge",
		},
		["creeping ruin"] = {
			name = "Las Ruinas Abyectas",
			short = "Las Ruinas Abyectas yacen destrozadas en las Tierras del Interior, piedra a la que antaño dieron forma manos de trols del bosque. Ahora los lodos se arrastran por sus salones derrumbados y rezuman entre las viejas piedras trol por donde antes caminaban los trols.",
			full = "Las Ruinas Abyectas yacen destrozadas en las Tierras del Interior, piedra a la que antaño dieron forma manos de trols del bosque. Ahora los lodos se arrastran por sus salones derrumbados y rezuman entre las viejas piedras trol por donde antes caminaban los trols.",
			source = "https://warcraft.wiki.gg/wiki/Creeping_Ruin",
		},
		["featherbeards hovel"] = {
			name = "Cobertizo de Barbapluma",
			short = "Junto a Pico Nidal se alza una pequeña casa que perteneció a alguien llamado Barbapluma. No alberga guarnición ni tesoro alguno.",
			full = "Junto a Pico Nidal se alza una pequeña casa que perteneció a alguien llamado Barbapluma. No alberga guarnición ni tesoro alguno. Ya no sirve para nada más que para seguir en pie donde siempre ha estado, vacía de la vida que alguna vez la llenó.",
			source = "https://warcraft.wiki.gg/wiki/Featherbeard's_Hovel",
		},
		["hiriwatha"] = {
			name = "Hiri'watha",
			short = "Los trols Secacorteza ocupan Hiri'watha, una aldea situada al sur de la Avanzada Quel'Danil, en las Tierras del Interior, en lo profundo del bosque que consideran suyo.",
			full = "Los trols Secacorteza ocupan Hiri'watha, una aldea situada al sur de la Avanzada Quel'Danil, en las Tierras del Interior, en lo profundo del bosque que consideran suyo.",
			source = "https://warcraft.wiki.gg/wiki/Hiri'watha",
		},
		["jinthaalor"] = {
			name = "Jintha'Alor",
			short = "Jintha'Alor se alza en terrazas sobre las Tierras del Interior, y entre las ciudades de los trols del bosque solo Zul'Aman la supera en tamaño.",
			full = "Jintha'Alor se alza en terrazas sobre las Tierras del Interior, y entre las ciudades de los trols del bosque solo Zul'Aman la supera en tamaño. Se levantó en los días del Imperio Amani y lleva el nombre de Jintha, uno de los antiguos líderes de los Amani.\n\nLa ciudad pertenece a la tribu Vilrama, que ha convertido sus alturas en una fortaleza de sacrificio. La sacerdotisa vil Hexx gobierna allí al servicio de Hakkar el Desollador de Almas, y los Vilrama cazan sin piedad a la tribu Sañadiente, más débil, para saciar el hambre de su dios. El anciano Colmillopartido de los Sañadiente fue capturado en una de esas incursiones y aún permanece cautivo dentro de la ciudad; su capitán de la guardia, el cazador Malkhor, fue capturado en el mismo ataque y ejecutado, y sus restos fueron arrojados a los lobos y a los lodos que se guardan dentro de los muros.\n\nEl clan Martillo Salvaje y la tribu Sañadiente, unidos por un agravio común contra los Vilrama, han sitiado juntos la ciudad para poner fin a sus incursiones y vengar a sus muertos.",
			source = "https://warcraft.wiki.gg/wiki/Jintha'Alor",
		},
		["overlook cliffs"] = {
			name = "Los Acantilados Dominantes",
			short = "Los Acantilados Dominantes marcan el lugar donde las Tierras del Interior dejan de ser montañas y se convierten en cielo.",
			full = "Los Acantilados Dominantes marcan el lugar donde las Tierras del Interior dejan de ser montañas y se convierten en cielo. El gran río que serpentea por la región se concentra aquí y se precipita por el borde en una sola y enorme cascada que cae hasta la costa de abajo.\n\nLos acantilados son empinados y engañosamente altos. Muchos de los que se acercaron a su borde calcularon mal la caída y murieron.",
			source = "https://warcraft.wiki.gg/wiki/Overlook_Cliffs",
		},
		["plaguemist ravine"] = {
			name = "Barranco Bruma Enferma",
			short = "Una niebla flota donde la muralla de montañas se abre al oeste de la Avanzada Quel'Danil, señalando el barranco que se extiende hacia el norte, en dirección a Castel Darrow. En el paso no vive nada.",
			full = "Una niebla flota donde la muralla de montañas se abre al oeste de la Avanzada Quel'Danil, señalando el barranco que se extiende hacia el norte, en dirección a Castel Darrow. En el paso no vive nada. Ningún pájaro lo cruza, ninguna bestia tiene su guarida en sus rocas.\n\nLas Tierras del Interior que lo rodean siguen verdes y limpias, pero el barranco exhala otra cosa, una bruma que no pertenece al bosque. Por eso el lugar lleva hoy el nombre que lleva: Bruma Enferma, por la niebla enfermiza que corrompe este único sendero mientras el resto de la tierra permanece intacto.",
			source = "https://warcraft.wiki.gg/wiki/Plaguemist_Ravine",
		},
		["queldanil lodge"] = {
			name = "Avanzada Quel'Danil",
			short = "La Avanzada Quel'Danil es uno de los últimos verdaderos asentamientos de los altos elfos, el mayor de los dos únicos que quedan en Lordaeron.",
			full = "La Avanzada Quel'Danil es uno de los últimos verdaderos asentamientos de los altos elfos, el mayor de los dos únicos que quedan en Lordaeron. Después de la Tercera Guerra se convirtió en un lugar de correspondencia, desde donde sus embajadores tendían la mano a los demás pueblos de la Alianza. Aquel acercamiento les valió a los elfos de Highvale una alianza con los enanos Martillo Salvaje, y también el odio de los trols Sañadiente, que querían ver masacrados a los elfos y quemados sus archivos. Los documentos sobrevivieron: registros de muertes, nacimientos, estaciones y de todos los tratados que habían firmado los elfos.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Danil_Lodge",
		},
		["revantusk village"] = {
			name = "Poblado Sañadiente",
			short = "El Poblado Sañadiente se alza en la costa de las Tierras del Interior, el último hogar de una tribu de trols del bosque que eligió la lealtad por encima de la supervivencia.",
			full = "El Poblado Sañadiente se alza en la costa de las Tierras del Interior, el último hogar de una tribu de trols del bosque que eligió la lealtad por encima de la supervivencia.\n\nCuando la antigua Horda se desmoronó en la Segunda Guerra, los captores de los orcos se volvieron contra sus antiguos aliados, y las tribus de trols del bosque de toda la región abandonaron a la Horda sin dudarlo. Los Sañadiente no lo hicieron. No eran lo bastante numerosos para liberar a los orcos cautivos, que de todos modos mostraban pocas ganas de ser liberados, pero su lealtad continuada los convirtió en blanco de otros trols que no querían saber nada más de los orcos. Expulsados de sus tierras, los Sañadiente huyeron a la costa de las Tierras del Interior con la esperanza de que el aislamiento los mantuviera a salvo, y allí construyeron su poblado.\n\nCon el tiempo les llegó la noticia de que Thrall había rehecho la Horda y había devuelto a su pueblo a los caminos chamánicos de sus ancestros. Los Sañadiente enviaron a sus corredores más veloces a buscarlo, y de aquel encuentro nació un pacto de amistad entre la tribu y la nueva Horda. Los demás trols del bosque nunca lo han perdonado y llaman débiles y traicioneros a los Sañadiente, mientras que los Sañadiente consideran verdaderos traidores a todos los que abandonaron a la Horda.",
			source = "https://warcraft.wiki.gg/wiki/Revantusk_Village",
		},
		["seradane"] = {
			name = "Seradane",
			short = "En el noreste de las Tierras del Interior se encuentra Seradane, donde un gran portal circular se abre al Sueño Esmeralda. El bosque pertenece al Vuelo Verde, que acude a custodiar el umbral que su especie considera sagrado.",
			full = "En el noreste de las Tierras del Interior se encuentra Seradane, donde un gran portal circular se abre al Sueño Esmeralda. El bosque pertenece al Vuelo Verde, que acude a custodiar el umbral que su especie considera sagrado. Los dracos Rothos y Dreamtracker establecieron su hogar entre estos árboles.\n\nLa mayoría de quienes guardan el bosque son dracónidos, nacidos del poder del vuelo. Se mueven en grupos de tres, un oráculo verdantino flanqueado por guardarramas y celadores de los árboles, y patrullan los senderos enmarañados en una vigilancia permanente sobre el camino hacia el Sueño.",
			source = "https://warcraft.wiki.gg/wiki/Seradane",
		},
		["shadraalor"] = {
			name = "Shadra'Alor",
			short = "En las Tierras del Interior se alza Shadra'Alor, un asentamiento levantado por los trols del bosque del Imperio Amani. Aquí podía invocarse y hacerse descender al loa Shadra, un lugar reservado solo para ese propósito.",
			full = "En las Tierras del Interior se alza Shadra'Alor, un asentamiento levantado por los trols del bosque del Imperio Amani. Aquí podía invocarse y hacerse descender al loa Shadra, un lugar reservado solo para ese propósito.",
			source = "https://warcraft.wiki.gg/wiki/Shadra'Alor",
		},
		["shaolwatha"] = {
			name = "Shaol'watha",
			short = "Shaol'watha es una ruina de los trols del bosque Vilrama en el noreste de las Tierras del Interior. En otro tiempo fue un templo.",
			full = "Shaol'watha es una ruina de los trols del bosque Vilrama en el noreste de las Tierras del Interior. En otro tiempo fue un templo.",
			source = "https://warcraft.wiki.gg/wiki/Shaol'watha",
		},
		["shindiggers camp"] = {
			name = "Campamento Machacacanillas",
			short = "Rapsodio Machacacanillas, un enano aficionado a la bebida, tiene su pequeño campamento en las Tierras del Interior junto al alto elfo Gilveradin Cazasol, una extraña pareja que ocupa este tranquilo trozo de tierra.",
			full = "Rapsodio Machacacanillas, un enano aficionado a la bebida, tiene su pequeño campamento en las Tierras del Interior junto al alto elfo Gilveradin Cazasol, una extraña pareja que ocupa este tranquilo trozo de tierra.",
			source = "https://warcraft.wiki.gg/wiki/Shindigger's_Camp",
		},
		["skulk rock"] = {
			name = "Roca Oculta",
			short = "La Roca Oculta es una ruina de los trols del bosque invadida por lodos. Una cueva bajo ella es uno de los pocos lugares donde todavía crecen los hongos fantasma.",
			full = "La Roca Oculta es una ruina de los trols del bosque invadida por lodos. Una cueva bajo ella es uno de los pocos lugares donde todavía crecen los hongos fantasma.\n\nDurante la Segunda Guerra, la antigua Horda utilizó la roca como base, hasta que la Alianza de Lordaeron la expulsó.",
			source = "https://warcraft.wiki.gg/wiki/Skulk_Rock",
		},
		["valorwind lake"] = {
			name = "Lago Ventobravo",
			short = "El Lago Ventobravo descansa tranquilo al noreste de Shadra'Alor, con unas aguas en apariencia corrientes.",
			full = "El Lago Ventobravo descansa tranquilo al noreste de Shadra'Alor, con unas aguas en apariencia corrientes. Sin embargo, a lo largo de sus orillas crece algo que no se encuentra en ningún otro lugar conocido del mundo: el tragano violeta, un misterioso hongo que guarda sus secretos para sí.",
			source = "https://warcraft.wiki.gg/wiki/Valorwind_Lake",
		},
		["wildhammer keep"] = {
			name = "Fortaleza de los Martillo Salvaje",
			short = "La Fortaleza de los Martillo Salvaje se alza en el corazón de Pico Nidal, sede de los enanos Martillo Salvaje que la ocupan. Sus salones están abiertos a los viajeros que llegan a la cima.",
			full = "La Fortaleza de los Martillo Salvaje se alza en el corazón de Pico Nidal, sede de los enanos Martillo Salvaje que la ocupan. Sus salones están abiertos a los viajeros que llegan a la cima.",
			source = "https://warcraft.wiki.gg/wiki/Wildhammer_Keep",
		},
		["zunwatha"] = {
			name = "Zun'watha",
			short = "Las piedras de Zun'watha dieron refugio en otro tiempo, y aún lo dan, a los trols Secacorteza de las Tierras del Interior.",
			full = "Las piedras de Zun'watha dieron refugio en otro tiempo, y aún lo dan, a los trols Secacorteza de las Tierras del Interior. Entre las ruinas que dejaron en pie, de vez en cuando se ve a un Zul'arek hatefowler, que camina por donde todavía habitan los Secacorteza.",
			source = "https://warcraft.wiki.gg/wiki/Zun'watha",
		},
	},
	-- Dun Morogh: 25 subzones
	[1426] = {
		["amberstill ranch"] = {
			name = "Granja de Semperámbar",
			short = "La Granja de Semperámbar se encuentra junto al camino a Loch Modan, al norte de la Cantera de Gol'Bolar, donde los enanos de la familia Semperámbar crían sus rebaños frente al frío de Dun Morogh.",
			full = "La Granja de Semperámbar se encuentra junto al camino a Loch Modan, al norte de la Cantera de Gol'Bolar, donde los enanos de la familia Semperámbar crían sus rebaños frente al frío de Dun Morogh. Rudra Semperámbar cría aquí carneros muy apreciados, mientras que la joven Yarlyn tiene sus conejos de las nieves correteando a sus pies.\n\nLos rebaños no se han librado de problemas. Un wendigo llamado Vagash ha empezado a acechar a los animales de la granja, y los Semperámbar han tenido que defender lo que crían de su hambre.",
			source = "https://warcraft.wiki.gg/wiki/Amberstill_Ranch",
		},
		["anvilmar"] = {
			name = "Yunquemar",
			short = "En el Valle de Crestanevada se alza Yunquemar, un salón construido alrededor de una gran forja. Fue el primer asentamiento verdadero que los enanos levantaron en estas tierras del norte, un lugar de reunión antes de que surgiera cualquier otro.",
			full = "En el Valle de Crestanevada se alza Yunquemar, un salón construido alrededor de una gran forja. Fue el primer asentamiento verdadero que los enanos levantaron en estas tierras del norte, un lugar de reunión antes de que surgiera cualquier otro. La forja de su corazón aún arde, aunque ahora ningún herrero enseña allí su oficio.",
			source = "https://warcraft.wiki.gg/wiki/Anvilmar",
		},
		["brewnall village"] = {
			name = "Las Birras",
			short = "Las Birras se encuentra en el Valle Escalofrío, cerca de Gnomeregan, y es el hogar de la familia Cebadiz. Los Cebadiz se han entregado a una sola tarea: perfeccionar el arte enano de la cervecería.",
			full = "Las Birras se encuentra en el Valle Escalofrío, cerca de Gnomeregan, y es el hogar de la familia Cebadiz. Los Cebadiz se han entregado a una sola tarea: perfeccionar el arte enano de la cervecería. Envían a sus jóvenes fuera de la aldea para protegerla de los animales salvajes y buscar ingredientes raros para la cerveza definitiva.",
			source = "https://warcraft.wiki.gg/wiki/Brewnall_Village",
		},
		["chill breeze valley"] = {
			name = "Valle Escalofrío",
			short = "El Valle Escalofrío se extiende de este a oeste entre Gnomeregan y Kharanos, y su camino es bien conocido por los jóvenes enanos y gnomos que lo recorren.",
			full = "El Valle Escalofrío se extiende de este a oeste entre Gnomeregan y Kharanos, y su camino es bien conocido por los jóvenes enanos y gnomos que lo recorren. Pero el valle también se desvía hacia el norte y el sur, y allí la nieve cuenta otra historia: manchas de sangre que se extienden sobre el blanco y cadáveres de animales despedazados y abandonados. Pocos toman este ramal por voluntad propia. Quienes lo hacen van a cazar a las bestias responsables, con la esperanza de acabar con su amenaza para las tierras enanas, y muchos no regresan. En lo profundo de una de las cuevas tiene su guarida un wendigo, la criatura que más responsabilidad tiene en la sangre sobre la nieve.",
			source = "https://warcraft.wiki.gg/wiki/Chill_Breeze_Valley",
		},
		["coldridge pass"] = {
			name = "Desfiladero de Crestanevada",
			short = "El Desfiladero de Crestanevada es la estrecha salida del Valle de Crestanevada, el último tramo que un enano debe cruzar antes de llegar a Kharanos y a los caminos más amplios de Dun Morogh.",
			full = "El Desfiladero de Crestanevada es la estrecha salida del Valle de Crestanevada, el último tramo que un enano debe cruzar antes de llegar a Kharanos y a los caminos más amplios de Dun Morogh. Los troggs han invadido el paso, y a los viajeros solo les quedan dos opciones: atravesarlo tan rápido como les permitan las piernas o abrirse un camino sangriento entre los invasores.\n\nFendrig Redbeard condujo en una ocasión a otros doce mineros al paso para investigar la infestación. En lo más profundo, quedó atrapado bajo un derrumbe de piedras. Los demás volvieron para desenterrarlo, pero el esfuerzo hizo que el paso se derrumbara sobre ellos. Murieron doce mineros. Solo Fendrig, sacado de entre los escombros, sobrevivió.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Pass",
		},
		["coldridge valley"] = {
			name = "Valle de Crestanevada",
			short = "La nieve cubre espesa el Valle de Crestanevada, cerrado por todos lados, y su única salida es el estrecho túnel del Desfiladero de Crestanevada, al noreste.",
			full = "La nieve cubre espesa el Valle de Crestanevada, cerrado por todos lados, y su única salida es el estrecho túnel del Desfiladero de Crestanevada, al noreste. Ese pasaje está infestado de asaltantes troggs, criaturas brutales que desde hace mucho hacen peligroso el cruce hacia Kharanos y Forjaz para cualquiera que viaje solo.\n\nMás allá del paso, el camino sube hacia el este y luego hacia el norte a través de Kharanos, antes de serpentear por las montañas hasta las mismas puertas de Forjaz.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Valley",
		},
		["frostmane hold"] = {
			name = "Poblado Peloescarcha",
			short = "El Poblado Peloescarcha se encuentra en el extremo occidental de las frías montañas de Dun Morogh, al sur de Gnomeregan: un grupo disperso de construcciones unidas a un sistema de cuevas excavado en la ladera.",
			full = "El Poblado Peloescarcha se encuentra en el extremo occidental de las frías montañas de Dun Morogh, al sur de Gnomeregan: un grupo disperso de construcciones unidas a un sistema de cuevas excavado en la ladera. Es el campamento base de los trols de hielo Peloescarcha, que defienden el terreno con cazadores de cabezas y desolladores que vigilan cada acceso.",
			source = "https://warcraft.wiki.gg/wiki/Frostmane_Hold",
		},
		["gates of ironforge"] = {
			name = "Puertas de Forjaz",
			short = "Las Puertas de Forjaz se alzan donde la gran rampa de Dun Morogh sube al encuentro de la montaña, visibles a kilómetros de distancia sobre la nieve mucho antes de que un viajero llegue a ellas.",
			full = "Las Puertas de Forjaz se alzan donde la gran rampa de Dun Morogh sube al encuentro de la montaña, visibles a kilómetros de distancia sobre la nieve mucho antes de que un viajero llegue a ellas. Son el umbral entre las tierras enanas abiertas y la propia Forjaz.\n\nAl cruzarlas, uno queda bajo la mirada de una enorme estatua erigida en honor al gran rey Modimus Yunquemar, colocada para vigilar justo detrás de la entrada, de modo que nadie entre en la ciudad sin pasar antes bajo sus ojos.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
		["gnomeregan"] = {
			name = "Gnomeregan",
			short = "Gnomeregan es la capital subterránea del reino gnomo del mismo nombre, una prueba en hierro forjado de la brillantez, la ambición y el ingenio de los gnomos.",
			full = "Gnomeregan es la capital subterránea del reino gnomo del mismo nombre, una prueba en hierro forjado de la brillantez, la ambición y el ingenio de los gnomos.\n\nDurante la Tercera Guerra, una invasión de troggs provocó su caída. Los troggs habían despertado de su letargo por la agitación de los emplazamientos de los titanes, y subieron en tropel a la ciudad desde abajo. En un intento desesperado por acabar con los invasores, el Manitas Mayor Gelbin Mekkatorque, por consejo de su asesor Sicco Termochufe, ordenó a su pueblo abrir las válvulas de presión de sus gigantescas máquinas trituradoras y liberar radiación tóxica por todo Gnomeregan. Aunque el gas mató a algunos troggs, solo fortaleció a otros, y casi el ochenta por ciento de los gnomos murió en cuestión de días. Los supervivientes huyeron a la protección de Forjaz. Otros se transformaron en horribles gnomos leprosos, sin mente y malvados, que todavía rondan los túneles en ruinas.\n\nEnloquecido él mismo por la radiación, Termochufe se proclamó \"rey de Gnomeregan\" y se apoderó de la ciudad envenenada, al frente de un ejército de troggs y gnomos leprosos que recorre sus salones y talleres destrozados.",
			source = "https://warcraft.wiki.gg/wiki/Gnomeregan",
		},
		["golbolar quarry"] = {
			name = "Cantera de Gol'Bolar",
			short = "La Cantera de Gol'Bolar está excavada en el sureste de Dun Morogh, un campamento minero interrumpido por lo que salió arrastrándose desde debajo.",
			full = "La Cantera de Gol'Bolar está excavada en el sureste de Dun Morogh, un campamento minero interrumpido por lo que salió arrastrándose desde debajo. Los enanos abrieron la excavación en busca de lo que guardaba la montaña, pero la excavación despertó a los troggs, que subieron en tropel desde las profundidades de la mina e invadieron los pozos y túneles que los mineros habían abierto.\n\nEl campamento que queda es un punto de apoyo, no una victoria: los enanos dominan la superficie mientras que la mina de abajo sigue perdida en manos de los troggs.",
			source = "https://warcraft.wiki.gg/wiki/Gol'Bolar_Quarry",
		},
		["grizzled den"] = {
			name = "El Cubil Pardo",
			short = "Un gran sistema de cuevas se abre al suroeste de Kharanos y se adentra en el hielo de Dun Morogh. Los wendigos han establecido aquí su guarida, bestias peludas de aliento helado que se agrupan contra cualquiera que invada su territorio.",
			full = "Un gran sistema de cuevas se abre al suroeste de Kharanos y se adentra en el hielo de Dun Morogh. Los wendigos han establecido aquí su guarida, bestias peludas de aliento helado que se agrupan contra cualquiera que invada su territorio. Sus crines son muy apreciadas para cubrir asientos, aunque pocos de los que entran a por ellas salen sin pelear, pues los wendigos no se dispersan, sino que cierran filas y expulsan a los intrusos con garras y aliento helado.",
			source = "https://warcraft.wiki.gg/wiki/Grizzled_Den",
		},
		["helms bed lake"] = {
			name = "Lago de Helm",
			short = "El Lago de Helm permanece congelado la mayor parte del año, con la superficie cubierta por una capa de hielo lo bastante gruesa para cruzarla sin peligro. Solo se mantiene abierto un único agujero, cortado para que todavía pueda sacarse agua dulce de debajo de la escarcha.",
			full = "El Lago de Helm permanece congelado la mayor parte del año, con la superficie cubierta por una capa de hielo lo bastante gruesa para cruzarla sin peligro. Solo se mantiene abierto un único agujero, cortado para que todavía pueda sacarse agua dulce de debajo de la escarcha.\n\nLa seguridad termina en la orilla. Lobos y otras criaturas salvajes recorren las riberas, y troggs extraviados rondan las rocas circundantes. Al sur del lago se alza un edificio abandonado reclamado por enanos Hierro Negro, que atacan a cualquiera que se acerque demasiado.",
			source = "https://warcraft.wiki.gg/wiki/Helm's_Bed_Lake",
		},
		["iceflow lake"] = {
			name = "Lago Glacial",
			short = "El Lago Glacial se congela por completo con el frío de Dun Morogh, pero los enanos de Las Birras mantienen un agujero abierto en el hielo para sacar agua dulce y peces de debajo de la superficie helada.",
			full = "El Lago Glacial se congela por completo con el frío de Dun Morogh, pero los enanos de Las Birras mantienen un agujero abierto en el hielo para sacar agua dulce y peces de debajo de la superficie helada.\n\nHacia el centro del lago se alzan un par de islas que es mejor dejar en paz. Una manada de lobos hambrientos las ha reclamado, al mando de un huargo llamado Timber, y su presencia mantiene las islas vacías de todo salvo de las bestias que las ocupan.",
			source = "https://warcraft.wiki.gg/wiki/Iceflow_Lake",
		},
		["ironbands compound"] = {
			name = "Complejo Vetaferro",
			short = "Al sur del Lago de Helm, el Complejo Vetaferro es un punto de apoyo de los enanos Hierro Negro, que atacan a cualquiera que se acerque demasiado. El lugar perteneció en otro tiempo a Sturgy Vetaferro, antes de caer en manos de los Hierro Negro.",
			full = "Al sur del Lago de Helm, el Complejo Vetaferro es un punto de apoyo de los enanos Hierro Negro, que atacan a cualquiera que se acerque demasiado. El lugar perteneció en otro tiempo a Sturgy Vetaferro, antes de caer en manos de los Hierro Negro.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Compound",
		},
		["kharanos"] = {
			name = "Kharanos",
			short = "Kharanos se encuentra entre los picos montañosos de Dun Morogh, con sus calles rodeadas de tierras salvajes invernales que nunca permiten que su gente se ablande.",
			full = "Kharanos se encuentra entre los picos montañosos de Dun Morogh, con sus calles rodeadas de tierras salvajes invernales que nunca permiten que su gente se ablande. En su corazón arde una forja, un taller gnomo traquetea sin descanso y la Destilería Cebatruenos sirve algunas de las mejores cervezas que pueden encontrarse en cualquier parte, pero el pueblo nunca ha podido descansar tranquilo en su encanto. Al oeste hay una caverna llena de wendigos, y al noroeste los trols Peloescarcha ocupan Monte Luz, desde donde vigilan el pueblo.\n\nEsa vigilancia se convirtió una vez en guerra, cuando un trol Peloescarcha gigante cayó sobre Kharanos y estuvo a punto de acabar con todos los enanos que vivían allí. Donde los defensores del pueblo flaquearon, un enano no lo hizo. Lazlo Grindwidget se enfrentó al trol y lo derribó él solo, y por ello el pueblo lo proclamó héroe, un título que lo acompaña desde entonces por unas calles que recuerdan lo cerca que estuvieron de quedar en silencio.",
			source = "https://warcraft.wiki.gg/wiki/Kharanos",
		},
		["misty pine refuge"] = {
			name = "Refugio Pinobruma",
			short = "El Refugio Pinobruma descansa tranquilo en el centro de Dun Morogh, un claro resguardado entre pinos cargados de nieve.",
			full = "El Refugio Pinobruma descansa tranquilo en el centro de Dun Morogh, un claro resguardado entre pinos cargados de nieve.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Pine_Refuge",
		},
		["north gate outpost"] = {
			name = "Avanzada de la Puerta Norte",
			short = "La Avanzada de la Puerta Norte se encuentra sobre el Paso de la Puerta Norte, el estrecho camino a través de las montañas que une Dun Morogh con Loch Modan, y es el más nororiental de los enclaves enanos de estas tierras altas.",
			full = "La Avanzada de la Puerta Norte se encuentra sobre el Paso de la Puerta Norte, el estrecho camino a través de las montañas que une Dun Morogh con Loch Modan, y es el más nororiental de los enclaves enanos de estas tierras altas.\n\nLos montaraces destacados aquí pasan sus días haciendo retroceder a la fauna que avanza desde los picos circundantes. Algunos de los que salieron a cazar a las bestias más peligrosas no han regresado, y se han recorrido las montañas en busca de noticias suyas, sin demasiados resultados.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Outpost",
		},
		["north gate pass"] = {
			name = "Paso de la Puerta Norte",
			short = "El paso atraviesa las altas montañas y desciende desde Dun Morogh hacia Loch Modan.",
			full = "El paso atraviesa las altas montañas y desciende desde Dun Morogh hacia Loch Modan. Es el camino más corto entre ambos, y los viajeros que se dirigen a las tierras más allá del lago pasan por aquí más que por ningún otro sitio.\n\nLa Avanzada de la Puerta Norte monta guardia aquí y controla el paso.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["shimmer ridge"] = {
			name = "Monte Luz",
			short = "Monte Luz se alza en el norte de Dun Morogh, en manos de los trols Peloescarcha, que mantienen dos campamentos unidos por un puente, donde cultivan cardaluz y doman jabalíes entre las rocas.",
			full = "Monte Luz se alza en el norte de Dun Morogh, en manos de los trols Peloescarcha, que mantienen dos campamentos unidos por un puente, donde cultivan cardaluz y doman jabalíes entre las rocas.",
			source = "https://warcraft.wiki.gg/wiki/Shimmer_Ridge",
		},
		["south gate outpost"] = {
			name = "Avanzada de la Puerta Sur",
			short = "La Avanzada de la Puerta Sur se encuentra donde el paso se estrecha entre Dun Morogh y Loch Modan, un cuello de botella de piedra defendido por montaraces enanos.",
			full = "La Avanzada de la Puerta Sur se encuentra donde el paso se estrecha entre Dun Morogh y Loch Modan, un cuello de botella de piedra defendido por montaraces enanos. Su trabajo es más tranquilo que el de sus parientes de la Puerta Norte: han hecho retroceder a la fauna que antes presionaba sobre el paso, y el camino que lo atraviesa sigue abierto y seguro para quienes van o vienen de Thelsamar.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Outpost",
		},
		["south gate pass"] = {
			name = "Paso de la Puerta Sur",
			short = "El Paso de la Puerta Sur atraviesa las montañas y une las altas nieves de Dun Morogh con los valles más bajos de Loch Modan. Es el camino más corto para bajar a Thelsamar, desgastado por los viajeros que van de una tierra a otra.",
			full = "El Paso de la Puerta Sur atraviesa las montañas y une las altas nieves de Dun Morogh con los valles más bajos de Loch Modan. Es el camino más corto para bajar a Thelsamar, desgastado por los viajeros que van de una tierra a otra.\n\nAquí se alza la Avanzada de la Puerta Sur, un puesto de guardia destinado a vigilar el paso.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["steelgrills depot"] = {
			name = "Almacén de Brasacerada",
			short = "El Almacén de Brasacerada se encuentra al este de Kharanos, un pequeño campamento de mineros e ingenieros que trabajan el suelo helado de Dun Morogh.",
			full = "El Almacén de Brasacerada se encuentra al este de Kharanos, un pequeño campamento de mineros e ingenieros que trabajan el suelo helado de Dun Morogh.",
			source = "https://warcraft.wiki.gg/wiki/Steelgrill's_Depot",
		},
		["thunderbrew distillery"] = {
			name = "Destilería Cebatruenos",
			short = "La Destilería Cebatruenos se encuentra en Kharanos, y su nombre es conocido mucho más allá del pueblo enano por la calidad de su cerveza. El tabernero Belm lleva el local y ofrece descanso y bebida a quienes pasan por allí.",
			full = "La Destilería Cebatruenos se encuentra en Kharanos, y su nombre es conocido mucho más allá del pueblo enano por la calidad de su cerveza. El tabernero Belm lleva el local y ofrece descanso y bebida a quienes pasan por allí.",
			source = "https://warcraft.wiki.gg/wiki/Thunderbrew_Distillery",
		},
		["tundrid hills"] = {
			name = "Las Colinas Tundra",
			short = "Las Colinas Tundra se encuentran al sur de la Cantera de Gol'Bolar, una extensión de terreno azotado por el viento donde pocos viajan sin un arma en la mano.",
			full = "Las Colinas Tundra se encuentran al sur de la Cantera de Gol'Bolar, una extensión de terreno azotado por el viento donde pocos viajan sin un arma en la mano. Lobos y otras criaturas salvajes merodean por las laderas, y quienes cruzan las colinas para atajar entre el Valle de Crestanevada y el este de Dun Morogh lo hacen sabiendo que el camino por Kharanos habría sido más seguro.\n\nLos trols Peloescarcha han levantado un campamento en el valle de aquí, y ocupan este terreno a la vista de la cantera de los enanos.",
			source = "https://warcraft.wiki.gg/wiki/Tundrid_Hills",
		},
	},
	-- La Garganta de Fuego: 11 subzones
	[1427] = {
		["blackchar cave"] = {
			name = "Cueva Tizonegro",
			short = "La Cueva Tizonegro permanece sellada cerca de la Montaña Roca Negra, con su piedra oscura en silencio y aislada del mundo exterior.",
			full = "La Cueva Tizonegro permanece sellada cerca de la Montaña Roca Negra, con su piedra oscura en silencio y aislada del mundo exterior.",
			source = "https://warcraft.wiki.gg/wiki/Blackchar_Cave",
		},
		["blackrock mountain"] = {
			name = "Montaña Roca Negra",
			short = "La Montaña Roca Negra no nació de un fuego corriente.",
			full = "La Montaña Roca Negra no nació de un fuego corriente. Cuando los ejércitos Barbabronce y Martillo Salvaje marcharon para acabar con el clan Hierro Negro durante la guerra de los Tres Martillos, el hechicero y señor feudal Thaurissan alcanzó el corazón fundido del mundo y arrastró su poder hacia la superficie como arma. Lo que le respondió fue Ragnaros. El renacimiento del Señor del Fuego desgarró las montañas, ahogó en fuego la tierra circundante e hizo que ambos reyes dieran media vuelta con sus ejércitos antes que enfrentarse a él. Donde antes se alzaba el reino Hierro Negro, ahora humeaba un volcán, con las Estepas Ardientes al sur y la Garganta de Fuego al norte. Ragnaros se retiró al núcleo de la montaña y esclavizó a los enanos Hierro Negro supervivientes para que excavaran la Ciudad Forjatiniebla bajo su propio hogar en ruinas.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["cauldron"] = {
			name = "La Caldera",
			short = "La Caldera es una enorme excavación abierta en el centro de la Garganta de Fuego, fortificada por los enanos Hierro Negro algún tiempo después de invocar a Ragnaros.",
			full = "La Caldera es una enorme excavación abierta en el centro de la Garganta de Fuego, fortificada por los enanos Hierro Negro algún tiempo después de invocar a Ragnaros. Las grandes máquinas que usaron para abrirla todavía rodean sus bordes. Abajo, elementales de fuego y de magma se mueven por las grietas resquebrajadas y resplandecientes.\n\nLos esclavos capturados por los Hierro Negro trabajan allí abajo sin fin, quebrados por el trabajo y el calor sofocante. Ya no distinguen al amigo del captor, y reciben a cualquiera que entre con la misma violencia insensata que cualquier capataz.",
			source = "https://warcraft.wiki.gg/wiki/Cauldron",
		},
		["dustfire valley"] = {
			name = "Valle Polvofuego",
			short = "El Valle Polvofuego atraviesa la Garganta de Fuego, un terreno azotado por el viento que lleva al norte hasta las puertas del Paso de Fraguapiedra y, más allá, hasta el Valle de los Reyes en Loch Modan.",
			full = "El Valle Polvofuego atraviesa la Garganta de Fuego, un terreno azotado por el viento que lleva al norte hasta las puertas del Paso de Fraguapiedra y, más allá, hasta el Valle de los Reyes en Loch Modan.",
			source = "https://warcraft.wiki.gg/wiki/Dustfire_Valley",
		},
		["firewatch ridge"] = {
			name = "Cresta Vigía",
			short = "La Cresta Vigía es el campamento principal de los enanos Hierro Negro en la Garganta de Fuego, con vistas a la gran excavación de La Caldera.",
			full = "La Cresta Vigía es el campamento principal de los enanos Hierro Negro en la Garganta de Fuego, con vistas a la gran excavación de La Caldera. Los enanos Hierro Negro dominan las laderas con gólems mecánicos y arañas de fuego gigantes, lo que convierte la cresta en un lugar peligroso.",
			source = "https://warcraft.wiki.gg/wiki/Firewatch_Ridge",
		},
		["grimesilt dig site"] = {
			name = "Excavación de Limugre",
			short = "Los enanos de Forjaz excavaron aquí en otro tiempo, hasta que llegaron los enanos Hierro Negro y se apoderaron del lugar. Sigue en manos de los Hierro Negro.",
			full = "Los enanos de Forjaz excavaron aquí en otro tiempo, hasta que llegaron los enanos Hierro Negro y se apoderaron del lugar. Sigue en manos de los Hierro Negro.",
			source = "https://warcraft.wiki.gg/wiki/Grimesilt_Dig_Site",
		},
		["sea of cinders"] = {
			name = "El Mar de las Cenizas",
			short = "El Mar de las Cenizas se extiende llano y abierto en el sur de la Garganta de Fuego, justo al norte de la Montaña Roca Negra. Allí no crece nada.",
			full = "El Mar de las Cenizas se extiende llano y abierto en el sur de la Garganta de Fuego, justo al norte de la Montaña Roca Negra. Allí no crece nada. El suelo sigue humeando, y la ceniza se eleva constantemente con el viento y se desliza por las llanuras yermas. El fuego y el viento no dejaron nada más que desolación, y el incendio nunca se ha detenido.",
			source = "https://warcraft.wiki.gg/wiki/Sea_of_Cinders",
		},
		["slag pit"] = {
			name = "La Fosa de la Escoria",
			short = "La Fosa de la Escoria se hunde en lo profundo de la excavación de La Caldera, en la Garganta de Fuego, trabajada por esclavos bajo la crueldad de los enanos Hierro Negro.",
			full = "La Fosa de la Escoria se hunde en lo profundo de la excavación de La Caldera, en la Garganta de Fuego, trabajada por esclavos bajo la crueldad de los enanos Hierro Negro. Negreros y capataces impulsan el trabajo, e incluso los trabajadores sometidos se vuelven contra cualquiera que ataque a sus vigilantes. Los Hierro Negro responden con abierta hostilidad a cualquier interferencia en su minería, y en la oscuridad más profunda de la fosa anidan voraces incendosaurios entre las excavaciones.",
			source = "https://warcraft.wiki.gg/wiki/Slag_Pit",
		},
		["stonewrought pass"] = {
			name = "Paso de Fraguapiedra",
			short = "El túnel conocido como el Paso de Fraguapiedra atraviesa las montañas y une la Garganta de Fuego con el Valle de los Reyes en Loch Modan, en el extremo norte del Valle Polvofuego.",
			full = "El túnel conocido como el Paso de Fraguapiedra atraviesa las montañas y une la Garganta de Fuego con el Valle de los Reyes en Loch Modan, en el extremo norte del Valle Polvofuego. Es obra de Franclorn Forjador, que también levantó la Presa de las Tres Cabezas y buena parte de la cantería enana de los Reinos del Este.\n\nEl montaraz Guijarro mantiene cerrada la puerta de Loch Modan, y cierra el paso a todos salvo a quienes han demostrado su valía contra Margol el Rabioso.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Pass",
		},
		["tanner camp"] = {
			name = "Base de Peleteros",
			short = "Sarah Peletera, maestra de la peletería elemental, tiene una tienda solitaria en la Garganta de Fuego. Detrás de ella, un largo pasaje se adentra serpenteando en la montaña y termina donde aguarda el truenagarto Margol el Rabioso.",
			full = "Sarah Peletera, maestra de la peletería elemental, tiene una tienda solitaria en la Garganta de Fuego. Detrás de ella, un largo pasaje se adentra serpenteando en la montaña y termina donde aguarda el truenagarto Margol el Rabioso.",
			source = "https://warcraft.wiki.gg/wiki/Tanner_Camp",
		},
		["thorium point"] = {
			name = "Puesto del Torio",
			short = "En el norte abrasado de la Garganta de Fuego se alza el Puesto del Torio, un pequeño pueblo neutral en manos de la Hermandad del Torio, habitado sobre todo por enanos Hierro Negro fieles a la Hermandad y no a los poderes oscuros que hay bajo las montañas.",
			full = "En el norte abrasado de la Garganta de Fuego se alza el Puesto del Torio, un pequeño pueblo neutral en manos de la Hermandad del Torio, habitado sobre todo por enanos Hierro Negro fieles a la Hermandad y no a los poderes oscuros que hay bajo las montañas. Aquí hay una forja y un yunque siempre listos, encendidos entre la ceniza y el calor, donde todavía se trabaja el metal a pesar de aquello en lo que se ha convertido la Garganta.",
			source = "https://warcraft.wiki.gg/wiki/Thorium_Point",
		},
	},
	-- Las Estepas Ardientes: 11 subzones
	[1428] = {
		["blackrock mountain"] = {
			name = "Montaña Roca Negra",
			short = "La Montaña Roca Negra no nació de un fuego corriente.",
			full = "La Montaña Roca Negra no nació de un fuego corriente. Cuando los ejércitos Barbabronce y Martillo Salvaje marcharon para acabar con el clan Hierro Negro durante la guerra de los Tres Martillos, el hechicero y señor feudal Thaurissan alcanzó el corazón fundido del mundo y arrastró su poder hacia la superficie como arma. Lo que le respondió fue Ragnaros. El renacimiento del Señor del Fuego desgarró las montañas, ahogó en fuego la tierra circundante e hizo que ambos reyes dieran media vuelta con sus ejércitos antes que enfrentarse a él. Donde antes se alzaba el reino Hierro Negro, ahora humeaba un volcán, con las Estepas Ardientes al sur y la Garganta de Fuego al norte. Ragnaros se retiró al núcleo de la montaña y esclavizó a los enanos Hierro Negro supervivientes para que excavaran la Ciudad Forjatiniebla bajo su propio hogar en ruinas.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["blackrock pass"] = {
			name = "Desfiladero de Roca Negra",
			short = "El Desfiladero de Roca Negra es el umbral entre dos mundos. A un lado se encuentra Crestagrana, verde y tranquila. Al otro esperan las Estepas Ardientes, abrasadas y retorcidas hasta volverse irreconocibles.",
			full = "El Desfiladero de Roca Negra es el umbral entre dos mundos. A un lado se encuentra Crestagrana, verde y tranquila. Al otro esperan las Estepas Ardientes, abrasadas y retorcidas hasta volverse irreconocibles. Una puerta se alza en la frontera y marca la línea con claridad.\n\nCruzarla es dejar atrás la seguridad en un solo paso. Quienes la atraviesan sin estar preparados descubren que el cambio es brutal: las criaturas del otro lado son mucho más crueles que cualquier cosa que se mueva en las montañas que quedan atrás.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Pass",
		},
		["blackrock stronghold"] = {
			name = "Bastión de Roca Negra",
			short = "El bastión se alza en el límite de las Estepas Ardientes, pegado a la sombra de la Cumbre de Roca Negra: una fortaleza de piedra negra en manos del clan Roca Negra.",
			full = "El bastión se alza en el límite de las Estepas Ardientes, pegado a la sombra de la Cumbre de Roca Negra: una fortaleza de piedra negra en manos del clan Roca Negra. Fuera de sus muros, en los Campos de Honor, los guerreros del clan y sus aliados se reúnen y entrenan, mantenidos a raya por el látigo y la voz de los sargentos Roca Negra.\n\nEl mando del bastión recae en el general Thorg'izog, que disciplina a las tropas reunidas en los campos y se asegura de que sus órdenes se cumplan sin cuestionarlas.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Stronghold",
		},
		["dracodar"] = {
			name = "Draco'dar",
			short = "Las colinas de Draco'dar yacen ennegrecidas y abrasadas, entregadas por completo al Vuelo Negro. Los de su especie se mueven libremente por el terreno, en número tal que nadie debería adentrarse en él sin precaución y sin compañía.",
			full = "Las colinas de Draco'dar yacen ennegrecidas y abrasadas, entregadas por completo al Vuelo Negro. Los de su especie se mueven libremente por el terreno, en número tal que nadie debería adentrarse en él sin precaución y sin compañía.",
			source = "https://warcraft.wiki.gg/wiki/Draco'dar",
		},
		["dreadmaul rock"] = {
			name = "Roca Machacamiedo",
			short = "La Roca Machacamiedo es un bastión de senderos de piedra y montículos de ogros ahuecados, sede del clan Pirontraña.",
			full = "La Roca Machacamiedo es un bastión de senderos de piedra y montículos de ogros ahuecados, sede del clan Pirontraña. Desde sus alturas y túneles, los Pirontraña lanzan sus incursiones hacia el sur, hacia las Montañas Crestagrana, usando la roca como base antes de replegarse de nuevo a sus profundidades.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Rock",
		},
		["flame crest"] = {
			name = "Peñasco Llamarada",
			short = "El Peñasco Llamarada se encuentra sobre un saliente desnudo de las Estepas Ardientes, al que solo se llega por un tosco puente. En la pequeña cueva de su parte trasera vive Kibler, que tiene un loro muy parlanchín.",
			full = "El Peñasco Llamarada se encuentra sobre un saliente desnudo de las Estepas Ardientes, al que solo se llega por un tosco puente. En la pequeña cueva de su parte trasera vive Kibler, que tiene un loro muy parlanchín.",
			source = "https://warcraft.wiki.gg/wiki/Flame_Crest",
		},
		["morgans vigil"] = {
			name = "Vigilia de Morgan",
			short = "La Vigilia de Morgan yace en ruinas en el sureste de las Estepas Ardientes, con sus casas quemadas hasta los cimientos y su torre de magos reducida a escombros.",
			full = "La Vigilia de Morgan yace en ruinas en el sureste de las Estepas Ardientes, con sus casas quemadas hasta los cimientos y su torre de magos reducida a escombros. Entre los restos se alzan tiendas que dan cobijo a quienes quedan.\n\nDesde estas tiendas, la Alianza vigila la Montaña Roca Negra y ataca el peligro más cerca de su origen.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Vigil",
		},
		["pillar of ash"] = {
			name = "El Pilar de Ceniza",
			short = "Una alta torre de piedra calcinada se alza en el extremo oriental de la Choza Diente Negro, con la superficie ennegrecida como si el propio fuego hubiera trepado por ella y se hubiera detenido.",
			full = "Una alta torre de piedra calcinada se alza en el extremo oriental de la Choza Diente Negro, con la superficie ennegrecida como si el propio fuego hubiera trepado por ella y se hubiera detenido. Nada crece a su alrededor, y nada más se alza tan alto aquí.",
			source = "https://warcraft.wiki.gg/wiki/Pillar_of_Ash",
		},
		["ruins of thaurissan"] = {
			name = "Ruinas de Thaurissan",
			short = "Antaño, estas llanuras cenicientas de las Estepas Ardientes eran verdes, y la ciudad que había aquí llevaba el nombre de su fundador: la Ciudad de Thaurissan, capital del clan Hierro Negro, exiliado de Forjaz y conducido al sur por el hechicero y señor feudal Thaurissan durante la guerra de los Tres Martillos.",
			full = "Antaño, estas llanuras cenicientas de las Estepas Ardientes eran verdes, y la ciudad que había aquí llevaba el nombre de su fundador: la Ciudad de Thaurissan, capital del clan Hierro Negro, exiliado de Forjaz y conducido al sur por el hechicero y señor feudal Thaurissan durante la guerra de los Tres Martillos.\n\nLos Hierro Negro estaban perdiendo aquella guerra. Su ejército acababa de ser derrotado frente a los bastiones de los otros dos clanes cuando Thaurissan, desesperado por cambiar el rumbo, reunió a siete de sus enanos de mayor confianza e invocó a los poderes que dormían bajo la tierra en busca de un sirviente que les devolviera la victoria. Lo que respondió no fue un sirviente, sino Ragnaros, Señor Elemental del Fuego, y su llegada partió las montañas con un volcán que redujo el valle a cenizas. La ciudad fue aniquilada, y los Hierro Negro supervivientes quedaron esclavizados al Señor del Fuego. Abandonaron las ruinas y construyeron un nuevo hogar bajo la Montaña Roca Negra, y de las cenizas de Thaurissan surgieron la Cumbre de Roca Negra y una nueva nación Hierro Negro.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Thaurissan",
		},
		["slither rock"] = {
			name = "Roca Desliz",
			short = "La Roca Desliz es una pequeña cueva oculta más allá de la Senda del Ala del Terror, en el extremo noreste de las Estepas Ardientes.",
			full = "La Roca Desliz es una pequeña cueva oculta más allá de la Senda del Ala del Terror, en el extremo noreste de las Estepas Ardientes. Da refugio al dracónido negro Cyrus Therepentous, que ayuda a otros contra un enemigo común, aunque nunca sin comentarios groseros y burlones.",
			source = "https://warcraft.wiki.gg/wiki/Slither_Rock",
		},
		["terror wing path"] = {
			name = "Senda del Ala del Terror",
			short = "La Senda del Ala del Terror es un valle en el este de las Estepas Ardientes, entregado por completo al Vuelo Negro. Crías y dragonantes anidan entre sus rocas y cenizas.",
			full = "La Senda del Ala del Terror es un valle en el este de las Estepas Ardientes, entregado por completo al Vuelo Negro. Crías y dragonantes anidan entre sus rocas y cenizas.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Wing_Path",
		},
	},
	-- Bosque de Elwynn: 23 subzones
	[1429] = {
		["brackwell pumpkin patch"] = {
			name = "Plantación de Calabazas de Brackwell",
			short = "En el sureste del Bosque de Elwynn se alza una granja que perteneció en otro tiempo a la familia Brackwell. Nadie sabe qué fue de ellos.",
			full = "En el sureste del Bosque de Elwynn se alza una granja que perteneció en otro tiempo a la familia Brackwell. Nadie sabe qué fue de ellos. La Hermandad Defias se apoderó del lugar, y los Brackwell simplemente desaparecieron de sus campos y sus cercas.\n\nDe ellos solo queda un recuerdo: una cerda premiada llamada Princesa, que engordó enormemente con las verduras que robaba colándose noche tras noche en la vecina Granja Pedregosa, mucho antes de que llegaran los bandidos.",
			source = "https://warcraft.wiki.gg/wiki/Brackwell_Pumpkin_Patch",
		},
		["crystal lake"] = {
			name = "Lago de Cristal",
			short = "El Lago de Cristal se encuentra al este de Villadorada, y sus aguas están llenas de múrlocs que hacen de la orilla un mal lugar para los incautos. Una granja humana vigila el agua desde la orilla sur.",
			full = "El Lago de Cristal se encuentra al este de Villadorada, y sus aguas están llenas de múrlocs que hacen de la orilla un mal lugar para los incautos. Una granja humana vigila el agua desde la orilla sur.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Lake",
		},
		["eastvale logging camp"] = {
			name = "Aserradero de la Vega del Este",
			short = "Los campamentos madereros de la Vega del Este se reparten por el este de Elwynn, con sus viviendas tendidas entre los fosos de aserrado, y el trabajo nunca se detiene del todo.",
			full = "Los campamentos madereros de la Vega del Este se reparten por el este de Elwynn, con sus viviendas tendidas entre los fosos de aserrado, y el trabajo nunca se detiene del todo. Los pedidos de madera llegan más rápido de lo que permiten los plazos, y los leñadores trabajan bajo la presión constante de compradores que esperan la madera de Ventormenta.\n\nEl mariscal Haggard, que antes dirigía la Guardia de Ventormenta, se retiró de ese mando hace unos años y eligió pasar el resto de sus días en una mansión dentro del campamento, en lugar de en la ciudad que antaño defendió. Ceya Northbrooke también se crio aquí.\n\nEl bosque aprieta por todos lados, y su naturaleza salvaje no es poca cosa. Lobos y osos han acosado a los leñadores, dispersando a las cuadrillas y amenazando con echar por tierra los plazos del campamento. El problema se agravó tanto que la Guardia de Ventormenta se vio obligada a pedir ayuda externa para reducir el número de bestias.",
			source = "https://warcraft.wiki.gg/wiki/Eastvale_Logging_Camp",
		},
		["echo ridge mine"] = {
			name = "Mina del Eco",
			short = "Los túneles de la Mina del Eco se encuentran en el noroeste del Valle de Villanorte.",
			full = "Los túneles de la Mina del Eco se encuentran en el noroeste del Valle de Villanorte. Los kóbolds invadieron los pozos y los hicieron suyos, para gran frustración de los humanos que viven cerca, y el alguacil McBride no pudo hacer más que enviar hombres una y otra vez a reducir su número.",
			source = "https://warcraft.wiki.gg/wiki/Echo_Ridge_Mine",
		},
		["fargodeep mine"] = {
			name = "Mina Abisal",
			short = "La Mina Abisal se explotó en otro tiempo en busca de oro para Ventormenta, con sus pozos hundidos en lo profundo de la tierra del Bosque de Elwynn. Ahora está abandonada, y sus túneles han sido reclamados por un clan de kóbolds.",
			full = "La Mina Abisal se explotó en otro tiempo en busca de oro para Ventormenta, con sus pozos hundidos en lo profundo de la tierra del Bosque de Elwynn. Ahora está abandonada, y sus túneles han sido reclamados por un clan de kóbolds. Las minas inferiores, las zonas más profundas bajo la explotación principal, se adentran aún más en la oscuridad.\n\nEl alguacil Dughan, que vela por la seguridad de Elwynn, ordenó aumentar las patrullas de los alrededores una vez confirmada la presencia de kóbolds en su interior. Entre los kóbolds merodea Dientes de Oro, que tiene un collar robado a la \"Tita\" Bernice Pedregosa, un recuerdo que ella no ha perdido la esperanza de volver a ver.",
			source = "https://warcraft.wiki.gg/wiki/Fargodeep_Mine",
		},
		["forests edge"] = {
			name = "Linde del bosque",
			short = "El Linde del Bosque se encuentra al suroeste de Ventormenta, una lengua de bosque entre el Vergel del Lago Espejo, el río Nazferiti y un arroyo más pequeño que va hacia los Páramos de Poniente.",
			full = "El Linde del Bosque se encuentra al suroeste de Ventormenta, una lengua de bosque entre el Vergel del Lago Espejo, el río Nazferiti y un arroyo más pequeño que va hacia los Páramos de Poniente. Los jabalíes hurgan en su maleza, y las vetas de cobre recorren las orillas. El bosque pertenece a una banda de gnolls, y entre ellos hay uno que no es una simple bestia de manada. Hogger recorre el bosque entre los gnolls menores, y no es un chucho cualquiera.",
			source = "https://warcraft.wiki.gg/wiki/Forest's_Edge",
		},
		["goldshire"] = {
			name = "Villadorada",
			short = "Villadorada se encuentra en el corazón del Bosque de Elwynn, con sus campos a la vista de Villanorte y sus caminos extendiéndose hacia Ventormenta, los Páramos de Poniente y Crestagrana.",
			full = "Villadorada se encuentra en el corazón del Bosque de Elwynn, con sus campos a la vista de Villanorte y sus caminos extendiéndose hacia Ventormenta, los Páramos de Poniente y Crestagrana. Creció en los años posteriores a la fundación de Ventormenta, cuando la gente del reino se extendió desde la capital hacia la campiña circundante.\n\nLa peor hora del pueblo llegó durante la Primera Guerra, cuando el Jefe de Guerra Puño Negro lanzó a la Horda contra la línea vital que unía el Castillo de Ventormenta con su pueblo. Villadorada y Arroyo de la Luna eran los dos últimos pueblos que se interponían entre los orcos y la capital, y cuando cayeron, el camino al castillo quedó abierto. Villadorada no volvió a levantarse hasta después de la Segunda Guerra, cuando la Alianza de Lordaeron la reconstruyó, y el propio comandante supremo Turalyon se encargó del regreso de los ciudadanos dispersos de Ventormenta.\n\nLo que queda ahora es más tranquilo: la Posada Orgullo de León se alza en el centro del pueblo, y su hogar y su cerveza atraen a los viajeros de todos los caminos que se cruzan aquí. El alguacil Dughan, de la Guardia de Ventormenta, aún vigila el pueblo, consciente de lo que costó perderlo en otro tiempo.",
			source = "https://warcraft.wiki.gg/wiki/Goldshire",
		},
		["heroes vigil"] = {
			name = "Vigilia de los Héroes",
			short = "Un anillo de piedras erguidas rodea la pequeña isla del Lago del Hito, con la Piedra de Recuerdo en el centro.",
			full = "Un anillo de piedras erguidas rodea la pequeña isla del Lago del Hito, con la Piedra de Recuerdo en el centro. Honra a los muertos de la Primera Guerra, cuando los orcos saquearon Villadorada y las tierras circundantes y las entregaron al fuego.\n\nAhora unos magos renegados ocupan la isla. Entre las piedras yace el cuerpo de Henze Faulk, abandonado donde cayó.",
			source = "https://warcraft.wiki.gg/wiki/Heroes'_Vigil",
		},
		["jasperlode mine"] = {
			name = "Cantera de Jaspe",
			short = "La Cantera de Jaspe abastecía en otro tiempo las forjas de Ventormenta; era uno de los lugares del Bosque de Elwynn que proporcionaban el mineral en bruto que la ciudad necesitaba para sus guerras.",
			full = "La Cantera de Jaspe abastecía en otro tiempo las forjas de Ventormenta; era uno de los lugares del Bosque de Elwynn que proporcionaban el mineral en bruto que la ciudad necesitaba para sus guerras. Ese trabajo terminó. Los kóbolds han invadido los túneles, y el ejército de Ventormenta, desbordado por amenazas más graves, no tiene hombres de sobra para expulsarlos.\n\nLos kóbolds no son el único peligro allá abajo. En los rincones más profundos de la mina se ha instalado una colonia de arañas de mina, y para ellas los kóbolds no son invasores a los que temer, sino presas que cazar. Su reina, Madre Colmillo, acecha en la oscuridad y no tolera ninguna intrusión en su nido.",
			source = "https://warcraft.wiki.gg/wiki/Jasperlode_Mine",
		},
		["jerods landing"] = {
			name = "Embarcadero de Jerod",
			short = "El Embarcadero de Jerod es un muelle para barcas en la orilla del río Nazferiti que da al Bosque de Elwynn.",
			full = "El Embarcadero de Jerod es un muelle para barcas en la orilla del río Nazferiti que da al Bosque de Elwynn. La Hermandad Defias lo ocupa, y el maestro de embarcadero y sus hombres lo utilizan para pasar de contrabando mercancía robada desde las Montañas Crestagrana hasta la torre de Klaven, en los Páramos de Poniente.",
			source = "https://warcraft.wiki.gg/wiki/Jerod's_Landing",
		},
		["maclure vineyards"] = {
			name = "Los Viñedos de Maclure",
			short = "Los Viñedos de Maclure se encuentran en el sur del Bosque de Elwynn, cuidados por la familia Maclure a lo largo de largas hileras de vides y tierra.",
			full = "Los Viñedos de Maclure se encuentran en el sur del Bosque de Elwynn, cuidados por la familia Maclure a lo largo de largas hileras de vides y tierra. Los Maclure mantienen una amarga rivalidad con la vecina familia Pedregosa, y se intercambian antipatía con la misma libertad con la que no se intercambian nada más. Sin embargo, un hijo de los Maclure y una hija de los Pedregosa se han enamorado, desafiando todo lo que defienden sus familias, y algunos esperan que un amor así pueda reparar lo que generaciones de rencor no pudieron.",
			source = "https://warcraft.wiki.gg/wiki/Maclure_Vineyards",
		},
		["mirror lake"] = {
			name = "Lago Espejo",
			short = "El Lago Espejo es pequeño y tranquilo, y se encuentra en el oeste del Bosque de Elwynn, con su cascada cayendo brillante junto a un huerto cercano: el tipo de lugar que parece hecho para nadar o pescar.",
			full = "El Lago Espejo es pequeño y tranquilo, y se encuentra en el oeste del Bosque de Elwynn, con su cascada cayendo brillante junto a un huerto cercano: el tipo de lugar que parece hecho para nadar o pescar. Ya no es tan sencillo. Los bandidos Defias se han instalado en el bosque que lo rodea, y lo que debería ser un lugar de descanso se ha convertido en uno que hay que cruzar con cuidado.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake",
		},
		["mirror lake orchard"] = {
			name = "Vergel del Lago Espejo",
			short = "El Vergel del Lago Espejo se encuentra en la orilla sur del Lago Espejo, con sus hileras de árboles y una cabaña solitaria entre los campos del oeste del Bosque de Elwynn.",
			full = "El Vergel del Lago Espejo se encuentra en la orilla sur del Lago Espejo, con sus hileras de árboles y una cabaña solitaria entre los campos del oeste del Bosque de Elwynn. Los bandidos Defias ocuparon en otro tiempo el huerto y la cabaña contigua y usaron el lugar como si fuera suyo, y nadie puede asegurar si fueron ellos quienes expulsaron a los verdaderos dueños del huerto.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake_Orchard",
		},
		["northshire abbey"] = {
			name = "Abadía de Villanorte",
			short = "La Abadía de Villanorte descansa en el valle que lleva su nombre, en las estribaciones del Bosque de Elwynn, con su salón principal, su sala de armas y su ala de la biblioteca alzándose donde se asentaron por primera vez los clérigos de la Iglesia de la Luz Sagrada tras aventurarse al sur desde Lordaeron.",
			full = "La Abadía de Villanorte descansa en el valle que lleva su nombre, en las estribaciones del Bosque de Elwynn, con su salón principal, su sala de armas y su ala de la biblioteca alzándose donde se asentaron por primera vez los clérigos de la Iglesia de la Luz Sagrada tras aventurarse al sur desde Lordaeron. Desde aquí, la Sagrada Orden de Clérigos de Villanorte dio a Ventormenta consuelo y sabiduría, y fue entre estos muros donde se cuidó a Medivh, el Guardián de Tirisfal, durante los largos años de su coma.\n\nLa abadía no salió indemne de la Primera Guerra. Su abad prestó a los clérigos de Villanorte para la defensa de Ventormenta, y poco después de que trajeran aquí como prisionera a la semiorca Garona, los orcos arrasaron Villanorte y la quemaron hasta dejarla en ruinas. Los refugiados huyeron hacia Lordaeron, pero no sin antes rescatar de entre los escombros unos tomos sagrados, textos que más tarde enseñarían a los magos de Dalaran el arte de la invisibilidad.\n\nLos terrenos en ruinas no quedaron vacíos. El clan Martillo Crepuscular de Cho'gall convirtió el lugar en su cuartel general durante la Segunda Guerra, hasta que la Alianza recuperó el Bosque de Elwynn y el arzobispo Alonsus Faol reconstruyó la abadía piedra a piedra y fundó en sus salones la Hermandad de Villanorte.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Abbey",
		},
		["northshire valley"] = {
			name = "Valle de Villanorte",
			short = "El Valle de Villanorte está cerrado por todos lados menos uno, con montañas infranqueables y su único paso hacia el sur sellado tras gruesos muros de piedra y una puerta vigilada.",
			full = "El Valle de Villanorte está cerrado por todos lados menos uno, con montañas infranqueables y su único paso hacia el sur sellado tras gruesos muros de piedra y una puerta vigilada. Un río atraviesa su quietud y serpentea hacia el Lago de Cristal, pasando junto a la abadía y a las hileras de viñedos que dan al lugar su aire de paz.\n\nEsa paz no siempre fue tan segura. Durante la Segunda Guerra, la Abadía de Villanorte fue el cuartel general del clan Martillo Crepuscular de Cho'gall, juramentado a la causa de Gul'dan, y sus muros dieron cobijo a consejos de guerra orcos en lugar de a novicios y granjeros.\n\nAhora el alguacil McBride está al mando de la guarnición de la abadía y responde de la seguridad de todo Villanorte, aunque el valle no está del todo en calma ni siquiera bajo su vigilancia. Los lobos llegan desde el Bosque del Ocaso en cantidades que nadie sabe explicar, y los kóbolds excavan en la Mina del Eco.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Valley",
		},
		["northshire vineyards"] = {
			name = "Viñedos de Villanorte",
			short = "Los viñedos se extienden al este de la abadía, cuidados en otro tiempo para su cosecha antes de que la Hermandad Defias reclamara la tierra.",
			full = "Los viñedos se extienden al este de la abadía, cuidados en otro tiempo para su cosecha antes de que la Hermandad Defias reclamara la tierra. Garrick Piesuaves dirigía a los agentes que la ocupaban y usaba las hileras como punto de apoyo para los esbirros de la Hermandad, que se llevaron consigo los bienes robados a Milly Osworth.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Vineyards",
		},
		["ridgepoint tower"] = {
			name = "Torre de la Peña",
			short = "La Torre de la Peña vigila la frontera del Bosque de Elwynn, una de las torres de exploración de la Guardia de Ventormenta.",
			full = "La Torre de la Peña vigila la frontera del Bosque de Elwynn, una de las torres de exploración de la Guardia de Ventormenta. Sus centinelas vuelven la mirada hacia Crestagrana, donde se reúnen gnolls y orcos; hacia el Bosque del Ocaso, donde los muertos no permanecen enterrados; y hacia los campamentos Defias cercanos. La guarnición está bien defendida frente a los tres.",
			source = "https://warcraft.wiki.gg/wiki/Ridgepoint_Tower",
		},
		["stone cairn lake"] = {
			name = "Lago del Hito",
			short = "El Lago del Hito debe su nombre a la Vigilia de los Héroes, el túmulo de piedras levantado en la isla de su centro para recordar a los muertos de la Primera Guerra contra los orcos, cuando cayeron tantos que ninguna tumba sola podía guardar su memoria.",
			full = "El Lago del Hito debe su nombre a la Vigilia de los Héroes, el túmulo de piedras levantado en la isla de su centro para recordar a los muertos de la Primera Guerra contra los orcos, cuando cayeron tantos que ninguna tumba sola podía guardar su memoria. En otro tiempo fue un lugar de peregrinación silenciosa.\n\nEsa paz desapareció. Unos magos renegados se han apoderado de la isla, y el túmulo destinado al duelo queda ahora a sus espaldas. A lo largo de la orilla sur, una tribu de múrlocs ha levantado sus toscas viviendas, indiferente al monumento al otro lado del agua.",
			source = "https://warcraft.wiki.gg/wiki/Stone_Cairn_Lake",
		},
		["stonefield farm"] = {
			name = "La Granja Pedregosa",
			short = "La Granja Pedregosa se encuentra en el sur del Bosque de Elwynn, trabajada por la familia Pedregosa, que mantiene una amarga rivalidad con los vecinos Maclure.",
			full = "La Granja Pedregosa se encuentra en el sur del Bosque de Elwynn, trabajada por la familia Pedregosa, que mantiene una amarga rivalidad con los vecinos Maclure. Sin embargo, un miembro de cada casa se ha enamorado, desafiando el viejo rencor entre sus familias. Algunos esperan que ese romance logre lo que años de peleas nunca consiguieron y repare lo que la enemistad ha roto.",
			source = "https://warcraft.wiki.gg/wiki/Stonefield_Farm",
		},
		["thunder falls"] = {
			name = "Cataratas del Trueno",
			short = "El sendero que sube desde la cascada del Lago Espejo trepa empinado y estrecho por las montañas antes de abrirse a las Cataratas del Trueno, un barranco distinto de los demás del Bosque de Elwynn por tener agua cayendo en ambos extremos.",
			full = "El sendero que sube desde la cascada del Lago Espejo trepa empinado y estrecho por las montañas antes de abrirse a las Cataratas del Trueno, un barranco distinto de los demás del Bosque de Elwynn por tener agua cayendo en ambos extremos. Una tercera cascada se precipita desde los acantilados del norte y alimenta el barranco desde arriba. Bajo la elevación se alza una pequeña cabaña rural, con su yunque y su fuego siempre encendidos, y un pequeño muelle con una barca que descansa en el río junto a la casa. Unos bandidos merodean cerca de la cabaña. El río sigue su curso por una segunda cascada cerca del límite de los Páramos de Poniente. Se dice que las percas violetas que nadan en estas aguas no se encuentran en ningún otro lugar con tanta facilidad como aquí.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Falls",
		},
		["tower of azora"] = {
			name = "Torre de Azora",
			short = "La Torre de Azora se alza entre los campos del centro del Bosque de Elwynn, hogar de un grupo de sirvientes gnomos que responden ante el archimago Theocritus.",
			full = "La Torre de Azora se alza entre los campos del centro del Bosque de Elwynn, hogar de un grupo de sirvientes gnomos que responden ante el archimago Theocritus.\n\nLejos, en las Montañas Crestagrana, se alza su rival, la Torre de Ilgalar, gobernada por el hechicero Morganth. Las dos torres nunca se han declarado la guerra abiertamente, pero se vigilan constantemente por medios mágicos, cada una esperando sorprender a la otra en algún paso en falso.\n\nLa magia de la propia torre se derrama sobre los campos que la rodean, y cualquier cosa que se quede demasiado cerca corre el riesgo de verse afectada por ella y convertirse en algo más extraño de lo que era. Los sirvientes cuidan su torre frente a este problema pequeño y constante, con un ojo siempre puesto en Crestagrana.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Azora",
		},
		["westbrook garrison"] = {
			name = "Cuartel de Arroyoeste",
			short = "El Cuartel de Arroyoeste se alza en el extremo occidental del Bosque de Elwynn, donde los árboles dan paso a la tierra más pobre de los Páramos de Poniente, y siempre ha sido un destino solitario para la Guardia de Ventormenta.",
			full = "El Cuartel de Arroyoeste se alza en el extremo occidental del Bosque de Elwynn, donde los árboles dan paso a la tierra más pobre de los Páramos de Poniente, y siempre ha sido un destino solitario para la Guardia de Ventormenta.\n\nSus años más duros llegaron mientras la corrupción de Lady Katrana Prestor pesaba sobre el reino y el grueso del ejército de Ventormenta estaba destinado en otros lugares. Con demasiados pocos soldados disponibles, los gnolls y los ladrones de los Páramos de Poniente presionaban cada temporada con más fuerza sobre el bosque, y el cuartel apenas lograba mantener seguros los caminos.\n\nEntre los gnolls, el jefe Zarparrío Hogger se convirtió en un nombre temido. Frustró todos los intentos de capturarlo, y en la puerta del cuartel todavía cuelgan carteles de \"Se busca\" con su nombre, sin que nadie los haya cobrado.",
			source = "https://warcraft.wiki.gg/wiki/Westbrook_Garrison",
		},
	},
	-- Paso de la Muerte: 9 subzones
	[1430] = {
		["aridens camp"] = {
			name = "Campamento de Ariden",
			short = "El campamento yace abandonado al norte del camino que atraviesa el Paso de la Muerte, un conjunto disperso de hogueras frías y petates vacíos bajo árboles siempre oscuros.",
			full = "El campamento yace abandonado al norte del camino que atraviesa el Paso de la Muerte, un conjunto disperso de hogueras frías y petates vacíos bajo árboles siempre oscuros. Ariden dirigió en otro tiempo a los Jinetes oscuros desde este lugar, donde acampó antes de ser maldecido, y desde aquí intentó vender falsos artefactos que, según afirmaba, habían pertenecido a Medivh. Hoy no queda nada más que el propio campamento.",
			source = "https://warcraft.wiki.gg/wiki/Ariden's_Camp",
		},
		["deadmans crossing"] = {
			name = "Cruce de la Muerte",
			short = "Un árbol de la horca se alza en el cruce, y de sus ramas todavía cuelgan un par de cadáveres. A su lado, un letrero muestra dos advertencias: \"¡Den media vuelta!\" y \"Abandonen toda esperanza quienes entren aquí\".",
			full = "Un árbol de la horca se alza en el cruce, y de sus ramas todavía cuelgan un par de cadáveres. A su lado, un letrero muestra dos advertencias: \"¡Den media vuelta!\" y \"Abandonen toda esperanza quienes entren aquí\".\n\nAquí, el camino del oeste lleva hacia el Bosque del Ocaso, el del este hacia el Pantano de las Penas y el del sur hacia el Paso de la Muerte, donde se alza Karazhan. La horca y la advertencia se levantaron para cualquiera que sintiera la tentación de desviarse del cruce hacia el paso de más allá.",
			source = "https://warcraft.wiki.gg/wiki/Deadman's_Crossing",
		},
		["deadwind ravine"] = {
			name = "Barranco de la Muerte",
			short = "El barranco abre una grieta escarpada entre las montañas, y su camino occidental recorre el nivel superior hacia Karazhan, cuya silueta aguarda ominosa en el otro extremo.",
			full = "El barranco abre una grieta escarpada entre las montañas, y su camino occidental recorre el nivel superior hacia Karazhan, cuya silueta aguarda ominosa en el otro extremo. Al final del barranco se encuentra el puente sur, el último cruce antes de la propia torre.",
			source = "https://warcraft.wiki.gg/wiki/Deadwind_Ravine",
		},
		["groshgok compound"] = {
			name = "Dominios Grosh'gok",
			short = "Los ogros del Paso de la Muerte consideran suyos los Dominios Grosh'gok, un montículo de tierra y piedra levantado en El Vicio.",
			full = "Los ogros del Paso de la Muerte consideran suyos los Dominios Grosh'gok, un montículo de tierra y piedra levantado en El Vicio. De las cuevas que salpican esa extensión de terreno, esta es la que está más al sur, y ninguna de las otras la iguala en tamaño.",
			source = "https://warcraft.wiki.gg/wiki/Grosh'gok_Compound",
		},
		["karazhan"] = {
			name = "Karazhan",
			short = "Karazhan se alza abandonada en el sur del Paso de la Muerte, construida sobre un nexo de líneas místicas. La torre es conocida sobre todo por su último ocupante, Medivh, el último Guardián de Tirisfal.",
			full = "Karazhan se alza abandonada en el sur del Paso de la Muerte, construida sobre un nexo de líneas místicas. La torre es conocida sobre todo por su último ocupante, Medivh, el último Guardián de Tirisfal. Después de que Medivh muriera a manos de Khadgar, Anduin Lothar y Garona, la torre se aisló del mundo. Pero recientemente Karazhan ha vuelto a agitarse: una presencia maligna se ha apoderado de ella, sus salones rebosan de espíritus y demonios, y la Sombra de Medivh todavía permanece allí, con un poder tan grande que su magia aún resuena por la torre.\n\nEs imposible contemplar Karazhan sin reflexionar sobre la oscura historia de su amo. Como correspondía a su título, el último Guardián de Tirisfal había reunido una enorme colección de escritos y artefactos, que superaba incluso a la del Kirin Tor. La torre es enorme y peligrosa, y sus salones están llenos de fantasmas.",
			source = "https://warcraft.wiki.gg/wiki/Karazhan",
		},
		["masters cellar"] = {
			name = "El Sótano del Maestro",
			short = "Bajo la aldea en ruinas al sur de Karazhan, donde antes tenían sus casas los sirvientes de la torre, el suelo se abre en sótanos que ya no pertenecen a los vivos.",
			full = "Bajo la aldea en ruinas al sur de Karazhan, donde antes tenían sus casas los sirvientes de la torre, el suelo se abre en sótanos que ya no pertenecen a los vivos. Dos entradas llevan abajo. Una se abre a una enorme bodega, con sus estantes y barriles abandonados hace mucho a los muertos. La otra desciende a un segundo sótano cuyo suelo ha cedido por completo y se ha derrumbado sobre un sistema de cuevas que se extiende muy por debajo de la tierra.\n\nAmbos están llenos de almas inquietas: cuidadores no-muertos que todavía parecen atender una casa sin amo, almas condenadas, sombras que no hallan reposo y espectros cuyos lamentos suben a través de la piedra rota. Cualquier servicio que los ató a Karazhan en vida se ha agriado hasta convertirse en algo que no les permite marcharse en la muerte.\n\nSolo la bodega guarda algo que destaque entre los muertos. El sistema de cuevas inferior, silencioso y sumido en la oscuridad, no guarda más que otros tantos muertos inquietos, nada con nombre, nada que nadie haya considerado digno de recordar.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Cellar",
		},
		["morgans plot"] = {
			name = "Terreno de Morgan",
			short = "Una pequeña iglesia decrépita se alza detrás de Karazhan, con su cementerio y su cripta hundidos en la penumbra del Paso de la Muerte.",
			full = "Una pequeña iglesia decrépita se alza detrás de Karazhan, con su cementerio y su cripta hundidos en la penumbra del Paso de la Muerte. La capilla alberga desde hace mucho cosas que no descansan tranquilas, y algo más todavía patrulla la colina que hay justo debajo.\n\nQue un lugar destinado a los muertos falle tan a menudo en retenerlos dice algo de lo que hay detrás.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Plot",
		},
		["sleeping gorge"] = {
			name = "Desfiladero del Letargo",
			short = "El Desfiladero del Letargo atraviesa el este del Paso de la Muerte, un pequeño abismo que los viajeros que se acercan a Karazhan por el sur deben cruzar antes de que el sendero gire al este hacia El Vicio.",
			full = "El Desfiladero del Letargo atraviesa el este del Paso de la Muerte, un pequeño abismo que los viajeros que se acercan a Karazhan por el sur deben cruzar antes de que el sendero gire al este hacia El Vicio.",
			source = "https://warcraft.wiki.gg/wiki/Sleeping_Gorge",
		},
		["vice"] = {
			name = "El Vicio",
			short = "El Vicio se extiende a lo largo del tramo sur del camino a Karazhan, donde los ogros del Paso de la Muerte han levantado sus montículos y campamentos entre los riscos.",
			full = "El Vicio se extiende a lo largo del tramo sur del camino a Karazhan, donde los ogros del Paso de la Muerte han levantado sus montículos y campamentos entre los riscos. Es una extensión desolada de terreno, hogar de poco más que espíritus inquietos y de los buitres que vuelan en círculos sobre ellos. Nadie que haya contemplado el lugar sabe por qué los ogros eligieron establecerse aquí, en un sitio tan vacío y desfavorecido.",
			source = "https://warcraft.wiki.gg/wiki/Vice",
		},
	},
	-- Bosque del Ocaso: 17 subzones
	[1431] = {
		["addles stead"] = {
			name = "Granja de Addle",
			short = "La Granja de Addle yace abandonada entre los campos del suroeste del Bosque del Ocaso, una de las muchas granjas que quedaron pudriéndose cuando la oscuridad se extendió por la tierra.",
			full = "La Granja de Addle yace abandonada entre los campos del suroeste del Bosque del Ocaso, una de las muchas granjas que quedaron pudriéndose cuando la oscuridad se extendió por la tierra. El granero está vacío, la casa en silencio, y ahora solo quedan espíritus desolados, que según se dice son las sombras de miembros muertos de la Hermandad Defias que antes ocuparon el lugar.\n\nLos Defias tomaron por completo la Granja de Addle: se deslizaban por el campo cubierto de maleza, se escondían en el granero y acechaban en las habitaciones de la casa.",
			source = "https://warcraft.wiki.gg/wiki/Addle's_Stead",
		},
		["beggars haunt"] = {
			name = "Refugio de los Mendigos",
			short = "La torre llamada Refugio de los Mendigos se alza abandonada sobre el camino que entra en el Paso de la Muerte, al noreste de la Mansión Mantoniebla.",
			full = "La torre llamada Refugio de los Mendigos se alza abandonada sobre el camino que entra en el Paso de la Muerte, al noreste de la Mansión Mantoniebla. Construida como puesto de exploración para la Guardia de Ventormenta, ahora sirve a los Renegados: el mortacechador Zraedus y el boticario Faustin realizan experimentos entre sus muros.\n\nUn sendero baja serpenteando hasta un pequeño estanque alimentado por una cascada, donde descansa una tumba sin nombre bajo dos grandes estatuas talladas como las del Portal Oscuro. Cerca de la torre hay otro pequeño cementerio, que guarda la tumba de un soldado desconocido.",
			source = "https://warcraft.wiki.gg/wiki/Beggar's_Haunt",
		},
		["brightwood grove"] = {
			name = "Arboleda del Destello",
			short = "La Arboleda del Destello se encuentra justo al oeste de Villa Oscura, y sus pocos edificios se derrumbaron hace mucho.",
			full = "La Arboleda del Destello se encuentra justo al oeste de Villa Oscura, y sus pocos edificios se derrumbaron hace mucho. Lo que queda del lugar pertenece ahora a los huargen Penumbría, que merodean en manadas por los campos oscuros, levantan toscos campamentos entre los restos y caen sobre cualquiera que se acerque demasiado.",
			source = "https://warcraft.wiki.gg/wiki/Brightwood_Grove",
		},
		["darkened bank"] = {
			name = "La Ribera Lóbrega",
			short = "La Ribera Lóbrega se extiende a lo largo de la orilla norte del Bosque del Ocaso, desde el extremo occidental de la región hacia el este hasta el puente que la une con Crestagrana.",
			full = "La Ribera Lóbrega se extiende a lo largo de la orilla norte del Bosque del Ocaso, desde el extremo occidental de la región hacia el este hasta el puente que la une con Crestagrana. En su extremo occidental hay un pequeño campamento donde se han refugiado Sven Yorgen y Lars, empujados hasta la orilla del agua por lo que sea que haya hecho demasiado peligroso el resto del Bosque del Ocaso.",
			source = "https://warcraft.wiki.gg/wiki/Darkened_Bank",
		},
		["darkshire"] = {
			name = "Villa Oscura",
			short = "Villa Oscura no siempre se llamó así. Surgió hace mucho tiempo como Gran Aldea, un pequeño pueblo del bosque que creció a medida que la gente de Ventormenta se extendía por las tierras cercanas.",
			full = "Villa Oscura no siempre se llamó así. Surgió hace mucho tiempo como Gran Aldea, un pequeño pueblo del bosque que creció a medida que la gente de Ventormenta se extendía por las tierras cercanas. Pero la tierra nunca se recuperó de lo que ocurrió en Karazhan. Cuando el Guardián Medivh murió en su torre, la energía vil liberada por su muerte se infiltró en el bosque circundante y lo retorció hasta convertirlo en el lugar espinoso y sin luz que sigue siendo. El Bosque del Destello se convirtió en el Bosque del Ocaso, y Gran Aldea adoptó el nombre más fiel de Villa Oscura.\n\nLa milicia del pueblo, la Guardia Nocturna, existe porque Ventormenta lo abandonó. Cuando las intrigas de Lady Katrana Prestor en Ventormenta vaciaron el bosque de las guarniciones del reino, los habitantes se armaron en lugar de esperar a unos soldados que nunca llegarían. Formada y entrenada por completo por la gente del bosque, desde entonces ha defendido los caminos contra lobos, cadáveres andantes y cosas peores, sin más ejército al que recurrir que ellos mismos.",
			source = "https://warcraft.wiki.gg/wiki/Darkshire",
		},
		["dawning wood catacombs"] = {
			name = "Catacumbas del Bosque Aurora",
			short = "Bajo el Cementerio del Cerro del Cuervo, la tierra se abre a las Catacumbas del Bosque Aurora, un laberinto de túneles tan retorcido y profundo que pocos de los que entran solos vuelven a salir.",
			full = "Bajo el Cementerio del Cerro del Cuervo, la tierra se abre a las Catacumbas del Bosque Aurora, un laberinto de túneles tan retorcido y profundo que pocos de los que entran solos vuelven a salir. Dos caminos llevan abajo. El pasaje oriental da a una guarida de necrófagos, enfermos y feroces. El pasaje occidental da a una sala de esqueletos, que montan guardia sobre las tumbas de los muertos que alguna vez fueron.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Wood_Catacombs",
		},
		["forlorn rowe"] = {
			name = "Loma Inhóspita",
			short = "Colina en el borde norte del Cementerio del Cerro del Cuervo, la Loma Inhóspita está envuelta en una oscuridad que se aferra más que la sombra de los árboles circundantes.",
			full = "Colina en el borde norte del Cementerio del Cerro del Cuervo, la Loma Inhóspita está envuelta en una oscuridad que se aferra más que la sombra de los árboles circundantes. Aquí se alza el hogar de Morbent Vil, un nigromante que somete a su voluntad a los no-muertos del bosque mediante una malvada magia arcana. Solo un arma de gran poder podría aspirar a detenerlo.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Rowe",
		},
		["hushed bank"] = {
			name = "La Ribera Silente",
			short = "La Ribera Silente se extiende a lo largo del río occidental del Bosque del Ocaso, desde el lugar donde se unen los Páramos de Poniente, el Bosque de Elwynn y el Bosque del Ocaso, hacia el sur en dirección a la Vega de Tuercespina.",
			full = "La Ribera Silente se extiende a lo largo del río occidental del Bosque del Ocaso, desde el lugar donde se unen los Páramos de Poniente, el Bosque de Elwynn y el Bosque del Ocaso, hacia el sur en dirección a la Vega de Tuercespina. Aquí, un puente cubierto cruza el río y une el Bosque del Ocaso con los Páramos de Poniente.\n\nEn la esquina norte de la ribera, los hermanos Lars y Sven Yorgen tienen un campamento.\n\nLobos y arañas recorren la ribera entre los árboles.",
			source = "https://warcraft.wiki.gg/wiki/Hushed_Bank",
		},
		["manor mistmantle"] = {
			name = "Mansión Mantoniebla",
			short = "La Mansión Mantoniebla se alza en el noreste del Bosque del Ocaso, con sus terrenos podridos y sus jardines en ruinas.",
			full = "La Mansión Mantoniebla se alza en el noreste del Bosque del Ocaso, con sus terrenos podridos y sus jardines en ruinas. En otro tiempo fue el hogar de Stalvan Mantoniebla, un maestro y tutor que se convirtió en agente de los no-muertos y dejó a los necrófagos arrastrándose por la propiedad en su lugar. En medio de la corrupción, todavía crece una cosa: una única flor llamada Lágrima de Tilloa, la única señal de vida que queda en un jardín entregado por lo demás a la podredumbre.",
			source = "https://warcraft.wiki.gg/wiki/Manor_Mistmantle",
		},
		["raven hill"] = {
			name = "Cerro del Cuervo",
			short = "Las casas del Cerro del Cuervo están vacías en el oeste del Bosque del Ocaso, entregadas a la podredumbre y la oscuridad. Aun así, unas pocas almas resistieron: Alterio, y Bliztik, un goblin que se mantenía oculto en un piso superior.",
			full = "Las casas del Cerro del Cuervo están vacías en el oeste del Bosque del Ocaso, entregadas a la podredumbre y la oscuridad. Aun así, unas pocas almas resistieron: Alterio, y Bliztik, un goblin que se mantenía oculto en un piso superior.\n\nEl pueblo está embrujado por los Invisibles, invisibles en algo más que el nombre, que se mueven por sus habitaciones vacías.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill",
		},
		["raven hill cemetery"] = {
			name = "Cementerio del Cerro del Cuervo",
			short = "El Cementerio del Cerro del Cuervo se extiende al norte del pueblo del que toma su nombre, y ha crecido mucho más allá de sus antiguos límites desde que la corrupción se apoderó del Bosque del Ocaso.",
			full = "El Cementerio del Cerro del Cuervo se extiende al norte del pueblo del que toma su nombre, y ha crecido mucho más allá de sus antiguos límites desde que la corrupción se apoderó del Bosque del Ocaso. Ahora los no-muertos caminan entre las lápidas, y arañas enormes y bandas de ladrones de tumbas trabajan las sepulturas sin que nadie los moleste, ahuyentando a cualquiera que se tope con sus asuntos.\n\nEn la esquina noroeste del cementerio se alza la Loma Inhóspita, hogar del nigromante Morbent Vil, cuya oscura obra agita a los muertos del cementerio.\n\nEse nombre, Ladimor, marca el dolor más antiguo del cementerio. Morgan Ladimor regresó de la Tercera Guerra y encontró a su esposa y sus hijos ya enterrados aquí. El dolor lo quebró; asesinó a tres de los cuidadores del cementerio sobre sus tumbas. Ahora el no-muerto Mor'Ladim patrulla los terrenos, y la muerte llega rápida e invisible a cualquiera que él encuentre desprevenido entre las lápidas.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill_Cemetery",
		},
		["rolands doom"] = {
			name = "Condena de Roland",
			short = "La Condena de Roland es una mina en el sureste del Bosque del Ocaso, al este del Huerto Podrido.",
			full = "La Condena de Roland es una mina en el sureste del Bosque del Ocaso, al este del Huerto Podrido. La sacerdotisa elfa de la noche Velinde Cantoestelar llevó la Guadaña de Elune a estas colinas antes de desaparecer, y la reliquia se perdió en la mina. El hombre llamado Alterio la encontró allí, y su hallazgo atrajo a más huargen sobre el Bosque del Ocaso y Villa Oscura.\n\nAhora la mina pertenece a Gutspill y Nefaru, de la manada Penumbría, cuyos huargen merodean hasta el Huerto Podrido.",
			source = "https://warcraft.wiki.gg/wiki/Roland's_Doom",
		},
		["rotting orchard"] = {
			name = "El Vergel Pútrido",
			short = "El huerto se encuentra en el sur del Bosque del Ocaso, con sus árboles ennegrecidos por la podredumbre y sus edificios en ruinas entre La Hacienda Yorgen y el Cementerio del Jardín Sereno.",
			full = "El huerto se encuentra en el sur del Bosque del Ocaso, con sus árboles ennegrecidos por la podredumbre y sus edificios en ruinas entre La Hacienda Yorgen y el Cementerio del Jardín Sereno.\n\nLos huargen de la manada Penumbría lo han hecho suyo. Los tejesombras practican su magia entre los edificios en ruinas, mientras los acechadores esperan invisibles en la oscuridad entre los árboles.\n\nEstar aquí ahora es estar en un lugar que ha dejado de ser una granja para convertirse en un coto de caza.",
			source = "https://warcraft.wiki.gg/wiki/Rotting_Orchard",
		},
		["tranquil gardens cemetery"] = {
			name = "Cementerio del Jardín Sereno",
			short = "El Cementerio del Jardín Sereno se encuentra al sureste de Villa Oscura, y su nombre es ahora una broma amarga.",
			full = "El Cementerio del Jardín Sereno se encuentra al sureste de Villa Oscura, y su nombre es ahora una broma amarga. Los muertos de aquí no descansan, aunque son más débiles que los no-muertos que se encuentran en otras partes del Bosque del Ocaso, y vagan entre las lápidas y la iglesia en ruinas del centro del cementerio. El Necrófago Demente ronda este terreno, a veces dentro de la iglesia destrozada, a veces entre las tumbas. Justo al norte se alza la casa de la Ciega Mary.",
			source = "https://warcraft.wiki.gg/wiki/Tranquil_Gardens_Cemetery",
		},
		["twilight grove"] = {
			name = "Arboleda del Crepúsculo",
			short = "Un gran árbol sin nombre se alza en el corazón de la Arboleda del Crepúsculo, en lo profundo del Bosque del Ocaso, junto a una poza de la luna y un viejo cenador de los elfos de la noche.",
			full = "Un gran árbol sin nombre se alza en el corazón de la Arboleda del Crepúsculo, en lo profundo del Bosque del Ocaso, junto a una poza de la luna y un viejo cenador de los elfos de la noche. Bajo sus ramas se encuentra uno de los cuatro únicos portales al Sueño Esmeralda, hermano de los que se ocultan en Feralas, las Tierras del Interior y Vallefresno.\n\nEl portal de la arboleda no quedó sin protección. Cuatro grandes dragones, antaño orgullosos lugartenientes de Ysera, Aspecto de los Sueños, montaban guardia aquí como protectores elegidos del Sueño. Pero la Pesadilla Esmeralda los corrompió a su vez y convirtió a los guardianes en destructores que no deseaban más que la muerte, y tanto a la Alianza como a la Horda les tocó tomar las armas contra los mismos dragones que una vez habían velado por este lugar.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Grove",
		},
		["vulgol ogre mound"] = {
			name = "Túmulo de Vul'Gol",
			short = "El sur del Bosque del Ocaso desciende hacia una pequeña cuenca donde el camino se divide hacia la Vega de Tuercespina, y donde antes se alzaban granjas antes de que llegaran los ogros.",
			full = "El sur del Bosque del Ocaso desciende hacia una pequeña cuenca donde el camino se divide hacia la Vega de Tuercespina, y donde antes se alzaban granjas antes de que llegaran los ogros. Ahora la ocupan los ogros Splinter Fist, y el lugar toma su nombre de su líder, Zzarc'Vul, que gobierna el túmulo desde su interior.\n\nLas granjas en ruinas son la única señal de que aquí vivió gente antes de que los ogros se apoderaran de la cuenca. Fuera cual fuera el destino de aquellas familias, los ogros no dejaron más que muros derrumbados.\n\nLa Guardia Nocturna no destina a los suyos a este lugar, pues considera la amenaza de aquí menos urgente que otras que acechan al Bosque del Ocaso, así que ha quedado en manos de forasteros reducir el número de ogros cuando es necesario. Entre el botín de los ogros había una caja de herramientas y hierbas robada al nigromante Abercrombie, llevada al túmulo después de que lo arrollaran. Y el propio Zzarc'Vul lleva un monóculo que un investigador codició en una ocasión para sus propios estudios, una pequeña vanidad en una criatura brutal.",
			source = "https://warcraft.wiki.gg/wiki/Vul'Gol_Ogre_Mound",
		},
		["yorgen farmstead"] = {
			name = "La Hacienda Yorgen",
			short = "La Hacienda Yorgen yace abandonada en el sur del Bosque del Ocaso, con sus campos podridos. Sven Yorgen trabajó en otro tiempo esta tierra, pero ahora vive en un pequeño campamento en la Ribera Lóbrega.",
			full = "La Hacienda Yorgen yace abandonada en el sur del Bosque del Ocaso, con sus campos podridos. Sven Yorgen trabajó en otro tiempo esta tierra, pero ahora vive en un pequeño campamento en la Ribera Lóbrega. Desde entonces, la hacienda ha caído en manos de la Hermandad Defias, cuyos asesinos se mueven invisibles por los campos y solo atacan cuando ya es demasiado tarde.",
			source = "https://warcraft.wiki.gg/wiki/Yorgen_Farmstead",
		},
	},
	-- Loch Modan: 16 subzones
	[1432] = {
		["algaz station"] = {
			name = "Estación de Algaz",
			short = "La Estación de Algaz se encuentra al este del Paso de la Puerta Norte, y toma su nombre de Dun Algaz, al norte.",
			full = "La Estación de Algaz se encuentra al este del Paso de la Puerta Norte, y toma su nombre de Dun Algaz, al norte. Aquí los montaraces enanos montan guardia, entre ellos el montaraz Pico Tormenta, y el armero Gothor Brumn se encarga de su equipo.",
			source = "https://warcraft.wiki.gg/wiki/Algaz_Station",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "El túnel de Dun Algaz es más antiguo que la disputa que dividió a los enanos. Cuando la guerra de los Tres Martillos expulsó a los Martillo Salvaje de Forjaz, fue por este paso por donde se retiraron.",
			full = "El túnel de Dun Algaz es más antiguo que la disputa que dividió a los enanos. Cuando la guerra de los Tres Martillos expulsó a los Martillo Salvaje de Forjaz, fue por este paso por donde se retiraron.\n\nTambién sirvió para la retirada de la Horda. Rechazados en Dun Modr, los orcos retrocedieron hacia el sur a través del valle de Thandol y se atrincheraron en el puesto de aquí, y Anduin Lothar, que quería expulsarlos por completo de Khaz Modan, envió a sus fuerzas a derribar el bastión. El asalto fracasó. Los orcos resistieron, y Dun Algaz se convirtió en el último terreno que la Horda conservó en la región, un punto de apoyo del que no hubo manera de desalojarlos.\n\nLos montaraces enanos que vigilaban este paso se mantenían sobre todo en las colinas de arriba, pero el clan Faucedraco arrasó su puesto y los obligó a replegarse al túnel superior, donde aún resisten. Con el paso inferior perdido, el camino entre las tierras natales de los enanos y el Puerto de Menethil se ha vuelto mucho más peligroso.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["farstrider lodge"] = {
			name = "Cabaña del Errante",
			short = "La Cabaña del Errante se encuentra en el sureste de Loch Modan, con una arquitectura inconfundiblemente propia de los altos elfos, aunque solo queda uno de esa raza entre sus salones.",
			full = "La Cabaña del Errante se encuentra en el sureste de Loch Modan, con una arquitectura inconfundiblemente propia de los altos elfos, aunque solo queda uno de esa raza entre sus salones. Desde entonces, humanos y enanos se han instalado allí, entre ellos cazadores, viviendo entre muros levantados por manos que hace mucho abandonaron este lugar.",
			source = "https://warcraft.wiki.gg/wiki/Farstrider_Lodge",
		},
		["grizzlepaw ridge"] = {
			name = "Fuerte Zarpagris",
			short = "El Fuerte Zarpagris se alza al sur de Thelsamar, lleno de osos que han hecho suyas las alturas.",
			full = "El Fuerte Zarpagris se alza al sur de Thelsamar, lleno de osos que han hecho suyas las alturas. El principal de ellos es el Viejo Tiznado, un oso de tamaño y temperamento temibles, que baja de su guarida hasta el fondo del valle, siempre dispuesto a abalanzarse sobre cualquiera que tenga la mala suerte de irritarlo.\n\nGorick Guzzledraught también vive en la cresta.",
			source = "https://warcraft.wiki.gg/wiki/Grizzlepaw_Ridge",
		},
		["ironbands excavation site"] = {
			name = "Excavación de Vetaferro",
			short = "La Excavación de Vetaferro, en el sureste de Loch Modan, es un yacimiento enano abierto por el prospector Vetaferro en busca de lo que los antiguos habían enterrado.",
			full = "La Excavación de Vetaferro, en el sureste de Loch Modan, es un yacimiento enano abierto por el prospector Vetaferro en busca de lo que los antiguos habían enterrado. Pero la tierra entregó algo más que reliquias: unos troggs, más grandes y volátiles que los que se encuentran en las otras excavaciones enanas, surgieron de abajo e invadieron el lugar, expulsando a los prospectores y mineros que lo habían abierto.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Excavation_Site",
		},
		["loch"] = {
			name = "Loch Modan",
			short = "El lago ocupa el corazón de Loch Modan: es la mayor masa de agua de todo Khaz Modan y la tercera en tamaño del mundo conocido, solo por detrás del Lordamere y del Darrowmere.",
			full = "El lago ocupa el corazón de Loch Modan: es la mayor masa de agua de todo Khaz Modan y la tercera en tamaño del mundo conocido, solo por detrás del Lordamere y del Darrowmere.",
			source = "https://warcraft.wiki.gg/wiki/The_Loch",
		},
		["mogrosh stronghold"] = {
			name = "Fortaleza de Mo'grosh",
			short = "Las cuevas de la Fortaleza de Mo'grosh se encuentran en el noreste de Loch Modan y son el hogar de una tribu de ogros, cuyos machacadores oscuros y doblegadores de tierra no responden ante nadie más que ante los suyos.",
			full = "Las cuevas de la Fortaleza de Mo'grosh se encuentran en el noreste de Loch Modan y son el hogar de una tribu de ogros, cuyos machacadores oscuros y doblegadores de tierra no responden ante nadie más que ante los suyos.",
			source = "https://warcraft.wiki.gg/wiki/Mo'grosh_Stronghold",
		},
		["north gate pass"] = {
			name = "Paso de la Puerta Norte",
			short = "El paso atraviesa las altas montañas y desciende desde Dun Morogh hacia Loch Modan.",
			full = "El paso atraviesa las altas montañas y desciende desde Dun Morogh hacia Loch Modan. Es el camino más corto entre ambos, y los viajeros que se dirigen a las tierras más allá del lago pasan por aquí más que por ningún otro sitio.\n\nLa Avanzada de la Puerta Norte monta guardia aquí y controla el paso.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["silver stream mine"] = {
			name = "Mina de Fuenteplata",
			short = "La Mina de Fuenteplata tuvo en otro tiempo ricas vetas de plata, y durante generaciones los enanos de Forjaz extrajeron riqueza de ellas.",
			full = "La Mina de Fuenteplata tuvo en otro tiempo ricas vetas de plata, y durante generaciones los enanos de Forjaz extrajeron riqueza de ellas. Cuando el mineral se agotó, la Liga de Mineros convirtió los túneles en un depósito de almacenamiento en lugar de abandonarlos.\n\nLa mina aún guarda algo que vale la pena llevarse: gemas de falla cargadas, que no se encuentran en ningún otro lugar y son muy apreciadas para confeccionar túnicas de mago.\n\nPero los enanos ya no controlan estos túneles. Los kóbolds ratatúneles han invadido la mina en busca de los recursos que aún le quedan.",
			source = "https://warcraft.wiki.gg/wiki/Silver_Stream_Mine",
		},
		["south gate pass"] = {
			name = "Paso de la Puerta Sur",
			short = "El Paso de la Puerta Sur atraviesa las montañas y une las altas nieves de Dun Morogh con los valles más bajos de Loch Modan. Es el camino más corto para bajar a Thelsamar, desgastado por los viajeros que van de una tierra a otra.",
			full = "El Paso de la Puerta Sur atraviesa las montañas y une las altas nieves de Dun Morogh con los valles más bajos de Loch Modan. Es el camino más corto para bajar a Thelsamar, desgastado por los viajeros que van de una tierra a otra.\n\nAquí se alza la Avanzada de la Puerta Sur, un puesto de guardia destinado a vigilar el paso.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["stonesplinter valley"] = {
			name = "Valle Rompecantos",
			short = "El Valle Rompecantos se abre entre las montañas del suroeste de Loch Modan. Antaño estaba intacto, pero ahora pertenece a los troggs Rompecantos, que han invadido su fondo y sus laderas.",
			full = "El Valle Rompecantos se abre entre las montañas del suroeste de Loch Modan. Antaño estaba intacto, pero ahora pertenece a los troggs Rompecantos, que han invadido su fondo y sus laderas. Los enanos de Loch Modan los consideran alimañas a las que hay que exterminar. En lo más profundo del valle habita Grawmug, el líder en torno al cual se agrupan los troggs.",
			source = "https://warcraft.wiki.gg/wiki/Stonesplinter_Valley",
		},
		["stonewrought dam"] = {
			name = "Presa de las Tres Cabezas",
			short = "La Presa de las Tres Cabezas se alza al este del paso de Dun Algaz, a lo largo del límite norte de Loch Modan.",
			full = "La Presa de las Tres Cabezas se alza al este del paso de Dun Algaz, a lo largo del límite norte de Loch Modan.\n\nSu constructor fue un enano Hierro Negro. Franclorn Forjador, arquitecto de aquel clan, ideó el método de la piedra forjada con el que se levantó la presa, aunque pocos de los que la cruzan saben que la construyó una mano Hierro Negro.\n\nLa presa contiene el lago y lo ha hecho crecer hasta más del doble de su tamaño anterior, y la inundación que provocó dio forma a los humedales que hay más allá, un terreno que antes estaba casi todo bajo el agua.\n\nEl clan Hierro Negro atacó la presa, y Forjaz respondió reforzando su vigilancia. El ingeniero jefe Hinderweir VII tiene ahora ese encargo.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Dam",
		},
		["stoutlager inn"] = {
			name = "Pensión La Cebada",
			short = "La Pensión La Cebada se encuentra en Thelsamar, y su hogar rara vez está frío. Enanos y viajeros por igual se reúnen aquí para beber e intercambiar noticias del lago, y pocos lugares de la región atraen a una clientela tan constante.",
			full = "La Pensión La Cebada se encuentra en Thelsamar, y su hogar rara vez está frío. Enanos y viajeros por igual se reúnen aquí para beber e intercambiar noticias del lago, y pocos lugares de la región atraen a una clientela tan constante.",
			source = "https://warcraft.wiki.gg/wiki/Stoutlager_Inn",
		},
		["thelsamar"] = {
			name = "Thelsamar",
			short = "Thelsamar se encuentra en la orilla occidental de Loch Modan, al norte del Fuerte Zarpagris y al noreste del Valle Rompecantos. Un camino pasa justo al oeste del pueblo y sube por los pasos hacia Dun Morogh y Los Humedales.",
			full = "Thelsamar se encuentra en la orilla occidental de Loch Modan, al norte del Fuerte Zarpagris y al noreste del Valle Rompecantos. Un camino pasa justo al oeste del pueblo y sube por los pasos hacia Dun Morogh y Los Humedales. Los grifos anidan en su posadero, y su posada da cobijo a los viajeros que cruzan las tierras altas.",
			source = "https://warcraft.wiki.gg/wiki/Thelsamar",
		},
		["valley of kings"] = {
			name = "Valle de los Reyes",
			short = "El Valle de los Reyes se encuentra en el extremo suroeste de Loch Modan, donde la tierra verde se estrecha hacia la puerta que baja a la ennegrecida Garganta de Fuego.",
			full = "El Valle de los Reyes se encuentra en el extremo suroeste de Loch Modan, donde la tierra verde se estrecha hacia la puerta que baja a la ennegrecida Garganta de Fuego. Esa puerta está cerrada y vigilada, bajo la mirada del montaraz Guijarro, que solo concede el paso a quienes demuestran ser dignos de él.\n\nLo que atrae la mirada aquí son las dos grandes estatuas que se alzan sobre el paso: Madoran Barbabronce y Khardros Martillo Salvaje, tallados en piedra para vigilar el camino hacia el sur. Cuando los dos reyes murieron, fueron sus hijos quienes levantaron juntos las estatuas, uniendo en piedra a Barbabronce y Martillo Salvaje como sus padres habían estado unidos en vida. Las tierras del sur que se extienden más allá habían sido convertidas en fuego y ceniza por Ragnaros, y las estatuas miran directamente hacia esa ruina: una advertencia para cualquiera que pretenda atacar a los reinos enanos y un recordatorio del precio que pagaron los Hierro Negro por lo que hicieron.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Kings",
		},
	},
	-- Montañas Crestagrana: 16 subzones
	[1433] = {
		["althers mill"] = {
			name = "Molino de Alther",
			short = "El molino al noreste de Villa del Lago está vacío, con su rueda detenida desde hace mucho. Apenas era una parada en el camino al Fuerte de Petravista, y sus ruinas son ahora el hogar de arañas, buitres y algún orco extraviado.",
			full = "El molino al noreste de Villa del Lago está vacío, con su rueda detenida desde hace mucho. Apenas era una parada en el camino al Fuerte de Petravista, y sus ruinas son ahora el hogar de arañas, buitres y algún orco extraviado.",
			source = "https://warcraft.wiki.gg/wiki/Alther's_Mill",
		},
		["galardell valley"] = {
			name = "Valle de Galardell",
			short = "El Valle de Galardell, en el noreste de las Montañas Crestagrana, está plagado de gnolls bajo el mando del teniente Fangore, cuyo aullido hace caer a las manadas sobre cualquiera que se enfrente a él sin estar preparado.",
			full = "El Valle de Galardell, en el noreste de las Montañas Crestagrana, está plagado de gnolls bajo el mando del teniente Fangore, cuyo aullido hace caer a las manadas sobre cualquiera que se enfrente a él sin estar preparado.\n\nSobre el valle se alza la Torre de Ilgalar, morada del malvado Morganth, cuyo solo nombre basta para señalar el lugar como uno que hay que temer.",
			source = "https://warcraft.wiki.gg/wiki/Galardell_Valley",
		},
		["lake everstill"] = {
			name = "Lago Sempiterno",
			short = "El Lago Sempiterno se encuentra en el corazón de las Montañas Crestagrana, con aguas tan amplias y azules que le dan al tranquilo pueblo de Villa del Lago toda su razón de ser.",
			full = "El Lago Sempiterno se encuentra en el corazón de las Montañas Crestagrana, con aguas tan amplias y azules que le dan al tranquilo pueblo de Villa del Lago toda su razón de ser. El lago desagua hacia el este, y su río continúa hacia las piedras oscuras del Fuerte de Petravista.\n\nEn otro tiempo fue un lago de pescadores, tranquilo y fiable, pero eso ha cambiado. Tribus de múrlocs han invadido tanto las aguas someras como las profundas, y en algún lugar de las aguas hondas todavía patrulla un tiburón trillador, tan viejo y enorme que incluso los cazadores más curtidos de las tribus múrloc lo evitan. El puente sempiterno todavía lleva a los viajeros de un lado a otro del agua, por encima de los campamentos múrloc y de la criatura que vigila desde abajo.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Everstill",
		},
		["lakeridge highway"] = {
			name = "Camino del Lago",
			short = "El Camino del Lago tenía en otro tiempo un tráfico constante a lo largo de la orilla sur del Lago Sempiterno, antes de que los orcos se apoderaran del Fuerte de Petravista y el camino cayera en desuso.",
			full = "El Camino del Lago tenía en otro tiempo un tráfico constante a lo largo de la orilla sur del Lago Sempiterno, antes de que los orcos se apoderaran del Fuerte de Petravista y el camino cayera en desuso. Ahora los gnolls recorren casi todo su trayecto, y más adelante acechan cazadores Roca Negra camuflados. Nadie aconsejaría viajar por él.",
			source = "https://warcraft.wiki.gg/wiki/Lakeridge_Highway",
		},
		["lakeshire"] = {
			name = "Villa del Lago",
			short = "El Lago Sempiterno yace quieto y frío bajo los picos de Crestagrana, y el pueblo de su orilla ha derramado sangre por esa tierra más de una vez.",
			full = "El Lago Sempiterno yace quieto y frío bajo los picos de Crestagrana, y el pueblo de su orilla ha derramado sangre por esa tierra más de una vez. Cuando el Jefe de Guerra Puño Negro condujo por primera vez a los orcos a estas montañas, sir Anduin Lothar y los Caballeros de Ventormenta les tendieron una emboscada en las laderas y estuvieron a punto de derrotarlos, hasta que dos brujos del Consejo de la Sombra cambiaron el curso de la batalla y obligaron a Lothar a retroceder. Puño Negro regresó semanas después con una hueste mayor y tomó Villa del Lago sin más. Solo después de la Segunda Guerra la recuperó la Alianza de Lordaeron, y el comandante supremo Turalyon supervisó el regreso de su gente dispersa.",
			source = "https://warcraft.wiki.gg/wiki/Lakeshire",
		},
		["redridge canyons"] = {
			name = "Cañones de Crestagrana",
			short = "Los cañones atraviesan el noroeste de Crestagrana, y sus paredes ocultan la guarida de Ululante, que dirige a los gnolls que dominan este terreno.",
			full = "Los cañones atraviesan el noroeste de Crestagrana, y sus paredes ocultan la guarida de Ululante, que dirige a los gnolls que dominan este terreno.",
			source = "https://warcraft.wiki.gg/wiki/Redridge_Canyons",
		},
		["renders camp"] = {
			name = "Campamento de Render",
			short = "Los orcos Roca Negra tienen un campamento en el noroeste de las Montañas Crestagrana, cerca del camino que lleva a las Estepas Ardientes.",
			full = "Los orcos Roca Negra tienen un campamento en el noroeste de las Montañas Crestagrana, cerca del camino que lleva a las Estepas Ardientes. Desde aquí vigilan el paso, un punto de apoyo del clan Roca Negra pegado a las montañas que llevan a los dominios de su amo.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Camp",
		},
		["renders rock"] = {
			name = "Roca de Render",
			short = "La Roca de Render es una amplia cueva en el noroeste de las Montañas Crestagrana, cerca de las Estepas Ardientes. Los orcos Roca Negra la ocupan en gran número.",
			full = "La Roca de Render es una amplia cueva en el noroeste de las Montañas Crestagrana, cerca de las Estepas Ardientes. Los orcos Roca Negra la ocupan en gran número.\n\nAquí yace herido el cabo Keeshan, aislado, con la necesidad de llegar con vida a Villa del Lago.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Rock",
		},
		["renders valley"] = {
			name = "Valle de Render",
			short = "El Valle de Render se encuentra en el sureste de las Montañas Crestagrana, un puesto de los orcos Roca Negra convertido en bastión, rodeado de torres y defendido por guerreros de élite.",
			full = "El Valle de Render se encuentra en el sureste de las Montañas Crestagrana, un puesto de los orcos Roca Negra convertido en bastión, rodeado de torres y defendido por guerreros de élite.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Valley",
		},
		["rethban caverns"] = {
			name = "Cavernas de Rethban",
			short = "Las Cavernas de Rethban se adentran en el noroeste de las Montañas Crestagrana. Los gnolls ocupan los túneles, dirigidos por el astuto Ardo Dirtpaw, y acumulan la mena de Rethban arrancada a la piedra.",
			full = "Las Cavernas de Rethban se adentran en el noroeste de las Montañas Crestagrana. Los gnolls ocupan los túneles, dirigidos por el astuto Ardo Dirtpaw, y acumulan la mena de Rethban arrancada a la piedra. Puede que las cavernas deban su nombre a un hombre llamado Bart Rethban, aunque poco más se recuerda de él.",
			source = "https://warcraft.wiki.gg/wiki/Rethban_Caverns",
		},
		["stonewatch"] = {
			name = "Petravista",
			short = "Petravista perteneció en otro tiempo a los humanos de Villa del Lago: un bastión levantado contra los acantilados donde las cascadas caen bajo el fuerte, que vigilaba Crestagrana frente a la amenaza orca de las Estepas Ardientes.",
			full = "Petravista perteneció en otro tiempo a los humanos de Villa del Lago: un bastión levantado contra los acantilados donde las cascadas caen bajo el fuerte, que vigilaba Crestagrana frente a la amenaza orca de las Estepas Ardientes.\n\nEsa vigilancia se rompió por una traición. El brujo Morganth se alió con Gath'Ilzogg y sus orcos Roca Negra, y juntos cayeron sobre el Fuerte de Petravista con una ferocidad que quebró a la guarnición. Los orcos tomaron el fuerte, pero su triunfo duró poco en cuanto a confianza, pues Morganth se volvió contra los aliados que lo habían conquistado para él. Levantó para sí la Torre de Ilgalar y sometió a sus propios fines a una partida de guerra de gnolls Pielsombra, bajo el mando del teniente Fangore. Desde aquel giro, tanto orcos como hombres que se cruzan en el camino de los gnolls lo han pagado caro.\n\nAbandonados por el brujo que los había utilizado, los orcos Roca Negra conservaron el fuerte por su cuenta, gobernado por Gath'Ilzogg con su lugarteniente Tharil'zun a su lado.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch",
		},
		["stonewatch falls"] = {
			name = "Cascadas Petravista",
			short = "Bajo Petravista, el río oriental del Lago Sempiterno cae en una larga cascada por la ladera y se acumula en un lago profundo en un rincón de las Montañas Crestagrana.",
			full = "Bajo Petravista, el río oriental del Lago Sempiterno cae en una larga cascada por la ladera y se acumula en un lago profundo en un rincón de las Montañas Crestagrana. Una pequeña tribu de múrlocs se ha instalado en sus orillas, donde pesca en el agua y levanta toscos refugios bajo las cascadas.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Falls",
		},
		["stonewatch keep"] = {
			name = "Fuerte de Petravista",
			short = "El Fuerte de Petravista perteneció en otro tiempo a los humanos de Villa del Lago, destinado a vigilar Crestagrana.",
			full = "El Fuerte de Petravista perteneció en otro tiempo a los humanos de Villa del Lago, destinado a vigilar Crestagrana. Cayó cuando el brujo Morganth se alió con el caudillo orco Roca Negra Gath'Ilzogg, y juntos lanzaron sus fuerzas contra el fuerte con una ferocidad alimentada por la magia oscura de Morganth. Los defensores cedieron, y el fuerte fue tomado.\n\nLa alianza no duró. Apenas había caído Petravista cuando Morganth se volvió contra los orcos que habían sangrado por ella a su lado. Levantó cerca la Torre de Ilgalar y la llenó de gnolls Pielsombra bajo el mando del teniente Fangore, criaturas sometidas solo a su voluntad. Desde entonces, orcos y hombres por igual han caído ante las bestias que desató.\n\nAbandonados por su aliado brujo, los orcos Roca Negra conservaron el fuerte por su cuenta, y Gath'Ilzogg y su lugarteniente Tharil'zun gobiernan lo que queda de él. Durante la batalla habían capturado al cabo Keeshan del ejército de Ventormenta y lo habían arrastrado al norte, a sus campamentos. Por ello, el magistrado Solomon puso precio a la cabeza de Gath'Ilzogg, y el alguacil Marris de Villa del Lago juró que Tharil'zun también respondería por sus crímenes.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Keep",
		},
		["stonewatch tower"] = {
			name = "Torre de Petravista",
			short = "La Torre de Petravista se alzaba en otro tiempo junto al Fuerte de Petravista, ambos en manos de los humanos de Villa del Lago, hasta que el clan Roca Negra se apoderó del bastión.",
			full = "La Torre de Petravista se alzaba en otro tiempo junto al Fuerte de Petravista, ambos en manos de los humanos de Villa del Lago, hasta que el clan Roca Negra se apoderó del bastión. La torre sirve como puesto de exploración para los subordinados de Gath'Ilzogg, orcos del clan Roca Negra que vigilan el bastión que sus parientes arrebataron a los hombres de Villa del Lago.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Tower",
		},
		["three corners"] = {
			name = "Tres Caminos",
			short = "En Tres Caminos, el camino se divide en tres direcciones: al oeste hacia Villadorada, en el Bosque de Elwynn; al este hacia Villa del Lago; y al sur hacia Villa Oscura, en el Bosque del Ocaso.",
			full = "En Tres Caminos, el camino se divide en tres direcciones: al oeste hacia Villadorada, en el Bosque de Elwynn; al este hacia Villa del Lago; y al sur hacia Villa Oscura, en el Bosque del Ocaso. Aquí, un viajero se encuentra en la costura de tres tierras, sin nada más que el cruce para marcar el paso entre ellas. Los gnolls presionan desde las colinas cercanas.",
			source = "https://warcraft.wiki.gg/wiki/Three_Corners",
		},
		["tower of ilgalar"] = {
			name = "Torre de Ilgalar",
			short = "La Torre de Ilgalar se alza en el este de las Montañas Crestagrana.",
			full = "La Torre de Ilgalar se alza en el este de las Montañas Crestagrana. La gobierna Morganth, un hechicero desterrado del Barrio de los Magos de Ventormenta por sus oscuros estudios, que tomó la torre como refugio y sometió a su voluntad al clan de gnolls Pielsombra.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Ilgalar",
		},
	},
	-- Vega de Tuercespina: 38 subzones
	[1434] = {
		["baliamah ruins"] = {
			name = "Ruinas de Balia'mah",
			short = "Las piedras de Balia'mah son una antigua obra trol que se alza al este del río, por debajo de Mosh'Ogg. Ahora las ocupan los trols Machacacráneos, que han hecho su hogar de lo que levantaron sus ancestros.",
			full = "Las piedras de Balia'mah son una antigua obra trol que se alza al este del río, por debajo de Mosh'Ogg. Ahora las ocupan los trols Machacacráneos, que han hecho su hogar de lo que levantaron sus ancestros.",
			source = "https://warcraft.wiki.gg/wiki/Balia'mah_Ruins",
		},
		["ballal ruins"] = {
			name = "Ruinas de Bal'lal",
			short = "Unas columnas rotas se alzan cerca del Arrecife Mortal, al norte del Campamento Grom'gol: es todo lo que queda de un asentamiento que los trols levantaron hace mucho tiempo. Poco de lo que fue sigue en pie.",
			full = "Unas columnas rotas se alzan cerca del Arrecife Mortal, al norte del Campamento Grom'gol: es todo lo que queda de un asentamiento que los trols levantaron hace mucho tiempo. Poco de lo que fue sigue en pie. Ahora los trols Sangrapellejo ocupan la ruina y viven entre las piedras que dejaron sus ancestros.",
			source = "https://warcraft.wiki.gg/wiki/Bal'lal_Ruins",
		},
		["bloodsail compound"] = {
			name = "Complejo Velasangre",
			short = "Los Bucaneros Velasangre tienen un campamento desordenado a lo largo de la costa occidental de la Vega de Tuercespina, hacia el tramo central de la orilla.",
			full = "Los Bucaneros Velasangre tienen un campamento desordenado a lo largo de la costa occidental de la Vega de Tuercespina, hacia el tramo central de la orilla. Aquí no ondea ningún estandarte de orden ni hay disciplina de puerto como es debido: solo la reunión dispersa de piratas que consideran suyo este lugar.",
			source = "https://warcraft.wiki.gg/wiki/Bloodsail_Compound",
		},
		["booty bay"] = {
			name = "Bahía del Botín",
			short = "Bahía del Botín se encuentra en una laguna azul en el extremo sur de la Vega de Tuercespina, y a pie se entra a través de las fauces blanqueadas de un tiburón gigante.",
			full = "Bahía del Botín se encuentra en una laguna azul en el extremo sur de la Vega de Tuercespina, y a pie se entra a través de las fauces blanqueadas de un tiburón gigante. Aquí la vida vale poco y no hay que confiar en nadie; es un paraíso de pícaros, lleno de informantes y comerciantes de toda clase.\n\nAntes de llevar ese nombre, la cala se llamaba Cala Aguasnegras, un pequeño puerto humano hasta que los trols de la selva lo invadieron. Los goblins del Cártel Bonvapor hicieron retroceder a los trols de la orilla y reclamaron la cala para sí, antes incluso de que se librara la Primera Guerra, y construyeron allí su centro de operaciones en los Reinos del Este.\n\nAhora los asaltantes Aguasnegras dirigen el puerto, en estrecha colaboración con el Cártel, y sus puertas están abiertas a cualquier viajero, sea cual sea su estandarte. El barón Revilgaz gobierna desde lo alto de la posada, junto al maestro de flota Cuernomarino de los asaltantes, y ha gastado sin reparos en contratar espadas contra los Bucaneros Velasangre, piratas que han conspirado, sin éxito, para apoderarse de la propia bahía.",
			source = "https://warcraft.wiki.gg/wiki/Booty_Bay",
		},
		["cape of stranglethorn"] = {
			name = "El Cabo de Tuercespina",
			short = "El sur de la Vega de Tuercespina está lleno de ruinas trol, medio engullidas por la selva, y de largas extensiones de playa arenosa donde los árboles dan paso al mar.",
			full = "El sur de la Vega de Tuercespina está lleno de ruinas trol, medio engullidas por la selva, y de largas extensiones de playa arenosa donde los árboles dan paso al mar.\n\nA lo largo de la costa se encuentra Bahía del Botín, una ciudad portuaria dirigida por piratas goblins, cuyos muelles y mercado están abiertos a cualquiera que tenga monedas, sea cual sea su estandarte.\n\nEsa neutralidad no es paz. Los goblins de Bahía del Botín conservan su puerto mediante el comercio y la fuerza, y sus rivales son los Bucaneros Velasangre, piratas que se han vuelto contra ellos y se dedican a asaltar las aguas y la costa que los goblins consideran suyas. El conflicto entre ambos no ha hecho más que empeorar, barco contra barco y campamento contra campamento, con los goblins defendiendo lo que construyeron mientras los Velasangre presionan para arrebatárselo.\n\nMás allá del puerto y de las ruinas, la tierra está en calma: arena, piedra antigua y el mar al fondo.",
			source = "https://warcraft.wiki.gg/wiki/Cape_of_Stranglethorn",
		},
		["crystal shore"] = {
			name = "La Costa de Cristal",
			short = "La Costa de Cristal es una orilla arenosa en el sureste de Tuercespina, donde los Mares del Sur rompen contra el continente y contra las playas orientales de la Isla Jaguero.",
			full = "La Costa de Cristal es una orilla arenosa en el sureste de Tuercespina, donde los Mares del Sur rompen contra el continente y contra las playas orientales de la Isla Jaguero. Se extiende desde la Orilla Salvaje hasta los acantilados donde la tierra se eleva hacia el norte, separada del interior por una cresta empinada que solo cruzan dos senderos, uno de los cuales sube hacia el Valle del Velo de Bruma.\n\nLas Ruinas de Aboraz se encuentran en el extremo norte de la costa.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Shore",
		},
		["crystalvein mine"] = {
			name = "Mina de Cristal",
			short = "Loquillo Pinchabujas los llamaba cristales canto, exclusivos de Tuercespina y que valen una fortuna.",
			full = "Loquillo Pinchabujas los llamaba cristales canto, exclusivos de Tuercespina y que valen una fortuna. Recorren en vetas la roca de la Mina de Cristal, cerca de Zul'Mamwe, y los basiliscos que anidan allí se los comen crudos, lo que endurece su piel hasta volverla de piedra. Ventura y Cía. entró con la esperanza de vaciar la mina, pero los basiliscos han rechazado todos sus intentos. Frente a la entrada, trols y humanos permanecen cristalizados allí donde cayeron.",
			source = "https://warcraft.wiki.gg/wiki/Crystalvein_Mine",
		},
		["gromgol base camp"] = {
			name = "Campamento Grom'gol",
			short = "El Campamento Grom'gol se alza fortificado en la costa suroeste de Tuercespina, con sus empalizadas levantadas contra los trols de la selva de la costa, contra los nagas que surgen del oleaje y contra la Alianza que se abre paso desde Bahía del Botín y el Bosque del Ocaso.",
			full = "El Campamento Grom'gol se alza fortificado en la costa suroeste de Tuercespina, con sus empalizadas levantadas contra los trols de la selva de la costa, contra los nagas que surgen del oleaje y contra la Alianza que se abre paso desde Bahía del Botín y el Bosque del Ocaso. El comandante Aggro'gosh defiende el campamento y lo mantiene como eslabón seguro de la cadena de suministros que llega hasta Rocal, en el Pantano de las Penas.",
			source = "https://warcraft.wiki.gg/wiki/Grom'gol_Base_Camp",
		},
		["gurubashi arena"] = {
			name = "Arena Gurubashi",
			short = "La Arena Gurubashi se alza en el noroeste de Tuercespina, una reliquia levantada en los días en que el Imperio Gurubashi gobernaba vastas extensiones del sur de los Reinos del Este.",
			full = "La Arena Gurubashi se alza en el noroeste de Tuercespina, una reliquia levantada en los días en que el Imperio Gurubashi gobernaba vastas extensiones del sur de los Reinos del Este.\n\nEn tiempos antiguos, los combates que se celebraban aquí no eran un deporte, sino una matanza. La arena se volvía barro con la sangre trol mientras los combatientes luchaban a muerte. Ahora Corto John Mitril supervisa combates de un tipo más amable, que ofrecen fama y botín en lugar de muerte. Viejas historias todavía advierten que quien encuentre un amuleto rojo sangre a medianoche será devorado por un demonio antes del amanecer.",
			source = "https://warcraft.wiki.gg/wiki/Gurubashi_Arena",
		},
		["jaguero isle"] = {
			name = "Isla Jaguero",
			short = "Frente a la costa de la Orilla Salvaje se encuentra la Isla Jaguero, una selva dominada por panteras y gorilas que no responden ante nadie.",
			full = "Frente a la costa de la Orilla Salvaje se encuentra la Isla Jaguero, una selva dominada por panteras y gorilas que no responden ante nadie. El principal de ellos es el rey Mukla, un simio enorme que gobierna la isla y mantiene cautiva a la princesa Poobah, una tauren retenida contra su voluntad.\n\nMedio enterradas a lo largo de la orilla hay botellas arrastradas por el mar, y una de ellas contiene una nota doblada.",
			source = "https://warcraft.wiki.gg/wiki/Jaguero_Isle",
		},
		["janeiros point"] = {
			name = "Cayo de Janeiro",
			short = "El Cayo de Janeiro es una pequeña isla frente a Bahía del Botín, señalada por un gran goblin de piedra con los brazos abiertos, levantado como faro para dar la bienvenida a los barcos que llegan al puerto.",
			full = "El Cayo de Janeiro es una pequeña isla frente a Bahía del Botín, señalada por un gran goblin de piedra con los brazos abiertos, levantado como faro para dar la bienvenida a los barcos que llegan al puerto. Hoy nadie recuerda a quién representa. El gigante marino Mok'rash el Rajador ha establecido su morada en la isla.",
			source = "https://warcraft.wiki.gg/wiki/Janeiro's_Point",
		},
		["kalai ruins"] = {
			name = "Ruinas de Kal'ai",
			short = "Las Ruinas de Kal'ai yacen medio engullidas por el mar en la Vega de Tuercespina, antigua cantería trol desgastada por la marea y el tiempo.",
			full = "Las Ruinas de Kal'ai yacen medio engullidas por el mar en la Vega de Tuercespina, antigua cantería trol desgastada por la marea y el tiempo. La tribu de múrlocs Murkgill anida ahora entre las columnas caídas, tras reclamar como suyos los salones anegados.",
			source = "https://warcraft.wiki.gg/wiki/Kal'ai_Ruins",
		},
		["kurzens compound"] = {
			name = "Base de Kurzen",
			short = "La Base de Kurzen se alza al este del Asentamiento Rebelde, sede de la expedición de Kurzen. La dirige el coronel Kurzen, aunque la locura se ha apoderado de él.",
			full = "La Base de Kurzen se alza al este del Asentamiento Rebelde, sede de la expedición de Kurzen. La dirige el coronel Kurzen, aunque la locura se ha apoderado de él. No se habla de aquello en lo que se convirtió, solo del resultado: los hombres a sus órdenes se dividieron. Quienes no quisieron seguirlo más allá se separaron y se convirtieron en los combatientes selváticos del Asentamiento Rebelde, y desde entonces la base está en guerra con ellos: hombres que antes pertenecían a un mismo mando ahora se matan unos a otros entre los árboles.\n\nEl propio Kurzen ya no se deja ver a menudo entre sus hombres; se dice que permanece en el Arsenal, al fondo de la base, donde los combatientes guardan sus armas. Cerca de los establos, panteras y tigres de Tuercespina permanecen enjaulados, domados y adiestrados como bestias de guerra para uso de la expedición.",
			source = "https://warcraft.wiki.gg/wiki/Kurzen's_Compound",
		},
		["lake nazferiti"] = {
			name = "Lago Nazferiti",
			short = "Las aguas del Lago Nazferiti están llenas de pirañas frenéticas y crocoliscos, y una gran base de Ventura y Cía. ocupa su orilla.",
			full = "Las aguas del Lago Nazferiti están llenas de pirañas frenéticas y crocoliscos, y una gran base de Ventura y Cía. ocupa su orilla.\n\nEl lago se alimenta del río Nazferiti, que algunos consideran el más largo del sur de los Reinos del Este, y que nace en una cascada de las Montañas Crestagrana, o quizá aún más lejos, en el Paso de la Muerte.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Nazferiti",
		},
		["mistvale valley"] = {
			name = "Valle del Velo de Bruma",
			short = "La niebla se asienta baja sobre el Valle del Velo de Bruma, tan espesa que desdibuja la línea de los árboles en el sur de la Vega de Tuercespina.",
			full = "La niebla se asienta baja sobre el Valle del Velo de Bruma, tan espesa que desdibuja la línea de los árboles en el sur de la Vega de Tuercespina. Los grandes gorilas del Velo de Bruma tienen aquí su hogar, se mueven entre la niebla y los árboles, amos indiscutidos de esta hondonada tranquila y húmeda.",
			source = "https://warcraft.wiki.gg/wiki/Mistvale_Valley",
		},
		["mizjah ruins"] = {
			name = "Ruinas de Mizjah",
			short = "Las Ruinas de Mizjah se encuentran al sureste del Campamento Grom'gol, en manos de los brutos Mosh'Ogg y sus médicos brujos.",
			full = "Las Ruinas de Mizjah se encuentran al sureste del Campamento Grom'gol, en manos de los brutos Mosh'Ogg y sus médicos brujos. Desde estas piedras rotas, los ogros atacan a las caravanas que se dirigen a Rocal, tendiendo emboscadas a las líneas de suministro y desapareciendo de nuevo entre las ruinas antes de que pueda haber respuesta.",
			source = "https://warcraft.wiki.gg/wiki/Mizjah_Ruins",
		},
		["moshogg ogre mound"] = {
			name = "Túmulo Ogro Mosh'Ogg",
			short = "El Túmulo Ogro Mosh'Ogg se encuentra al sur de Zul'Gurub, y sus oscuras cavidades son el hogar de la tribu de ogros Mosh'Ogg.",
			full = "El Túmulo Ogro Mosh'Ogg se encuentra al sur de Zul'Gurub, y sus oscuras cavidades son el hogar de la tribu de ogros Mosh'Ogg. En lo más profundo, su líder, el mago ogro Mai'Zoth, guarda una poderosa reliquia conocida como el Ojo de la Mente, y es desde esas profundidades desde donde gobierna hoy el túmulo.",
			source = "https://warcraft.wiki.gg/wiki/Mosh'Ogg_Ogre_Mound",
		},
		["nekmani wellspring"] = {
			name = "Manantial Nek'mani",
			short = "El Manantial Nek'mani brota en los acantilados que dominan la Costa Salvaje del Sur, en el extremo occidental de Tuercespina.",
			full = "El Manantial Nek'mani brota en los acantilados que dominan la Costa Salvaje del Sur, en el extremo occidental de Tuercespina.\n\nLos eruditos de todas las razas afirman que sus aguas fueron consagradas solo para su propio pueblo, y nadie lo ha resuelto jamás.",
			source = "https://warcraft.wiki.gg/wiki/Nek'mani_Wellspring",
		},
		["nesingwarys expedition"] = {
			name = "Expedición de Nesingwary",
			short = "Hemet Nesingwary, un maestro cazador enano, dirigió una expedición a Tuercespina, atraído por la caza salvaje de la selva.",
			full = "Hemet Nesingwary, un maestro cazador enano, dirigió una expedición a Tuercespina, atraído por la caza salvaje de la selva. Instaló su campamento justo por debajo del río, al norte del Lago Nazferiti, y todavía sigue en pie: un punto de apoyo de cazadores abierto en la maraña verde de Tuercespina.",
			source = "https://warcraft.wiki.gg/wiki/Nesingwary's_Expedition",
		},
		["rebel camp"] = {
			name = "Asentamiento Rebelde",
			short = "El Asentamiento Rebelde se encuentra en el norte de la Vega de Tuercespina, al oeste del camino que baja hacia el sur desde el Bosque del Ocaso y al noroeste de la Base de Kurzen.",
			full = "El Asentamiento Rebelde se encuentra en el norte de la Vega de Tuercespina, al oeste del camino que baja hacia el sur desde el Bosque del Ocaso y al noroeste de la Base de Kurzen.\n\nSus fundadores sirvieron en la expedición del coronel Kurzen hasta que la locura se apoderó de él y de sus hombres y les retorció la mente hasta volverlos irreconocibles. Un pequeño grupo al mando del teniente Doren logró liberarse antes de que la locura los alcanzara y huyó de la Base de Kurzen hacia el oeste a través de la selva.\n\nAllí construyeron el Asentamiento Rebelde, un punto de apoyo desde el que deshacer aquello en lo que se había convertido Kurzen. Krazek, de Bahía del Botín, los abastece de minas terrestres y otros medios de defensa, suficientes para que los rebeldes resistan frente a la guarnición maldita junto a la que antes servían.",
			source = "https://warcraft.wiki.gg/wiki/Rebel_Camp",
		},
		["ruins of aboraz"] = {
			name = "Ruinas de Aboraz",
			short = "Aboraz fue levantada por trols antiguos, pero ahora no pertenece a nadie.",
			full = "Aboraz fue levantada por trols antiguos, pero ahora no pertenece a nadie. Zanzil el Desterrado, exiliado de su propia gente, ha reclamado las ruinas como su dominio y las ha llenado de necrófagos, nagas y esbirros trol que obedecen a sus artes de médico brujo.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Aboraz",
		},
		["ruins of jubuwal"] = {
			name = "Ruinas de Jubuwal",
			short = "Las Ruinas de Jubuwal se encuentran al este de la Arena Gurubashi, un antiguo asentamiento trol ocupado ahora por necrófagos, nagas y trols al servicio de Zanzil el Desterrado.",
			full = "Las Ruinas de Jubuwal se encuentran al este de la Arena Gurubashi, un antiguo asentamiento trol ocupado ahora por necrófagos, nagas y trols al servicio de Zanzil el Desterrado. Entre ellos se esconden Jon-Jon el Cuervo y Maury \"Pie Zambo\" Wilkins, hombres que huyeron a esa lúgubre compañía para escapar de las deudas que tenían con el despiadado MacKinley \"Lobo de Mar\".",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Jubuwal",
		},
		["ruins of zulkunda"] = {
			name = "Ruinas de Zul'Kunda",
			short = "Las terrazas de piedra de Zul'Kunda pertenecen ahora a los trols Sangrapellejo, gobernados por Nezzliok el Temible y Gan'zulah.",
			full = "Las terrazas de piedra de Zul'Kunda pertenecen ahora a los trols Sangrapellejo, gobernados por Nezzliok el Temible y Gan'zulah. El sendero que va hacia el este desde las Ruinas Zuuldaia lleva directamente a su territorio, donde la antigua cantería trol ha sido reclamada por los vivos.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Kunda",
		},
		["ruins of zulmamwe"] = {
			name = "Ruinas de Zul'Mamwe",
			short = "Las Ruinas de Zul'Mamwe están rodeadas de montañas por todos lados salvo por el norte, al sur del Túmulo Ogro Mosh'Ogg.",
			full = "Las Ruinas de Zul'Mamwe están rodeadas de montañas por todos lados salvo por el norte, al sur del Túmulo Ogro Mosh'Ogg. Son la sede de los Machacacráneos, la segunda de las tribus trol de la Vega de Tuercespina, gobernados por su jefe, Ana'thek el Cruel.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Mamwe",
		},
		["savage coast"] = {
			name = "La Costa Salvaje",
			short = "La Costa Salvaje se extiende a lo largo de la orilla norte de la Vega de Tuercespina, desde la frontera con los Páramos de Poniente, pasando por el Arrecife Mortal, hasta Grom'gol.",
			full = "La Costa Salvaje se extiende a lo largo de la orilla norte de la Vega de Tuercespina, desde la frontera con los Páramos de Poniente, pasando por el Arrecife Mortal, hasta Grom'gol.\n\nLos crocoliscos rondan sus aguas poco profundas y los basiliscos acechan en sus rocas, con una mirada que convierte en piedra a los incautos. Varios asentamientos trol vigilan estas aguas.",
			source = "https://warcraft.wiki.gg/wiki/Savage_Coast",
		},
		["south seas"] = {
			name = "Mares del Sur",
			short = "Los Mares del Sur ocupan las aguas entre los continentes conocidos, una parte del Mare Magnum. De estas aguas surge Zandalar, antiguo hogar del imperio trol.",
			full = "Los Mares del Sur ocupan las aguas entre los continentes conocidos, una parte del Mare Magnum. De estas aguas surge Zandalar, antiguo hogar del imperio trol. Entre ellas se encuentra también Kezan, una isla volcánica cuyo pueblo se mantiene apartado de las potencias del continente. Más cerca de la Vega de Tuercespina, el mar se vuelve traicionero, con arrecifes e islotes, algunos no más que un banco de arena, otros con ruinas cuyos constructores ya no existen. Los Mares del Sur bañan las fronteras de Tuercespina, Tanaris y Uldum.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southern savage coast"] = {
			name = "Costa Salvaje del Sur",
			short = "La Costa Salvaje del Sur se encuentra donde los Mares del Sur rompen contra playas abiertas y aguas poco profundas, y llega hasta las aguas cercanas a Bahía del Botín y al Cayo de Janeiro, donde la orilla da paso a la Orilla Salvaje.",
			full = "La Costa Salvaje del Sur se encuentra donde los Mares del Sur rompen contra playas abiertas y aguas poco profundas, y llega hasta las aguas cercanas a Bahía del Botín y al Cayo de Janeiro, donde la orilla da paso a la Orilla Salvaje.\n\nEl Arrecife Mortal marca la línea entre esta costa y su homóloga del norte, donde el Mare Magnum da paso a los Mares del Sur. Bahías y ensenadas ponen la costa en contacto con la Arena Gurubashi y el Manantial Nek'mani.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Savage_Coast",
		},
		["spirit den"] = {
			name = "Cubil del Espíritu",
			short = "El Cubil del Espíritu se oculta en una cueva en el extremo norte del Valle del Velo de Bruma. Allí, el médico brujo Unbagwa permanece entre las sombras de la guarida, atendiendo a los espíritus que rondan esa hondonada tranquila e invisible.",
			full = "El Cubil del Espíritu se oculta en una cueva en el extremo norte del Valle del Velo de Bruma. Allí, el médico brujo Unbagwa permanece entre las sombras de la guarida, atendiendo a los espíritus que rondan esa hondonada tranquila e invisible.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Den",
		},
		["stockpile"] = {
			name = "Las Reservas",
			short = "En una cueva al fondo de la Base de Kurzen, el coronel Kurzen guarda el equipo de su guerra.",
			full = "En una cueva al fondo de la Base de Kurzen, el coronel Kurzen guarda el equipo de su guerra.",
			source = "https://warcraft.wiki.gg/wiki/Stockpile",
		},
		["tkashi ruins"] = {
			name = "Ruinas de Tkashi",
			short = "Las Ruinas de Tkashi se encuentran en la Vega de Tuercespina, antigua cantería trol reconquistada por la selva.",
			full = "Las Ruinas de Tkashi se encuentran en la Vega de Tuercespina, antigua cantería trol reconquistada por la selva. Ahora las ocupa la tribu Sangrapellejo, cuyos chamanes practican ritos antiguos entre los muros derrumbados, y todavía hay artefactos esparcidos entre los restos.",
			source = "https://warcraft.wiki.gg/wiki/Tkashi_Ruins",
		},
		["venture co base camp"] = {
			name = "Base de Ventura y Cía.",
			short = "Ventura y Cía. tiene aquí un campamento base dedicado a la búsqueda de cristales pulidos. Cerca se alza su Centro de Operaciones, y ambos trabajan juntos en busca del mismo hallazgo.",
			full = "Ventura y Cía. tiene aquí un campamento base dedicado a la búsqueda de cristales pulidos. Cerca se alza su Centro de Operaciones, y ambos trabajan juntos en busca del mismo hallazgo.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Base_Camp",
		},
		["venture co operations center"] = {
			name = "Centro de Operaciones de Ventura y Cía.",
			short = "La plataforma petrolera de Ventura y Cía. se alza en un lago de la selva, el centro de operaciones de su avance hacia las tierras salvajes.",
			full = "La plataforma petrolera de Ventura y Cía. se alza en un lago de la selva, el centro de operaciones de su avance hacia las tierras salvajes. Mecánicos, geólogos y otras cuadrillas goblin abarrotan la plataforma, manejando la maquinaria de una empresa empeñada en despojar la tierra para obtener beneficios.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Operations_Center",
		},
		["vile reef"] = {
			name = "El Arrecife Mortal",
			short = "Frente a la costa occidental de la Vega de Tuercespina, cerca de Grom'gol, el mar rompe brillante sobre el coral.",
			full = "Frente a la costa occidental de la Vega de Tuercespina, cerca de Grom'gol, el mar rompe brillante sobre el coral. Debajo yacen ruinas trol hundidas, y entre esa piedra anegada los múrlocs han hecho ahora su hogar: densos bancos que se mueven por salones que antes pertenecieron a otros. El Altar de las Mareas todavía sigue en pie allí. Almejas gigantes cubren el fondo del arrecife, y se dice que guardan perlas azules, mientras los restos de barcos que nunca lograron sortear el arrecife llegan rodando a la orilla.",
			source = "https://warcraft.wiki.gg/wiki/Vile_Reef",
		},
		["wild shore"] = {
			name = "Orilla Salvaje",
			short = "La Orilla Salvaje es el lugar donde los Reinos del Este dan paso a los Mares del Sur, y sus playas están en manos de los Bucaneros Velasangre, cuya flota navega frente a la costa y cuyas tripulaciones reclaman la arena como suya.",
			full = "La Orilla Salvaje es el lugar donde los Reinos del Este dan paso a los Mares del Sur, y sus playas están en manos de los Bucaneros Velasangre, cuya flota navega frente a la costa y cuyas tripulaciones reclaman la arena como suya. En algún lugar de la orilla vaga Gorlash, un gigante solitario, y entre piratas y gigante, la costa no responde ante ninguna corona.\n\nLa tierra se estrecha hacia el oeste hasta formar una punta rocosa antes de girar hacia Bahía del Botín. Al este, al otro lado de un estrecho poco profundo, se encuentra la Isla Jaguero. Hacia el norte, la arena se funde con la Costa de Cristal.",
			source = "https://warcraft.wiki.gg/wiki/Wild_Shore",
		},
		["yojamba isle"] = {
			name = "Isla Yojamba",
			short = "En estas pequeñas islas frente a la costa noroeste de Tuercespina, cerca de la frontera con los Páramos de Poniente, la tribu Zandalar se enfrentó a un dios enloquecido.",
			full = "En estas pequeñas islas frente a la costa noroeste de Tuercespina, cerca de la frontera con los Páramos de Poniente, la tribu Zandalar se enfrentó a un dios enloquecido.\n\nHakkar el Desollador de Almas había convertido Zul'Gurub en un lugar de sangre y locura, y los zandalari sabían que no podían enfrentarse solos a él. Así que vinieron a la Isla Yojamba y pidieron tanto a la Alianza como a la Horda que dejaran de lado su guerra el tiempo suficiente para ayudarlos a destruirlo. Era una tribu antigua y orgullosa que confiaba a extraños el destino de su ciudad tocada por los dioses.",
			source = "https://warcraft.wiki.gg/wiki/Yojamba_Isle",
		},
		["ziatajai ruins"] = {
			name = "Ruinas de Ziata'jai",
			short = "Las Ruinas de Ziata'jai son piedras antiguas levantadas por trols hace mucho tiempo, ahora reclamadas por la tribu Machacacráneos, que considera suyos los viejos muros.",
			full = "Las Ruinas de Ziata'jai son piedras antiguas levantadas por trols hace mucho tiempo, ahora reclamadas por la tribu Machacacráneos, que considera suyos los viejos muros.",
			source = "https://warcraft.wiki.gg/wiki/Ziata'jai_Ruins",
		},
		["zulgurub"] = {
			name = "Zul'Gurub",
			short = "Zul'Gurub se alza de la selva en el noreste de la Vega de Tuercespina, con sus terrazas e ídolos cubiertos de vegetación pero todavía en pie: una ciudad templo que fue en otro tiempo el corazón palpitante de un imperio.",
			full = "Zul'Gurub se alza de la selva en el noreste de la Vega de Tuercespina, con sus terrazas e ídolos cubiertos de vegetación pero todavía en pie: una ciudad templo que fue en otro tiempo el corazón palpitante de un imperio. Hace miles de años fue la capital del Imperio Gurubashi, sede de todas las tribus de trols de la selva ligadas a él. Ahora solo pertenece a la tribu Gurubashi que queda, y la selva que la rodea no se siente vacía.\n\nEl imperio se desgarró cuando un círculo de sacerdotes llamados los Atal'ai invocó al avatar de un antiguo dios de la sangre, Hakkar el Desollador de Almas, y fue desterrado por ello. Descubrieron que Hakkar solo podía adoptar forma física en un lugar: la propia capital antigua de los Gurubashi. Es aquí donde Jin'do el Maleficiador ha esclavizado a varios sumos sacerdotes de los Gurubashi y los ha doblegado para la tarea de traer a Hakkar al mundo. Los campeones enviados a detenerlo, cada uno ligado a un dios primigenio, han caído en cambio bajo el dominio de Hakkar, y ahora su poder alimenta precisamente aquello que vinieron a destruir.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Gurub",
		},
		["zuuldaia ruins"] = {
			name = "Ruinas Zuuldaia",
			short = "Piedra desgastada se alza sobre la costa occidental de la Vega de Tuercespina, ruinas de un asentamiento caído hace mucho tiempo.",
			full = "Piedra desgastada se alza sobre la costa occidental de la Vega de Tuercespina, ruinas de un asentamiento caído hace mucho tiempo. Ahora los trols Sangrapellejo ocupan los muros derrumbados, apiñados entre los viejos cimientos, y reclaman un terreno que sus ancestros nunca levantaron.",
			source = "https://warcraft.wiki.gg/wiki/Zuuldaia_Ruins",
		},
	},
	-- Pantano de las Penas: 14 subzones
	[1435] = {
		["fallow sanctuary"] = {
			name = "Retiro Fangoso",
			short = "En el Pantano de las Penas se alza el Retiro Fangoso, hogar de una tribu de Perdidos conocida simplemente como Los Perdidos.",
			full = "En el Pantano de las Penas se alza el Retiro Fangoso, hogar de una tribu de Perdidos conocida simplemente como Los Perdidos. La nostalgia se ha apoderado de todos ellos y los ha vuelto completamente salvajes, de modo que no queda nada de lo que fueron para recibir a quien se acerque a su aldea.",
			source = "https://warcraft.wiki.gg/wiki/Fallow_Sanctuary",
		},
		["harborage"] = {
			name = "El Puerto",
			short = "En el norte del Pantano de las Penas se alza un refugio de quienes cruzaron de Draenor a Azeroth y, a diferencia de tantos de sus congéneres, conservaron la mente intacta.",
			full = "En el norte del Pantano de las Penas se alza un refugio de quienes cruzaron de Draenor a Azeroth y, a diferencia de tantos de sus congéneres, conservaron la mente intacta. Magtoor los dirige aquí.",
			source = "https://warcraft.wiki.gg/wiki/Harborage",
		},
		["ithariuss cave"] = {
			name = "Cueva de Itharius",
			short = "En el suroeste del Pantano de las Penas, una cueva da refugio al alto elfo Itharius. Afuera, unas revoltosas crías de dragón verde se pelean y tropiezan, demasiado jóvenes para dominar las alas o el fuego.",
			full = "En el suroeste del Pantano de las Penas, una cueva da refugio al alto elfo Itharius. Afuera, unas revoltosas crías de dragón verde se pelean y tropiezan, demasiado jóvenes para dominar las alas o el fuego. Itharius ha asumido la tarea de cuidarlas mientras crecen.",
			source = "https://warcraft.wiki.gg/wiki/Itharius's_Cave",
		},
		["misty reed post"] = {
			name = "Puesto Juncobruma",
			short = "El Puesto Juncobruma es un pequeño puesto de avanzada de Rocal, situado entre Stagalbog y el sur de la Playa Juncobruma. Lo ocupa Tok'Kar, junto con Katar, un puñado de cazadores de Rocal y un chamán de Rocal.",
			full = "El Puesto Juncobruma es un pequeño puesto de avanzada de Rocal, situado entre Stagalbog y el sur de la Playa Juncobruma. Lo ocupa Tok'Kar, junto con Katar, un puñado de cazadores de Rocal y un chamán de Rocal. Es solo un campamento, sin madriguera ni torre, aunque Tok'Kar sueña con levantar una algún día.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Post",
		},
		["misty reed strand"] = {
			name = "Playa Juncobruma",
			short = "La Playa Juncobruma se extiende a lo largo del Pantano de las Penas, un sombrío tramo de playa donde apenas crece otra cosa que madera arrastrada por el mar y podredumbre. Los crocoliscos toman el sol en sus aguas poco profundas, y cangrejos y múrlocs ocupan la orilla que hay más allá.",
			full = "La Playa Juncobruma se extiende a lo largo del Pantano de las Penas, un sombrío tramo de playa donde apenas crece otra cosa que madera arrastrada por el mar y podredumbre. Los crocoliscos toman el sol en sus aguas poco profundas, y cangrejos y múrlocs ocupan la orilla que hay más allá.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Strand",
		},
		["misty valley"] = {
			name = "Valle Brumoso",
			short = "La niebla flota baja sobre este rincón del Pantano de las Penas, tan espesa que se traga el sonido. En lo profundo de una cueva al fondo del valle habitaba el Señor del Fango, una fuerza elemental.",
			full = "La niebla flota baja sobre este rincón del Pantano de las Penas, tan espesa que se traga el sonido. En lo profundo de una cueva al fondo del valle habitaba el Señor del Fango, una fuerza elemental.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Valley",
		},
		["pool of tears"] = {
			name = "Charca de Lágrimas",
			short = "La Charca de Lágrimas se extiende amplia y quieta en el borde oriental del Pantano de las Penas. Bajo su superficie tranquila se encuentra el Templo de Atal'Hakkar, hundido allí por Ysera después de que los trols lo levantaran, oculto al mundo.",
			full = "La Charca de Lágrimas se extiende amplia y quieta en el borde oriental del Pantano de las Penas. Bajo su superficie tranquila se encuentra el Templo de Atal'Hakkar, hundido allí por Ysera después de que los trols lo levantaran, oculto al mundo. El Vuelo Verde vigiló durante mucho tiempo aquel lugar anegado, para evitar que nada despertara lo que dormía abajo.\n\nAhora pirañas frenéticas sedientas de sangre se mueven por el agua, y restos de cantería Atal'ai rota cubren la orilla.",
			source = "https://warcraft.wiki.gg/wiki/Pool_of_Tears",
		},
		["shifting mire"] = {
			name = "Lodo Traicionero",
			short = "El limo del Fango Cambiante nunca está quieto. Se acumula en el suelo en finos montones y se arrastra por el pantano como si algo invisible tirara de él, enroscándose y encharcándose como un ser vivo.",
			full = "El limo del Fango Cambiante nunca está quieto. Se acumula en el suelo en finos montones y se arrastra por el pantano como si algo invisible tirara de él, enroscándose y encharcándose como un ser vivo.\n\nAlgunos dicen que la fuerza que provoca ese movimiento no es malévola, sino una energía positiva que agita el limo sin ninguna intención de hacer daño.",
			source = "https://warcraft.wiki.gg/wiki/Shifting_Mire",
		},
		["sorrowmurk"] = {
			name = "Tinieblas de las Penas",
			short = "Las Tinieblas de las Penas se encuentran al este de la Charca de Lágrimas, cerca del Templo Sumergido.",
			full = "Las Tinieblas de las Penas se encuentran al este de la Charca de Lágrimas, cerca del Templo Sumergido. Pertenecen a los dragonantes: dracónidos verdes se arrastran por su fango bajo la vigilancia de un gran draco verde, que mantiene alejados a todos los viajeros salvo a los más temerarios.",
			source = "https://warcraft.wiki.gg/wiki/Sorrowmurk",
		},
		["splinterspear junction"] = {
			name = "Cruce Lanzarrota",
			short = "Donde se bifurca el camino que entra en el Pantano de las Penas, aún se alza una vieja torre de vigilancia orca, y las patrullas de la Horda no pierden de vista el cruce.",
			full = "Donde se bifurca el camino que entra en el Pantano de las Penas, aún se alza una vieja torre de vigilancia orca, y las patrullas de la Horda no pierden de vista el cruce.\n\nLa torre es lo que queda de Kyross, un puesto orco levantado aquí durante la Primera Guerra. Kyross estaba más cerca del poblado humano de Gran Aldea que ninguna otra posición de la Horda en el pantano, y Ventormenta no podía permitirlo. Se enviaron partidas de guerra para derribarlo.\n\nLa torre aún vigila la bifurcación del camino.",
			source = "https://warcraft.wiki.gg/wiki/Splinterspear_Junction",
		},
		["stagalbog"] = {
			name = "Stagalbog",
			short = "Al sur de la Charca de Lágrimas, donde el Pantano de las Penas se eleva hacia las montañas, la ciénaga se espesa hasta formar Stagalbog. Al oeste de esa tierra salvaje y húmeda, en el borde de la montaña, se abre una cueva en la roca.",
			full = "Al sur de la Charca de Lágrimas, donde el Pantano de las Penas se eleva hacia las montañas, la ciénaga se espesa hasta formar Stagalbog. Al oeste de esa tierra salvaje y húmeda, en el borde de la montaña, se abre una cueva en la roca.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog",
		},
		["stagalbog cave"] = {
			name = "Cueva Stagalbog",
			short = "En el este de Stagalbog, en el Pantano de las Penas, una cueva se abre al fango.",
			full = "En el este de Stagalbog, en el Pantano de las Penas, una cueva se abre al fango.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog_Cave",
		},
		["stonard"] = {
			name = "Rocal",
			short = "Rocal surge del fango del Pantano de las Penas, con su gran salón todavía en pie donde tantos otros salones orcos cayeron hace mucho.",
			full = "Rocal surge del fango del Pantano de las Penas, con su gran salón todavía en pie donde tantos otros salones orcos cayeron hace mucho. Dos madrigueras protegen el acceso, y las patrullas orcas salen a defender los pequeños campamentos cercanos, cada uno otra reivindicación clavada frente al pantano.\n\nEl puesto es antiguo, más que casi cualquier otro enclave orco de este lado del mundo, hermano de la fortaleza conocida antaño como Rockard. Lo levantó la antigua Horda en la Ciénaga Negra en los días posteriores a la primera apertura del Portal Oscuro. Cuando llegó la Segunda Guerra y la Horda se desmoronó, Rocal quedó en silencio, probablemente abandonado o destruido junto con tantas otras cosas que los orcos habían construido.\n\nNo permaneció vacío. Con el surgimiento de la nueva Horda y una renovada voluntad de conservar este terreno, Rocal fue reconstruido, con su salón restaurado y sus madrigueras excavadas de nuevo. Rockard no tuvo tanta suerte: los ogros Machacamiedo se apoderaron de la vieja fortaleza y la rebautizaron como Bastión Machacamiedo, lo que dejó a Rocal como el único puesto de la Horda en el pantano, el último salón de su clase todavía encendido en estas tierras bajas.",
			source = "https://warcraft.wiki.gg/wiki/Stonard",
		},
		["temple of atalhakkar"] = {
			name = "El Templo de Atal'Hakkar",
			short = "Hace más de mil años, el Imperio Gurubashi se desgarró en una guerra civil. En su centro estaban los Atal'ai, sacerdotes trols que buscaban devolver al mundo al dios de la sangre Hakkar el Desollador de Almas.",
			full = "Hace más de mil años, el Imperio Gurubashi se desgarró en una guerra civil. En su centro estaban los Atal'ai, sacerdotes trols que buscaban devolver al mundo al dios de la sangre Hakkar el Desollador de Almas. Derrotados y exiliados, huyeron al norte, al Pantano de las Penas, y allí levantaron un templo para preparar su regreso.\n\nEl Aspecto dragón Ysera descubrió su plan y hundió el templo bajo el pantano, con la intención de enterrar su obra para siempre. No ocurrió así. Sin que nadie los molestara en la oscuridad anegada, protegidos de cualquier mirada que pudiera haberlos detenido, los Atal'ai continuaron sus rituales en paz. Los dragones verdes que Ysera puso a custodiar las ruinas han montado guardia desde entonces, manteniendo cerrada una puerta que nunca llegó a sellarse del todo.\n\nEl templo sigue hundido y medio inundado, con sus altares a Hakkar intactos, y quienes entran se arriesgan a algo peor que la muerte. Al Loa de la Sangre se le deben almas además de carne, y cada una que recibe alimenta el día en que no fracase.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Atal'Hakkar",
		},
	},
	-- Páramos de Poniente: 17 subzones
	[1436] = {
		["alexston farmstead"] = {
			name = "Hacienda de Alexston",
			short = "Los campos de la Hacienda de Alexston alimentaron en otro tiempo a familias, antes de que la Hermandad Defias se apoderara de la tierra.",
			full = "Los campos de la Hacienda de Alexston alimentaron en otro tiempo a familias, antes de que la Hermandad Defias se apoderara de la tierra. Ahora solo los mecánicos vigías de la cosecha se mueven entre los surcos, incansables y sin que nadie los atienda, custodiando hileras que ya nadie siembra.\n\nBaros Alexston, que llegó a servir en la Ciudad de Ventormenta como arquitecto, nació en esta tierra. Trabajó aquí de niño, entre los mismos campos que ahora patrullan los vigías de la cosecha, antes de que la tierra que lo formó pasara a otras manos.",
			source = "https://warcraft.wiki.gg/wiki/Alexston_Farmstead",
		},
		["dagger hills"] = {
			name = "Las Colinas Afiladas",
			short = "Las Colinas Afiladas se alzan como una cresta detrás de Arroyo de la Luna, en el sur de los Páramos de Poniente. Poco se mueve allí ahora.",
			full = "Las Colinas Afiladas se alzan como una cresta detrás de Arroyo de la Luna, en el sur de los Páramos de Poniente. Poco se mueve allí ahora. Tragoamargo Cebatruenos vive entre las colinas, una de las pocas almas vivas que pueden encontrarse en ese tramo silencioso de tierra, y se sabe que el necrófago Leprithus también surge de la tierra allí.",
			source = "https://warcraft.wiki.gg/wiki/Dagger_Hills",
		},
		["dead acre"] = {
			name = "El Campo Funesto",
			short = "El Campo Funesto fue en otro tiempo una granja más en el sureste de los Páramos de Poniente, cerca del puente que lleva al Bosque del Ocaso. Cuando la Hermandad Defias se apoderó de la región, tomó la granja que había allí, junto con sus campos.",
			full = "El Campo Funesto fue en otro tiempo una granja más en el sureste de los Páramos de Poniente, cerca del puente que lleva al Bosque del Ocaso. Cuando la Hermandad Defias se apoderó de la región, tomó la granja que había allí, junto con sus campos.\n\nYa ningún granjero lo recorre. En su lugar, los mecánicos vigías de la cosecha rondan el terreno, vagando donde antes crecía una cosecha.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Acre",
		},
		["deadmines"] = {
			name = "Las Minas de la Muerte",
			short = "Bajo Arroyo de la Luna, los túneles se adentran en las profundidades, y en otro tiempo rebosaban de oro. Antes de que los orcos llegaran a las tierras humanas, las Minas de la Muerte llenaban el tesoro de Ventormenta; según algunos relatos, un tercio procedía de esta roca.",
			full = "Bajo Arroyo de la Luna, los túneles se adentran en las profundidades, y en otro tiempo rebosaban de oro. Antes de que los orcos llegaran a las tierras humanas, las Minas de la Muerte llenaban el tesoro de Ventormenta; según algunos relatos, un tercio procedía de esta roca. La Primera Guerra vació las minas de mineros, y después quedaron abandonadas, consideradas embrujadas, y nadie las tocó durante mucho tiempo.\n\nEn ese silencio llegó Edwin VanCleef, que reunió a la Hermandad Defias, antiguos obreros convertidos en bandoleros, y los puso a construir un acorazado en las profundidades con ayuda goblin.\n\nEn esas profundidades permanece VanCleef, protegido por su Hermandad, mientras Gryan Mantorrecio reúne en la Colina del Centinela a hombres que han jurado traer su cabeza.",
			source = "https://warcraft.wiki.gg/wiki/Deadmines",
		},
		["demonts place"] = {
			name = "Paraje de Demont",
			short = "Poco queda del Paraje de Demont salvo maderas rotas y campos cubiertos de maleza, al oeste de Arroyo de la Luna. Antes fue una granja en funcionamiento; ahora está ocupada por agentes Defias, que la consideran suya.",
			full = "Poco queda del Paraje de Demont salvo maderas rotas y campos cubiertos de maleza, al oeste de Arroyo de la Luna. Antes fue una granja en funcionamiento; ahora está ocupada por agentes Defias, que la consideran suya.",
			source = "https://warcraft.wiki.gg/wiki/Demont's_Place",
		},
		["dust plains"] = {
			name = "Los Yermos Polvorientos",
			short = "Los Yermos Polvorientos se extienden por el sur de los Páramos de Poniente, una tierra seca entregada a los gnolls, que tienen allí varios campamentos dispersos y amenazan a cualquiera que cruce su territorio.",
			full = "Los Yermos Polvorientos se extienden por el sur de los Páramos de Poniente, una tierra seca entregada a los gnolls, que tienen allí varios campamentos dispersos y amenazan a cualquiera que cruce su territorio.\n\nEn el extremo oriental se alza la Torre de Mortoalerta, una vieja torre de magos cuyo propósito original hace mucho que cedió ante nuevos amos.",
			source = "https://warcraft.wiki.gg/wiki/Dust_Plains",
		},
		["furlbrows pumpkin farm"] = {
			name = "Plantación de Calabazas de Cejade",
			short = "La Plantación de Calabazas de Cejade la cuidaban en otro tiempo el granjero Cejade y su esposa Verna, pero cuando la Hermandad Defias arrasó los Páramos de Poniente con sus gólems cosechadores mecánicos, la granja cayó como tantas otras de aquella región.",
			full = "La Plantación de Calabazas de Cejade la cuidaban en otro tiempo el granjero Cejade y su esposa Verna, pero cuando la Hermandad Defias arrasó los Páramos de Poniente con sus gólems cosechadores mecánicos, la granja cayó como tantas otras de aquella región. Cejade y Verna huyeron y se refugiaron junto al camino, cerca de La Finca de Jansen, al norte, dejando atrás sus calabazas y su nombre.",
			source = "https://warcraft.wiki.gg/wiki/Furlbrow's_Pumpkin_Farm",
		},
		["gold coast quarry"] = {
			name = "Mina de la Costa del Oro",
			short = "La Mina de la Costa del Oro producía en otro tiempo oro y mineral para Ventormenta, antes de que los Páramos de Poniente cayeran en la ruina. Ahora la Hermandad Defias la ocupa y explota los pozos bajo su propio estandarte.",
			full = "La Mina de la Costa del Oro producía en otro tiempo oro y mineral para Ventormenta, antes de que los Páramos de Poniente cayeran en la ruina. Ahora la Hermandad Defias la ocupa y explota los pozos bajo su propio estandarte. La Milicia Popular y sus miembros se han enfrentado aquí a la Hermandad, y han sufrido emboscadas de los Defias entre la piedra que aún patrullan.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Coast_Quarry",
		},
		["jangolode mine"] = {
			name = "Mina de Jango",
			short = "La Mina de Jango enviaba en otro tiempo mineral a Ventormenta y era una de las fuentes de riqueza mineral más estables de los Páramos de Poniente.",
			full = "La Mina de Jango enviaba en otro tiempo mineral a Ventormenta y era una de las fuentes de riqueza mineral más estables de los Páramos de Poniente.\n\nEsa estabilidad se rompió cuando la Hermandad Defias se apoderó de la mina. Desde entonces, los kóbolds se han colado en sus pozos y los han reclamado como propios.",
			source = "https://warcraft.wiki.gg/wiki/Jangolode_Mine",
		},
		["jansen stead"] = {
			name = "La Finca de Jansen",
			short = "La Finca de Jansen se encuentra en el extremo norte de los Páramos de Poniente, cerca del puente que lleva al Bosque de Elwynn. Como las demás granjas de la región, quedó vacía de sus legítimos dueños cuando la Hermandad Defias los expulsó.",
			full = "La Finca de Jansen se encuentra en el extremo norte de los Páramos de Poniente, cerca del puente que lleva al Bosque de Elwynn. Como las demás granjas de la región, quedó vacía de sus legítimos dueños cuando la Hermandad Defias los expulsó.\n\nCerca se encuentran el granjero Cejade y su esposa, que huyeron de su propio hogar en la Plantación de Calabazas de Cejade y ahora se refugian en la finca.",
			source = "https://warcraft.wiki.gg/wiki/Jansen_Stead",
		},
		["longshore"] = {
			name = "Playa Larga",
			short = "La costa de los Páramos de Poniente se extiende larga y vacía, una de las playas más amplias de Azeroth.",
			full = "La costa de los Páramos de Poniente se extiende larga y vacía, una de las playas más amplias de Azeroth. Los múrlocs la recorren en cantidades imposibles de contener, y entre ellos nada el Old Murk-Eye, una criatura a la que la gente de mar de la costa ha aprendido a temer y a nombrar. Más allá de las rompientes yacen los restos de barcos que nunca llegaron a puerto, entre ellos destructores élficos, entregados a la marea.\n\nEn el extremo suroeste de la playa se encuentra la granja de Daphne Fontana. La Hermandad Defias vino a por ella más de una vez con la intención de quemarla, como quemó tantas otras cosas en los Páramos de Poniente. La noticia de sus problemas llegó a Duthorian Rall, que envió a aspirantes a Caballeros de la Mano de Plata a la costa para vigilar su tierra, y la defendieron.",
			source = "https://warcraft.wiki.gg/wiki/Longshore",
		},
		["molsen farm"] = {
			name = "La Granja de Molsen",
			short = "La Granja Molsen es una de las muchas granjas de los Páramos de Poniente en manos de la Hermandad Defias.",
			full = "La Granja Molsen es una de las muchas granjas de los Páramos de Poniente en manos de la Hermandad Defias. Sus hileras están entregadas al óxido y a la maquinaria, y los mecánicos vigías de la cosecha recorren los campos, derribando a cualquiera que se acerque demasiado.",
			source = "https://warcraft.wiki.gg/wiki/Molsen_Farm",
		},
		["moonbrook"] = {
			name = "Arroyo de la Luna",
			short = "Bajo los campos de Arroyo de la Luna corría en otro tiempo un tercio del tesoro de Ventormenta: oro extraído de los túneles que más tarde se llamaron las Minas de la Muerte.",
			full = "Bajo los campos de Arroyo de la Luna corría en otro tiempo un tercio del tesoro de Ventormenta: oro extraído de los túneles que más tarde se llamaron las Minas de la Muerte. El pueblo era el granero del reino, hasta que la disolución de la Hermandad de los Albañiles desató los disturbios que costaron la vida a la reina Tiffin Wrynn. La venganza del rey Varian por su muerte cayó con más fuerza sobre el gremio, y los albañiles huyeron a las tierras de cultivo de los Páramos de Poniente para escapar de él. Avivada desde las sombras, su ira se convirtió en la Hermandad Defias. Bajo el mando de Edwin VanCleef se dedicaron al bandidaje, expulsaron a los granjeros de Arroyo de la Luna y tomaron como cuartel general los túneles mineros abandonados bajo el pueblo, donde trabajaban en secreto para construir un arma destinada a destruir Ventormenta desde el mar.\n\nDurante años, ningún ejército ha venido a enfrentarse a ellos. La Hermandad aún ocupa Arroyo de la Luna, y solo la Milicia Popular de Gryan Mantorrecio se opone a ella, reuniendo fuerzas en la Colina del Centinela para un ajuste de cuentas que aún está por llegar.",
			source = "https://warcraft.wiki.gg/wiki/Moonbrook",
		},
		["saldeans farm"] = {
			name = "Finca de Saldean",
			short = "La Finca de Saldean es la única de los Páramos de Poniente que la Hermandad Defias nunca llegó a invadir. Los gólems cosechadores Defias recorren sus campos, pero el granjero Saldean y su esposa Salma se negaron a marcharse.",
			full = "La Finca de Saldean es la única de los Páramos de Poniente que la Hermandad Defias nunca llegó a invadir. Los gólems cosechadores Defias recorren sus campos, pero el granjero Saldean y su esposa Salma se negaron a marcharse. Su casa ha servido durante años como refugio de paso, y la pareja hace lo que puede por mantener con vida a sus huéspedes.",
			source = "https://warcraft.wiki.gg/wiki/Saldean's_Farm",
		},
		["sentinel hill"] = {
			name = "Colina del Centinela",
			short = "La Colina del Centinela se alza sobre un terreno elevado que domina las tierras de cultivo de los Páramos de Poniente, con su torre vigilando las cabañas, la forja y el molino construidos en la ladera de abajo.",
			full = "La Colina del Centinela se alza sobre un terreno elevado que domina las tierras de cultivo de los Páramos de Poniente, con su torre vigilando las cabañas, la forja y el molino construidos en la ladera de abajo.\n\nTanto los gnolls Zarparrío como la Hermandad Defias han atacado la colina y las tierras que protege.",
			source = "https://warcraft.wiki.gg/wiki/Sentinel_Hill",
		},
		["stendels pond"] = {
			name = "Estanque de Stendel",
			short = "Un pequeño estanque se encuentra al suroeste de la Colina del Centinela, con el agua inmóvil bajo un anillo de gnolls.",
			full = "Un pequeño estanque se encuentra al suroeste de la Colina del Centinela, con el agua inmóvil bajo un anillo de gnolls. Dos tumbas descansan en su orilla, junto con viejos huesos dispersos, y algo en el agua parece estar mal, como si nunca más debiera beberse.\n\nLos pescadores que prueban suerte allí suelen sacar solo salvias comunes. Pero se dice que algo más nada bajo la superficie, un pez llamado la Perdición de Stendel, que rara vez se ve y aún más rara vez se pesca.",
			source = "https://warcraft.wiki.gg/wiki/Stendel's_Pond",
		},
		["westfall lighthouse"] = {
			name = "Faro de Poniente",
			short = "El faro se alza en el extremo sur de los Páramos de Poniente, y su haz aún gira sobre el agua por las noches, aunque la mano que lo mantiene pertenece ahora a un hombre muerto.",
			full = "El faro se alza en el extremo sur de los Páramos de Poniente, y su haz aún gira sobre el agua por las noches, aunque la mano que lo mantiene pertenece ahora a un hombre muerto.\n\nUna familia cuidaba en otro tiempo la llama, hasta que el múrloc Old Murk-Eye salió del oleaje y la ahuyentó aterrorizada. Regresaron y volvieron a encender la luz, pero el Old Murk-Eye volvió, y esta vez trajo consigo a los múrlocs de la costa en un asalto al faro. La familia no sobrevivió. Grayson vio cómo morían ante él, sin poder impedirlo, y es su fantasma el que mantiene ahora la luz, montando guardia fuera de la torre sin que quede nadie para relevarlo.",
			source = "https://warcraft.wiki.gg/wiki/Westfall_Lighthouse",
		},
	},
	-- Los Humedales: 23 subzones
	[1437] = {
		["angerfang encampment"] = {
			name = "Campamento Dentellada",
			short = "El Campamento Dentellada se extiende por el centro de Los Humedales; es el mayor campamento que el clan Faucedraco tiene en la región y el hogar de los orcos Dentellada.",
			full = "El Campamento Dentellada se extiende por el centro de Los Humedales; es el mayor campamento que el clan Faucedraco tiene en la región y el hogar de los orcos Dentellada.\n\nBajo el mando de Nek'rosh Skullcrusher, hijo de Nekros Skullcrusher, el campamento se ha convertido en una base de operaciones donde se concentran catapultas destinadas a un asalto al Puerto de Menethil. La amenaza es tan real que el capitán Puñorrecio ha jurado ver muerto a Nek'rosh y arrancados los estandartes de guerra del clan antes de que las catapultas se pongan en marcha.",
			source = "https://warcraft.wiki.gg/wiki/Angerfang_Encampment",
		},
		["baradin bay"] = {
			name = "Bahía de Baradin",
			short = "Las aguas de la Bahía de Baradin bañan la costa donde Khaz Modan se une a Lordaeron, tocando las orillas del Puerto de Menethil y del Castillo de Stromgarde.",
			full = "Las aguas de la Bahía de Baradin bañan la costa donde Khaz Modan se une a Lordaeron, tocando las orillas del Puerto de Menethil y del Castillo de Stromgarde. Múrlocs y crocoliscos flotan en sus aguas poco profundas, mientras que tiburones y cangrejos dominan las aguas más profundas.\n\nLa verdadera historia de la bahía yace rota en su fondo. Durante la Segunda Guerra, la armada de Kul Tiras patrullaba estas aguas y defendía la costa frente a la guerra que se extendía por los Reinos del Este. Pero Kul Tiras pagó caro esa vigilancia: la Tercera Flota de la nación fue destruida en los combates. Algunos de sus restos aún yacen destrozados a lo largo de la costa de Los Humedales, visibles en las aguas poco profundas donde se partieron, mientras que otros se hundieron por completo y se asentaron en la oscuridad, donde nadie los ha sacado desde entonces.",
			source = "https://warcraft.wiki.gg/wiki/Baradin_Bay",
		},
		["black channel marsh"] = {
			name = "Pantano del Canal Negro",
			short = "El camino al Puerto de Menethil bordea el Pantano del Canal Negro, en el suroeste de Los Humedales.",
			full = "El camino al Puerto de Menethil bordea el Pantano del Canal Negro, en el suroeste de Los Humedales. Los raptores anidan por todo el pantano, y los más hambrientos se acercan al borde del camino, así que los viajeros que pasan por este tramo hacen bien en estar atentos.",
			source = "https://warcraft.wiki.gg/wiki/Black_Channel_Marsh",
		},
		["bluegill marsh"] = {
			name = "Pantano Branquiazul",
			short = "Las aguas del Pantano Branquiazul, en el oeste de Los Humedales, albergan campamentos de múrlocs Branquiazul, que nunca van solos, sino de dos en dos o de tres en tres entre los juncos.",
			full = "Las aguas del Pantano Branquiazul, en el oeste de Los Humedales, albergan campamentos de múrlocs Branquiazul, que nunca van solos, sino de dos en dos o de tres en tres entre los juncos. A la cabeza de ellos está Engullidor, un múrloc más feroz que los demás, cuya presencia convierte el pantano en un lugar al que es mejor entrar con cautela.",
			source = "https://warcraft.wiki.gg/wiki/Bluegill_Marsh",
		},
		["deepwater tavern"] = {
			name = "Mesón Aguahonda",
			short = "El Mesón Aguahonda se encuentra en el Puerto de Menethil, y su salón común está lleno de las conversaciones de los marineros que pasan por allí.",
			full = "El Mesón Aguahonda se encuentra en el Puerto de Menethil, y su salón común está lleno de las conversaciones de los marineros que pasan por allí. Es un lugar rudo: las sillas vuelan tan a menudo como se sirve la cerveza, y las peleas suelen empezar a instancias de Tapoke \"El Flaco\" Jahn.",
			source = "https://warcraft.wiki.gg/wiki/Deepwater_Tavern",
		},
		["direforge hill"] = {
			name = "Cerro Fraguaferoz",
			short = "El Cerro Fraguaferoz fue en otro tiempo un importante campamento de los enanos Hierro Negro, dirigido por el brujo Balgaras el Hediondo.",
			full = "El Cerro Fraguaferoz fue en otro tiempo un importante campamento de los enanos Hierro Negro, dirigido por el brujo Balgaras el Hediondo.",
			source = "https://warcraft.wiki.gg/wiki/Direforge_Hill",
		},
		["dragonmaw gates"] = {
			name = "Puertas Faucedraco",
			short = "Las Puertas Faucedraco están custodiadas por el Vuelo Rojo bajo el mando del draco Axtroz, que cierra el paso a quienes intentan llegar a Grim Batol.",
			full = "Las Puertas Faucedraco están custodiadas por el Vuelo Rojo bajo el mando del draco Axtroz, que cierra el paso a quienes intentan llegar a Grim Batol.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmaw_Gates",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "El túnel de Dun Algaz es más antiguo que la disputa que dividió a los enanos. Cuando la guerra de los Tres Martillos expulsó a los Martillo Salvaje de Forjaz, fue por este paso por donde se retiraron.",
			full = "El túnel de Dun Algaz es más antiguo que la disputa que dividió a los enanos. Cuando la guerra de los Tres Martillos expulsó a los Martillo Salvaje de Forjaz, fue por este paso por donde se retiraron.\n\nTambién sirvió para la retirada de la Horda. Rechazados en Dun Modr, los orcos retrocedieron hacia el sur a través del valle de Thandol y se atrincheraron en el puesto de aquí, y Anduin Lothar, que quería expulsarlos por completo de Khaz Modan, envió a sus fuerzas a derribar el bastión. El asalto fracasó. Los orcos resistieron, y Dun Algaz se convirtió en el último terreno que la Horda conservó en la región, un punto de apoyo del que no hubo manera de desalojarlos.\n\nLos montaraces enanos que vigilaban este paso se mantenían sobre todo en las colinas de arriba, pero el clan Faucedraco arrasó su puesto y los obligó a replegarse al túnel superior, donde aún resisten. Con el paso inferior perdido, el camino entre las tierras natales de los enanos y el Puerto de Menethil se ha vuelto mucho más peligroso.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["dun modr"] = {
			name = "Dun Modr",
			short = "Dun Modr se alza al sur del Puente Thandol, una antigua ciudad enana que cayó en ruinas hace mucho, con su herrería y su posada cervecería todavía en pie entre unos restos que los enanos Hierro Negro reclaman ahora como suyos.",
			full = "Dun Modr se alza al sur del Puente Thandol, una antigua ciudad enana que cayó en ruinas hace mucho, con su herrería y su posada cervecería todavía en pie entre unos restos que los enanos Hierro Negro reclaman ahora como suyos.\n\nDurante la Segunda Guerra, la Horda orca se apoderó de las ruinas y construyó allí un puesto, desde el que rechazaba a las tropas de la Alianza y asaltaba las tierras de cultivo de los alrededores: una base de operaciones vital para sus ejércitos. Los guerreros de Stromgarde partieron de la ciudadela isleña de Tol Barad para destruir aquel puesto, lo asediaron y obligaron a los orcos a replegarse al sur, a su bastión secundario de Dun Algaz. La Horda contraatacó, recuperó Dun Modr y volvió su fuerza incluso contra la propia Tol Barad. Solo cuando la Horda fue derrotada en la Ciudad Capital, Anduin Lothar la hizo retroceder a través del Puente Thandol hasta Khaz Modan, y Dun Modr pasó a manos de la Alianza.\n\nEsa paz no duró. Con los soldados de Forjaz agotados en guerras libradas lejos de casa, los enanos Hierro Negro arrasaron el Puente Thandol, y Dun Modr cayó poco después bajo el brujo Balgaras el Hediondo, que ahora domina la ciudad que su pueblo ha reclamado como propia.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Modr",
		},
		["green belt"] = {
			name = "La Franja Verde",
			short = "La Franja Verde está llena de crocoliscos, bestias del pantano y cienos, y Rethiel el Guardaverde vigila aquí, enfurecido por una tierra que se ha vuelto extraña e inquieta.",
			full = "La Franja Verde está llena de crocoliscos, bestias del pantano y cienos, y Rethiel el Guardaverde vigila aquí, enfurecido por una tierra que se ha vuelto extraña e inquieta.\n\nAl oeste, las bestias del fango se han vuelto malévolas. Al noreste, elementales de fuego surgen inesperadamente del Cerro Fraguaferoz. Ambos son heridas en la tierra que Rethiel custodia, y ninguno ha remitido.\n\nDentro de la Franja se encuentra una caravana destrozada del clan Faucedraco, donde ahora anidan crías de dragón rojo entre sus restos: todo lo que queda de un intento de robar crías del Vuelo Negro que terminó aquí, engullido por el pantano.",
			source = "https://warcraft.wiki.gg/wiki/Green_Belt",
		},
		["grim batol"] = {
			name = "Grim Batol",
			short = "Grim Batol es una fortaleza en la montaña situada en el este de Los Humedales. Tiene grandes murallas y agujas que se alzan hacia un cielo gris acero, pero la mayor parte del bastión es subterránea.",
			full = "Grim Batol es una fortaleza en la montaña situada en el este de Los Humedales. Tiene grandes murallas y agujas que se alzan hacia un cielo gris acero, pero la mayor parte del bastión es subterránea. La fundaron los enanos Martillo Salvaje, hasta que fue maldecida durante la guerra de los Tres Martillos. Más tarde, los orcos se apoderaron de ella para usarla como prisión del Aspecto dragón Alexstrasza, hasta que fue liberada durante la batalla de Grim Batol.",
			source = "https://warcraft.wiki.gg/wiki/Grim_Batol",
		},
		["ironbeards tomb"] = {
			name = "Tumba de Barbaférrea",
			short = "La Tumba de Barbaférrea se encuentra al oeste del camino a Dun Modr, en el centro norte de Los Humedales. Una estatua enana se alza sobre el cementerio, presumiblemente tallada a imagen del propio Barbaférrea.",
			full = "La Tumba de Barbaférrea se encuentra al oeste del camino a Dun Modr, en el centro norte de Los Humedales. Una estatua enana se alza sobre el cementerio, presumiblemente tallada a imagen del propio Barbaférrea.\n\nLos muertos ya no descansan tranquilos en ella. Cienos negros, carmesíes y de tonos monstruosos se han colado en la cripta y la han profanado, extendiéndose por el cementerio hasta que nadie que desee enterrar a los suyos se acerca ya al lugar.",
			source = "https://warcraft.wiki.gg/wiki/Ironbeard's_Tomb",
		},
		["lost fleet"] = {
			name = "La Flota Perdida",
			short = "Los restos del Dueña de las Olas y de El Intrépido yacen en el fondo de la Bahía de Baradin, frente a la costa norte del Pantano Branquiazul.",
			full = "Los restos del Dueña de las Olas y de El Intrépido yacen en el fondo de la Bahía de Baradin, frente a la costa norte del Pantano Branquiazul.\n\nFormaban parte de la Tercera Flota de Kul Tiras, comandada por Derek Valiente, hijo mayor del lord almirante Daelin Valiente, durante la Segunda Guerra. En la batalla de Crestfall, dragones rojos esclavizados por el clan Faucedraco cayeron del cielo e incendiaron la flota. Derek subió a la cofa para advertir a su padre del peligro. Un dragón lo mató allí antes de que la advertencia sirviera de algo, y su barco se hundió con el resto de la flota poco después. Solo sobrevivió un hombre, el contramaestre Fistimos, del Dueña de las Olas.\n\nLos muertos no permanecieron en silencio. En lo profundo de la bodega de El Intrépido, su comandante, el capitán Halyndor, había escondido por codicia un orbe ennegrecido: el Ojo maldito de Paleth. Años después, su maldición alcanzó a la tripulación hundida y la ató a la no-muerte. Solo el primer oficial Snellig conservó la razón, y su fantasma todavía recorre la orilla cercana.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Fleet",
		},
		["menethil bay"] = {
			name = "Bahía de Menethil",
			short = "La Bahía de Menethil se encuentra entre el puerto y los acantilados de Dun Morogh, encajada en la ensenada de la Bahía de Baradin.",
			full = "La Bahía de Menethil se encuentra entre el puerto y los acantilados de Dun Morogh, encajada en la ensenada de la Bahía de Baradin.\n\nCerca de la entrada de la bahía descansan los restos del Flying Osprey, con su casco roto asentado en el agua.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Bay",
		},
		["menethil harbor"] = {
			name = "Puerto de Menethil",
			short = "La muralla es lo primero que cualquiera advierte: gruesa piedra levantada alrededor de un pueblo portuario que se asienta mitad sobre roca y mitad sobre el mar.",
			full = "La muralla es lo primero que cualquiera advierte: gruesa piedra levantada alrededor de un pueblo portuario que se asienta mitad sobre roca y mitad sobre el mar. Cuatro torres se alzan sobre él, vigilando tanto el agua como el camino, y no hay otra forma de entrar que el puente, la marea o un sendero oculto que corre bajo tierra hasta el continente.\n\nLos orcos levantaron aquí el primer astillero. Después de la Primera Guerra, el Jefe de Guerra Orgrim Martillo Maldito eligió esta orilla para construir la flota destinada a llevar a la Horda más allá de las defensas terrestres de Lordaeron, y para ello despojó de hierro y madera las minas enanas de Khaz Modan. Cuando terminó la Segunda Guerra, la Alianza se apoderó del lugar y lo reconstruyó como propio, y el almirante general Daelin Valiente lo llamó Puerto de Menethil en honor a Terenas Menethil II, rey de Lordaeron.\n\nDurante años después, los raptores bajaban de las colinas para atacar el pueblo, nunca en gran número, pero sí con frecuencia.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Harbor",
		},
		["menethil keep"] = {
			name = "Castillo de Menethil",
			short = "Cuatro torres se alzan sobre el Puerto de Menethil y vigilan el pueblo de abajo como severos guardianes. Este es el Castillo de Menethil.",
			full = "Cuatro torres se alzan sobre el Puerto de Menethil y vigilan el pueblo de abajo como severos guardianes. Este es el Castillo de Menethil.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Keep",
		},
		["mosshide fen"] = {
			name = "Pantano Pellejomusgo",
			short = "El Pantano Pellejomusgo es un tramo anegado del este de Los Humedales, con el suelo salpicado por los campamentos de los gnolls Pellejomusgo. La tribu domina el pantano, y atrapa y devora a cualquiera que se adentre demasiado en la ciénaga.",
			full = "El Pantano Pellejomusgo es un tramo anegado del este de Los Humedales, con el suelo salpicado por los campamentos de los gnolls Pellejomusgo. La tribu domina el pantano, y atrapa y devora a cualquiera que se adentre demasiado en la ciénaga.",
			source = "https://warcraft.wiki.gg/wiki/Mosshide_Fen",
		},
		["raptor ridge"] = {
			name = "Colina del Raptor",
			short = "La Colina del Raptor se alza en el este de Los Humedales, al noroeste de las Puertas Faucedraco, con sus laderas y su caverna llenas de raptores. En lo más profundo, la matriarca Tajobuche cuida de su nidada.",
			full = "La Colina del Raptor se alza en el este de Los Humedales, al noroeste de las Puertas Faucedraco, con sus laderas y su caverna llenas de raptores. En lo más profundo, la matriarca Tajobuche cuida de su nidada.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Ridge",
		},
		["saltspray glen"] = {
			name = "Cañada Salobre",
			short = "La Cañada Salobre se encuentra donde Los Humedales se unen a la Bahía de Baradin, entre el Pantano Branquiazul y la Tumba de Barbaférrea.",
			full = "La Cañada Salobre se encuentra donde Los Humedales se unen a la Bahía de Baradin, entre el Pantano Branquiazul y la Tumba de Barbaférrea. Su nombre proviene del viento: cuando sopla con fuerza desde la bahía, el océano lanza aquí su espuma tierra adentro, más lejos que en ningún otro punto de esta costa, hasta que el propio suelo queda resbaladizo de sal. Los raptores anidan en abundancia por toda la cañada, como en el pantano y la colina cercanos.",
			source = "https://warcraft.wiki.gg/wiki/Saltspray_Glen",
		},
		["sundown marsh"] = {
			name = "Pantano del Ocaso",
			short = "En lo profundo del noroeste de Los Humedales se encuentra el Pantano del Ocaso, lleno de crocoliscos, gnolls, raptores, bestias del pantano y cienos que mantienen alejados a la mayoría de los viajeros.",
			full = "En lo profundo del noroeste de Los Humedales se encuentra el Pantano del Ocaso, lleno de crocoliscos, gnolls, raptores, bestias del pantano y cienos que mantienen alejados a la mayoría de los viajeros. En su centro se alza la Estación Swiftgear, una pequeña vivienda de piedra con un molino de viento, donde Fradd Swiftgear y Wenna Silkbeard han establecido su hogar. La pareja comercia con lo que da el pantano: objetos extraños sacados del lodo y recetas que rara vez se encuentran en otros lugares.",
			source = "https://warcraft.wiki.gg/wiki/Sundown_Marsh",
		},
		["thandol span"] = {
			name = "Puente Thandol",
			short = "Dos grandes arcos de piedra salvan la distancia entre Los Humedales y las Tierras Altas de Arathi, levantados por manos enanas y custodiados durante tres generaciones por el linaje Yunquemar.",
			full = "Dos grandes arcos de piedra salvan la distancia entre Los Humedales y las Tierras Altas de Arathi, levantados por manos enanas y custodiados durante tres generaciones por el linaje Yunquemar. Se construyeron después de la guerra de los Tres Martillos, cuando Forjaz quiso mantener la lealtad con sus parientes Martillo Salvaje de Pico Nidal, y los puentes se convirtieron a la vez en camino y en símbolo entre los dos reinos enanos, llevando un comercio que enriqueció a ambos.\n\nAhora los puentes están marcados por las cicatrices. Kam Furiahonda y Balgaras el Hediondo condujeron a los enanos Hierro Negro contra el puente, derribaron por completo uno de los dos arcos y estuvieron a punto de tomar el segundo. Las fuerzas enanas lucharon con ferocidad para defender lo que quedaba y recuperar el cercano pueblo de Dun Modr, y muchos murieron en esos combates, entre ellos Sully Balloo, Ebenezer Herrumbra y el hermano de Largatrenza el Nefasto. Los Hierro Negro aún ocupan los restos, y Balgaras el Hediondo sigue vivo entre ellos.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thelgen rock"] = {
			name = "Roca Thelgen",
			short = "La Roca Thelgen se alza en el sur de Los Humedales, con cavernas que se adentran en lo profundo de la montaña y están llenas de arañas venenosas que tejen seda en cada grieta.",
			full = "La Roca Thelgen se alza en el sur de Los Humedales, con cavernas que se adentran en lo profundo de la montaña y están llenas de arañas venenosas que tejen seda en cada grieta. En algún lugar de los túneles más profundos hay vetas de mena de incendicita, protegidas por la multitud de arañas.",
			source = "https://warcraft.wiki.gg/wiki/Thelgen_Rock",
		},
		["whelgars excavation site"] = {
			name = "Excavación de Whelgar",
			short = "La excavación al este del Puerto de Menethil fue en otro tiempo un trabajo tranquilo para enanos que cavaban en una tierra más antigua que la memoria. Entonces los raptores jaspeados la invadieron y acorralaron a los excavadores en una loma sobre su propia excavación.",
			full = "La excavación al este del Puerto de Menethil fue en otro tiempo un trabajo tranquilo para enanos que cavaban en una tierra más antigua que la memoria. Entonces los raptores jaspeados la invadieron y acorralaron a los excavadores en una loma sobre su propia excavación. No resistieron, y abandonaron el lugar por un campamento de construcción propia junto al camino principal, el Retiro de Whelgar.\n\nLo que dejaron atrás sigue medio desenterrado. Ahora fósiles vivientes y viejos elementales recorren los pozos, sin que les importen los picos que se oxidan allí.",
			source = "https://warcraft.wiki.gg/wiki/Whelgar's_Excavation_Site",
		},
	},
	-- Teldrassil: 17 subzones
	[1438] = {
		["aldrassil"] = {
			name = "Aldrassil",
			short = "Aldrassil se alza en el corazón de Cañada Umbría, un árbol que ha crecido tanto que alberga una aldea entre sus ramas.",
			full = "Aldrassil se alza en el corazón de Cañada Umbría, un árbol que ha crecido tanto que alberga una aldea entre sus ramas. En lo más alto, por encima del asentamiento de abajo, Tenaron Tormentagarre ha establecido su hogar y vigila la cañada desde la copa del gran árbol.",
			source = "https://warcraft.wiki.gg/wiki/Aldrassil",
		},
		["banethil barrow den"] = {
			name = "Túmulo de Ban'ethil",
			short = "Los elfos de la noche levantaron el Túmulo de Ban'ethil como un túmulo sagrado para que sus druidas de la Garra dormidos descansaran en paz.",
			full = "Los elfos de la noche levantaron el Túmulo de Ban'ethil como un túmulo sagrado para que sus druidas de la Garra dormidos descansaran en paz.\n\nEsa paz está rota ahora. Los fúrbolgs Tuercepinos corrompidos han invadido su cubil inferior y su cubil superior, y lo que antes era suelo consagrado ya no es un lugar por el que un elfo de la noche deba vagar solo.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Barrow_Den",
		},
		["banethil hollow"] = {
			name = "Hondonada Ban'ethil",
			short = "Un barranco se abre en la tierra al sur del camino entre Dolanaar y Darnassus, y sus laderas están en manos de fúrbolgs hostiles que tienden emboscadas a los viajeros que se acercan demasiado.",
			full = "Un barranco se abre en la tierra al sur del camino entre Dolanaar y Darnassus, y sus laderas están en manos de fúrbolgs hostiles que tienden emboscadas a los viajeros que se acercan demasiado. Al fondo de la hondonada se encuentra el Túmulo de Ban'ethil, hundido en la tierra. Conviene ir con cautela por el camino de arriba.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Hollow",
		},
		["cleft"] = {
			name = "La Grieta",
			short = "La Grieta se encuentra al noroeste de Dolanaar, una guarida de fúrbolgs Tuercepinos corrompidos dirigidos por Ursal el Violento. Tienden emboscadas a los viajeros en el camino a Darnassus y retienen cautivo en su interior a un grupo de druidas durmientes.",
			full = "La Grieta se encuentra al noroeste de Dolanaar, una guarida de fúrbolgs Tuercepinos corrompidos dirigidos por Ursal el Violento. Tienden emboscadas a los viajeros en el camino a Darnassus y retienen cautivo en su interior a un grupo de druidas durmientes. La sacerdotisa lunar Amara y sus guardaespaldas vigilan el camino cerca de la entrada.",
			source = "https://warcraft.wiki.gg/wiki/Cleft",
		},
		["dolanaar"] = {
			name = "Dolanaar",
			short = "Dolanaar se encuentra en el centro este de Teldrassil, al suroeste de Cañada Umbría, con sus raíces y sus puentes de cuerda entretejidos en el propio gran árbol.",
			full = "Dolanaar se encuentra en el centro este de Teldrassil, al suroeste de Cañada Umbría, con sus raíces y sus puentes de cuerda entretejidos en el propio gran árbol. Su posición central entre los senderos de la isla la ha convertido desde hace mucho en un punto de idas y venidas, una aldea que sentía el pulso de todo lo que ocurría a su alrededor.",
			source = "https://warcraft.wiki.gg/wiki/Dolanaar",
		},
		["fel rock"] = {
			name = "Roca Mácula",
			short = "Al norte de Dolanaar se encuentra una cueva que antes fue hermosa y ahora está corrompida. Los grell infestan sus oscuras cavidades, y en su interior habita el sátiro lord Melenas, cuya presencia ha envenenado el lugar.",
			full = "Al norte de Dolanaar se encuentra una cueva que antes fue hermosa y ahora está corrompida. Los grell infestan sus oscuras cavidades, y en su interior habita el sátiro lord Melenas, cuya presencia ha envenenado el lugar. El druida elfo de la noche Tallonkai Cruzarraíz observa esta corrupción con temor, pues lo que antes era un lugar bello es ahora un lugar ominoso.",
			source = "https://warcraft.wiki.gg/wiki/Fel_Rock",
		},
		["gnarlpine hold"] = {
			name = "Tierras de los Tuercepinos",
			short = "En el extremo suroeste de Teldrassil se encuentran las Tierras de los Tuercepinos, hogar de los fúrbolgs Tuercepinos.",
			full = "En el extremo suroeste de Teldrassil se encuentran las Tierras de los Tuercepinos, hogar de los fúrbolgs Tuercepinos.",
			source = "https://warcraft.wiki.gg/wiki/Gnarlpine_Hold",
		},
		["lake alameth"] = {
			name = "Lago Al'Ameth",
			short = "El Lago Al'Ameth se extiende amplio al sur de Dolanaar, una de las grandes masas de agua de Teldrassil. Poco marca sus orillas, aparte de un pequeño embarcadero.",
			full = "El Lago Al'Ameth se extiende amplio al sur de Dolanaar, una de las grandes masas de agua de Teldrassil. Poco marca sus orillas, aparte de un pequeño embarcadero.\n\nÚltimamente su calma se ha agriado: unos brezomaderas enfurecidos rondan la orilla, y ya no es seguro recorrer el lago a solas.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Al'Ameth",
		},
		["oracle glade"] = {
			name = "El Claro del Oráculo",
			short = "El Claro del Oráculo se encuentra en el noroeste de Teldrassil y acoge la primera y más poderosa de las pozas de la luna del gran árbol.",
			full = "El Claro del Oráculo se encuentra en el noroeste de Teldrassil y acoge la primera y más poderosa de las pozas de la luna del gran árbol. Aquí se alza el Árbol del Oráculo, cuyo ancho tronco se eleva hasta unas ramas con la forma de un águila posada sobre un oso. Muchos susurran que ningún crecimiento corriente podría adoptar semejante forma y que solo la magia de la naturaleza le dio esa figura.\n\nEl árbol ha velado por el crecimiento de Teldrassil junto a los druidas.\n\nLas arpías Sangrepluma han anidado cerca y amenazan el árbol, y se ha enviado a una pequeña compañía de centinelas para contenerlas.",
			source = "https://warcraft.wiki.gg/wiki/Oracle_Glade",
		},
		["pools of arlithrien"] = {
			name = "Estanques de Arlithrien",
			short = "Al sur de Darnassus, en el oeste de Teldrassil, los Estanques de Arlithrien fueron en otro tiempo un lugar tranquilo. Los elfos de la noche abandonaron allí una poza de la luna cuando los fúrbolgs Tuercepinos invadieron la zona.",
			full = "Al sur de Darnassus, en el oeste de Teldrassil, los Estanques de Arlithrien fueron en otro tiempo un lugar tranquilo. Los elfos de la noche abandonaron allí una poza de la luna cuando los fúrbolgs Tuercepinos invadieron la zona. La poza sigue en pie sin que nadie la atienda entre los estanques, que ahora son el hogar de una fauna hostil.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Arlithrien",
		},
		["ruttheran village"] = {
			name = "Aldea Rut'theran",
			short = "La Aldea Rut'theran se encuentra en las raíces de Teldrassil, donde el Árbol del Mundo se une al agua, muy por debajo de Darnassus.",
			full = "La Aldea Rut'theran se encuentra en las raíces de Teldrassil, donde el Árbol del Mundo se une al agua, muy por debajo de Darnassus. Sus edificios son humildes al lado de los de la capital, pero se mantienen extraordinariamente cuidados, como si se sintiera orgullo por la sencillez más que por el tamaño.\n\nAquí los kaldorei cuidan el nidal de hipogrifos: recogen y atienden los huevos y crían a los jóvenes hasta que pueden volar. Es un trabajo tranquilo, hecho por gente que por lo demás se esfuerza por mantener en marcha la aldea en apoyo de la ciudad de arriba, sin pedir mucho reconocimiento por ello.\n\nSin embargo, la aldea no es solo trabajo. Cuando llega el Festival de Fuego del Solsticio de Verano, se encienden sus braseros, y las mismas manos que cuidan huevos de hipogrifo y cargan barcas se dedican a la celebración.",
			source = "https://warcraft.wiki.gg/wiki/Rut'theran_Village",
		},
		["shadowglen"] = {
			name = "Cañada Umbría",
			short = "Bajo las ramas de Teldrassil, escondido en el noreste de la isla, se encuentra un claro que nunca llega a ver la plena luz del día. Cañada Umbría conserva un crepúsculo perpetuo, rodeada de montañas por todos lados menos uno.",
			full = "Bajo las ramas de Teldrassil, escondido en el noreste de la isla, se encuentra un claro que nunca llega a ver la plena luz del día. Cañada Umbría conserva un crepúsculo perpetuo, rodeada de montañas por todos lados menos uno. Solo hacia el sur se abre la piedra y deja pasar un sendero hacia Dolanaar.\n\nEn el corazón del claro se alza Aldrassil, un gran árbol cuya presencia domina por completo el lugar, como si toda la cañada estuviera dispuesta a su alrededor. Al noroeste, el terreno se abre a la Gruta Narácnida, una oscura hendidura en las colinas que rodean el claro.",
			source = "https://warcraft.wiki.gg/wiki/Shadowglen",
		},
		["shadowthread cave"] = {
			name = "Gruta Narácnida",
			short = "La Gruta Narácnida se encuentra en la esquina noroeste de Cañada Umbría, en las raíces de Teldrassil. Siempre ha pertenecido a las grandes arañas de la isla, pero últimamente se han vuelto inquietas y la cueva se ha vuelto más peligrosa.",
			full = "La Gruta Narácnida se encuentra en la esquina noroeste de Cañada Umbría, en las raíces de Teldrassil. Siempre ha pertenecido a las grandes arañas de la isla, pero últimamente se han vuelto inquietas y la cueva se ha vuelto más peligrosa.\n\nEn lo más profundo habita Githyiss la Vil, la mayor de la camada, perdición de más de un joven kaldorei que se adentró demasiado.",
			source = "https://warcraft.wiki.gg/wiki/Shadowthread_Cave",
		},
		["starbreeze village"] = {
			name = "Aldea Brisa Estelar",
			short = "La Aldea Brisa Estelar perteneció en otro tiempo a los elfos de la noche, un grupo de casitas al sureste de Cañada Umbría. Ya no quedan elfos allí, y sus casas han sido reclamadas por los fúrbolgs Tuercepinos corrompidos.",
			full = "La Aldea Brisa Estelar perteneció en otro tiempo a los elfos de la noche, un grupo de casitas al sureste de Cañada Umbría. Ya no quedan elfos allí, y sus casas han sido reclamadas por los fúrbolgs Tuercepinos corrompidos. Uruson recorre sus senderos, y en sus límites acecha Ferocitas el Comesueños, una bestia cuya sola presencia muestra cuánto ha caído la aldea desde lo que fue.",
			source = "https://warcraft.wiki.gg/wiki/Starbreeze_Village",
		},
		["wellspring lake"] = {
			name = "Lago Primigenio",
			short = "El Lago Primigenio obtiene su agua de un manantial en lo profundo de la propia Teldrassil, y su excedente fluye como el Río Primigenio. Los pescadores elfos de la noche apreciaban en otro tiempo estas aguas tranquilas.",
			full = "El Lago Primigenio obtiene su agua de un manantial en lo profundo de la propia Teldrassil, y su excedente fluye como el Río Primigenio. Los pescadores elfos de la noche apreciaban en otro tiempo estas aguas tranquilas. Ahora los brezomaderas que habitan aquí se han corrompido, y los sables de la noche y las arañas se han colado en las tierras circundantes, convirtiendo lo que antes era un apacible lugar de pesca en un lugar peligroso.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_Lake",
		},
		["wellspring river"] = {
			name = "Río Primigenio",
			short = "El Río Primigenio nace de un manantial en lo profundo de Teldrassil y fluye desde el Lago Primigenio hacia el norte hasta el borde del árbol, donde cae en una gran cascada al mar.",
			full = "El Río Primigenio nace de un manantial en lo profundo de Teldrassil y fluye desde el Lago Primigenio hacia el norte hasta el borde del árbol, donde cae en una gran cascada al mar.\n\nAhora unos brezomaderas enloquecidos acechan en sus orillas y atacan a cualquiera que se acerque.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_River",
		},
	},
	-- Costa Oscura: 15 subzones
	[1439] = {
		["ametharan"] = {
			name = "Ameth'Aran",
			short = "Las ruinas de Ameth'Aran se encuentran al sureste de Auberdine, en Costa Oscura, y algo del pueblo todavía camina por allí.",
			full = "Las ruinas de Ameth'Aran se encuentran al sureste de Auberdine, en Costa Oscura, y algo del pueblo todavía camina por allí.\n\nLa reina Azshara levantó en otro tiempo Ameth'Aran como gemela de Bashal'Aran e instaló a sus Altonato favoritos entre sus bazares y sus templos a Elune. Al frente puso a Athrikus Narassin, un mago de gran poder que se recluía en su Torre de Althalaxx.\n\nCuando llegó el Gran Cataclismo y el pueblo ya se desmoronaba, su gente se aferró al suelo como si solo eso pudiera salvarla. Athrikus Narassin apareció entre ellos y les prometió un hechizo que los libraría de la destrucción que se avecinaba, concediéndoles la vida eterna dentro de unas gemas de alma que llevaba consigo. Mientras lo pronunciaba, los elfos que lo rodeaban murieron. La eternidad que les dio fue una prisión, no un rescate, y son sus espíritus, no sus vidas, los que permanecen en Ameth'Aran desde entonces.\n\nEntre las ruinas aún se alzan dos grandes tablillas de piedra con la historia de la caída del pueblo grabada en ellas. Una centinela que vino a leerlas fue atacada por los inquietos Altonato antes de poder terminar, y huyó.",
			source = "https://warcraft.wiki.gg/wiki/Ameth'Aran",
		},
		["auberdine"] = {
			name = "Auberdine",
			short = "Auberdine se alza donde el Gran Cataclismo quebró la tierra, en una costa que se tragó las grandes ciudades del antiguo Imperio kaldorei. Todos los asentamientos que se han intentado en Costa Oscura desde entonces han fracasado, salvo este pueblo junto al Mar de la Bruma.",
			full = "Auberdine se alza donde el Gran Cataclismo quebró la tierra, en una costa que se tragó las grandes ciudades del antiguo Imperio kaldorei. Todos los asentamientos que se han intentado en Costa Oscura desde entonces han fracasado, salvo este pueblo junto al Mar de la Bruma.\n\nHa crecido de manera distinta al resto de la sociedad de los elfos de la noche. Su puerto atrae barcos y comerciantes de los Reinos del Este, y sus calles están llenas de enanos, gnomos, humanos e incluso altos elfos, de modo que Auberdine está más iluminada de lo que un pueblo de elfos de la noche tendría motivos para estar, y sus letreros están escritos en dos lenguas por consideración a los forasteros. Darnassus la mira por encima del hombro por ello. Broll Bearmantle, que visitó el pueblo en una ocasión, considera a sus habitantes poco más que marginados e inadaptados, y las centinelas destacadas aquí se mantienen apartadas de la gente a la que protegen. Sin embargo, Shandris Plumaluna, que estuvo destinada aquí, lo recuerda como un lugar lleno de risas.\n\nCerca del faro, los restos de un barco que comandó en otro tiempo la elfa Elura todavía marcan las rocas; su cargamento de mena de elunita se perdió cuando se hundió.",
			source = "https://warcraft.wiki.gg/wiki/Auberdine",
		},
		["bashalaran"] = {
			name = "Bashal'Aran",
			short = "Antes de que el mar se alzara sobre el mundo y lo quebrara, la reina Azshara levantó dos pueblos gemelos en el norte de Costa Oscura para sus Altonato favoritos: Ameth'Aran y Bashal'Aran.",
			full = "Antes de que el mar se alzara sobre el mundo y lo quebrara, la reina Azshara levantó dos pueblos gemelos en el norte de Costa Oscura para sus Altonato favoritos: Ameth'Aran y Bashal'Aran. Puso a Athrikus Narassin, un elfo de gran poder mágico, a gobernarlos, y bajo él servía Asterion, un mago tan hábil en las artes arcanas como en las armas, que vivía entre la gente de Bashal'Aran y viajaba a menudo a Ameth'Aran para atender a sus habitantes. En aquellos días, las ciudades gemelas tenían bazares y templos a Elune, agraciados por el favor de la propia reina.\n\nCuando el primer Pozo de la Eternidad se hizo añicos, ambas ciudades quedaron en ruinas. Pero en algún momento Athrikus Narassin volvió sus artes contra su propio segundo, encerró a Asterion en un sello de piedra lunar y lo aprisionó entre las piedras de Bashal'Aran. Nadie vivo hoy sabe decir por qué el amo se volvió contra su sirviente. Asterion soportó la prisión durante una vida larga y dolorosa, y cuando por fin murió, descubrió que la muerte no lo había liberado. Su espíritu quedó tan atado como lo había estado su carne.",
			source = "https://warcraft.wiki.gg/wiki/Bashal'Aran",
		},
		["blackwood den"] = {
			name = "Cubil del Bosque Negro",
			short = "En el extremo sur de Costa Oscura, cerca de la frontera con Vallefresno, un grupo disperso de campamentos fúrbolg y una pequeña cueva forman el lugar llamado Cubil del Bosque Negro, a veces llamado Bastión del Bosque Negro.",
			full = "En el extremo sur de Costa Oscura, cerca de la frontera con Vallefresno, un grupo disperso de campamentos fúrbolg y una pequeña cueva forman el lugar llamado Cubil del Bosque Negro, a veces llamado Bastión del Bosque Negro. Los fúrbolgs que lo ocupan están corrompidos, retorcidos respecto de lo que alguna vez fueron.\n\nDentro de la cueva hay un elfo de la noche solitario llamado Volcor, retenido como prisionero entre los fúrbolgs.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Den",
		},
		["cliffspring falls"] = {
			name = "Salto de Fonroca",
			short = "El Salto de Fonroca es el nacimiento del Río Fonroca; antaño era su agua más pura y la fuente de agua potable de toda Costa Oscura. Esa agua ya no está limpia.",
			full = "El Salto de Fonroca es el nacimiento del Río Fonroca; antaño era su agua más pura y la fuente de agua potable de toda Costa Oscura. Esa agua ya no está limpia. La cueva de la que brota la cascada se ha vuelto inmunda, y la corrupción se extiende con la corriente por la región a la que antes daba vida.\n\nNadie se pone de acuerdo sobre el motivo. Algunos culpan a Frondavil y dicen que la corrupción simplemente se filtra desde aquel bosque arruinado. Otros señalan lo que se ha encontrado en lo profundo de la propia cueva, donde ahora los nagas se arrastran por la oscuridad en el nacimiento del agua.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_Falls",
		},
		["cliffspring river"] = {
			name = "Río Fonroca",
			short = "El Río Fonroca fluye desde el Salto de Fonroca hasta el mar, en el norte de Costa Oscura. Sus aguas están contaminadas por los nagas Stormscale, y la fauna que bebe de él a menudo enferma.",
			full = "El Río Fonroca fluye desde el Salto de Fonroca hasta el mar, en el norte de Costa Oscura. Sus aguas están contaminadas por los nagas Stormscale, y la fauna que bebe de él a menudo enferma.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_River",
		},
		["grove of the ancients"] = {
			name = "Páramo de los Ancianos",
			short = "El Páramo de los Ancianos es un antiguo templo de los elfos de la noche, cuyas piedras se asientan en torno al impetuoso Río Culebra, en las montañas de Costa Oscura.",
			full = "El Páramo de los Ancianos es un antiguo templo de los elfos de la noche, cuyas piedras se asientan en torno al impetuoso Río Culebra, en las montañas de Costa Oscura. Aquí habita Onu, un anciano de la sabiduría, junto con un druida dormido y un par de mercaderes, y aquí todavía se reúne el Círculo de los Ancestros.",
			source = "https://warcraft.wiki.gg/wiki/Grove_of_the_Ancients",
		},
		["long wash"] = {
			name = "Playa del Oleaje",
			short = "La Playa del Oleaje se extiende hacia el sur desde Auberdine hasta las aguas al oeste de Ameth'Aran, y a pesar de su nombre es el tramo de costa más corto de Costa Oscura.",
			full = "La Playa del Oleaje se extiende hacia el sur desde Auberdine hasta las aguas al oeste de Ameth'Aran, y a pesar de su nombre es el tramo de costa más corto de Costa Oscura. Arena gris bajo un cielo siempre encapotado. La marea deja poco más que madera arrastrada y los cadáveres de criaturas marinas muertas. Se ven múrlocs a lo largo de la orilla.",
			source = "https://warcraft.wiki.gg/wiki/Long_Wash",
		},
		["masters glaive"] = {
			name = "La Espada del Maestro",
			short = "En el suroeste de Costa Oscura yace un cráneo colosal, medio engullido por la tierra, con una guja de adamantita todavía clavada en el hueso.",
			full = "En el suroeste de Costa Oscura yace un cráneo colosal, medio engullido por la tierra, con una guja de adamantita todavía clavada en el hueso. Era Soggoth el Reptante, un heraldo de los dioses antiguos, y la hoja se llama la Guja del Maestro.\n\nLas tablillas descubiertas en la Excavación de Tripirrem contaron lo que ocurrió aquí. Los titanes habían enviado a veinte gigantes de piedra contra Soggoth, y la batalla que siguió fue tan terrible que solo uno de ellos vivió para ver su final: Kronn, el más grande de los veinte. Cuando los tentáculos de Soggoth se cerraron a su alrededor, Kronn no luchó por liberarse. Se dejó arrastrar hacia dentro, cada vez más cerca del cráneo de la criatura, hasta estar lo bastante cerca para golpear. El golpe que mató a Soggoth se asestó desde dentro de su propio abrazo, y la espada que quedó enterrada en su cráneo tomó el nombre de aquella victoria.\n\nDesde entonces, el Martillo Crepuscular ha reclamado el lugar y excava en los restos de Soggoth, esforzándose por deshacer lo que logró la espada de Kronn y devolver al mundo al heraldo del dios antiguo.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Glaive",
		},
		["mists edge"] = {
			name = "Cabo de la Niebla",
			short = "La costa llamada Cabo de la Niebla recorre todo Costa Oscura y es la orilla más larga de la región.",
			full = "La costa llamada Cabo de la Niebla recorre todo Costa Oscura y es la orilla más larga de la región.\n\nEs un tramo sombrío: playas grises y bahías lúgubres, sembradas de enormes cadáveres de animales marinos muertos y de restos de barcos hundidos.\n\nLos cangrejos corretean por toda su extensión, y los múrlocs acechan en las bahías poco profundas, una amenaza constante para cualquiera que camine por la orilla.",
			source = "https://warcraft.wiki.gg/wiki/Mist's_Edge",
		},
		["remtravels excavation"] = {
			name = "Excavación de Tripirrem",
			short = "El prospector Tripirrem dio su nombre a esta excavación de Costa Oscura.",
			full = "El prospector Tripirrem dio su nombre a esta excavación de Costa Oscura. Mientras excavaba encontró un fósil distinto de cualquier otro, que vibraba con propiedades místicas, pero el despistado prospector ha perdido desde entonces la pista de dónde lo dejó.\n\nLa propia excavación se ha vuelto peligrosa: los troggs Gravelflint han reclamado sus túneles, y enormes gólems, desenterrados por las excavaciones, se agitan ahora en su interior.",
			source = "https://warcraft.wiki.gg/wiki/Remtravel's_Excavation",
		},
		["ruins of mathystra"] = {
			name = "Ruinas de Mathystra",
			short = "Más allá de la Torre de Althalaxx, en el norte de Costa Oscura, se encuentran las Ruinas de Mathystra. Antes del Gran Cataclismo era una ciudad de los elfos de la noche, levantada en la era de los Altonato.",
			full = "Más allá de la Torre de Althalaxx, en el norte de Costa Oscura, se encuentran las Ruinas de Mathystra. Antes del Gran Cataclismo era una ciudad de los elfos de la noche, levantada en la era de los Altonato. Cuando el Pozo de la Eternidad se desgarró y el mundo se quebró bajo él, Mathystra quedó en ruinas junto con tantas otras cosas, y los elfos de la noche que sobrevivieron no regresaron a reconstruirla. En cambio, se retiraron a aldeas más pequeñas a lo largo de la costa, más al sur, y dejaron atrás las ruinas.\n\nEntre las piedras caídas todavía quedan reliquias dispersas de los antiguos Altonato, y a veces jóvenes elfos de la noche vienen a buscarlas por Mathystra, atentos a los sables fantasmales que merodean entre las ruinas de lo que su pueblo construyó en otro tiempo.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Mathystra",
		},
		["tower of althalaxx"] = {
			name = "Torre de Althalaxx",
			short = "En la época del Gran Cataclismo, cuando la reina Azshara elevó a los Altonato por encima de todos los demás, puso a un elfo llamado Athrikus Narassin a gobernar los pueblos gemelos de Ameth'Aran y Bashal'Aran.",
			full = "En la época del Gran Cataclismo, cuando la reina Azshara elevó a los Altonato por encima de todos los demás, puso a un elfo llamado Athrikus Narassin a gobernar los pueblos gemelos de Ameth'Aran y Bashal'Aran. Al principio Athrikus la sirvió bastante bien, pero el trabajo lo aburría, y empezó a pasar sus días lejos de los pueblos, en una torre propia llamada Althalaxx.\n\nDiez mil años después, lo que durante mucho tiempo se había susurrado sobre aquella torre resultó ser cierto. Un culto que se hacía llamar el Culto de la Facción Oscura se había reunido allí, con brujos y un sátiro entre sus miembros, y a su cabeza estaba el propio Athrikus Narassin. Su propósito no estaba claro hasta que salió a la luz que el culto respondía ante el Consejo de la Sombra, y que Althalaxx se había convertido en un hilo más de la red de aquella antigua conspiración.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Althalaxx",
		},
		["twilight vale"] = {
			name = "Vega Crepuscular",
			short = "Los bosques al sur de Ameth'Aran, que llegan hasta la frontera con Vallefresno, se llaman Vega Crepuscular.",
			full = "Los bosques al sur de Ameth'Aran, que llegan hasta la frontera con Vallefresno, se llaman Vega Crepuscular. Fúrbolgs corrompidos, sables de la noche salvajes y osos rabiosos rondan estos bosques, y se aconseja a los viajeros que se mantengan en los caminos en lugar de vagar bajo los árboles.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Vale",
		},
		["wildbend river"] = {
			name = "Río Culebra",
			short = "El Río Culebra arrastra su enfermedad desde las montañas: es la continuación del Río del Veneno, que sale de Frondavil hacia el sur de Costa Oscura, cerca del Páramo de los Ancianos.",
			full = "El Río Culebra arrastra su enfermedad desde las montañas: es la continuación del Río del Veneno, que sale de Frondavil hacia el sur de Costa Oscura, cerca del Páramo de los Ancianos. Sus aguas corren contaminadas, pues la corrupción de Frondavil sigue la corriente hasta estas tierras más bajas.",
			source = "https://warcraft.wiki.gg/wiki/Wildbend_River",
		},
	},
	-- Vallefresno: 41 subzones
	[1440] = {
		["astranaar"] = {
			name = "Astranaar",
			short = "Astranaar se alza sobre una isla en el corazón de Vallefresno; es el mayor de los asentamientos de los elfos de la noche de la región, y solo se llega a ella por un par de puentes que llevan el camino sobre el agua.",
			full = "Astranaar se alza sobre una isla en el corazón de Vallefresno; es el mayor de los asentamientos de los elfos de la noche de la región, y solo se llega a ella por un par de puentes que llevan el camino sobre el agua. El lago la separa del bosque que la rodea: un lugar tranquilo y defendible en el centro de una tierra en disputa.\n\nSu cementerio se encuentra junto a la orilla y guarda a los muertos del pueblo entre silenciosas hileras de piedra.\n\nMás allá del pueblo, los fúrbolgs Piel de Cardo han cobrado fuerza en el norte, y en Astranaar se teme que algún día encuentren el valor para volver esa fuerza contra el propio pueblo.",
			source = "https://warcraft.wiki.gg/wiki/Astranaar",
		},
		["bathrans haunt"] = {
			name = "Ruinas de Bathran",
			short = "Los pilares de las Ruinas de Bathran formaban parte en otro tiempo de unas ruinas kaldorei, levantadas en una época en que los elfos de la noche aún recorrían esta parte de Vallefresno.",
			full = "Los pilares de las Ruinas de Bathran formaban parte en otro tiempo de unas ruinas kaldorei, levantadas en una época en que los elfos de la noche aún recorrían esta parte de Vallefresno. Aquella época pasó, los elfos se retiraron, y el mármol quedó abandonado a agrietarse y caer.\n\nAhora no está vacío. Agentes Renegados se han instalado entre las columnas rotas, herboristas y los matones que los protegen, y allí donde se asientan, la tierra responde en consecuencia: la hierba se ha vuelto parda y las flores se han marchitado. Entre las piedras caídas han levantado un laboratorio improvisado, donde trabajan las hierbas locales con fines propios.\n\nLo que más los atrae aquí es una planta que no se encuentra en ningún otro lugar cercano: el cabello de Bathran, una hierba curativa lo bastante rara como para justificar por sí sola la ocupación del lugar.",
			source = "https://warcraft.wiki.gg/wiki/Bathran's_Haunt",
		},
		["blackfathom deeps"] = {
			name = "Cavernas de Brazanegra",
			short = "Bajo la Ensenada de Zoram, donde la antigua ciudad de Zoram se hundió en el mar, se encuentran los salones anegados de Lathar'Lazal, que en otro tiempo fue un templo a Elune.",
			full = "Bajo la Ensenada de Zoram, donde la antigua ciudad de Zoram se hundió en el mar, se encuentran los salones anegados de Lathar'Lazal, que en otro tiempo fue un templo a Elune. Se creía que el Gran Cataclismo lo había destruido por completo, y durante milenios lo guardó el océano.\n\nEntonces llegó el Martillo Crepuscular, atraído por susurros y sueños inmundos hasta las cavernas acuáticas en que se había convertido el templo. El culto sacrificó a innumerables inocentes en aquellas profundidades, y fue recompensado con una misión: alimentar y proteger a una criatura muy querida de los dioses antiguos, la monstruosa hidra Aku'mai la Devoradora, hasta el día en que sea liberada sobre el mundo. Ahora el lugar se llama Brazanegra, y el nombre le queda bien.",
			source = "https://warcraft.wiki.gg/wiki/Blackfathom_Deeps",
		},
		["bloodtooth camp"] = {
			name = "Asentamiento Sangradientes",
			short = "El Asentamiento Sangradientes se encuentra al oeste del Río Falfarren, al suroeste de la poza de la luna meridional de Vallefresno. Toma su nombre de Ran Sangradientes, jefe de la tribu fúrbolg que lo ocupa.",
			full = "El Asentamiento Sangradientes se encuentra al oeste del Río Falfarren, al suroeste de la poza de la luna meridional de Vallefresno. Toma su nombre de Ran Sangradientes, jefe de la tribu fúrbolg que lo ocupa.\n\nEstos fúrbolgs fueron en otro tiempo como cualquier otro de su especie, pero la corrupción se ha apoderado de todos ellos, y ahora el campamento responde con hostilidad a cualquier forastero que se acerque.",
			source = "https://warcraft.wiki.gg/wiki/Bloodtooth_Camp",
		},
		["bough shadow"] = {
			name = "Talloumbrío",
			short = "Más allá de Canción del Bosque, donde los árboles de Vallefresno crecen espesos y viejos, Talloumbrío alberga uno de los portales al Sueño Esmeralda.",
			full = "Más allá de Canción del Bosque, donde los árboles de Vallefresno crecen espesos y viejos, Talloumbrío alberga uno de los portales al Sueño Esmeralda.\n\nLo custodia el Vuelo Verde. Los dracos Phantim y Dreamstalker vigilan el paso, y los dracónidos recorren los bosques circundantes en patrullas de tres, un oráculo esmeraldino flanqueado por guardarramas y celadores de los árboles, pisando una y otra vez el mismo terreno en su larga vigilia.",
			source = "https://warcraft.wiki.gg/wiki/Bough_Shadow",
		},
		["demon fall canyon"] = {
			name = "Barranco del Demonio",
			short = "El Barranco del Demonio lleva la cicatriz del momento en que los orcos se liberaron de su antigua esclavitud.",
			full = "El Barranco del Demonio lleva la cicatriz del momento en que los orcos se liberaron de su antigua esclavitud.\n\nAquí, el señor del foso Mannoroth se enfrentó a Grommash Grito Infernal y a Thrall en combate singular. El demonio derribó a Thrall, pero no pudo apartarse a tiempo del hacha de Grom, que se le clavó en el pecho. La muerte de Mannoroth estalló hacia fuera en fuego y luz, y ese mismo fuego arrancó la vida a Grom mientras acababa con el demonio. Los orcos tomaron el lugar de su sacrificio y le dieron su nombre, pues fue allí donde se rompió la maldición que la Legión Ardiente había impuesto a su pueblo.\n\nMuchos orcos todavía viajan hasta aquí para honrar al guerrero que pagó por esa libertad, y un monumento se alza en su memoria. Pero el suelo sigue tocado por lo vil, y ahora demonios menores rondan el barranco.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Canyon",
		},
		["demon fall ridge"] = {
			name = "Cresta del Demonio",
			short = "Sobre el Barranco del Demonio, la cresta se alza quebrada, con sus laderas y el túmulo excavado en su costado invadidos por demonios menores.",
			full = "Sobre el Barranco del Demonio, la cresta se alza quebrada, con sus laderas y el túmulo excavado en su costado invadidos por demonios menores. Más adentro, más allá del alcance de la luz del día, aguarda Diathorus el Buscador, un señor del terror que gobierna el cónclave demoníaco reunido en Vallefresno y celebra su corte en la oscuridad mientras los demonios menores custodian la cresta de arriba.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Ridge",
		},
		["dordanil barrow den"] = {
			name = "El Túmulo de Dor'danil",
			short = "El Túmulo de Dor'danil ha sido durante mucho tiempo un lugar de descanso para los druidas elfos de la noche, que duermen allí con el cuerpo mientras sus espíritus vagan libres.",
			full = "El Túmulo de Dor'danil ha sido durante mucho tiempo un lugar de descanso para los druidas elfos de la noche, que duermen allí con el cuerpo mientras sus espíritus vagan libres. Fueron los Renegados quienes pusieron su atención en los durmientes y separaron a los druidas de sus espíritus errantes. El experimento no los mató. Los volvió locos.\n\nAhora el túmulo ya no alberga durmientes tranquilos. Asesinos Renegados se mueven por él sin ser vistos, mientras las almas enfurecidas de los druidas separados se enfurecen por el montículo sin ningún lugar al que regresar. Entre ellas permanecen tres espíritus más fuertes que el resto: Uthil Mooncall, Mavoris Quiebranubes y Taneel Darkwood.",
			source = "https://warcraft.wiki.gg/wiki/Dor'Danil_Barrow_Den",
		},
		["falfarren river"] = {
			name = "Río Falfarren",
			short = "El Falfarren divide Vallefresno casi por la mitad. Al oeste están los elfos de la noche bajo Astranaar; al este, los orcos ocupan el Puesto del Hachazo.",
			full = "El Falfarren divide Vallefresno casi por la mitad. Al oeste están los elfos de la noche bajo Astranaar; al este, los orcos ocupan el Puesto del Hachazo. El río es lo bastante poco profundo para vadearlo y lo bastante estrecho para cruzarlo sin muchos problemas, salvo cuando las lluvias lo desbordan, pero aun así marca una frontera, una que ambos pueblos entienden sin necesidad de hablar de ella.\n\nSus aguas nacen en las laderas del Monte Hyjal, caen en cascadas hasta el lago de Xavian y luego siguen entre el Puesto del Hachazo y la Senda de la Noche, bajo el gran puente que la mayoría de los viajeros usa para cruzar Vallefresno, y pasan junto a la Avanzada Ala de Plata y la Poza de la Luna de la Purificación, antes de deslizarse bajo tierra bajo las montañas del norte hacia Los Baldíos.\n\nCerca del Cerro Lumbrevil, el río oculta otro peligro. Allí acechan bajo su superficie bestias del pantano, que atacan a cualquier cosa que se quede demasiado tiempo en el agua.",
			source = "https://warcraft.wiki.gg/wiki/Falfarren_River",
		},
		["fallen sky lake"] = {
			name = "Lago Cielo Estrellado",
			short = "Un pequeño lago se encuentra al sur de la Avanzada Ala de Plata, en Vallefresno, con sus aguas reunidas alrededor de una isla solitaria.",
			full = "Un pequeño lago se encuentra al sur de la Avanzada Ala de Plata, en Vallefresno, con sus aguas reunidas alrededor de una isla solitaria. En esa isla habita un oráculo de Sombramatorral, un anciano entre los Sombramatorral, que rodean la orilla en menor número y vigilan el agua desde los juncos y matorrales que la rodean.",
			source = "https://warcraft.wiki.gg/wiki/Fallen_Sky_Lake",
		},
		["felfire hill"] = {
			name = "Cerro Lumbrevil",
			short = "El Cerro Lumbrevil aún lleva las cicatrices de la Tercera Guerra, cuando los infernales cayeron ardiendo del cielo y golpearon aquí la tierra. Desde entonces han permanecido los demonios, criaturas inmundas que tienen su guarida entre las piedras.",
			full = "El Cerro Lumbrevil aún lleva las cicatrices de la Tercera Guerra, cuando los infernales cayeron ardiendo del cielo y golpearon aquí la tierra. Desde entonces han permanecido los demonios, criaturas inmundas que tienen su guarida entre las piedras.\n\nLa Horda ha fortificado los dos puentes que llevan a la colina y los defiende para impedir que los demonios se desborden hacia los asentamientos cercanos.",
			source = "https://warcraft.wiki.gg/wiki/Felfire_Hill",
		},
		["fire scar shrine"] = {
			name = "Santuario de la Escara",
			short = "El Santuario de la Escara se alza en el suroeste de Vallefresno, corrompido por la influencia demoníaca del Consejo de la Sombra hasta convertirse en un lugar de gran maldad.",
			full = "El Santuario de la Escara se alza en el suroeste de Vallefresno, corrompido por la influencia demoníaca del Consejo de la Sombra hasta convertirse en un lugar de gran maldad. El brujo orco Ilkrud Magthrull residió aquí en otro tiempo, al servicio de Athrikus Narassin, líder del Culto de la Facción Oscura.\n\nAhora los demonios infestan el santuario, atraídos por la corrupción que quedó en la piedra. Entre ellos, se sabe que un guardia apocalíptico llamado Akkrilus aparece de vez en cuando por la zona, una señal rara y peligrosa de lo profunda que es la corrupción.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Scar_Shrine",
		},
		["forest song"] = {
			name = "Canción del Bosque",
			short = "Canción del Bosque es una antigua ruina de los elfos de la noche en los bosques de Vallefresno, abandonada desde hace mucho al musgo y al recuerdo. Durante un tiempo apenas tuvo habitantes.",
			full = "Canción del Bosque es una antigua ruina de los elfos de la noche en los bosques de Vallefresno, abandonada desde hace mucho al musgo y al recuerdo. Durante un tiempo apenas tuvo habitantes.\n\nEntonces el druida Kayneth Ventoleve la hizo suya: fue el único habitante de la ruina y dirigió desde sus piedras la lucha contra los Renegados en la región. Un lugar olvidado se convirtió en un puesto de vigilancia, sostenido no por el número, sino por la negativa de un druida a abandonarlo.",
			source = "https://warcraft.wiki.gg/wiki/Forest_Song",
		},
		["greenpaw village"] = {
			name = "Poblado Zarpaverde",
			short = "El Poblado Zarpaverde es el hogar de la tribu Maderiza, fúrbolgs dirigidos por el jefe Murgut y el chamán Oakpaw. Los hombres oso de aquí están corrompidos.",
			full = "El Poblado Zarpaverde es el hogar de la tribu Maderiza, fúrbolgs dirigidos por el jefe Murgut y el chamán Oakpaw. Los hombres oso de aquí están corrompidos.",
			source = "https://warcraft.wiki.gg/wiki/Greenpaw_Village",
		},
		["howling vale"] = {
			name = "Vega del Aullido",
			short = "Una cueva se abre al valle donde se alza el Santuario de Mel'Thandris, cuya piedra lleva grabada una antigua inscripción de alabanza a Elune y, encima, en darnassiano: la verdad es una luz que guía.",
			full = "Una cueva se abre al valle donde se alza el Santuario de Mel'Thandris, cuya piedra lleva grabada una antigua inscripción de alabanza a Elune y, encima, en darnassiano: la verdad es una luz que guía.\n\nEl santuario lo levantó la madre de Velinde Cantoestelar en honor a Mel'Thandris, a quien se había confiado la Guadaña de Elune. Cuando Mel'Thandris murió, la guadaña quedó aquí, oculta dentro del santuario. Permaneció olvidada hasta que Velinde, tras encontrar en Darnassus un libro que relataba la historia, llegó al valle y la desenterró ella misma.\n\nCon el tiempo, el santuario quedó en ruinas, y una tribu de huargen llamada Terrowulf lo invadió e hizo de la cueva su guarida. Sus aullidos, que resuenan por la piedra, le dieron al valle el nombre que lleva hoy.",
			source = "https://warcraft.wiki.gg/wiki/Howling_Vale",
		},
		["iris lake"] = {
			name = "Lago Iris",
			short = "El Lago Iris se encuentra en el centro norte de Vallefresno, al este de Astranaar y al oeste de la poza de la luna de Shael'dryn.",
			full = "El Lago Iris se encuentra en el centro norte de Vallefresno, al este de Astranaar y al oeste de la poza de la luna de Shael'dryn. En otro tiempo formaba parte del bosque intacto de los elfos de la noche, pero cayó ante la corrupción que se extiende desde Frondavil, y su agua se volvió de un verde amarillento enfermizo. Ahora bestias del pantano retorcidas rondan sus orillas y atacan a cualquiera que venga en busca de Lágrimas de Elune.",
			source = "https://warcraft.wiki.gg/wiki/Iris_Lake",
		},
		["kargathia keep"] = {
			name = "Fuerte de Kargathia",
			short = "El Fuerte de Kargathia se alza entre barricadas de estacas en el Aserradero Grito de Guerra, en el este de Vallefresno, cerca del Río Furia del Sur.",
			full = "El Fuerte de Kargathia se alza entre barricadas de estacas en el Aserradero Grito de Guerra, en el este de Vallefresno, cerca del Río Furia del Sur. Sirve como sede de los oficiales del clan Grito de Guerra, y su ubicación se eligió para poder pedir refuerzos a Orgrimmar si la Alianza avanzaba en fuerza contra el campamento.\n\nEl fuerte toma su nombre de Kargath Garrafilada, el héroe orco a quien también se honra en Kargath, en las Tierras Inhóspitas, y en la Bahía de Garrafilada, en Durotar. El sobrestante Gorthak dirige el campamento desde dentro de sus muros y ordena la tala de la madera de Vallefresno.",
			source = "https://warcraft.wiki.gg/wiki/Kargathia_Keep",
		},
		["lake falathim"] = {
			name = "Lago Falathim",
			short = "El Lago Falathim se encuentra en el oeste de Vallefresno, donde la luz de la luna de la diosa siempre toca el agua, de día o de noche. Los elfos de la noche venían aquí libremente a nadar y pescar, hasta que los múrlocs invadieron el lago y lo volvieron salvaje.",
			full = "El Lago Falathim se encuentra en el oeste de Vallefresno, donde la luz de la luna de la diosa siempre toca el agua, de día o de noche. Los elfos de la noche venían aquí libremente a nadar y pescar, hasta que los múrlocs invadieron el lago y lo volvieron salvaje. El erudito Teronis fue visto por última vez cerca de sus orillas y nunca regresó.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Falathim",
		},
		["maestras post"] = {
			name = "Atalaya de Maestra",
			short = "Aquí se alzan en silencio una torre y un único salón de los elfos de la noche, que albergan a un puñado de defensores y, lo más extraño de todo en Vallefresno, a dos humanos entre los elfos: Feero Ferramán y Delgren el Purificador, los únicos de su especie en este puesto.",
			full = "Aquí se alzan en silencio una torre y un único salón de los elfos de la noche, que albergan a un puñado de defensores y, lo más extraño de todo en Vallefresno, a dos humanos entre los elfos: Feero Ferramán y Delgren el Purificador, los únicos de su especie en este puesto.\n\nSon pocos, pues la corrupción que se extiende entre los fúrbolgs cercanos se lleva manos que de otro modo montarían guardia aquí, y deja a los defensores del puesto desbordados.",
			source = "https://warcraft.wiki.gg/wiki/Maestra's_Post",
		},
		["mystral lake"] = {
			name = "Lago Mystral",
			short = "El agua del Lago Mystral la custodiaban en otro tiempo espíritus leales a los elfos de la noche, atados al lago como sus guardianes.",
			full = "El agua del Lago Mystral la custodiaban en otro tiempo espíritus leales a los elfos de la noche, atados al lago como sus guardianes. Sarilus Foulborne los volvió contra ellos, corrompiendo a los elementales hasta que le obedecieron a él en lugar de a los elfos a los que antes servían. Lo que aguarda ahora en el lago no es lo que fue.",
			source = "https://warcraft.wiki.gg/wiki/Mystral_Lake",
		},
		["night run"] = {
			name = "Senda de la Noche",
			short = "La Senda de la Noche se encuentra en un saliente que se adentra en la tierra, con acantilados demasiado escarpados para escalarlos, de modo que un viajero debe seguir el Falfarren casi hasta las aguas de Xavian antes de girar al oeste, o bien encontrar la estrecha cornisa al norte de la Algaba.",
			full = "La Senda de la Noche se encuentra en un saliente que se adentra en la tierra, con acantilados demasiado escarpados para escalarlos, de modo que un viajero debe seguir el Falfarren casi hasta las aguas de Xavian antes de girar al oeste, o bien encontrar la estrecha cornisa al norte de la Algaba. Una vez dentro, hay poco que encontrar: solo unos pilares rotos dispersos y restos de cantería en ruinas, la más pequeña y pobre de las tres fortalezas de sátiros de Vallefresno, empequeñecida tanto por Xavian como por Satyrnaar. Los sátiros Felmusk que se refugian entre estas ruinas apenas necesitan muros cuando la propia tierra los protege. Entre los escombros yace una de las gemas de alma del Culto de la Facción Oscura, con el que los Felmusk están aliados.",
			source = "https://warcraft.wiki.gg/wiki/Night_Run",
		},
		["nightsong woods"] = {
			name = "Bosque Arrullanoche",
			short = "El Río Falfarren parte en dos los bosques orientales, y la línea que traza es la de una guerra que nunca termina.",
			full = "El Río Falfarren parte en dos los bosques orientales, y la línea que traza es la de una guerra que nunca termina. Al oeste de sus orillas, las centinelas Ala de Plata defienden el terreno para la Alianza; al este, el clan Grito de Guerra ha clavado sus estacas en la tierra, y aquí la lucha entre ambos pueblos es más intensa y constante.\n\nMás al este, un segundo río sin nombre marca otra frontera. A un lado se alza el Puesto del Hachazo, el corazón del poder de la Horda en estos bosques; al otro, el Claro Ala de Plata responde por la Alianza. Más allá de ese río se extiende un terreno que nunca pertenece a nadie por mucho tiempo, reclamado a trozos por los elfos de la noche de Canción del Bosque, los sátiros de Satyrnaar y Xavian, los orcos Grito de Guerra y la propia Legión Ardiente. Allí nunca ha ondeado un solo estandarte sin ser desafiado.\n\nAl sur de los combates, el bosque ha pagado el precio de la guerra. El clan Grito de Guerra ha dejado desnudas estas tierras, talando los viejos árboles para obtener madera con la que levantar sus asentamientos, y ha dejado un terreno abierto y herido donde antes se alzaba intacto un bosque antiguo.",
			source = "https://warcraft.wiki.gg/wiki/Nightsong_Woods",
		},
		["raynewood retreat"] = {
			name = "Refugio de la Algaba",
			short = "En lo alto de las ramas del Gran Árbol que da nombre a este lugar se esconde Ordanus, un guardián de la arboleda y uno de los hijos mayores de Cenarius.",
			full = "En lo alto de las ramas del Gran Árbol que da nombre a este lugar se esconde Ordanus, un guardián de la arboleda y uno de los hijos mayores de Cenarius. Vino aquí para ocultarse del Consejo de la Sombra, cuyos agentes lo habían señalado para morir. La principal de ellos era Braelyn Firehand, que convirtió su muerte en su único propósito y envió asesinos contra él. Ordanus sobrevivió al atentado y aún permanece oculto en las altas ramas del árbol.\n\nDebajo de él, protectores cenarion, dragones intermitentes y las hermanas sonrientes vigilan desde el puesto, custodiando el sendero norte que lleva a las tierras arruinadas de Frondavil.",
			source = "https://warcraft.wiki.gg/wiki/Raynewood_Retreat",
		},
		["ruins of ordilaran"] = {
			name = "Las Ruinas de Ordil'Aran",
			short = "Poco queda ya de Ordil'Aran salvo piedra rota. El Culto de la Facción Oscura hizo suyas las ruinas en otro tiempo, dispuesto a caer sobre cualquiera que se acercara demasiado.",
			full = "Poco queda ya de Ordil'Aran salvo piedra rota. El Culto de la Facción Oscura hizo suyas las ruinas en otro tiempo, dispuesto a caer sobre cualquiera que se acercara demasiado. Aquello terminó en sangre: los fúrbolgs Piel de Cardo los expulsaron y reclamaron las ruinas para sí, y los cuerpos de los cultistas todavía yacen dispersos donde cayeron.\n\nEntre los restos se alza el Duramen, arraigado en lo que fue una ciudad de cierto nombre y prestigio. Nada más de ella sobrevive para decir qué fue.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ordil'Aran",
		},
		["ruins of stardust"] = {
			name = "Las Ruinas del Polvo Estelar",
			short = "Las Ruinas del Polvo Estelar se encuentran en una isla del lago, antaño sumida en la santidad y ahora sumida en la podredumbre. La corrupción demoníaca que desciende de Frondavil se ha infiltrado tanto en el agua como en la piedra y ha teñido la isla de un amarillo verdoso enfermizo.",
			full = "Las Ruinas del Polvo Estelar se encuentran en una isla del lago, antaño sumida en la santidad y ahora sumida en la podredumbre. La corrupción demoníaca que desciende de Frondavil se ha infiltrado tanto en el agua como en la piedra y ha teñido la isla de un amarillo verdoso enfermizo. Ahora bestias del pantano, retorcidas por el lago envenenado, se arrastran entre los restos.\n\nAun así, los arbustos de polvo estelar todavía crecen allí, intactos ante la corrupción que los rodea. Se dice que sus hojas tienen una virtud curativa, lo único de las ruinas que todavía se parece a lo que debió de ser el lugar antes de que llegara la podredumbre.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Stardust",
		},
		["satyrnaar"] = {
			name = "Satyrnaar",
			short = "Satyrnaar se alza destrozada entre los árboles del noreste de Vallefresno, con sus edificios en ruinas desde hace mucho, aunque ahora hay tiendas agrupadas entre los restos donde los sátiros Almaumbría han establecido su hogar.",
			full = "Satyrnaar se alza destrozada entre los árboles del noreste de Vallefresno, con sus edificios en ruinas desde hace mucho, aunque ahora hay tiendas agrupadas entre los restos donde los sátiros Almaumbría han establecido su hogar. De las tres fortalezas de sátiros del bosque, solo Satyrnaar sigue en gran parte intacta, y su posición junto al camino que va del Puesto del Hachazo hacia Azshara la ha convertido a la vez en la más accesible y la más disputada de las tres.\n\nLos Almaumbría tienen aquí algo más que un refugio. Dentro de Satyrnaar descansa una de las gemas de alma del Culto de la Facción Oscura, prenda del pacto que une a los sátiros con los oscuros propósitos de ese culto.",
			source = "https://warcraft.wiki.gg/wiki/Satyrnaar",
		},
		["shady nook"] = {
			name = "El Rincón Lóbrego",
			short = "El Rincón Umbrío se encuentra al sur del Refugio de la Algaba y al este del Poblado Zarpaverde, un pequeño valle escondido tranquilamente en Vallefresno.",
			full = "El Rincón Umbrío se encuentra al sur del Refugio de la Algaba y al este del Poblado Zarpaverde, un pequeño valle escondido tranquilamente en Vallefresno. En su ladera se abre una cueva, hogar de una pequeña familia de osos que viven a su aire entre los árboles y las sombras.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Nook",
		},
		["shrine of aessina"] = {
			name = "El Santuario de Aessina",
			short = "El Santuario de Aessina se alza en el suroeste de Vallefresno, escondido entre la Atalaya de Maestra y Astranaar.",
			full = "El Santuario de Aessina se alza en el suroeste de Vallefresno, escondido entre la Atalaya de Maestra y Astranaar.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Aessina",
		},
		["silverwind refuge"] = {
			name = "Refugio Brisa de Plata",
			short = "El Refugio Brisa de Plata pertenece a los elfos de la noche, bajo la vigilancia de las centinelas y de los elementales de agua que sirven junto a ellas.",
			full = "El Refugio Brisa de Plata pertenece a los elfos de la noche, bajo la vigilancia de las centinelas y de los elementales de agua que sirven junto a ellas. Junto con Astranaar, es uno de los principales puestos de Vallefresno, y se ha ganado bien su nombre: un lugar acogedor, cuya posada se cuenta entre las más cómodas de la región.",
			source = "https://warcraft.wiki.gg/wiki/Silverwind_Refuge",
		},
		["silverwing grove"] = {
			name = "Claro Ala de Plata",
			short = "El Claro Ala de Plata se encuentra en el centro sur de Vallefresno, una arboleda en manos de las centinelas Ala de Plata, al suroeste de su avanzada y al oeste del Lago Cielo Estrellado.",
			full = "El Claro Ala de Plata se encuentra en el centro sur de Vallefresno, una arboleda en manos de las centinelas Ala de Plata, al suroeste de su avanzada y al oeste del Lago Cielo Estrellado. La centinela Cantolejano monta guardia aquí entre quienes han jurado defender el claro.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Grove",
		},
		["silverwing outpost"] = {
			name = "Avanzada Ala de Plata",
			short = "La Avanzada Ala de Plata se alza en el lado equivocado del Río Falfarren, en lo profundo de un territorio que los orcos del Puesto del Hachazo pretenden despejar.",
			full = "La Avanzada Ala de Plata se alza en el lado equivocado del Río Falfarren, en lo profundo de un territorio que los orcos del Puesto del Hachazo pretenden despejar. Duriel Fuegolunar está al mando, y aquí el mando significa guerra constante: los orcos no atacan para saquear, sino para borrar la avanzada y expulsar para siempre a todas las centinelas de estos bosques.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Outpost",
		},
		["southfury river"] = {
			name = "Río Furia del Sur",
			short = "El Furia del Sur nace en lo alto del Monte Hyjal y brota de un lago de montaña en una cascada que cae con estruendo hacia las tierras bajas.",
			full = "El Furia del Sur nace en lo alto del Monte Hyjal y brota de un lago de montaña en una cascada que cae con estruendo hacia las tierras bajas. Desde allí fluye ancho y veloz, partiendo la tierra en dos: marca el lugar donde Vallefresno da paso a Azshara y, más al sur, donde terminan Los Baldíos y comienza Durotar. En su desembocadura, el río se precipita por una última cascada al Mare Magnum, justo al noreste del puerto goblin de Trinquete.\n\nVarios puentes lo cruzan a lo largo de su recorrido: uno une Azshara con Vallefresno, y otro une Durotar con Los Baldíos. Justo al norte del que está más al oeste, un solo tramo de agua toca las cuatro tierras a la vez, el único lugar donde se encuentran Vallefresno, Azshara, Durotar y Los Baldíos.\n\nEl río todavía alimenta los campos de sus orillas y todavía tiñe de verde la tierra por donde pasa. Pero ya no se puede beber.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["splintertree post"] = {
			name = "Puesto del Hachazo",
			short = "Las maderas del Puesto del Hachazo todavía llevan las marcas de las hachas que lo levantaron, pues fueron Grommash Grito Infernal y su clan Grito de Guerra quienes construyeron este puesto cuando los orcos avanzaron por primera vez en Vallefresno durante la Tercera Guerra, talando los árboles antiguos para su camino y sus campamentos.",
			full = "Las maderas del Puesto del Hachazo todavía llevan las marcas de las hachas que lo levantaron, pues fueron Grommash Grito Infernal y su clan Grito de Guerra quienes construyeron este puesto cuando los orcos avanzaron por primera vez en Vallefresno durante la Tercera Guerra, talando los árboles antiguos para su camino y sus campamentos.\n\nLos elfos de la noche nunca han hecho las paces con lo que los Grito de Guerra hicieron a sus bosques, y las viejas heridas se asientan incómodas bajo la tensa tregua entre la Horda y la Alianza. Por eso el Puesto del Hachazo atrae más represalias que la mayoría de los puestos de estos bosques, y las incursiones contra la cercana Astranaar son frecuentes por ambas partes.\n\nLo que queda ahora es una guarnición, no un asentamiento: orcos y tauren que hacen de exploradores y guardias, vigilando la línea de árboles en busca de los asaltantes que han aprendido a esperar.",
			source = "https://warcraft.wiki.gg/wiki/Splintertree_Post",
		},
		["talondeep path"] = {
			name = "El Paso del Espolón",
			short = "El Paso del Espolón es un túnel sinuoso que une Vallefresno con la Sierra Espolón, con un recorrido irregular lleno de pequeños callejones sin salida y extraños huecos desgastados en la roca.",
			full = "El Paso del Espolón es un túnel sinuoso que une Vallefresno con la Sierra Espolón, con un recorrido irregular lleno de pequeños callejones sin salida y extraños huecos desgastados en la roca. Por un extremo se abre al oeste del Lago Mystral, y por el otro en el noroeste del Risco Cortaviento. Nada habita allí; es simplemente un camino a través de las montañas.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["thistlefur village"] = {
			name = "Poblado Piel de Cardo",
			short = "El Poblado Piel de Cardo se encuentra en el centro oeste de Vallefresno, al norte de Astranaar. Es el hogar de la tribu Piel de Cardo, fúrbolgs corrompidos y hostiles que atacan a cualquiera que se acerque.",
			full = "El Poblado Piel de Cardo se encuentra en el centro oeste de Vallefresno, al norte de Astranaar. Es el hogar de la tribu Piel de Cardo, fúrbolgs corrompidos y hostiles que atacan a cualquiera que se acerque. Dos guerreros feroces, Dal Zarpasangrante y Rorgish Jowl, dirigen la tribu y defienden el poblado contra todo el que se aproxime.",
			source = "https://warcraft.wiki.gg/wiki/Thistlefur_Village",
		},
		["warsong labor camp"] = {
			name = "Campo de trabajos forzados Grito de Guerra",
			short = "En el sureste de Vallefresno, al este del Lago Cielo Estrellado, el clan Grito de Guerra mantiene un campo de trabajos forzados donde leñadores y recolectores trabajan bajo vigilancia orca, talando madera para los dominios del clan.",
			full = "En el sureste de Vallefresno, al este del Lago Cielo Estrellado, el clan Grito de Guerra mantiene un campo de trabajos forzados donde leñadores y recolectores trabajan bajo vigilancia orca, talando madera para los dominios del clan.\n\nEl campo se encuentra apartado del grueso de las fuerzas Grito de Guerra, y sus guardias están aislados y sin esperanza de recibir refuerzos.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Labor_Camp",
		},
		["warsong lumber camp"] = {
			name = "Aserradero Grito de Guerra",
			short = "Los bosques de Vallefresno resuenan con hachas en el Aserradero Grito de Guerra, donde el clan Grito de Guerra despoja los árboles antiguos para obtener madera.",
			full = "Los bosques de Vallefresno resuenan con hachas en el Aserradero Grito de Guerra, donde el clan Grito de Guerra despoja los árboles antiguos para obtener madera. El campamento se sostiene sobre una perrera de bestias de guerra y sobre el Fuerte de Kargathia, un bastión levantado para proteger la tala.\n\nEl hambre de madera del clan no ha quedado sin respuesta. Illiyana y sus hermanas se han adentrado en los bosques de aquí y vuelven la magia de la naturaleza contra las trituradoras que roen los troncos, y el terreno entre los troncos apilados se ha convertido en un campo de batalla entre la Alianza y la Horda.\n\nAun así, el campamento sigue cumpliendo su propósito: un flujo constante de madera sale de aquí hacia el Puesto del Hachazo, cuyas murallas y cuya gente dependen de lo que les envía el Aserradero Grito de Guerra.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Lumber_Camp",
		},
		["xavian"] = {
			name = "Xavian",
			short = "Xavian se alza donde antes había un templo de los elfos de la noche, cuyas piedras están ahora entregadas a los sátiros.",
			full = "Xavian se alza donde antes había un templo de los elfos de la noche, cuyas piedras están ahora entregadas a los sátiros. De las tres fortalezas de sátiros de Vallefresno, es aquí donde se concentra el poder: tanto el príncipe Raze como Geltharis tienen su sede entre estas ruinas, y es aquí donde los sátiros han recurrido al aceite Grito de Guerra robado para sus rituales.\n\nEl lugar toma su nombre de Xavius, que hace mucho tiempo ayudó a abrir el camino a la Legión Ardiente a través de un portal extraído del Pozo de la Eternidad en Zin-Azshari. Sargeras, descontento con la lentitud de aquel trabajo, transformó a Xavius en el primero de todos los sátiros. Xavian se encuentra tan cerca de Azshara que el nombre no parece casual.\n\nLas dríades se han enfrentado a Xavian: una de ellas, Anilia, fue encontrada aquí herida de muerte tras buscar una rama de Cenarius que los sátiros se habían llevado, tendida en el suelo entre las ruinas que no pudo despejar.",
			source = "https://warcraft.wiki.gg/wiki/Xavian",
		},
		["zoram strand"] = {
			name = "La Ensenada de Zoram",
			short = "Las olas de la Ensenada de Zoram rompen sobre lo que antes fue una ciudad.",
			full = "Las olas de la Ensenada de Zoram rompen sobre lo que antes fue una ciudad. Antes de que el mundo se desgarrara en el Gran Cataclismo, aquí se alzaba Zoram, un pueblo de los elfos de la noche, y cuando el mar se alzó para reclamar su parte del mundo destrozado, Zoram se hundió con él. Ya no queda nada sobre el agua salvo el nombre.\n\nLo que recorre hoy la ensenada no son elfos, sino nagas. Han tomado la orilla como propia, y los restos esparcidos por la arena, barcos rotos y cuerpos de criaturas marinas varadas, muestran hasta qué punto la costa ha pasado a sus manos. Entre las rocas y las cavidades anegadas cercanas se encuentran las Cavernas de Brazanegra, hundidas en la tierra como Zoram se hundió en el mar.\n\nLa Horda tiene aquí un pequeño punto de apoyo, la Avanzada de Zoram'gar, más por necesidad que por elección, y se ha desgastado combatiendo a los nagas Wrathtail, que le disputan cada palmo de la ensenada. Esos mismos nagas cayeron sobre Talen, lo que dejó a la avanzada con enemigos presionando desde más de una dirección. Es un tramo de costa duro, húmedo y disputado, reclamado por un imperio que se ahogó y ocupado ahora por criaturas nacidas del mar que se lo tragó.",
			source = "https://warcraft.wiki.gg/wiki/Zoram_Strand",
		},
		["zoramgar outpost"] = {
			name = "Avanzada de Zoram'gar",
			short = "La Avanzada de Zoram'gar es un puerto de la Horda a lo largo de la Ensenada de Zoram, en Vallefresno, con sus muelles extendiéndose sobre las aguas de abajo.",
			full = "La Avanzada de Zoram'gar es un puerto de la Horda a lo largo de la Ensenada de Zoram, en Vallefresno, con sus muelles extendiéndose sobre las aguas de abajo.",
			source = "https://warcraft.wiki.gg/wiki/Zoram'gar_Outpost",
		},
	},
	-- Las Mil Agujas: 20 subzones
	[1441] = {
		["camp ethok"] = {
			name = "Campamento E'thok",
			short = "El Campamento E'thok es un campamento de centauros Galak en el noroeste de Las Mil Agujas.",
			full = "El Campamento E'thok es un campamento de centauros Galak en el noroeste de Las Mil Agujas. Sus centauros asaltaron una caravana en la que viajaba el goblin Wizlo Rodabrillante, pero no pudieron robar el artilugio que él más apreciaba, que estaba a salvo colgado del cuello de su feroz pantera mascota.",
			source = "https://warcraft.wiki.gg/wiki/Camp_E'thok",
		},
		["darkcloud pinnacle"] = {
			name = "Cumbre de la Nube Negra",
			short = "La Cumbre de la Nube Negra se alza sobre tres pequeñas mesetas al este del Gran Elevador, con sus cimas unidas por puentes de cuerda tendidos sobre el vacío.",
			full = "La Cumbre de la Nube Negra se alza sobre tres pequeñas mesetas al este del Gran Elevador, con sus cimas unidas por puentes de cuerda tendidos sobre el vacío. Solo dos caminos llevan arriba, ambos bien custodiados: una pendiente natural que cruza una cuarta meseta o un puente que llega desde Zahúrda Rajacieno.\n\nLos tauren Tótem Siniestro ocupan estas alturas, dirigidos por Arnak Tótem Siniestro y Harb Foulmountain. Tras los puentes vigilados, los dos líderes mantienen una correspondencia secreta con algún poder oscuro cuya identidad se desconoce. No se habla abiertamente de lo que pasa entre ellos, pero el cuidado con que se han aislado las mesetas muestra lo celosamente que se guarda ese secreto.",
			source = "https://warcraft.wiki.gg/wiki/Darkcloud_Pinnacle",
		},
		["freewind post"] = {
			name = "Poblado Viento Libre",
			short = "El Poblado Viento Libre se alza en lo alto de una meseta de Las Mil Agujas, fuera del alcance de los centauros que recorren las tierras de abajo.",
			full = "El Poblado Viento Libre se alza en lo alto de una meseta de Las Mil Agujas, fuera del alcance de los centauros que recorren las tierras de abajo. Unos elevadores de madera suben a su gente desde el fondo del cañón, y puentes de cuerda se tienden entre los picos vecinos, subiendo de pico en pico hasta llegar al poblado. Abajo, los centauros Galak lanzan sus partidas de guerra y las arpías vuelan en círculos chillando sobre las llanuras, pero la propia altura es la verdadera defensa del poblado.\n\nEl problema más profundo llegó del noroeste, de la Cumbre de la Nube Negra, donde la tribu Tótem Siniestro ocupaba sus propias alturas. El Poblado Viento Libre desconfió de ellos mucho antes de que estallara la guerra abierta: desaparecían tauren, se veía a agentes de origen desconocido y oscuro visitar la cumbre, y se atribuyeron asesinatos a los Tótem Siniestro. El jefe Arnak Tótem Siniestro cargó con la peor parte de la culpa. Cuando Lakota Son del Viento, del Poblado Viento Libre, rechazó sus insinuaciones, él la hizo raptar por la fuerza, y cuando su hermano acudió a defenderla, los Tótem Siniestro lo mataron.",
			source = "https://warcraft.wiki.gg/wiki/Freewind_Post",
		},
		["great lift"] = {
			name = "El Gran Elevador",
			short = "El Gran Elevador es un ascensor construido por los tauren que lleva a los viajeros entre Los Baldíos y Las Mil Agujas, más abajo. Grish Largo Camino y Valiente Cuerno de Luna lo vigilan en nombre de la Horda.",
			full = "El Gran Elevador es un ascensor construido por los tauren que lleva a los viajeros entre Los Baldíos y Las Mil Agujas, más abajo. Grish Largo Camino y Valiente Cuerno de Luna lo vigilan en nombre de la Horda.",
			source = "https://warcraft.wiki.gg/wiki/Great_Lift",
		},
		["highperch"] = {
			name = "Nido Alto",
			short = "Nido Alto se alza sobre Las Mil Agujas, hogar de dracoleones y de sus nidos. Entre los riscos está atrapado el tauren Pao'ka Monte Presto, con la esperanza de escabullirse entre los dracoleones y volver a casa.",
			full = "Nido Alto se alza sobre Las Mil Agujas, hogar de dracoleones y de sus nidos. Entre los riscos está atrapado el tauren Pao'ka Monte Presto, con la esperanza de escabullirse entre los dracoleones y volver a casa.",
			source = "https://warcraft.wiki.gg/wiki/Highperch",
		},
		["ironstone camp"] = {
			name = "Campamento Roca de Hierro",
			short = "El Campamento Roca de Hierro se encuentra al borde del Desierto de Sal.",
			full = "El Campamento Roca de Hierro se encuentra al borde del Desierto de Sal.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Camp",
		},
		["mirage raceway"] = {
			name = "Circuito del Espejismo",
			short = "Un goblin llamado Pozzik y un gnomo llamado Fizzle Pernolatón creían cada uno que su pueblo tenía a los ingenieros más ingeniosos, y ninguno quería dar su brazo a torcer.",
			full = "Un goblin llamado Pozzik y un gnomo llamado Fizzle Pernolatón creían cada uno que su pueblo tenía a los ingenieros más ingeniosos, y ninguno quería dar su brazo a torcer. Así que lo resolvieron como lo hacen los inventores: construyeron una pista y construyeron coches cohete para correr en ella.\n\nLa rivalidad atrae multitudes mucho más allá de ellos dos. Tanto la Horda como la Alianza vienen a animar a sus favoritos mientras los coches de arrancones gnomos y goblins corren a diario, y después cada equipo se apresura a reconstruir sus motores con alguna nueva ventaja. La verdadera competencia es siempre la misma: qué raza construye la mejor máquina, y nunca se resuelve.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Raceway",
		},
		["razorfen downs"] = {
			name = "Zahúrda Rajacieno",
			short = "En lo profundo de los zarzales de Las Mil Agujas se encuentra un laberinto de espinas y huesos cuya entrada, según se dice, tiene la forma de las propias fauces de Agamaggan: una abertura arqueada en la cúpula exterior tan oculta que solo quienes ya conocen su forma pueden encontrarla.",
			full = "En lo profundo de los zarzales de Las Mil Agujas se encuentra un laberinto de espinas y huesos cuya entrada, según se dice, tiene la forma de las propias fauces de Agamaggan: una abertura arqueada en la cúpula exterior tan oculta que solo quienes ya conocen su forma pueden encontrarla. Es la Zahúrda Rajacieno, cementerio ancestral y capital tradicional de los jabaespines, hecha con las mismas vides poderosas que el Horado Rajacieno. Charlga Filonavaja dio forma a la mayor parte de la gran cúpula de espinas que la cubre.\n\nDurante generaciones, la Zahúrda fue un lugar de los muertos jabaespines, cuidado por los sumos sacerdotes de la tribu Caramuerte. Pero después de la Tercera Guerra, el exánime Amnennar el Gélido lanzó a sus agentes contra los jabaespines y se apoderó de su ciudad sagrada, convirtiéndola en un bastión de la Plaga. Los jabaespines lucharon con encono para recuperar lo que era suyo antes de que la peste de Amnennar pudiera extenderse más por Los Baldíos, y en esa lucha los vivos fueron arrastrados y enjaulados entre las espinas junto a los muertos.\n\nAmnennar sigue dentro del laberinto, gobernando a los jabaespines que ha sometido a su voluntad, y su dominio sobre la Zahúrda sigue intacto.",
			source = "https://warcraft.wiki.gg/wiki/Razorfen_Downs",
		},
		["roguefeather den"] = {
			name = "Guarida Malapluma",
			short = "En una pequeña caverna del centro sur de Las Mil Agujas, las arpías de la Guarida Malapluma han hecho su nido.",
			full = "En una pequeña caverna del centro sur de Las Mil Agujas, las arpías de la Guarida Malapluma han hecho su nido. Chillan a cualquiera que se acerque, y al fondo de la guarida acumulan los víveres que han reunido, protegiendo las provisiones con la misma ferocidad con que protegen a sus crías.",
			source = "https://warcraft.wiki.gg/wiki/Roguefeather_Den",
		},
		["rustmaul dig site"] = {
			name = "Excavación Oximelena",
			short = "La Excavación Oximelena se encuentra en el Desierto de Sal, con sus zanjas a medio trabajar. La Liga de Expedicionarios había venido aquí para desenterrar unas antiguas ruinas, y trabajaba la tierra a la sombra de una cueva que albergaba un nido de silítidos.",
			full = "La Excavación Oximelena se encuentra en el Desierto de Sal, con sus zanjas a medio trabajar. La Liga de Expedicionarios había venido aquí para desenterrar unas antiguas ruinas, y trabajaba la tierra a la sombra de una cueva que albergaba un nido de silítidos.\n\nLa excavación se detuvo antes de terminar. Las zanjas siguen abiertas y vacías, las herramientas de los enanos abandonadas donde las dejaron, y la cueva bajo la excavación sigue siendo el hogar de los silítidos que todavía habitan allí.",
			source = "https://warcraft.wiki.gg/wiki/Rustmaul_Dig_Site",
		},
		["screeching canyon"] = {
			name = "Cañón del Chirrido",
			short = "El Cañón del Chirrido atraviesa el sur de Las Mil Agujas, y sus paredes resuenan con los gritos de las arpías chillonas que lo infestan.",
			full = "El Cañón del Chirrido atraviesa el sur de Las Mil Agujas, y sus paredes resuenan con los gritos de las arpías chillonas que lo infestan. Al fondo del cañón se encuentra la Guarida Malapluma, el bastión de las arpías.",
			source = "https://warcraft.wiki.gg/wiki/Screeching_Canyon",
		},
		["shimmering flats"] = {
			name = "El Desierto de Sal",
			short = "El Desierto de Sal se encuentra en el extremo sureste de Las Mil Agujas, donde la tierra se extiende llana y desnuda hasta la frontera con Tanaris.",
			full = "El Desierto de Sal se encuentra en el extremo sureste de Las Mil Agujas, donde la tierra se extiende llana y desnuda hasta la frontera con Tanaris. Aquí no crece nada. El suelo es sal endurecida por el sol, hogar solo de basiliscos, escórpidos, tortugas y buitres. Antaño esto era el fondo de un lago: el casco destrozado de un velero todavía está medio enterrado en el norte de la llanura, un barco varado lejos de cualquier agua, prueba de lo que fue este lugar antes de secarse hasta quedar en sal y tierra agrietada.\n\nEsa llanura atrajo a goblins y gnomos desde los extremos opuestos de su larga rivalidad. Levantaron aquí el Circuito del Espejismo y compitieron por construir máquinas más rápidas que las del otro. Los artefactos rara vez aguantaban. Los cráteres salpican la llanura allí donde los motores fallaron, y los restos de corredores fracasados yacen esparcidos por la sal, abandonados a cocerse donde cayeron.",
			source = "https://warcraft.wiki.gg/wiki/Shimmering_Flats",
		},
		["splithoof crag"] = {
			name = "Risco Pezuña Quebrada",
			short = "El Risco Pezuña Quebrada se alza contra la pared norte de Las Mil Agujas, al este de la Cumbre de la Nube Negra, y es el hogar de los centauros Galak.",
			full = "El Risco Pezuña Quebrada se alza contra la pared norte de Las Mil Agujas, al este de la Cumbre de la Nube Negra, y es el hogar de los centauros Galak. En su centro se encuentra el Campamento Pezuña Quebrada, una caverna en la ladera de la montaña donde los Galak guardan la Pezuña Partida, un antiguo artefacto protegido por el Brasero Antiguo y su llama sacra.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Crag",
		},
		["splithoof hold"] = {
			name = "Campamento Pezuña Quebrada",
			short = "Los centauros Galak convirtieron el Campamento Pezuña Quebrada en su bastión, en las cuevas del Risco Pezuña Quebrada. En su interior arde la llama sacra sobre el Brasero Antiguo, un fuego que, según se dice, resiste incluso bajo el agua.",
			full = "Los centauros Galak convirtieron el Campamento Pezuña Quebrada en su bastión, en las cuevas del Risco Pezuña Quebrada. En su interior arde la llama sacra sobre el Brasero Antiguo, un fuego que, según se dice, resiste incluso bajo el agua.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Hold",
		},
		["tahonda ruins"] = {
			name = "Ruinas de Tahonda",
			short = "Donde ahora se extiende el Desierto de Sal se alzaba en otro tiempo una aldea tauren, que cayó en ruinas hace mucho y fue engullida por la arena. Ahora los basiliscos piedrasal anidan entre las piedras, y algunos dicen que fueron ellos quienes expulsaron a los tauren.",
			full = "Donde ahora se extiende el Desierto de Sal se alzaba en otro tiempo una aldea tauren, que cayó en ruinas hace mucho y fue engullida por la arena. Ahora los basiliscos piedrasal anidan entre las piedras, y algunos dicen que fueron ellos quienes expulsaron a los tauren.\n\nQueda una pista: en la pared de cuero de un edificio, dos series de tres desgarros paralelos, la marca de unas garras, no del viento ni del tiempo. Algo vino a por esa aldea con un propósito.\n\nNo sobrevive ningún nombre. Solo quedan las ruinas, cerca del sendero de montaña que lleva a Tanaris.",
			source = "https://warcraft.wiki.gg/wiki/Tahonda_Ruins",
		},
		["weathered nook"] = {
			name = "El Hueco Perdido",
			short = "La pared norte de Las Mil Agujas oculta una pequeña cueva conocida como el Recoveco Erosionado, fácil de pasar por alto a menos que uno sepa buscarla.",
			full = "La pared norte de Las Mil Agujas oculta una pequeña cueva conocida como el Recoveco Erosionado, fácil de pasar por alto a menos que uno sepa buscarla. Aquí Dorn Acechallanos y Prate Vidente de las Nubes establecieron su hogar, resguardados del viento y del polvo del cañón de abajo.",
			source = "https://warcraft.wiki.gg/wiki/Weathered_Nook",
		},
		["weazels crater"] = {
			name = "Cráter de la Comadreja",
			short = "Una gran cicatriz se abre en el norte del Desierto de Sal, lo bastante profunda como para tragarse la luz al mediodía. Nadie sabe cómo se formó, aunque su nombre sugiere a algún personaje llamado Comadreja, ya fuera quien lo encontró o quien lo hizo.",
			full = "Una gran cicatriz se abre en el norte del Desierto de Sal, lo bastante profunda como para tragarse la luz al mediodía. Nadie sabe cómo se formó, aunque su nombre sugiere a algún personaje llamado Comadreja, ya fuera quien lo encontró o quien lo hizo. Los escombros dispersos y los cráteres menores de los alrededores sugieren algún invento goblin o gnomo que salió mal, algún artefacto llevado demasiado lejos.\n\nDesde entonces, los basiliscos piedrasal han reclamado el pozo como propio.",
			source = "https://warcraft.wiki.gg/wiki/Weazel's_Crater",
		},
		["whitereach post"] = {
			name = "Campamento del Tramo Blanco",
			short = "El Campamento del Tramo Blanco es un pequeño campamento de la Horda junto al camino, cerca del Campamento E'thok, en Las Mil Agujas.",
			full = "El Campamento del Tramo Blanco es un pequeño campamento de la Horda junto al camino, cerca del Campamento E'thok, en Las Mil Agujas.",
			source = "https://warcraft.wiki.gg/wiki/Whitereach_Post",
		},
		["windbreak canyon"] = {
			name = "Cañón Rompevientos",
			short = "El Cañón Rompevientos se encuentra entre el Poblado Viento Libre y el Desierto de Sal, con sus paredes llenas de nidos. Las serpientes aladas reclaman el lugar como suyo y se elevan en las corrientes que dan nombre al cañón.",
			full = "El Cañón Rompevientos se encuentra entre el Poblado Viento Libre y el Desierto de Sal, con sus paredes llenas de nidos. Las serpientes aladas reclaman el lugar como suyo y se elevan en las corrientes que dan nombre al cañón. Un sendero lleva desde aquí hasta el Recoveco Erosionado.",
			source = "https://warcraft.wiki.gg/wiki/Windbreak_Canyon",
		},
	},
	-- Sierra Espolón: 18 subzones
	[1442] = {
		["blackwolf river"] = {
			name = "Río Lobonegro",
			short = "El Río Lobonegro fluye desde el Lago del Peñasco a través del Risco Cortaviento, en la Sierra Espolón. Sus aguas están inmundas, envenenadas por la deforestación del valle a manos de Ventura y Cía.",
			full = "El Río Lobonegro fluye desde el Lago del Peñasco a través del Risco Cortaviento, en la Sierra Espolón. Sus aguas están inmundas, envenenadas por la deforestación del valle a manos de Ventura y Cía.",
			source = "https://warcraft.wiki.gg/wiki/Blackwolf_River",
		},
		["boulderslide cavern"] = {
			name = "Cueva del Alud",
			short = "Al final del Barranco del Alud, la Cueva del Alud alberga el nido de los kóbolds del Alud. Extraen un raro cristal morado llamado resonita, tocado por la magia terránea, y protegen cada veta con su vida.",
			full = "Al final del Barranco del Alud, la Cueva del Alud alberga el nido de los kóbolds del Alud. Extraen un raro cristal morado llamado resonita, tocado por la magia terránea, y protegen cada veta con su vida.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Cavern",
		},
		["boulderslide ravine"] = {
			name = "Barranco del Alud",
			short = "El Barranco del Alud se extiende tranquilo a lo largo de la Senda de las Tejedoras, ajeno a las guerras que agitan las tierras que lo rodean. Los carneros avanzan con cuidado por sus laderas, y los tronadores de los riscos vuelan en círculos por encima.",
			full = "El Barranco del Alud se extiende tranquilo a lo largo de la Senda de las Tejedoras, ajeno a las guerras que agitan las tierras que lo rodean. Los carneros avanzan con cuidado por sus laderas, y los tronadores de los riscos vuelan en círculos por encima.\n\nFrente a la caverna del barranco se alza una cueva abandonada, con sus barriles todavía apilados y sus toscas antorchas aún en pie, aunque ya no queda nadie para encenderlas. En sus paredes perdura un arte tribal, trazado en un estilo que parece obra tauren.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Ravine",
		},
		["camp aparaje"] = {
			name = "Campamento Aparaje",
			short = "El Campamento Aparaje era una aldea tauren en el este de la Sierra Espolón, atacada por las fuerzas Tótem Siniestro del Poblado Tótem Siniestro al mando de Grundig Nube Negra.",
			full = "El Campamento Aparaje era una aldea tauren en el este de la Sierra Espolón, atacada por las fuerzas Tótem Siniestro del Poblado Tótem Siniestro al mando de Grundig Nube Negra. Makaba Pezuña Plana había vivido allí con su hija Kaya antes del ataque.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Aparaje",
		},
		["charred vale"] = {
			name = "La Vega Carbonizada",
			short = "La Vega Carbonizada fue verde en otro tiempo, un valle en el suroeste de Espolón donde las arpías Furia Sangrienta tenían sus nidos y los antárboles recorrían el bosque como sus guardianes.",
			full = "La Vega Carbonizada fue verde en otro tiempo, un valle en el suroeste de Espolón donde las arpías Furia Sangrienta tenían sus nidos y los antárboles recorrían el bosque como sus guardianes.\n\nEntonces llegaron los goblins de Ventura y Cía. para despojar la vega de su madera y su mineral. Los antárboles se alzaron contra ellos e hicieron retroceder a las máquinas, pero los espíritus de la vega no se calmaron. Las excavaciones habían despertado algo bajo la tierra, y el fuego y los elementales brotaron a través del suelo quebrado donde antes se alzaba el bosque. Los antárboles que rechazaron a los goblins no regresaron enteros; lo que fuera con lo que los tocaron las armas de los goblins se quedó en ellos, y ahora se cuentan entre los peligros de la vega y no entre sus guardianes.\n\nLo que queda es un valle de llamas y lava, con árboles negros alzándose entre cenizas donde antes había árboles verdes. Los druidas del Refugio Roca del Sol han asumido la labor que antes hacían los antárboles, animando a brotar nueva vegetación de la tierra quemada con la esperanza de que la vega vuelva a ser un bosque y no una herida en las montañas.",
			source = "https://warcraft.wiki.gg/wiki/Charred_Vale",
		},
		["cragpool lake"] = {
			name = "Lago del Peñasco",
			short = "El Lago del Peñasco se encuentra bajo la gran estructura de madera que Ventura y Cía. levantó sobre el Risco Cortaviento. Gerenzo Silbillave vigila la operación desde este lugar.",
			full = "El Lago del Peñasco se encuentra bajo la gran estructura de madera que Ventura y Cía. levantó sobre el Risco Cortaviento. Gerenzo Silbillave vigila la operación desde este lugar.\n\nEl propio lago está vedado, reclamado por Cragjaw, un pez que se ha vuelto monstruoso en sus aguas quietas.",
			source = "https://warcraft.wiki.gg/wiki/Cragpool_Lake",
		},
		["greatwood vale"] = {
			name = "Vega del Gran Bosque",
			short = "La Vega del Gran Bosque se extiende boscosa en las estribaciones de la Sierra Espolón; se llega a ella por la Senda de las Tejedoras, y Malaka'jin queda al sur.",
			full = "La Vega del Gran Bosque se extiende boscosa en las estribaciones de la Sierra Espolón; se llega a ella por la Senda de las Tejedoras, y Malaka'jin queda al sur.\n\nLa calma de la vega se rompió cuando la tribu Tótem Siniestro, al mando de Grundig Nube Negra, cayó sobre el Campamento Aparaje y masacró a casi todos sus habitantes. Makaba Pezuña Plana sobrevivió y pidió que, en respuesta, se diera caza a los Tótem Siniestro de la vega.",
			source = "https://warcraft.wiki.gg/wiki/Greatwood_Vale",
		},
		["grimtotem post"] = {
			name = "Poblado Tótem Siniestro",
			short = "El Poblado Tótem Siniestro es el punto de apoyo de la tribu en la Sierra Espolón, y sus brutos, rufianes, hechiceros y mercenarios patrullan las laderas que lo rodean.",
			full = "El Poblado Tótem Siniestro es el punto de apoyo de la tribu en la Sierra Espolón, y sus brutos, rufianes, hechiceros y mercenarios patrullan las laderas que lo rodean. Grundig Nube Negra los comanda aquí y defiende el poblado para los propios fines de los Tótem Siniestro.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Post",
		},
		["malakajin"] = {
			name = "Malaka'jin",
			short = "Malaka'jin se encuentra en la Sierra Espolón, al sur del Poblado Tótem Siniestro.",
			full = "Malaka'jin se encuentra en la Sierra Espolón, al sur del Poblado Tótem Siniestro. Es una aldea modesta, hogar de cazadores trols que se ganan la vida vendiendo sus presas a los miembros de la Horda que pasan por allí, un punto de apoyo a la vista del territorio Tótem Siniestro.",
			source = "https://warcraft.wiki.gg/wiki/Malaka'jin",
		},
		["mirkfallon lake"] = {
			name = "Lago Mirkfallon",
			short = "El Lago Mirkfallon se encuentra en el corazón de la Sierra Espolón, una cuenca salvaje llena de dracoleones, lodos y truenagartos que se mueven por sus aguas y sus orillas.",
			full = "El Lago Mirkfallon se encuentra en el corazón de la Sierra Espolón, una cuenca salvaje llena de dracoleones, lodos y truenagartos que se mueven por sus aguas y sus orillas. Una colina se alza en el centro del lago, y sobre ella, en las Alturas Cortaviento, todavía anidan los dracoleones que quedan en la zona.",
			source = "https://warcraft.wiki.gg/wiki/Mirkfallon_Lake",
		},
		["sishir canyon"] = {
			name = "Cañón Sishir",
			short = "El cañón lleva desde el camino principal de la Sierra Espolón hacia las Ruinas de Eldre'thar, pero nadie lo atraviesa con facilidad.",
			full = "El cañón lleva desde el camino principal de la Sierra Espolón hacia las Ruinas de Eldre'thar, pero nadie lo atraviesa con facilidad. El Cañón Sishir está entregado por completo a las arañas Musgondo, una camada monstruosa cuyos huevos y telarañas ahogan cada saliente y cada hueco de la piedra. En lo más profundo, la mayor de ellas, Besseleth, aguarda entre los suyos.",
			source = "https://warcraft.wiki.gg/wiki/Sishir_Canyon",
		},
		["stonetalon peak"] = {
			name = "Cima del Espolón",
			short = "La Cima del Espolón se encuentra en un valle verde en el extremo noroeste de las montañas que comparten su nombre, cuidada por los druidas del cercano Cubil del Espolón.",
			full = "La Cima del Espolón se encuentra en un valle verde en el extremo noroeste de las montañas que comparten su nombre, cuidada por los druidas del cercano Cubil del Espolón. La montaña se considera sagrada, y la magia corre densa por su piedra.\n\nDurante la Tercera Guerra, Jaina Valiente y su expedición llegaron aquí y establecieron una base cerca de la entrada a las cavernas bajo la cima. Thrall y su Horda llegaron después, en busca del Oráculo.\n\nDesde entonces se ha convertido en un centro para los elfos de la noche y la Alianza, y sus druidas vigilan el valle.",
			source = "https://warcraft.wiki.gg/wiki/Stonetalon_Peak",
		},
		["sun rock retreat"] = {
			name = "Refugio Roca del Sol",
			short = "El Refugio Roca del Sol se oculta entre los picos al sur del Lago Mirkfallon, en la Sierra Espolón, un lugar donde el mundo de los espíritus se aprieta contra el de los vivos.",
			full = "El Refugio Roca del Sol se oculta entre los picos al sur del Lago Mirkfallon, en la Sierra Espolón, un lugar donde el mundo de los espíritus se aprieta contra el de los vivos. Mucho antes de que la Horda alzara aquí sus estandartes, los tauren peregrinaban a esta piedra para realizar sus ritos de paso al reino de los espíritus. Se dice que An'she, el sol, besó en otro tiempo la montaña donde hoy se alza el refugio.\n\nAhora orcos y tauren ocupan juntos el Refugio Roca del Sol, la mayor concentración de fuerzas de la Horda en estas montañas, un centro de comercio y trabajo que repara lo que Ventura y Cía. y otras fuerzas malignas le han arrancado a la tierra.",
			source = "https://warcraft.wiki.gg/wiki/Sun_Rock_Retreat",
		},
		["talon den"] = {
			name = "El Cubil del Espolón",
			short = "En lo alto de la Cima del Espolón, la tierra se abre al Cubil del Espolón, un túmulo que es hogar de las dríades Mirkfallon y de los guardianes que comparten su nombre, vigilado por los cuidadores cenarion elfos de la noche.",
			full = "En lo alto de la Cima del Espolón, la tierra se abre al Cubil del Espolón, un túmulo que es hogar de las dríades Mirkfallon y de los guardianes que comparten su nombre, vigilado por los cuidadores cenarion elfos de la noche.",
			source = "https://warcraft.wiki.gg/wiki/Talon_Den",
		},
		["talondeep path"] = {
			name = "El Paso del Espolón",
			short = "El Paso del Espolón es un túnel sinuoso que une Vallefresno con la Sierra Espolón, con un recorrido irregular lleno de pequeños callejones sin salida y extraños huecos desgastados en la roca.",
			full = "El Paso del Espolón es un túnel sinuoso que une Vallefresno con la Sierra Espolón, con un recorrido irregular lleno de pequeños callejones sin salida y extraños huecos desgastados en la roca. Por un extremo se abre al oeste del Lago Mystral, y por el otro en el noroeste del Risco Cortaviento. Nada habita allí; es simplemente un camino a través de las montañas.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["webwinder path"] = {
			name = "Senda de las Tejedoras",
			short = "La Senda de las Tejedoras discurre entre Malaka'jin y el Lago Mirkfallon, a través de una tierra que se ha hundido a ambos lados.",
			full = "La Senda de las Tejedoras discurre entre Malaka'jin y el Lago Mirkfallon, a través de una tierra que se ha hundido a ambos lados. Al oeste de Malaka'jin, la Horda construyó una barricada en el camino para impedir que la Alianza avanzara más hacia el este.",
			source = "https://warcraft.wiki.gg/wiki/Webwinder_Path",
		},
		["windshear crag"] = {
			name = "Risco Cortaviento",
			short = "El Risco Cortaviento fue en otro tiempo un bosque primario, espeso y verde, en su valle entre la Sierra Espolón. Ahora ya no lo es. Lo que hay aquí son tocones, agua inmunda y maquinaria que nunca deja del todo de chirriar.",
			full = "El Risco Cortaviento fue en otro tiempo un bosque primario, espeso y verde, en su valle entre la Sierra Espolón. Ahora ya no lo es. Lo que hay aquí son tocones, agua inmunda y maquinaria que nunca deja del todo de chirriar.\n\nLa ruina tiene un nombre detrás: Gerenzo Silbillave, un gnomo leproso al que se le encomendó dirigir toda la expedición maderera bajo el estandarte de Ventura y Cía. Construyó la Súper Segadora 6000, una máquina capaz de reducir a serrín los árboles más antiguos del risco, y observa su obra desde una plataforma levantada sobre el Lago del Peñasco, señor de todo lo que la máquina ha despejado. Su dominio del lugar lo ha vuelto prescindible para sus superiores: el director Riddlevox, del Gremio de Manitas de Villabajo, lo quiere muerto, y el goblin Ziz Fizziks acecha en el risco, esperando ver cumplida la orden.\n\nEn la esquina sureste del risco, los kóbolds Cortaviento se han apoderado de la Mina Cortaviento y excavan en busca de mena de hierro ahumado.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Crag",
		},
		["windshear mine"] = {
			name = "Mina Cortaviento",
			short = "La Mina Cortaviento se encuentra al final del Río Lobonegro, dentro del Risco Cortaviento. Ventura y Cía. explotaba aquí sus vetas de estaño y ponía a los kóbolds a excavar.",
			full = "La Mina Cortaviento se encuentra al final del Río Lobonegro, dentro del Risco Cortaviento. Ventura y Cía. explotaba aquí sus vetas de estaño y ponía a los kóbolds a excavar.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Mine",
		},
	},
	-- Desolace: 20 subzones
	[1443] = {
		["bolgans hole"] = {
			name = "Cuenca de Bolgan",
			short = "En el Poblado Gelkis, la cueva llamada Cuenca de Bolgan da refugio a los miembros más destacados del clan, entre ellos su kan, Shaka.",
			full = "En el Poblado Gelkis, la cueva llamada Cuenca de Bolgan da refugio a los miembros más destacados del clan, entre ellos su kan, Shaka.\n\nEn lo más profundo crecen cristales azules, las lágrimas de Theradras, que acumulan los chamanes Gelkis, convencidos de que las piedras llevan consigo la protección de la princesa.",
			source = "https://warcraft.wiki.gg/wiki/Bolgan's_Hole",
		},
		["ethel rethor"] = {
			name = "Ethel Rethor",
			short = "Frente a la costa noroeste de Desolace, el mar se ha tragado casi todo Ethel Rethor. Solo una torre solitaria emerge sobre la superficie, unida a la orilla por un estrecho puente que lleva a una puerta que permanece cerrada.",
			full = "Frente a la costa noroeste de Desolace, el mar se ha tragado casi todo Ethel Rethor. Solo una torre solitaria emerge sobre la superficie, unida a la orilla por un estrecho puente que lleva a una puerta que permanece cerrada. Los nagas han tomado la ruina anegada como propia.",
			source = "https://warcraft.wiki.gg/wiki/Ethel_Rethor",
		},
		["gelkis village"] = {
			name = "Poblado Gelkis",
			short = "El Poblado Gelkis rodea un amplio barranco en el suroeste de Desolace y es la sede del clan Gelkis.",
			full = "El Poblado Gelkis rodea un amplio barranco en el suroeste de Desolace y es la sede del clan Gelkis. Unos puentes tendidos entre los acantilados y los riscos del barranco bajan hasta la Cuenca de Bolgan, una cueva excavada en la pared sur de la montaña, donde reside el kan de los Gelkis.\n\nEl poblado está pegado al principal camino de norte a sur de Desolace, tan cerca que el propio camino se ha vuelto peligroso para quienes lo recorren. Los Gelkis han levantado nuevas chozas en el lado este del camino que lleva a Feralas, a lo largo del lago, extendiéndose más allá del barranco que les dio refugio al principio.",
			source = "https://warcraft.wiki.gg/wiki/Gelkis_Village",
		},
		["ghost walker post"] = {
			name = "Campamento del Espíritu Errante",
			short = "El Campamento del Espíritu Errante se alza junto al Cementerio de Kodos, en el centro de Desolace, y los muertos de allí marcan todo en el lugar.",
			full = "El Campamento del Espíritu Errante se alza junto al Cementerio de Kodos, en el centro de Desolace, y los muertos de allí marcan todo en el lugar. Los chamanes tauren vigilan los huesos, ayudan a los espíritus de los kodos caídos a pasar a sus siguientes vidas y, cuando es necesario, hablan con quienes ya se han ido. Gurda Ferocrín los dirige, y defiende este puesto expuesto con poco más que lo imprescindible para sostenerlo.\n\nA diferencia de la Aldea Cazasombras, segura en otro lugar de la región, el Campamento del Espíritu Errante no goza de esa seguridad. Es un campamento avanzado construido para la guerra, no para la comodidad, sin posada y sin lugar donde descansar. Existe con un único propósito: llevar la lucha de la Horda contra los cultistas del Filo Ardiente y las tribus de centauros que recorren Desolace.",
			source = "https://warcraft.wiki.gg/wiki/Ghost_Walker_Post",
		},
		["kodo graveyard"] = {
			name = "Cementerio de Kodos",
			short = "Los kodos de Desolace vienen aquí a morir, y sus huesos se amontonan blanqueados sobre la tierra agrietada. Si alguien los perturba, los muertos no permanecen en silencio: apariciones de kodos surgen del suelo para proteger lo que queda de los suyos.",
			full = "Los kodos de Desolace vienen aquí a morir, y sus huesos se amontonan blanqueados sobre la tierra agrietada. Si alguien los perturba, los muertos no permanecen en silencio: apariciones de kodos surgen del suelo para proteger lo que queda de los suyos.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Graveyard",
		},
		["kolkar village"] = {
			name = "Poblado Kolkar",
			short = "La aldea del margen oriental de Desolace es la sede del clan Kolkar, el más prolífico de los clanes de centauros de Kalimdor, con puestos tan lejanos como Los Baldíos y Durotar.",
			full = "La aldea del margen oriental de Desolace es la sede del clan Kolkar, el más prolífico de los clanes de centauros de Kalimdor, con puestos tan lejanos como Los Baldíos y Durotar. Los rivales Magram los presionan constantemente, pues la enemistad entre los clanes nunca descansa.",
			source = "https://warcraft.wiki.gg/wiki/Kolkar_Village",
		},
		["kormeks hut"] = {
			name = "Cabaña de Kormek",
			short = "La cabaña se alza desgastada en el centro norte de Desolace. En su interior vive Willow, miembro del Martillo Crepuscular, que cuida el lugar con una calidez inesperada en alguien de ese culto.",
			full = "La cabaña se alza desgastada en el centro norte de Desolace. En su interior vive Willow, miembro del Martillo Crepuscular, que cuida el lugar con una calidez inesperada en alguien de ese culto. Afuera, en un corral sembrado de huesos de kodo, Bibbly F'utzhebilla baila entre los restos, encantado con el beneficio que esos huesos podrían reportarle.",
			source = "https://warcraft.wiki.gg/wiki/Kormek's_Hut",
		},
		["magram village"] = {
			name = "Poblado Magram",
			short = "El Poblado Magram surge de un conjunto de islas entre charcas amarillas y contaminadas en el sureste de Desolace, con sus chozas unidas por toscos puentes tendidos sobre el agua.",
			full = "El Poblado Magram surge de un conjunto de islas entre charcas amarillas y contaminadas en el sureste de Desolace, con sus chozas unidas por toscos puentes tendidos sobre el agua. Aquí tiene su hogar el clan Magram, uno de los pueblos de centauros enzarzados en guerra con el clan Gelkis por el dominio de estas tierras yermas.",
			source = "https://warcraft.wiki.gg/wiki/Magram_Village",
		},
		["mannoroc coven"] = {
			name = "Aquelarre Mannoroc",
			short = "Entre las ruinas de los elfos de la noche que yacen destrozadas por Desolace, un lugar lleva un nombre que ningún viajero pronuncia a la ligera.",
			full = "Entre las ruinas de los elfos de la noche que yacen destrozadas por Desolace, un lugar lleva un nombre que ningún viajero pronuncia a la ligera. El Aquelarre Mannoroc toma su nombre de Mannoroth, el temido señor del foso, y la tierra de aquí lo recuerda. La tierra ya estaba muerta mucho antes de que llegaran los demonios, pero la magia vil la ha arrasado aún más, hasta que el propio aire está cargado de corrupción y un manto mortal cae sobre cualquiera que se adentre en él.\n\nLos cultistas del Filo Ardiente abrieron el camino: desgarraron varios portales en el mundo para invocar a través de ellos a los sirvientes de la Legión Ardiente, infernales, súcubos, canes manáfagos y guardias viles que ahora merodean por las ruinas. Lord Azrethoc comanda a estos demonios, mientras que el brujo orco Jugkar Grim'rod se alza entre ellos como la voz del propio Filo Ardiente en el aquelarre. Juntos han formado la mayor concentración de demonios de todo el centro de Kalimdor, prueba de que el plan de los cultistas ha tenido un éxito que va mucho más allá de una simple advertencia.",
			source = "https://warcraft.wiki.gg/wiki/Mannoroc_Coven",
		},
		["nijels point"] = {
			name = "Punta de Nijel",
			short = "La Punta de Nijel vigila las montañas del norte de Desolace, un puesto en manos de la Alianza y del Círculo Cenarion.",
			full = "La Punta de Nijel vigila las montañas del norte de Desolace, un puesto en manos de la Alianza y del Círculo Cenarion.\n\nEl guardián Marandis llegó aquí con sus hermanas dríades y utilizó el puesto como base mientras perseguían a la princesa Theradras. Su propósito era recuperar el cuerpo de Zaetar de las profundidades de Maraudon y llevarlo de vuelta a casa, a la Sierra Espolón.\n\nAl mismo tiempo, el ejército de Ventormenta destacó aquí a la Guardia de la Punta de Nijel bajo el mando del capitán Pentigast, frente a la amenaza de los clanes de centauros que dominaban la región. Pentigast observaba la rivalidad entre los Gelkis y los Magram con la cautela de un soldado, convencido de que el clan que se impusiera se volvería lo bastante audaz como para atacar los dominios cercanos de la Alianza, y por eso buscaba saber cómo derrotar a los centauros enfrentando a un clan contra el otro.",
			source = "https://warcraft.wiki.gg/wiki/Nijel's_Point",
		},
		["ranazjar isle"] = {
			name = "Isla Ranazjar",
			short = "La Isla Ranazjar es una pequeña isla rocosa frente a la costa noroeste de Desolace, hogar de los serpentinos nagas.",
			full = "La Isla Ranazjar es una pequeña isla rocosa frente a la costa noroeste de Desolace, hogar de los serpentinos nagas. Entre las piedras se alzan ruinas de los elfos de la noche, parte de la misma ciudad antigua que Ethel Rethor, ahora en silencio sobre los nagas que habitan allí.",
			source = "https://warcraft.wiki.gg/wiki/Ranazjar_Isle",
		},
		["sargeron"] = {
			name = "Sargeron",
			short = "La ciudad que se alzaba aquí llevó en otro tiempo un nombre de los elfos de la noche, perdido desde que la Guerra de los Ancestros desgarró el mundo.",
			full = "La ciudad que se alzaba aquí llevó en otro tiempo un nombre de los elfos de la noche, perdido desde que la Guerra de los Ancestros desgarró el mundo. Lo que queda es una ruina, a la que ahora los sátiros Hatefury que habitan allí llaman Sargeron, en honor a su amo demoníaco, Sargeras.\n\nLas ruinas albergaron en otro tiempo tres lugares sagrados de Elune: su catedral, su templo y su santuario. Las reliquias de aquella fe más antigua todavía yacen entre las piedras: el Brasero de Elune, su Doncella, su Copa y la Antigua Piedra Rúnica del Vórtice.",
			source = "https://warcraft.wiki.gg/wiki/Sargeron",
		},
		["sartheris strand"] = {
			name = "Playa de Sar'theris",
			short = "La costa donde Desolace se une al mar no se parece a la tierra que hay detrás. Mientras el interior es gris y desolado, la Playa de Sar'theris es soleada y su hierba es verde.",
			full = "La costa donde Desolace se une al mar no se parece a la tierra que hay detrás. Mientras el interior es gris y desolado, la Playa de Sar'theris es soleada y su hierba es verde. Los gigantes marinos vadean sus aguas poco profundas, los nagas se enroscan en sus aguas y los makrura corretean por sus arenas.\n\nBajo Ethel Rethor, una pequeña barca yace destrozada en la playa, con la madera astillada y sin rastro de la tripulación que llevaba.",
			source = "https://warcraft.wiki.gg/wiki/Sar'theris_Strand",
		},
		["scrabblescrews camp"] = {
			name = "Campamento de los Mezclatornillos",
			short = "Cerca del Cementerio de Kodos, en Desolace, se alza un pequeño campamento goblin.",
			full = "Cerca del Cementerio de Kodos, en Desolace, se alza un pequeño campamento goblin. Pertenece a Smeed Mezclatornillos, un goblin emprendedor que mantiene una caravana de kodos y conduce a las grandes bestias a través de los páramos en busca de cualquier beneficio que la tierra permita.",
			source = "https://warcraft.wiki.gg/wiki/Scrabblescrew's_Camp",
		},
		["shadowbreak ravine"] = {
			name = "Barranco Rompesombras",
			short = "El Barranco Rompesombras se oculta en las montañas al sureste de Shok'Thokar, un pliegue de Desolace con el que pocos se toparían por casualidad.",
			full = "El Barranco Rompesombras se oculta en las montañas al sureste de Shok'Thokar, un pliegue de Desolace con el que pocos se toparían por casualidad. Entre sus rocas se alzan hongos gigantes, y en su centro hay un círculo de invocación atado con enormes cadenas, construido por los cultistas del Filo Ardiente que hicieron del barranco su refugio.",
			source = "https://warcraft.wiki.gg/wiki/Shadowbreak_Ravine",
		},
		["shadowprey village"] = {
			name = "Aldea Cazasombras",
			short = "La Aldea Cazasombras se encuentra donde la Playa de Sar'theris se une a la costa sur de Desolace, un asentamiento pesquero de los trols.",
			full = "La Aldea Cazasombras se encuentra donde la Playa de Sar'theris se une a la costa sur de Desolace, un asentamiento pesquero de los trols. Su gente vive del mar, y sus capturas son lo que mantiene alimentado al Campamento del Espíritu Errante, más hacia el interior.",
			source = "https://warcraft.wiki.gg/wiki/Shadowprey_Village",
		},
		["tethris aran"] = {
			name = "Tethris Aran",
			short = "Unas ruinas de los elfos de la noche yacen dispersas en el norte de Desolace, al norte de la Fortaleza del Hacha de Trueno: los restos de un asentamiento que se creía destruido en el Gran Cataclismo.",
			full = "Unas ruinas de los elfos de la noche yacen dispersas en el norte de Desolace, al norte de la Fortaleza del Hacha de Trueno: los restos de un asentamiento que se creía destruido en el Gran Cataclismo. No se ha reconstruido nada. Ahora solo las criaturas salvajes de Desolace se mueven entre las piedras rotas.",
			source = "https://warcraft.wiki.gg/wiki/Tethris_Aran",
		},
		["thunder axe fortress"] = {
			name = "Fortaleza del Hacha de Trueno",
			short = "La Fortaleza del Hacha de Trueno se alza en el noroeste de Desolace, entregada al culto del Filo Ardiente.",
			full = "La Fortaleza del Hacha de Trueno se alza en el noroeste de Desolace, entregada al culto del Filo Ardiente. Tras sus muros, con su bastión, sus barracones, su cueva y sus torres de vigilancia, los cultistas a las órdenes de Kohor trabajan para invocar al demonio Nazargen con toda su fuerza, con cuidado de no llamarlo demasiado pronto, cuando estaría lo bastante débil como para ser destruido.\n\nLa fortaleza albergó en otro tiempo el Cetro de Luz, un artefacto de terrible poder que el Filo Ardiente robó a los nagas. Azore Aldamort, al servicio de El Alba Argenta, se propuso recuperarlo, y con ayuda logró arrebatárselo al culto.\n\nEntre estos muros vivió también Tyranis Malem, un nombre que su propio pueblo pronuncia con desprecio, pues se volvió traidor a ellos y se entregó al estudio de la magia demoníaca, haciendo de la Fortaleza del Hacha de Trueno su refugio para tan oscuras búsquedas.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Axe_Fortress",
		},
		["valley of bones"] = {
			name = "Valle de los Huesos",
			short = "El Valle de los Huesos es un risco en el extremo sur de Desolace, rondado por esqueletos, nigromantes centauros y los fantasmas del clan Magram masacrado.",
			full = "El Valle de los Huesos es un risco en el extremo sur de Desolace, rondado por esqueletos, nigromantes centauros y los fantasmas del clan Magram masacrado. Contra las paredes del acantilado descansan un par de esqueletos enormes, los Goliats Muertos, de origen desconocido.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Bones",
		},
		["valley of spears"] = {
			name = "Valle de las Lanzas",
			short = "El Valle de las Lanzas, en el oeste de Desolace, es el hogar del clan de centauros Maraudine, y a pie solo se llega por estrechos pasos de montaña al sur y al este.",
			full = "El Valle de las Lanzas, en el oeste de Desolace, es el hogar del clan de centauros Maraudine, y a pie solo se llega por estrechos pasos de montaña al sur y al este. En su extremo suroeste se encuentra la entrada a Maraudon. Entre los centauros, retenida como prisionera, está Melizza Zumbala.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Spears",
		},
	},
	-- Feralas: 28 subzones
	[1444] = {
		["camp mojache"] = {
			name = "Campamento Mojache",
			short = "El Campamento Mojache se encuentra donde un arroyo veloz desemboca en el Lago Ventosalvaje.",
			full = "El Campamento Mojache se encuentra donde un arroyo veloz desemboca en el Lago Ventosalvaje. Los tauren que ocupan este terreno son conocidos por lo gruesa que tienen la piel y por el valor de sus bravos, que protegen a los viajeros de los peligros de Feralas.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Mojache",
		},
		["dire maul"] = {
			name = "La Masacre",
			short = "Hace doce mil años, una secta secreta de hechiceros elfos de la noche levantó Eldre'Thalas para proteger los secretos arcanos más preciados de la reina Azshara.",
			full = "Hace doce mil años, una secta secreta de hechiceros elfos de la noche levantó Eldre'Thalas para proteger los secretos arcanos más preciados de la reina Azshara. Entre sus Altonato, los arcanistas conocidos como los Shen'dralar vivían con un esplendor discreto, y una de ellos, Millicent Serene, creó el Fruto de la Fertilidad, una enredadera cuya aura de crecimiento y protección permitió florecer a toda la ciudad.\n\nAislados del Pozo de la Eternidad tras el Gran Cataclismo, los Altonato ataron a un demonio, Immol'thar, y obtuvieron su poder de su encarcelamiento. Eso los sostuvo durante miles de años, hasta que el precio de retenerlo se volvió mayor que lo que él les daba. Su líder, el príncipe Tortheldrin, respondió volviéndose contra su propio pueblo y masacrando a muchos para liberar el poder suficiente con el que mantener con vida al resto. Los supervivientes se retiraron a lo más profundo de las ruinas que antes gobernaban y abandonaron el resto de la ciudad a lo que fuera que viniera a habitarla.\n\nLa piedra de Eldre'Thalas sigue en pie, con energía arcana atada en ella mediante un arte que ya nadie recuerda, conservando la forma de una ciudad que se alimentó de su propio pueblo para sobrevivir.",
			source = "https://warcraft.wiki.gg/wiki/Dire_Maul",
		},
		["dream bough"] = {
			name = "Rama Oniria",
			short = "Un gran árbol se alza en una pequeña isla en medio del Lago Jademir, y sus raíces y ramas albergan uno de los portales al Sueño Esmeralda.",
			full = "Un gran árbol se alza en una pequeña isla en medio del Lago Jademir, y sus raíces y ramas albergan uno de los portales al Sueño Esmeralda. El Vuelo Verde lo vigila y protege el umbral contra cualquiera que pretenda alterar el sueño que hay más allá.",
			source = "https://warcraft.wiki.gg/wiki/Dream_Bough",
		},
		["feathermoon stronghold"] = {
			name = "Bastión Plumaluna",
			short = "Frente a la costa occidental de Feralas, en la Isla de Sardor, se alza una fortaleza levantada en el mar por la general Shandris Plumaluna, que durante diez mil años ha estado al lado de Tyrande Susurravientos como su mano derecha entre las centinelas.",
			full = "Frente a la costa occidental de Feralas, en la Isla de Sardor, se alza una fortaleza levantada en el mar por la general Shandris Plumaluna, que durante diez mil años ha estado al lado de Tyrande Susurravientos como su mano derecha entre las centinelas. Dio su nombre al bastión, que aún defiende este tramo de la costa de Kalimdor para los elfos de la noche.\n\nSolo el mar lo une al continente: una travesía en barca desde la Costa Olvidada hasta el muelle de la isla.",
			source = "https://warcraft.wiki.gg/wiki/Feathermoon_Stronghold_(Classic)",
		},
		["feral scar vale"] = {
			name = "Vega Cicatriz Feral",
			short = "En las Altas Tierras Salvajes del oeste de Feralas se encuentra la Vega Cicatriz Feral, reclamada por los yetis Cicatriz Feral, que le dan su nombre.",
			full = "En las Altas Tierras Salvajes del oeste de Feralas se encuentra la Vega Cicatriz Feral, reclamada por los yetis Cicatriz Feral, que le dan su nombre.",
			source = "https://warcraft.wiki.gg/wiki/Feral_Scar_Vale",
		},
		["forgotten coast"] = {
			name = "La Costa Olvidada",
			short = "La Costa Olvidada recorre todo el extremo occidental de Feralas, donde la tierra se une al Mar de la Bruma. Aquí los elementales de agua surgen del oleaje, y los gigantes marinos acechan en la orilla.",
			full = "La Costa Olvidada recorre todo el extremo occidental de Feralas, donde la tierra se une al Mar de la Bruma. Aquí los elementales de agua surgen del oleaje, y los gigantes marinos acechan en la orilla.\n\nUna aldea pesquera de múrlocs se aferra a esta costa. Se sabe que los pájaros bajan en picado y se llevan a los renacuajos, y la aldea ha sufrido incursiones de humanos y de gnolls por turnos. Lo peor de todo son los ogros Gordunni, que la han acosado durante años y se han llevado múrlocs cautivos a las ruinas de La Masacre. Una docena o más han sido capturados así, entre ellos dos llamados Murrl y Murrgly.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Coast",
		},
		["frayfeather highlands"] = {
			name = "Tierras Altas de Plumavieja",
			short = "Las Tierras Altas de Plumavieja pertenecen a los hipogrifos Plumavieja, que anidan en los lugares altos de allí y dan nombre a la tierra.",
			full = "Las Tierras Altas de Plumavieja pertenecen a los hipogrifos Plumavieja, que anidan en los lugares altos de allí y dan nombre a la tierra. Entre los riscos, sus huevos permanecen ocultos en nidos dispersos, protegidos por las bandadas que vuelan en círculos y consideran su hogar estas tierras altas.",
			source = "https://warcraft.wiki.gg/wiki/Frayfeather_Highlands",
		},
		["gordunni outpost"] = {
			name = "Avanzada Gordunni",
			short = "En las montañas al norte del Pabellón de Lariss, el suelo lleva la marca de los Gordunni. Mientras que el resto de Feralas es verde, la avanzada está marchita y parda bajo la presencia de los ogros.",
			full = "En las montañas al norte del Pabellón de Lariss, el suelo lleva la marca de los Gordunni. Mientras que el resto de Feralas es verde, la avanzada está marchita y parda bajo la presencia de los ogros.\n\nDos cuevas marcan las colinas, una pequeña cerca de la entrada y un gran montículo al fondo, ambas en manos de los Gordunni que reclaman este terreno arruinado.",
			source = "https://warcraft.wiki.gg/wiki/Gordunni_Outpost",
		},
		["grimtotem compound"] = {
			name = "Dominios Tótem Siniestro",
			short = "Los Dominios Tótem Siniestro, al este de La Masacre, son un hogar que los tauren Tótem Siniestro se han construido para sí. En su sección sur se alza una gran jaula que retiene a unos dardos de duende cautivos.",
			full = "Los Dominios Tótem Siniestro, al este de La Masacre, son un hogar que los tauren Tótem Siniestro se han construido para sí. En su sección sur se alza una gran jaula que retiene a unos dardos de duende cautivos. Al este de la sección norte, los gnolls han levantado sus propios campamentos.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Compound",
		},
		["high wilderness"] = {
			name = "Altas Tierras Salvajes",
			short = "Las Altas Tierras Salvajes se extienden por el oeste de Feralas, desde la Costa Olvidada hasta el Río Verdantis.",
			full = "Las Altas Tierras Salvajes se extienden por el oeste de Feralas, desde la Costa Olvidada hasta el Río Verdantis. Osos, lobos e hipogrifos recorren sus árboles antiguos, los antárboles se alzan entre las arboledas más profundas, y yetis y ogros reclaman las zonas más salvajes que hay más allá.",
			source = "https://warcraft.wiki.gg/wiki/High_Wilderness",
		},
		["isle of dread"] = {
			name = "Isla del Terror",
			short = "La Isla del Terror se encuentra frente a la costa de Feralas, al sur de la Isla de Sardor, con su valle central cercado por todos lados por acantilados infranqueables, salvo por un único acceso en el sureste.",
			full = "La Isla del Terror se encuentra frente a la costa de Feralas, al sur de la Isla de Sardor, con su valle central cercado por todos lados por acantilados infranqueables, salvo por un único acceso en el sureste. En esa cuenca oculta tienen su hogar los quimerok, bestias tocadas por lo arcano y devoradoras por igual, gobernadas por lord Lakmaeran. Su carne se ha buscado para fines más extraños que la supervivencia: una vez derretida y transformada, se convirtió en una monstruosa ave de quinientas libras que devoró entera el mago gnomo Narain Sabelotodo.\n\nEn el extremo norte de la isla, una cueva se hunde en la roca, distinta de cualquier otra cosa conocida allí, profunda y extraña en su construcción. Un pasaje secreto bajo el agua lleva a una cámara interior que no tiene otro propósito conocido que dar cobijo en sus profundidades a lady Szallah. La cueva y sus nagas están al mando de lord Shalzaru, cuya presencia atrajo la atención del Bastión Plumaluna, receloso de tener a los nagas tan cerca de sus propias costas.",
			source = "https://warcraft.wiki.gg/wiki/Isle_of_Dread",
		},
		["jademir lake"] = {
			name = "Lago Jademir",
			short = "El Lago Jademir, en el norte de Feralas, alberga en su centro una pequeña isla, Rama Oniria. Allí se alza un portal al Sueño Esmeralda, custodiado por Lethlas y varios dracónidos verdes.",
			full = "El Lago Jademir, en el norte de Feralas, alberga en su centro una pequeña isla, Rama Oniria. Allí se alza un portal al Sueño Esmeralda, custodiado por Lethlas y varios dracónidos verdes. Crías de dragón verde infectadas rondan la orilla noroeste del lago.",
			source = "https://warcraft.wiki.gg/wiki/Jademir_Lake",
		},
		["lariss pavilion"] = {
			name = "Pabellón de Lariss",
			short = "El Pabellón de Lariss, de cantería propia de los elfos de la noche, se alza al norte del Campamento Mojache, en Feralas. Sus dríades fueron en otro tiempo pacíficas, pero la Pesadilla Esmeralda las ha corrompido, y ahora atacan a cualquiera que se acerque.",
			full = "El Pabellón de Lariss, de cantería propia de los elfos de la noche, se alza al norte del Campamento Mojache, en Feralas. Sus dríades fueron en otro tiempo pacíficas, pero la Pesadilla Esmeralda las ha corrompido, y ahora atacan a cualquiera que se acerque.\n\nBajo el pabellón hay un camino oculto hacia abajo, conocido por Azj'Tordin, un Altonato que rompió con el príncipe Tortheldrin y huyó de La Masacre por él. Escapó con poco, pues un diablillo llamado Pusillín le robó su libro de conjuros antes de que pudiera desaparecer bajo tierra, y desde entonces no se ha movido de ese pasaje.",
			source = "https://warcraft.wiki.gg/wiki/Lariss_Pavilion",
		},
		["lower wilds"] = {
			name = "Bajas Tierras Salvajes",
			short = "Las Bajas Tierras Salvajes ocupan el este de Feralas, donde los antárboles se mueven entre los árboles y caminan dríades corrompidas, con sus dones vueltos extraños.",
			full = "Las Bajas Tierras Salvajes ocupan el este de Feralas, donde los antárboles se mueven entre los árboles y caminan dríades corrompidas, con sus dones vueltos extraños.",
			source = "https://warcraft.wiki.gg/wiki/Lower_Wilds",
		},
		["oneiros"] = {
			name = "Oneiros",
			short = "Al sur del Lago Jademir, en el norte de Feralas, se encuentran las ruinas de Oneiros.",
			full = "Al sur del Lago Jademir, en el norte de Feralas, se encuentran las ruinas de Oneiros.",
			source = "https://warcraft.wiki.gg/wiki/Oneiros",
		},
		["rage scar hold"] = {
			name = "Dominios de los Cicatriz de Rabia",
			short = "Los Dominios de los Cicatriz de Rabia son una cueva excavada en Feralas que alberga a los yetis más feroces de la zona.",
			full = "Los Dominios de los Cicatriz de Rabia son una cueva excavada en Feralas que alberga a los yetis más feroces de la zona. En su interior hay libros y extraños símbolos dispersos, que sugieren estudios arcanos, o quizá los restos de algún mago desafortunado que encontró allí su final.",
			source = "https://warcraft.wiki.gg/wiki/Rage_Scar_Hold",
		},
		["ruins of isildien"] = {
			name = "Ruinas de Isildien",
			short = "Las Ruinas de Isildien son lo que queda de una gran ciudad de los elfos de la noche, destruida hace diez mil años. Ahora los ogros Gordunni anidan entre sus columnatas caídas y gobiernan sobre piedras levantadas por manos mucho más antiguas que las suyas.",
			full = "Las Ruinas de Isildien son lo que queda de una gran ciudad de los elfos de la noche, destruida hace diez mil años. Ahora los ogros Gordunni anidan entre sus columnatas caídas y gobiernan sobre piedras levantadas por manos mucho más antiguas que las suyas.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Isildien",
		},
		["ruins of ravenwind"] = {
			name = "Ruinas de Viento Azabache",
			short = "El norte de Feralas guarda las piedras rotas de Viento Azabache, levantadas hace mucho tiempo por los Altonato de los kaldorei, del mismo modo que La Masacre se levantó en otro lugar.",
			full = "El norte de Feralas guarda las piedras rotas de Viento Azabache, levantadas hace mucho tiempo por los Altonato de los kaldorei, del mismo modo que La Masacre se levantó en otro lugar. Poco de aquella gloria sigue en pie. Las arpías Nortearroyo han tomado las ruinas como propias y anidan entre las columnas caídas y los salones vacíos.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ravenwind",
		},
		["ruins of solarsal"] = {
			name = "Ruinas de Solarsal",
			short = "Al suroeste del Bastión Plumaluna, en la Isla de Sardor, las viejas piedras de Solarsal todavía se alzan entre los árboles, obra de los elfos de la noche abandonada hace mucho a la naturaleza salvaje.",
			full = "Al suroeste del Bastión Plumaluna, en la Isla de Sardor, las viejas piedras de Solarsal todavía se alzan entre los árboles, obra de los elfos de la noche abandonada hace mucho a la naturaleza salvaje. Ahora los nagas Crestafuria ocupan las ruinas y se enroscan entre las columnas rotas por donde antes caminaban los elfos.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Solarsal",
		},
		["sardor isle"] = {
			name = "Isla de Sardor",
			short = "La Isla de Sardor se alza frente a la costa de Feralas, un pequeño refugio en manos de los elfos de la noche bajo el mando de Shandris Plumaluna.",
			full = "La Isla de Sardor se alza frente a la costa de Feralas, un pequeño refugio en manos de los elfos de la noche bajo el mando de Shandris Plumaluna. Los nagas se han colado en sus orillas, y los lobos recorren los lugares salvajes que quedan, así que la vigilancia del bastión nunca descansa.",
			source = "https://warcraft.wiki.gg/wiki/Sardor_Isle",
		},
		["shalzarus lair"] = {
			name = "Guarida de Shalzaru",
			short = "Al sur de la isla del Bastión Plumaluna, en el extremo norte de la Isla del Terror, una cueva sinuosa alberga dos cámaras unidas por un canal.",
			full = "Al sur de la isla del Bastión Plumaluna, en el extremo norte de la Isla del Terror, una cueva sinuosa alberga dos cámaras unidas por un canal. Hechiceras y guardias serpentinos Crestafuria la llenan de principio a fin. En lo más profundo habita Shalzaru, señor de los Crestafuria.",
			source = "https://warcraft.wiki.gg/wiki/Shalzaru's_Lair",
		},
		["thalanaar"] = {
			name = "Thalanaar",
			short = "Thalanaar se alza en silencio, un pequeño puesto con poco que atraiga a los viajeros más allá de su propósito.",
			full = "Thalanaar se alza en silencio, un pequeño puesto con poco que atraiga a los viajeros más allá de su propósito. Caryssia Cazaluna ejerce aquí su oficio, trabajando pieles y cuero a la antigua manera tribal, uno de los pocos motivos por los que alguien tendría razones para quedarse.",
			source = "https://warcraft.wiki.gg/wiki/Thalanaar",
		},
		["twin colossals"] = {
			name = "Los Dos Colosos",
			short = "Los Dos Colosos se alzan en el extremo occidental de Feralas: dos montañas verticales tan altas que son el punto más elevado de la región, con el camino a Desolace pasando por el hueco entre ambas.",
			full = "Los Dos Colosos se alzan en el extremo occidental de Feralas: dos montañas verticales tan altas que son el punto más elevado de la región, con el camino a Desolace pasando por el hueco entre ambas.\n\nEn la cima del pico oriental hay un estanque pequeño y profundo, con el agua lo bastante tranquila para pescar, donde puede encontrarse a Gregan Tirabirras. Desde la cumbre, toda la región se abre abajo.",
			source = "https://warcraft.wiki.gg/wiki/Twin_Colossals",
		},
		["verdantis river"] = {
			name = "Río Verdantis",
			short = "El Río Verdantis serpentea por el centro de Feralas, al sureste de las ruinas de La Masacre, trazando un tranquilo hilo verde a través del bosque enmarañado.",
			full = "El Río Verdantis serpentea por el centro de Feralas, al sureste de las ruinas de La Masacre, trazando un tranquilo hilo verde a través del bosque enmarañado. Sus aguas albergan atún de Feralas, que no se encuentra en ningún otro lugar del mundo.",
			source = "https://warcraft.wiki.gg/wiki/Verdantis_River",
		},
		["wildwind lake"] = {
			name = "Lago Ventosalvaje",
			short = "El Lago Ventosalvaje se encuentra cerca del Campamento Mojache, en Feralas, con sus aguas tranquilas bajo las tierras salvajes que lo rodean, hogar de nada más notable que lo que nada bajo su superficie y la quietud que cubre el campamento cercano.",
			full = "El Lago Ventosalvaje se encuentra cerca del Campamento Mojache, en Feralas, con sus aguas tranquilas bajo las tierras salvajes que lo rodean, hogar de nada más notable que lo que nada bajo su superficie y la quietud que cubre el campamento cercano.",
			source = "https://warcraft.wiki.gg/wiki/Wildwind_Lake",
		},
		["woodpaw den"] = {
			name = "Guarida de los Zarpaleña",
			short = "En el corazón de Feralas se encuentra la Guarida de los Zarpaleña, madriguera de los gnolls Zarpaleña. Aquí los alfas Zarpaleña dominan a los suyos, apiñados en un número que pocos forasteros se atreven a poner a prueba.",
			full = "En el corazón de Feralas se encuentra la Guarida de los Zarpaleña, madriguera de los gnolls Zarpaleña. Aquí los alfas Zarpaleña dominan a los suyos, apiñados en un número que pocos forasteros se atreven a poner a prueba. Al sur de la guarida se alzan las Ruinas Niebla Negra, vecinas silenciosas del alboroto de los gnolls.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Den",
		},
		["woodpaw hills"] = {
			name = "Colinas Zarpaleña",
			short = "Las Colinas Zarpaleña están cubiertas de un bosque espeso y son el hogar de los gnolls del clan Zarpaleña.",
			full = "Las Colinas Zarpaleña están cubiertas de un bosque espeso y son el hogar de los gnolls del clan Zarpaleña. Su dominio sobre la tierra se les escapa, pues en el extremo sureste el suelo se ha abierto en lo que ahora se llama las Galerías Retorcidas, y las criaturas que brotan en enjambre desde debajo de la tierra han ido expulsando a los gnolls de su propio territorio. Donde antes los alfas Zarpaleña dirigían a su tribu desde los campamentos, ahora solo resisten en la Guarida de los Zarpaleña.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Hills",
		},
		["writhing deep"] = {
			name = "Las Galerías Retorcidas",
			short = "Las Galerías Retorcidas, en el sureste de Feralas, están entregadas a la Colmena Zukk'ash. Los silítidos de allí han envenenado la tierra que los rodea, llevando a los gnolls cercanos al frenesí y empujándolos hacia el norte, contra el Campamento Mojache.",
			full = "Las Galerías Retorcidas, en el sureste de Feralas, están entregadas a la Colmena Zukk'ash. Los silítidos de allí han envenenado la tierra que los rodea, llevando a los gnolls cercanos al frenesí y empujándolos hacia el norte, contra el Campamento Mojache.\n\nLos guerreros del campamento abatieron a los silítidos de la superficie, pero el corazón de la colmena bajo tierra, repleto de huevos, nunca fue tocado. Rexxar advierte que solo es cuestión de tiempo que eclosione la siguiente generación.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Deep",
		},
	},
	-- Marjal Revolcafango: 24 subzones
	[1445] = {
		["alcaz island"] = {
			name = "Isla de Alcaz",
			short = "La Isla de Alcaz surge del mar frente al Marjal Revolcafango, cubierta de un verde tropical que no tiene por qué crecer tan cerca del barro gris del marjal, como si algún poder más antiguo y más cálido hubiera reclamado este terreno y nunca lo hubiera soltado.",
			full = "La Isla de Alcaz surge del mar frente al Marjal Revolcafango, cubierta de un verde tropical que no tiene por qué crecer tan cerca del barro gris del marjal, como si algún poder más antiguo y más cálido hubiera reclamado este terreno y nunca lo hubiera soltado. Los nagas Strashaz la ocupan, con mirmidones y sirenas en abundancia a lo largo de sus orillas.\n\nSin embargo, durante la guerra contra Ahn'Qiraj, el doctor Weavil llegó a la isla en una máquina voladora y se instaló con sus esbirros en lo alto de la colina, convirtiendo un tramo de la orilla en un taller de invención tecnológica.",
			source = "https://warcraft.wiki.gg/wiki/Alcaz_Island",
		},
		["beezils wreck"] = {
			name = "Siniestro de Beezil",
			short = "Un zepelín goblin que se dirigía al sur con suministros cayó en las zonas más profundas del Marjal Revolcafango, al este de la granja de Tabetha.",
			full = "Un zepelín goblin que se dirigía al sur con suministros cayó en las zonas más profundas del Marjal Revolcafango, al este de la granja de Tabetha. Su casco yace roto en el barro, con la carga esparcida entre los restos y los propulsores de seforio todavía donde cayeron.",
			source = "https://warcraft.wiki.gg/wiki/Beezil's_Wreck",
		},
		["bloodfen burrow"] = {
			name = "Madriguera de los Cienorrojo",
			short = "Una cueva en el suroeste del Marjal Revolcafango da refugio a un número inusual de raptores Cienorrojo. Frente a la entrada yacen los restos de algún asentamiento, destrozado por las criaturas, cuya gente se ha perdido ahora en el barro del marjal.",
			full = "Una cueva en el suroeste del Marjal Revolcafango da refugio a un número inusual de raptores Cienorrojo. Frente a la entrada yacen los restos de algún asentamiento, destrozado por las criaturas, cuya gente se ha perdido ahora en el barro del marjal. En algún lugar de su interior, una parte del enigma de Cortello aguarda entre los restos.",
			source = "https://warcraft.wiki.gg/wiki/Bloodfen_Burrow",
		},
		["bluefen"] = {
			name = "Ciénaga Azul",
			short = "La Ciénaga Azul se encuentra en el norte del Marjal Revolcafango, con su terreno bajo lleno de juncos y agua estancada.",
			full = "La Ciénaga Azul se encuentra en el norte del Marjal Revolcafango, con su terreno bajo lleno de juncos y agua estancada. Arañas, crocoliscos, raptores y aves de pantano se mueven por la ciénaga sin control, y los infiltrados de Theramore pasan por ella sin ser vistos entre los juncos.",
			source = "https://warcraft.wiki.gg/wiki/Bluefen",
		},
		["brackenwall village"] = {
			name = "Poblado Murohelecho",
			short = "El Poblado Murohelecho se alza entre chozas y montículos de ogros en el noroeste del Marjal Revolcafango, hogar de los ogros Quebrantarrocas y leal a la Horda.",
			full = "El Poblado Murohelecho se alza entre chozas y montículos de ogros en el noroeste del Marjal Revolcafango, hogar de los ogros Quebrantarrocas y leal a la Horda. No siempre fue su hogar. Los Quebrantarrocas tenían antes una aldea al sur, hasta que el Vuelo Negro cayó sobre ella y la redujo a cenizas. El señor supremo Mok'Morokk, que había asumido el liderazgo después de Rexxar, condujo a los supervivientes al norte y levantó Murohelecho en su lugar.\n\nMok'Morokk basó su gobierno en quedarse quieto. Cuando el ogro Draz'Zilb descubrió que los atacantes habían sido la progenie de Onyxia y le llevó la verdad, Mok'Morokk no quiso actuar. Murohelecho estaba a salvo, allí no vivían dragones negros, y eso le bastaba. Draz'Zilb no piensa dejar el asunto, y sopesa en silencio lo que haría falta para ver caer al señor supremo y conducir a los Quebrantarrocas de vuelta a lo que han perdido.",
			source = "https://warcraft.wiki.gg/wiki/Brackenwall_Village",
		},
		["darkmist cavern"] = {
			name = "Cueva Niebla Negra",
			short = "Una pequeña mina se encuentra en el noroeste del Marjal Revolcafango, entregada desde hace mucho a unas arañas que han crecido hasta un tamaño aterrador en la oscuridad.",
			full = "Una pequeña mina se encuentra en el noroeste del Marjal Revolcafango, entregada desde hace mucho a unas arañas que han crecido hasta un tamaño aterrador en la oscuridad. La gente del marjal las llama arañas Niebla Negra, y a la caverna, a su vez, Niebla Negra, aunque nadie sabe decir qué nombre llegó primero, si el del lugar o el de las criaturas que lo reclamaron.\n\nFrente a la boca de la mina se alzan las ruinas de unas casitas, medio hundidas en el suelo húmedo, lo único que queda de algún asentamiento olvidado hace mucho.",
			source = "https://warcraft.wiki.gg/wiki/Darkmist_Cavern",
		},
		["den of flame"] = {
			name = "Cubil de la Llama",
			short = "El Cubil de la Llama lo levantaron los ogros Quebrantarrocas como su montículo, y su cantería todavía lleva la huella de su oficio. Se encuentra al oeste de las ruinas Quebrantarrocas, en un pantano reclamado por Onyxia.",
			full = "El Cubil de la Llama lo levantaron los ogros Quebrantarrocas como su montículo, y su cantería todavía lleva la huella de su oficio. Se encuentra al oeste de las ruinas Quebrantarrocas, en un pantano reclamado por Onyxia.\n\nLos ogros ya no están. Los dragonantes negros han invadido el cubil y lo ocupan como nido del Vuelo Negro. Solo la vieja cantería y el estandarte Quebrantarrocas, que sigue en pie en su interior, recuerdan a sus primeros constructores.",
			source = "https://warcraft.wiki.gg/wiki/Den_of_Flame",
		},
		["dragonmurk"] = {
			name = "El Pantano del Dragón",
			short = "En el sur del Marjal Revolcafango se extiende un tramo de terreno fétido llamado la Ciénaga del Dragón, lleno de crías y progenie del Vuelo Negro.",
			full = "En el sur del Marjal Revolcafango se extiende un tramo de terreno fétido llamado la Ciénaga del Dragón, lleno de crías y progenie del Vuelo Negro. Cerca se alzan el Cubil de la Llama y las Ruinas Quebrantarrocas, ambos igualmente invadidos por dracónidos negros.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmurk",
		},
		["dreadmurk shore"] = {
			name = "Playa Tenebruma",
			short = "La costa entre la Isla Theramore y el Fuerte del Norte está llena de múrlocs de la tribu Ancalodo, que reclaman la costa y sus islas dispersas como propias.",
			full = "La costa entre la Isla Theramore y el Fuerte del Norte está llena de múrlocs de la tribu Ancalodo, que reclaman la costa y sus islas dispersas como propias. Tortugas marinas y otras criaturas comparten las aguas que los rodean.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmurk_Shore",
		},
		["dustwallow bay"] = {
			name = "Bahía Revolcafango",
			short = "La Bahía Revolcafango forma parte del Mare Magnum y se adentra en la costa oriental del Marjal Revolcafango, al oeste de la Isla Theramore.",
			full = "La Bahía Revolcafango forma parte del Mare Magnum y se adentra en la costa oriental del Marjal Revolcafango, al oeste de la Isla Theramore. En una pequeña isla frente a la bahía, en la Cala Furiamarea, el pescador Nat Pagle monta su vigilia solitaria sobre el agua.",
			source = "https://warcraft.wiki.gg/wiki/Dustwallow_Bay",
		},
		["emberstrifes den"] = {
			name = "Cubil de Brasaliza",
			short = "Una amplia cueva se abre a la hedionda Ciénaga de Fuego, hogar del draco negro Brasaliza.",
			full = "Una amplia cueva se abre a la hedionda Ciénaga de Fuego, hogar del draco negro Brasaliza. Aquí pone a prueba a los jóvenes dragones negros con pruebas de resistencia y crueldad, pues solo quienes demuestran ser dignos pueden entrar en la Guarida de Onyxia.",
			source = "https://warcraft.wiki.gg/wiki/Emberstrife's_Den",
		},
		["foothold citadel"] = {
			name = "Ciudadela Garrida",
			short = "La Ciudadela Garrida se alza en el corazón de la Isla Theramore, cuartel general de la Guardia de Theramore.",
			full = "La Ciudadela Garrida se alza en el corazón de la Isla Theramore, cuartel general de la Guardia de Theramore.\n\nFue aquí donde Daelin Valiente encontró su final, cuando las fuerzas de Thrall asaltaron Theramore, conducidas al interior del castillo por Rexxar y sus compañeros. El almirante que desafió la paz de su hija Jaina con los orcos cayó entre estos muros.",
			source = "https://warcraft.wiki.gg/wiki/Foothold_Citadel",
		},
		["lost point"] = {
			name = "Punta Perdida",
			short = "Punta Perdida, una decrépita torre de exploración que Theramore levantó en otro tiempo en el oeste del Marjal Revolcafango, ya no sirve a sus constructores.",
			full = "Punta Perdida, una decrépita torre de exploración que Theramore levantó en otro tiempo en el oeste del Marjal Revolcafango, ya no sirve a sus constructores. Ahora la ocupan desertores de Theramore, dirigidos por Balos Jacken, que conoce el papel del soldado Hendel en el secuestro de una persona de gran importancia.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Point",
		},
		["north point tower"] = {
			name = "Torre de la Punta Norte",
			short = "La Torre de la Punta Norte vigila el norte del Marjal Revolcafango junto a un camino muy transitado, ocupada por un contingente considerable de guardias de Theramore.",
			full = "La Torre de la Punta Norte vigila el norte del Marjal Revolcafango junto a un camino muy transitado, ocupada por un contingente considerable de guardias de Theramore. Desde que los desertores se apoderaron de Punta Perdida, esta torre es el puesto más lejano de Theramore.",
			source = "https://warcraft.wiki.gg/wiki/North_Point_Tower",
		},
		["onyxias lair"] = {
			name = "Guarida de Onyxia",
			short = "El pasaje que lleva a la guarida de Onyxia tiene la forma de las fauces abiertas de la madre de linaje. Más allá, el camino está bordeado de magma, con el suelo agrietado y brillando con el fuego que viene de abajo.",
			full = "El pasaje que lleva a la guarida de Onyxia tiene la forma de las fauces abiertas de la madre de linaje. Más allá, el camino está bordeado de magma, con el suelo agrietado y brillando con el fuego que viene de abajo. El techo de piedra cruje y se mueve, soltando constantes desprendimientos de roca, y las propias paredes rezuman lava allí donde el calor no puede contenerse. Onyxia excavó este lugar ella misma, en lo profundo bajo la Ciénaga del Dragón, el lúgubre pantano del Marjal Revolcafango.\n\nNo es como los de su especie. Mientras su padre gobierna mediante la fuerza bruta y su hermano da forma a retorcidas abominaciones para que cumplan su voluntad, Onyxia actúa mediante susurros y encanto, disfrutando de la enmarañada política de los mortales y doblegándola en silencio a sus propios fines. Durante un tiempo llevó un nombre robado, haciéndose llamar Katrana Prestor, y con ese disfraz se introdujo en el corazón de la corte de Ventormenta, trabajando para deshacerla desde dentro. Fue el mariscal Windsor quien vio a través de la máscara y la llamó por lo que era. Desenmascarada, huyó de la ciudad y regresó a su ardiente salón bajo el marjal, donde permanece, custodiada todavía por los suyos, el Vuelo Negro.",
			source = "https://warcraft.wiki.gg/wiki/Onyxia's_Lair",
		},
		["quagmire"] = {
			name = "El Lodazal",
			short = "El Lodazal es el empapado corazón del Marjal Revolcafango, y se extiende entre Punta Perdida y la Bahía Revolcafango, delimitado por el Poblado Murohelecho al norte y la Ciénaga del Dragón al sur.",
			full = "El Lodazal es el empapado corazón del Marjal Revolcafango, y se extiende entre Punta Perdida y la Bahía Revolcafango, delimitado por el Poblado Murohelecho al norte y la Ciénaga del Dragón al sur.\n\nLos crocoliscos acechan en su agua negra, cienos y arañas se arrastran entre sus juncos, y los tauren Tótem Siniestro ocupan aquí terreno, lejos de cualquier pariente que los reclame. Es mejor cruzarlo que quedarse en él.",
			source = "https://warcraft.wiki.gg/wiki/Quagmire",
		},
		["sentry point"] = {
			name = "Alto del Centinela",
			short = "El Alto del Centinela se alza justo al otro lado del puente de Theramore, una torre de exploración construida por la ciudadela para vigilar el camino de abajo. Sigue intacta, manteniendo su vigilia silenciosa sobre todos los que pasan hacia la ciudad.",
			full = "El Alto del Centinela se alza justo al otro lado del puente de Theramore, una torre de exploración construida por la ciudadela para vigilar el camino de abajo. Sigue intacta, manteniendo su vigilia silenciosa sobre todos los que pasan hacia la ciudad.",
			source = "https://warcraft.wiki.gg/wiki/Sentry_Point",
		},
		["shady rest inn"] = {
			name = "Posada Reposo Umbrío",
			short = "La Posada Reposo Umbrío se alzaba en otro tiempo cerca de la frontera entre el Marjal Revolcafango y los Baldíos del Sur, una parada en el camino construida por humanos.",
			full = "La Posada Reposo Umbrío se alzaba en otro tiempo cerca de la frontera entre el Marjal Revolcafango y los Baldíos del Sur, una parada en el camino construida por humanos.\n\nSe quemó hasta los cimientos sin previo aviso. Dos hombres podrían haber nombrado a los culpables, Paval Reethe y el teniente Caldwell, pero ambos murieron antes de que ninguno pudiera decir la verdad, y el incendio quedó sin resolver.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Rest_Inn",
		},
		["stonemaul ruins"] = {
			name = "Ruinas Quebrantarrocas",
			short = "La Aldea Quebrantarrocas se alzaba en otro tiempo en el Marjal Revolcafango, hogar de los ogros del clan Quebrantarrocas, hasta que el caudillo Kor'gall, tras apoderarse de la antigua hacha orca Serathil, tomó el clan y lo gobernó con brutalidad.",
			full = "La Aldea Quebrantarrocas se alzaba en otro tiempo en el Marjal Revolcafango, hogar de los ogros del clan Quebrantarrocas, hasta que el caudillo Kor'gall, tras apoderarse de la antigua hacha orca Serathil, tomó el clan y lo gobernó con brutalidad. Fue aquí adonde llegó Rexxar, al que se le negó la entrada, y se abrió paso luchando. Kor'gall le ofreció un lugar en el clan si lograba sobrevivir al Guantelete, un valle lleno de bestias mortíferas. Rexxar lo resistió y regresó, y fue nombrado Quebrantarrocas. Cuando Kor'gall se negó a prestar el clan para la guerra de la Horda contra Kul Tiras, Rexxar lo desafió por el liderazgo y lo mató, y luego condujo él mismo a los Quebrantarrocas a la guerra. Después nombró a Mok'Morokk para gobernar en su lugar y se marchó.\n\nMok'Morokk no gobernó como lo había hecho Rexxar. Tomaba de su pueblo en lugar de servirlo, y cuando la progenie de Onyxia cayó sobre la aldea y la reclamó, condujo a los supervivientes a un lugar seguro y se conformó con quedarse allí, lejos de los dragones, en lugar de luchar por recuperar su antiguo hogar.\n\nLas ruinas se encuentran ahora dentro de la Ciénaga del Dragón, infestadas de dracónidos Pirocabello.",
			source = "https://warcraft.wiki.gg/wiki/Stonemaul_Ruins",
		},
		["swamplight manor"] = {
			name = "Mansión Cienaluz",
			short = "La Mansión Cienaluz es una casa modesta en la Colina de las Brujas, en el Marjal Revolcafango, hogar del cocinero \"Ojolodo\" Jarl.",
			full = "La Mansión Cienaluz es una casa modesta en la Colina de las Brujas, en el Marjal Revolcafango, hogar del cocinero \"Ojolodo\" Jarl.\n\nEn el jardín de fuera, un montón de tierra removida oculta algo que la cocina de Jarl nunca explica: un informe enterrado por un espía orco, dejado bajo la tierra para guardar su secreto de miradas indiscretas.",
			source = "https://warcraft.wiki.gg/wiki/Swamplight_Manor",
		},
		["theramore isle"] = {
			name = "Isla Theramore",
			short = "Después de la Tercera Guerra, Jaina Valiente condujo a los supervivientes de Lordaeron a través del mar hasta Kalimdor.",
			full = "Después de la Tercera Guerra, Jaina Valiente condujo a los supervivientes de Lordaeron a través del mar hasta Kalimdor. En una isla rocosa frente al Marjal Revolcafango levantaron Theramore, una ciudad amurallada destinada a dar refugio a lo que quedaba de la Alianza en una tierra extraña.\n\nLa ciudad está rodeada por una muralla rectangular salpicada de torres de cañones, interrumpida solo en el puerto, que custodian en su lugar dos torres de exploración. En su corazón se alza la torre de Jaina, la Ciudadela, el edificio más alto de Theramore, con sus muchos pisos de suelo de madera unidos por escaleras sinuosas y protegidos contra ataques, donde se encuentran los aposentos privados de Jaina, su biblioteca y la pequeña sala del trono de la ciudad. Cerca se alza la Ciudadela Garrida, el cuartel de la guardia, donde los soldados entrenan contra muñecos de práctica y los reclutas combaten bajo la mirada de sacerdotes dispuestos a invocar la Luz en cuanto alguien resulte herido.\n\nEl marjal da un suelo pobre y una madera pobre, y los marineros de Theramore refunfuñan que los robles que los orcos talan más allá de Orgrimmar son mucho mejores que cualquier cosa que ofrezca Revolcafango. Aun así, humanos y orcos intercambian pescado por el excedente de cosechas de Durotar, y por ahora la delincuencia en la ciudad es baja y su gente, en su mayor parte, vive en paz.",
			source = "https://warcraft.wiki.gg/wiki/Theramore_Isle",
		},
		["tidefury cove"] = {
			name = "Cala Furiamarea",
			short = "La Cala Furiamarea se encuentra al final de la Bahía Revolcafango, al sur de la Isla Theramore, con sus aguas salpicadas de islotes y arrecifes ocultos. Son aguas traicioneras para navegar.",
			full = "La Cala Furiamarea se encuentra al final de la Bahía Revolcafango, al sur de la Isla Theramore, con sus aguas salpicadas de islotes y arrecifes ocultos. Son aguas traicioneras para navegar. Dos barcos yacen destrozados en sus bajíos, entregados ahora a los makrura errantes.\n\nEntre sus islotes se encuentra el Embarcadero de Nat, hogar del pescador Nat Pagle.",
			source = "https://warcraft.wiki.gg/wiki/Tidefury_Cove",
		},
		["witch hill"] = {
			name = "Colina de las Brujas",
			short = "La Mansión Cienaluz se alza en el centro de la Colina de las Brujas, hogar de \"Ojolodo\" Jarl. Los múrlocs Ancalodo tienen sus campamentos cerca, en el fango.",
			full = "La Mansión Cienaluz se alza en el centro de la Colina de las Brujas, hogar de \"Ojolodo\" Jarl. Los múrlocs Ancalodo tienen sus campamentos cerca, en el fango.",
			source = "https://warcraft.wiki.gg/wiki/Witch_Hill",
		},
		["wyrmbog"] = {
			name = "Ciénaga de Fuego",
			short = "Al sur de la Ciénaga del Dragón, en el Marjal Revolcafango, el fango se espesa hasta formar la Ciénaga de Fuego.",
			full = "Al sur de la Ciénaga del Dragón, en el Marjal Revolcafango, el fango se espesa hasta formar la Ciénaga de Fuego. Los dragones negros tienen aquí su hogar, y la tierra se abre en dos lugares ocultos: la entrada al Cubil de Brasaliza y la guarida de la propia Onyxia.",
			source = "https://warcraft.wiki.gg/wiki/Wyrmbog",
		},
	},
	-- Tanaris: 23 subzones
	[1446] = {
		["abyssal sands"] = {
			name = "Arenas Abisales",
			short = "Las arenas de aquí se encuentran en Tanaris, un desierto que se extiende en todas direcciones.",
			full = "Las arenas de aquí se encuentran en Tanaris, un desierto que se extiende en todas direcciones.",
			source = "https://warcraft.wiki.gg/wiki/Abyssal_Sands",
		},
		["broken pillar"] = {
			name = "Pilar Partido",
			short = "Al sur de Gadgetzan, cerca de las Arenas Abisales, se alza un pequeño grupo de ruinas trol conocido como el Pilar Partido.",
			full = "Al sur de Gadgetzan, cerca de las Arenas Abisales, se alza un pequeño grupo de ruinas trol conocido como el Pilar Partido. Allí el científico goblin Marvon Buscarroblones ha instalado su campamento, buscando entre las piedras caídas respuestas propias.",
			source = "https://warcraft.wiki.gg/wiki/Broken_Pillar",
		},
		["caverns of time"] = {
			name = "Cavernas del Tiempo",
			short = "Las Cavernas del Tiempo se encuentran bajo las arenas orientales de Tanaris, un laberinto sinuoso sellado frente al mundo de arriba. Aquí el Vuelo Bronce vigila los caminos ramificados del propio tiempo.",
			full = "Las Cavernas del Tiempo se encuentran bajo las arenas orientales de Tanaris, un laberinto sinuoso sellado frente al mundo de arriba. Aquí el Vuelo Bronce vigila los caminos ramificados del propio tiempo. Desde que el mundo era joven, esa ha sido su misión sagrada, impuesta por los titanes: proteger las cavernas de la intrusión de los mortales, pues la intromisión de manos menores podría deshacer el curso de la historia. En el corazón de las cavernas se alza un gran reloj de arena.\n\nNozdormu, el Aspecto del Tiempo, habita aquí entre los suyos, dedicado a una afición personal: coleccionar artefactos raros. Tras la Segunda Guerra, el mago Krasus llegó a la guarida de Nozdormu por medio de una Rosa Eónica, un artilugio que le permitió cruzar la distancia en un instante. A Nozdormu le desagradó la intrusión, pues lo interrumpió en medio de su colección, y dejó clara su molestia.",
			source = "https://warcraft.wiki.gg/wiki/Caverns_of_Time",
		},
		["dunemaul compound"] = {
			name = "Base Machacaduna",
			short = "La Base Machacaduna es el montículo de los ogros Machacaduna, extendido sobre las arenas de Tanaris, donde el clan se reúne en sus refugios de tierra bajo el sol.",
			full = "La Base Machacaduna es el montículo de los ogros Machacaduna, extendido sobre las arenas de Tanaris, donde el clan se reúne en sus refugios de tierra bajo el sol.",
			source = "https://warcraft.wiki.gg/wiki/Dunemaul_Compound",
		},
		["eastmoon ruins"] = {
			name = "Ruinas de Lunaeste",
			short = "Terrazas de piedra y pilares agrietados marcan las Ruinas de Lunaeste, al oeste de la Sima Abierta, en Tanaris: todo lo que queda de un asentamiento trol abandonado hace mucho.",
			full = "Terrazas de piedra y pilares agrietados marcan las Ruinas de Lunaeste, al oeste de la Sima Abierta, en Tanaris: todo lo que queda de un asentamiento trol abandonado hace mucho. Los ogros Machacaduna reclamaron la cantería que se desmoronaba después de los trols, y todavía la ocupan.",
			source = "https://warcraft.wiki.gg/wiki/Eastmoon_Ruins",
		},
		["gadgetzan"] = {
			name = "Gadgetzan",
			short = "Gadgetzan surge del norte del desierto de Tanaris bajo un manto permanente de humo negro, capital del Cártel Bonvapor, el mayor de los cárteles goblin.",
			full = "Gadgetzan surge del norte del desierto de Tanaris bajo un manto permanente de humo negro, capital del Cártel Bonvapor, el mayor de los cárteles goblin. Aquí el credo de los goblins lo rige todo: el beneficio por encima de la lealtad. Tanto la Horda como la Alianza reconocen oficialmente la ciudad como territorio neutral, y los matones goblin patrullan sus calles, listos para dejar hecho papilla a cualquiera lo bastante necio como para traer la guerra a un lugar construido sobre el comercio. Son las carteras, no los estandartes, las que deciden quién es bienvenido.\n\nEsa neutralidad nunca ha sentado bien a todos. Los bandidos Vagayermos tomaron las Ruinas Sombrasol y el Campo del Manantial, al noreste. A los goblins no les importaban nada las viejas ruinas, pero el Campo del Manantial era otra cosa: las torres de agua que la Compañía de Agua de Gadgetzan había levantado y mantenía allí, bajo el sol abrasador del desierto, eran el oro líquido que mantenía viva la ciudad. Los goblins no estaban dispuestos a entregar unas torres por las que habían sudado, y así, mercenarios de los rincones más lejanos del mundo se vieron arrastrados a defender el agua de Gadgetzan frente a los bandidos que querían verla caer.",
			source = "https://warcraft.wiki.gg/wiki/Gadgetzan",
		},
		["gaping chasm"] = {
			name = "Sima Abierta",
			short = "La Sima Abierta está plagada de silítidos Hazzali, con sus complejos de colmenas horadando la roca en el sureste de Tanaris.",
			full = "La Sima Abierta está plagada de silítidos Hazzali, con sus complejos de colmenas horadando la roca en el sureste de Tanaris.\n\nEl perito jefe Picoflojo envió en una ocasión a su subordinado, Patagolpe, al interior de la sima para inspeccionarla. Patagolpe nunca volvió a salir. Murió entre las colmenas, y solo su equipo fue recuperado más tarde y devuelto a Picoflojo, que lo había enviado a la muerte sin saberlo.",
			source = "https://warcraft.wiki.gg/wiki/Gaping_Chasm",
		},
		["lands end beach"] = {
			name = "Playa Finisterrae",
			short = "La Playa Finisterrae se encuentra en el punto más meridional de Tanaris, donde el extremo sureste de Kalimdor se une al mar. La orilla es tranquila, marcada sobre todo por las criaturas que la recorren.",
			full = "La Playa Finisterrae se encuentra en el punto más meridional de Tanaris, donde el extremo sureste de Kalimdor se une al mar. La orilla es tranquila, marcada sobre todo por las criaturas que la recorren. Planeadores de las olas y cangrejos de las dunas avanzan con cuidado por el tramo oriental de la arena, sin que nadie los moleste.",
			source = "https://warcraft.wiki.gg/wiki/Land's_End_Beach",
		},
		["lost rigger cove"] = {
			name = "Cala del Aparejo Perdido",
			short = "Oculta tras montañas por tres lados, la Cala del Aparejo Perdido esconde el puerto de los Piratas de los Mares del Sur en la costa de Tanaris, con su astillero ocupado en la construcción de un nuevo barco.",
			full = "Oculta tras montañas por tres lados, la Cala del Aparejo Perdido esconde el puerto de los Piratas de los Mares del Sur en la costa de Tanaris, con su astillero ocupado en la construcción de un nuevo barco.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Rigger_Cove",
		},
		["noonshade ruins"] = {
			name = "Ruinas Sombrasol",
			short = "Las Ruinas Sombrasol se encuentran al este de Gadgetzan, piedra desgastada que dejaron atrás unos trols desaparecidos hace mucho. Las arenas del desierto ya no dicen qué propósito tuvieron las ruinas ni qué fue de quienes las levantaron.",
			full = "Las Ruinas Sombrasol se encuentran al este de Gadgetzan, piedra desgastada que dejaron atrás unos trols desaparecidos hace mucho. Las arenas del desierto ya no dicen qué propósito tuvieron las ruinas ni qué fue de quienes las levantaron.",
			source = "https://warcraft.wiki.gg/wiki/Noonshade_Ruins",
		},
		["noxious lair"] = {
			name = "La Guarida Ponzoñosa",
			short = "El suroeste de Tanaris guarda una herida en la arena donde antes había agua. Algo ancho y poco profundo, un río o un lago, se extendía sobre este terreno antes de que llegaran los silítidos, y el enjambre Centipaar vació lo que encontró allí.",
			full = "El suroeste de Tanaris guarda una herida en la arena donde antes había agua. Algo ancho y poco profundo, un río o un lago, se extendía sobre este terreno antes de que llegaran los silítidos, y el enjambre Centipaar vació lo que encontró allí. Por ello, el oeste de Tanaris quedó seco.\n\nLa superficie todavía muestra la forma de lo que se perdió. La tierra se hunde, hueca y deprimida, con vistas al Cráter de Un'Goro, como si recordara haber sido una orilla. Aquí y allá, grandes garras se alzan erguidas sobre la arena y se crispan, como si criaturas enterradas se hubieran quedado congeladas en pleno ataque. Alrededor de cada garra, el suelo está negro y húmedo de fluido silítido, la única humedad que queda en un lugar que antes albergaba un lago.\n\nBajo la superficie, La Guarida Ponzoñosa es una colmena como cualquier otra de las que los Centipaar han excavado en Tanaris: húmeda, cálida, inquietante en su quietud, con sus túneles cubiertos de ácido silítido.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Lair",
		},
		["sandsorrow watch"] = {
			name = "Vigía Penas de Arena",
			short = "La Vigía Penas de Arena se extiende al oeste de Gadgetzan por la cuenca seca de Tanaris, en manos de los trols Farraki y de los zombis que han alzado entre sus propios muertos.",
			full = "La Vigía Penas de Arena se extiende al oeste de Gadgetzan por la cuenca seca de Tanaris, en manos de los trols Farraki y de los zombis que han alzado entre sus propios muertos.",
			source = "https://warcraft.wiki.gg/wiki/Sandsorrow_Watch",
		},
		["south seas"] = {
			name = "Mares del Sur",
			short = "Las aguas al sur de los continentes conocidos se abren a una amplia extensión del Mare Magnum, con corrientes que pasan junto a islas cuyos nombres conocen sobre todo los marineros.",
			full = "Las aguas al sur de los continentes conocidos se abren a una amplia extensión del Mare Magnum, con corrientes que pasan junto a islas cuyos nombres conocen sobre todo los marineros. De estas aguas surge Zandalar, antiguo hogar del imperio trol. Entre ellas se encuentra también Kezan, una isla volcánica cuyo pueblo se mantiene apartado de las potencias del continente.\n\nMás cerca de la Vega de Tuercespina, el mar se vuelve traicionero, con arrecifes y calas ocultas, el tipo de aguas donde un capitán o conoce cada roca por su nombre o pierde el barco. Pequeñas islas salpican este tramo, algunas no más que un banco de arena, otras con ruinas cuyos constructores desaparecieron hace mucho bajo las olas.\n\nLo que hace que este mar merezca un nombre no es tanto una batalla concreta librada en él como lo que se ha tragado y ha vuelto a revelar a medias: templos hundidos, costas anegadas, ruinas vislumbradas a través del agua clara con la marea baja. Es un mar de bordes y lugares intermedios, que recorre las fronteras de Tuercespina, Tanaris y Uldum, y que lleva lo que las mareas decidan traer a las costas que separa.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southbreak shore"] = {
			name = "Tierras del Sur",
			short = "Las Tierras del Sur se extienden tranquilas a lo largo del borde sur de Tanaris, un tramo llano de playa casi vacío de vida. Tortugas y gigantes marinos recorren el oleaje.",
			full = "Las Tierras del Sur se extienden tranquilas a lo largo del borde sur de Tanaris, un tramo llano de playa casi vacío de vida. Tortugas y gigantes marinos recorren el oleaje.",
			source = "https://warcraft.wiki.gg/wiki/Southbreak_Shore",
		},
		["southmoon ruins"] = {
			name = "Ruinas de Lunasur",
			short = "Las Ruinas de Lunasur son los restos de un antiguo asentamiento trol en el sur de Tanaris, con sus piedras desgastadas y medio enterradas en la arena del desierto.",
			full = "Las Ruinas de Lunasur son los restos de un antiguo asentamiento trol en el sur de Tanaris, con sus piedras desgastadas y medio enterradas en la arena del desierto.",
			source = "https://warcraft.wiki.gg/wiki/Southmoon_Ruins",
		},
		["steamwheedle port"] = {
			name = "Puerto Bonvapor",
			short = "Puerto Bonvapor se encuentra en la costa oriental de Tanaris, con un camino que va hacia el oeste hasta su ciudad madre, Gadgetzan, y un muelle que se extiende hacia Kezan.",
			full = "Puerto Bonvapor se encuentra en la costa oriental de Tanaris, con un camino que va hacia el oeste hasta su ciudad madre, Gadgetzan, y un muelle que se extiende hacia Kezan. Pertenece al Cártel Bonvapor, goblins que tratan con cualquiera mientras el oro sea bueno.\n\nEntre los residentes del puerto está Yeh'kinya, cuyos tratos propiciaron el regreso de Hakkar el Desollador de Almas.",
			source = "https://warcraft.wiki.gg/wiki/Steamwheedle_Port",
		},
		["thistleshrub valley"] = {
			name = "Valle Cardizal",
			short = "El Valle Cardizal está lleno de cactus gigantes, algo extraño en un desierto tan árido que logra sostener vida.",
			full = "El Valle Cardizal está lleno de cactus gigantes, algo extraño en un desierto tan árido que logra sostener vida. Los cardizales que antes crecían densos aquí se han ido reduciendo en los últimos tiempos, y ahora pueden encontrarse flores del desierto entre ellos, aunque solo de forma dispersa.",
			source = "https://warcraft.wiki.gg/wiki/Thistleshrub_Valley",
		},
		["uldum"] = {
			name = "Uldum",
			short = "Uldum se encuentra en la costa sur de Kalimdor, cercada por el Cráter de Un'Goro al norte, Tanaris al este y Silithus al noroeste.",
			full = "Uldum se encuentra en la costa sur de Kalimdor, cercada por el Cráter de Un'Goro al norte, Tanaris al este y Silithus al noroeste. Es un lugar rico en el saber de los titanes, con sus pasos de montaña envueltos de modo que ningún ojo mortal pueda encontrar la entrada.",
			source = "https://warcraft.wiki.gg/wiki/Uldum",
		},
		["valley of the watchers"] = {
			name = "Valle de los Vigías",
			short = "El Valle de los Vigías protege el sur de Tanaris, donde una gran puerta se alza impenetrable frente a Uldum. Los gigantes de montaña, los machacadunas, recorren el lugar como sus vigilantes.",
			full = "El Valle de los Vigías protege el sur de Tanaris, donde una gran puerta se alza impenetrable frente a Uldum. Los gigantes de montaña, los machacadunas, recorren el lugar como sus vigilantes.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_the_Watchers",
		},
		["waterspring field"] = {
			name = "Campo del Manantial",
			short = "El Campo del Manantial debe su nombre a las torres de agua que se alzan en él y que extraen agua de reservas profundas bajo tierra.",
			full = "El Campo del Manantial debe su nombre a las torres de agua que se alzan en él y que extraen agua de reservas profundas bajo tierra. Las construyeron los goblins de Gadgetzan con la intención de asegurar agua para sus operaciones en el desierto de Tanaris.\n\nAquel plan no sobrevivió a los Vagayermos. Los bandidos nómadas irrumpieron en el campo y simplemente se lo quedaron, apoderándose de las torres sin pensar en los goblins que las habían levantado. Todavía siguen instalados allí, bastante contentos con este terreno después de aquello de lo que huyeron antes; no les gusta hablar del campamento de ogros que hubo antes, solo de que esto es mejor.",
			source = "https://warcraft.wiki.gg/wiki/Waterspring_Field",
		},
		["wavestrider beach"] = {
			name = "Playa Baile de las Olas",
			short = "La Playa Baile de las Olas recorre la costa oriental de Tanaris, el tramo de arena entre Puerto Bonvapor y la Cala del Aparejo Perdido.",
			full = "La Playa Baile de las Olas recorre la costa oriental de Tanaris, el tramo de arena entre Puerto Bonvapor y la Cala del Aparejo Perdido. Aquí los reptadores del desierto corretean por la playa, junto a las tortugas quijacero que comparten la misma orilla.",
			source = "https://warcraft.wiki.gg/wiki/Wavestrider_Beach",
		},
		["zalashjis den"] = {
			name = "Guarida de Zalashji",
			short = "La Guarida de Zalashji todavía lleva el nombre de quien tuvo aquí su guarida. Nada en los relatos que sobreviven dice quién fue Zalashji ni qué fue del lugar después.",
			full = "La Guarida de Zalashji todavía lleva el nombre de quien tuvo aquí su guarida. Nada en los relatos que sobreviven dice quién fue Zalashji ni qué fue del lugar después. Nadie puede asegurar si Zalashji sigue vivo, si murió aquí o en otro lugar.",
			source = "https://warcraft.wiki.gg/wiki/Zalashji's_Den",
		},
		["zulfarrak"] = {
			name = "Zul'Farrak",
			short = "Zul'Farrak fue en otro tiempo una ciudad de la selva, cuando Tanaris todavía era bosque bajo el Imperio Gurubashi.",
			full = "Zul'Farrak fue en otro tiempo una ciudad de la selva, cuando Tanaris todavía era bosque bajo el Imperio Gurubashi. Cuando el Gran Cataclismo desgarró el mundo antiguo, la selva ardió hasta convertirse en desierto, y los trols Farraki que habían construido aquí su ciudad se encontraron varados en medio de la arena. Resistieron, endureciéndose hasta convertirse en los Furiarena, una tribu conocida incluso entre los trols por su crueldad y su oscuro misticismo.\n\nDentro de sus muros abrasados por el sol, la leyenda trol habla de Sul'thraze el Azotador, una hoja de la que se dice que infunde miedo y debilidad en cualquier enemigo al que toque. Hace mucho tiempo, la espada se partió en dos, y se susurra que ambas mitades todavía yacen en algún lugar dentro de la ciudad, perdidas entre sus patios y templos.\n\nEn el corazón de Zul'Farrak hay un estanque sagrado, y se dice que bajo su agua quieta los Furiarena mantienen dormido algo mucho más antiguo que ellos: un semidiós cuyo despertar traería la ruina sobre la ciudad y todos los que están en ella.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Farrak",
		},
	},
	-- Azshara: 26 subzones
	[1447] = {
		["bay of storms"] = {
			name = "Bahía de la Tempestad",
			short = "La Bahía de la Tempestad se encuentra frente a la costa oriental de Azshara, y sus aguas son conocidas por los viajeros por las tormentas que se forman allí. A lo largo de su orilla se encuentran la Cueva de Barbaescamas, la Guarida de Hetaera y el Templo de Arkkoran.",
			full = "La Bahía de la Tempestad se encuentra frente a la costa oriental de Azshara, y sus aguas son conocidas por los viajeros por las tormentas que se forman allí. A lo largo de su orilla se encuentran la Cueva de Barbaescamas, la Guarida de Hetaera y el Templo de Arkkoran.",
			source = "https://warcraft.wiki.gg/wiki/Bay_of_Storms",
		},
		["bears head"] = {
			name = "Cabeza de Oso",
			short = "Cabeza de Oso debe su nombre a las aldeas fúrbolg dispersas por la región, pequeños puestos que vigilan los accesos al Bastión Fauces de Madera y a Ursolan, más al norte.",
			full = "Cabeza de Oso debe su nombre a las aldeas fúrbolg dispersas por la región, pequeños puestos que vigilan los accesos al Bastión Fauces de Madera y a Ursolan, más al norte.\n\nEn un acantilado sobre las aldeas se alza la Torre de Xylem, hogar del archimago Xylem, que tiene la compañía de varios aprendices y colaboradores que estudian y trabajan entre sus muros.",
			source = "https://warcraft.wiki.gg/wiki/Bear's_Head",
		},
		["bitter reaches"] = {
			name = "Costa Amarga",
			short = "La Costa Amarga se encuentra en el noreste de Azshara, llena de hipogrifos, cienos y quimeras. A lo largo del límite norte, los gigantes de montaña han expulsado a la fauna menor y han reclamado el terreno para sí.",
			full = "La Costa Amarga se encuentra en el noreste de Azshara, llena de hipogrifos, cienos y quimeras. A lo largo del límite norte, los gigantes de montaña han expulsado a la fauna menor y han reclamado el terreno para sí.",
			source = "https://warcraft.wiki.gg/wiki/Bitter_Reaches",
		},
		["forlorn ridge"] = {
			name = "Loma Desolada",
			short = "La Loma Desolada se alza sobre el oeste de Azshara y domina la tierra a kilómetros a la redonda.",
			full = "La Loma Desolada se alza sobre el oeste de Azshara y domina la tierra a kilómetros a la redonda. En sus laderas se alzan fortificaciones por parejas, obras de la Alianza y de la Horda levantadas a la vista unas de otras, construidas para una batalla que nunca llegó y ahora vacías.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Ridge",
		},
		["haldarr encampment"] = {
			name = "Campamento Haldarr",
			short = "El Campamento Haldarr está plagado de sátiros en el oeste de Azshara, una hueste corrompida de demonios con patas de cabra cuyas hogueras arden al noreste del Santuario Cantosombrío y al suroeste del viejo Valormok.",
			full = "El Campamento Haldarr está plagado de sátiros en el oeste de Azshara, una hueste corrompida de demonios con patas de cabra cuyas hogueras arden al noreste del Santuario Cantosombrío y al suroeste del viejo Valormok.",
			source = "https://warcraft.wiki.gg/wiki/Haldarr_Encampment",
		},
		["hetaeras clutch"] = {
			name = "Guarida de Hetaera",
			short = "Bajo la Bahía de la Tempestad, frente a Azshara, se encuentra la Guarida de Hetaera, un templo que ahora es hogar de hidras.",
			full = "Bajo la Bahía de la Tempestad, frente a Azshara, se encuentra la Guarida de Hetaera, un templo que ahora es hogar de hidras.",
			source = "https://warcraft.wiki.gg/wiki/Hetaera's_Clutch",
		},
		["jagged reef"] = {
			name = "Arrecife Dentado",
			short = "El Arrecife Dentado es la costa norte de Azshara, una playa arenosa interrumpida una y otra vez por salientes de piedra y pequeñas ensenadas. Rocas y bajíos se ocultan bajo la superficie y hacen peligroso recorrer la orilla.",
			full = "El Arrecife Dentado es la costa norte de Azshara, una playa arenosa interrumpida una y otra vez por salientes de piedra y pequeñas ensenadas. Rocas y bajíos se ocultan bajo la superficie y hacen peligroso recorrer la orilla. Múrlocs, hidras y makrura dominan esta costa, nadando en las aguas poco profundas o avanzando pesadamente por la arena en busca de comida.",
			source = "https://warcraft.wiki.gg/wiki/Jagged_Reef",
		},
		["lake mennar"] = {
			name = "Lago Mennar",
			short = "Las aguas del Lago Mennar están quietas en su centro, aunque el terreno que lo rodea por todos lados pertenece a los dracónidos.",
			full = "Las aguas del Lago Mennar están quietas en su centro, aunque el terreno que lo rodea por todos lados pertenece a los dracónidos. Quien cruza ese perímetro descubre que el lago en sí está libre de peligro, un lugar de calma y descanso en medio de unas orillas vigiladas.\n\nEs uno de los pocos lugares del mundo, fuera de Rasganorte, donde el Vuelo Azul ha dado señales de vida. Solo Mazthoril, en Cuna del Invierno, se le compara. Las jóvenes crías de dragón azur son algo habitual cerca de estas aguas.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mennar",
		},
		["legash encampment"] = {
			name = "Campamento Legashi",
			short = "Los sátiros Legashi tienen su campamento en el norte de Azshara, al este de Ursolan.",
			full = "Los sátiros Legashi tienen su campamento en el norte de Azshara, al este de Ursolan.\n\nAquí el archimago Xylem encontró en una ocasión un grimorio, un hallazgo que atrajo la atención sobre este campamento, por lo demás corriente, de criaturas tocadas por lo vil.",
			source = "https://warcraft.wiki.gg/wiki/Legash_Encampment",
		},
		["ravencrest monument"] = {
			name = "Monumento Cresta Cuervo",
			short = "Los acantilados del extremo sur de Azshara guardan los restos de un coloso, aunque poco queda ya que justifique la palabra.",
			full = "Los acantilados del extremo sur de Azshara guardan los restos de un coloso, aunque poco queda ya que justifique la palabra. Solo siguen en pie las piernas rotas, plantadas sobre el mar, mientras el resto de la gran figura yace esparcido por la piedra a su alrededor o se ha deslizado bajo las olas.\n\nAhora los nagas Látigo de Ira ocupan las ruinas. No se puede llegar al lugar desde el agua; quien quiera alcanzarlo debe venir por tierra y cruzar el puente que sale más allá de las Ruinas de Eldarath, para detenerse bajo las piernas derribadas de algo que en su día fue, sin duda, impresionante de contemplar.",
			source = "https://warcraft.wiki.gg/wiki/Ravencrest_Monument",
		},
		["rethress sanctum"] = {
			name = "Sagrario de Rethress",
			short = "El Sagrario de Rethress se alza en ruinas en la Costa de las Ruinas, al suroeste del Monumento Cresta Cuervo. Ya nadie lo cuida. Múrlocs y makrura vagan entre sus piedras caídas, los únicos que vienen hasta aquí.",
			full = "El Sagrario de Rethress se alza en ruinas en la Costa de las Ruinas, al suroeste del Monumento Cresta Cuervo. Ya nadie lo cuida. Múrlocs y makrura vagan entre sus piedras caídas, los únicos que vienen hasta aquí.",
			source = "https://warcraft.wiki.gg/wiki/Rethress_Sanctum",
		},
		["ruined reaches"] = {
			name = "Las Ruinas",
			short = "La costa sur de Azshara muestra su ruina sin disimulo. Acantilados y playas se rompen en ensenadas, y el agua oculta bajíos que han atrapado más cascos de los que cualquier marinero querría contar.",
			full = "La costa sur de Azshara muestra su ruina sin disimulo. Acantilados y playas se rompen en ensenadas, y el agua oculta bajíos que han atrapado más cascos de los que cualquier marinero querría contar. Barcos naufragados yacen medio enterrados en la arena junto a ruinas más antiguas y extrañas cuyos constructores ya no existen. Múrlocs, hidras y makrura rondan la orilla, e incluso quienes conocen la costa la recorren con cuidado.\n\nEn las orillas occidentales, sobre la playa, se alza un edificio gnomo en una colina, al que solo se llega por un empinado sendero desde el interior. Blimo y Jubie Gadgetspring han establecido aquí su hogar y su negocio. Arriba, en sus aposentos privados, hay una tercera cama. Nadie sabe a quién pertenece, ni si alguien duerme en ella.",
			source = "https://warcraft.wiki.gg/wiki/Ruined_Reaches",
		},
		["ruins of eldarath"] = {
			name = "Ruinas de Eldarath",
			short = "Antes de que el mundo se quebrara, Eldarath se alzaba como uno de los grandes bastiones de los Altonato, una ciudad de saber arcano donde los magos más poderosos tallaban runas y tablillas en piedra y las dejaban en lugares públicos, para que cualquiera que pasara pudiera reflexionar sobre sus conocimientos de lo arcano.",
			full = "Antes de que el mundo se quebrara, Eldarath se alzaba como uno de los grandes bastiones de los Altonato, una ciudad de saber arcano donde los magos más poderosos tallaban runas y tablillas en piedra y las dejaban en lugares públicos, para que cualquiera que pasara pudiera reflexionar sobre sus conocimientos de lo arcano.\n\nLa ciudad no cayó en silencio. Durante la Guerra de los Ancestros, la resistencia kaldorei resistió aquí frente a la Legión Ardiente. Cuando el Gran Cataclismo desgarró el mundo, Eldarath no pudo soportarlo: la mayor parte de la ciudad se desmoronó y se hundió en las aguas de la Bahía de la Tempestad.\n\nLo que queda se aferra a los acantilados orientales, un conjunto roto de torres que los elfos de la noche, que antes la consideraban su hogar, evitan desde hace mucho. Ahora los nagas han reclamado las ruinas, y el señor de la guerra Krellian gobierna lo que queda desde el Templo de Zin-Malor. Entre los restos, las tablillas rúnicas de los antiguos Altonato todavía siguen en pie, con su sabiduría arcana intacta a lo largo de las eras.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Eldarath",
		},
		["scalebeards cave"] = {
			name = "Cueva de Barbaescamas",
			short = "Una cueva en una diminuta isla de la Bahía de la Tempestad lleva el nombre de Barbaescamas, una vieja tortuga poco común. Es su hogar, aunque rara vez su lugar de descanso, pues prefiere cazar lejos, en el Mare Magnum, y deja la guarida vacía.",
			full = "Una cueva en una diminuta isla de la Bahía de la Tempestad lleva el nombre de Barbaescamas, una vieja tortuga poco común. Es su hogar, aunque rara vez su lugar de descanso, pues prefiere cazar lejos, en el Mare Magnum, y deja la guarida vacía.",
			source = "https://warcraft.wiki.gg/wiki/Scalebeard's_Cave",
		},
		["shadowsong shrine"] = {
			name = "Santuario Cantosombrío",
			short = "Colina cubierta de ruinas en el oeste de Azshara, el Santuario Cantosombrío no guarda ningún registro claro de por qué lleva ese nombre.",
			full = "Colina cubierta de ruinas en el oeste de Azshara, el Santuario Cantosombrío no guarda ningún registro claro de por qué lleva ese nombre. Comparte nombre con Jarod Cantosombrío, que dirigió la resistencia en la Guerra de los Ancestros, y con su hermana Maiev, la celadora recordada por mantener cautivo a Illidan Tempestira tras su traición en el Monte Hyjal. Nadie sabe decir qué tiene que ver ninguno de los dos con esta colina.\n\nLo que sí puede decirse es qué camina por allí. Fantasmas de los Altonato permanecen entre las piedras, hambrientos de cualquier ser vivo que se acerque.",
			source = "https://warcraft.wiki.gg/wiki/Shadowsong_Shrine",
		},
		["shattered strand"] = {
			name = "La Playa Arrasada",
			short = "La Playa Arrasada recorre el lado norte de la Bahía de la Tempestad, en Azshara, llena de hidras, gigantes marinos, makrura y múrlocs, cada uno dueño de su propio tramo de arena.",
			full = "La Playa Arrasada recorre el lado norte de la Bahía de la Tempestad, en Azshara, llena de hidras, gigantes marinos, makrura y múrlocs, cada uno dueño de su propio tramo de arena. El Templo de Arkkoran y la Torre de Eldara se alzan en la orilla a pesar del amontonamiento de garras y tentáculos.\n\nLos goblins también han reclamado terrenos a lo largo de esta costa, especulando con la propiedad frente a la playa entre tantos dientes y mareas.",
			source = "https://warcraft.wiki.gg/wiki/Shattered_Strand",
		},
		["southfury river"] = {
			name = "Río Furia del Sur",
			short = "El Furia del Sur nace en lo alto del Monte Hyjal y brota de un lago de montaña en una cascada que cae con estruendo hacia las tierras bajas.",
			full = "El Furia del Sur nace en lo alto del Monte Hyjal y brota de un lago de montaña en una cascada que cae con estruendo hacia las tierras bajas. Desde allí fluye ancho y veloz, partiendo la tierra en dos: marca el lugar donde Vallefresno da paso a Azshara y, más al sur, donde terminan Los Baldíos y comienza Durotar. En su desembocadura, el río se precipita por una última cascada al Mare Magnum, justo al noreste del puerto goblin de Trinquete.\n\nVarios puentes lo cruzan a lo largo de su recorrido: uno une Azshara con Vallefresno, y otro une Durotar con Los Baldíos.\n\nEl río todavía alimenta los campos de sus orillas y todavía tiñe de verde la tierra por donde pasa.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["southridge beach"] = {
			name = "Playa del Arrecife Sur",
			short = "La Playa del Arrecife Sur bordea el extremo sur de la Bahía de la Tempestad, con sus arenas sembradas de ruinas de la otrora gran ciudad de Eldarath.",
			full = "La Playa del Arrecife Sur bordea el extremo sur de la Bahía de la Tempestad, con sus arenas sembradas de ruinas de la otrora gran ciudad de Eldarath. Ahora los nagas ocupan la orilla y la comparten con makrura, hidras, múrlocs y algún que otro gigante marino surgido de aguas más profundas.",
			source = "https://warcraft.wiki.gg/wiki/Southridge_Beach",
		},
		["storm cliffs"] = {
			name = "Acantilados de la Tormenta",
			short = "Los Acantilados de la Tormenta se alzan en Azshara, reclamados por los nagas Látigo de Ira que habitan entre la roca. En el extremo oriental de los acantilados se alza el Monumento Cresta Cuervo, un hito solitario que domina la piedra en manos de los nagas.",
			full = "Los Acantilados de la Tormenta se alzan en Azshara, reclamados por los nagas Látigo de Ira que habitan entre la roca. En el extremo oriental de los acantilados se alza el Monumento Cresta Cuervo, un hito solitario que domina la piedra en manos de los nagas.",
			source = "https://warcraft.wiki.gg/wiki/Storm_Cliffs",
		},
		["talrendis point"] = {
			name = "Punta Talrendis",
			short = "Punta Talrendis se alza en el suroeste de Azshara, con sus dos torres de guardia vigilando la frontera con Vallefresno, y una poza de la luna todavía riega el terreno del sur.",
			full = "Punta Talrendis se alza en el suroeste de Azshara, con sus dos torres de guardia vigilando la frontera con Vallefresno, y una poza de la luna todavía riega el terreno del sur.\n\nLa punta comenzó como poco más que un pequeño campamento de los elfos de la noche, un puesto de vigilancia en el límite del bosque.",
			source = "https://warcraft.wiki.gg/wiki/Talrendis_Point",
		},
		["temple of arkkoran"] = {
			name = "Templo de Arkkoran",
			short = "El Templo de Arkkoran perteneció en otro tiempo al culto de Elune, con sus piedras levantadas en las costas nororientales de Azshara. Aquella santidad desapareció hace mucho.",
			full = "El Templo de Arkkoran perteneció en otro tiempo al culto de Elune, con sus piedras levantadas en las costas nororientales de Azshara. Aquella santidad desapareció hace mucho. Ahora el gigante marino Arkkoroc habita en su cima, protegido por múrlocs y makrura que caen sobre cualquiera que se acerque. La orilla circundante, la Playa Arrasada, no ofrece un paso más seguro, vigilada por hidras y gigantes marinos tan agresivos como el propio Arkkoroc.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Arkkoran",
		},
		["temple of zin malor"] = {
			name = "Templo de Zin-Malor",
			short = "El Templo de Zin-Malor se alza entre las Ruinas de Eldarath, con sus piedras labradas a semejanza del cercano Templo de Arkkoran y del Templo de la Luna que más tarde se levantaría en Darnassus.",
			full = "El Templo de Zin-Malor se alza entre las Ruinas de Eldarath, con sus piedras labradas a semejanza del cercano Templo de Arkkoran y del Templo de la Luna que más tarde se levantaría en Darnassus. Se construyó en devoción a Elune, en los días anteriores a que los elfos de la noche se volcaran en la magia arcana.\n\nEn su interior descansó en otro tiempo el cristal de Zin-Malor, un obsequio destinado a llevar un mensaje a los Altonato: que en realidad no tenían ninguna necesidad de la magia arcana. El cristal ya no está; se lo llevaron hace mucho.\n\nDesde entonces, el templo ha caído en manos de la tribu de nagas Látigo de Ira. Ahora el señor de la guerra Krellian gobierna allí, y ha tomado para sí el lugar de honor antes reservado al culto de la diosa.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Zin-Malor",
		},
		["thalassian base camp"] = {
			name = "Campamento Base Thalassiano",
			short = "La colina sobre los campamentos Legashi pertenece a los elfos de sangre, con sus laderas divididas en pequeños puestos fortificados bajo el mando de la magus Rimtori.",
			full = "La colina sobre los campamentos Legashi pertenece a los elfos de sangre, con sus laderas divididas en pequeños puestos fortificados bajo el mando de la magus Rimtori. Ella cerró un trato con la Horda y prometió una parte de todo lo que desenterrara su expedición a cambio de oro y acero para protegerla. El trato no se cumplió. Rimtori se quedó con los fondos y no devolvió nada, y la noticia de la traición se ha extendido hasta el punto de que se dice que a ella y a sus seguidores se les debe una venganza de la misma medida.\n\nLa propia Rimtori rara vez está en el campamento, entregada a explorar Azshara bajo una guardia elegida por ella, y deja al magister Hawkhelm defendiendo la colina en su ausencia. Lo que ambos buscan en realidad no es oro. En una de las crestas del campamento hay un tomo kaldorei de invocación, algo capaz de traer demonios al mundo, y su presencia allí revela la expedición por lo que es: no una búsqueda de tesoros, sino algo más oscuro disfrazado de ella.",
			source = "https://warcraft.wiki.gg/wiki/Thalassian_Base_Camp",
		},
		["tower of eldara"] = {
			name = "Torre de Eldara",
			short = "La Torre de Eldara se alza en la punta nororiental de la tierra sobre la Bahía de la Tempestad, con su orilla arenosa patrullada por múrlocs, makrura e hidras.",
			full = "La Torre de Eldara se alza en la punta nororiental de la tierra sobre la Bahía de la Tempestad, con su orilla arenosa patrullada por múrlocs, makrura e hidras. Perteneció en otro tiempo a la civilización de los elfos de la noche que se extendió por esta costa, pero ahora la torre está cerrada y abandonada.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Eldara",
		},
		["ursolan"] = {
			name = "Ursolan",
			short = "Ursolan debe su nombre a Ursol, el semidiós oso venerado por la raza fúrbolg. Ahora es el emplazamiento de un extenso asentamiento de fúrbolgs Fauces de Madera, que se extiende hacia el sur a través del Bastión hasta Cabeza de Oso.",
			full = "Ursolan debe su nombre a Ursol, el semidiós oso venerado por la raza fúrbolg. Ahora es el emplazamiento de un extenso asentamiento de fúrbolgs Fauces de Madera, que se extiende hacia el sur a través del Bastión hasta Cabeza de Oso.",
			source = "https://warcraft.wiki.gg/wiki/Ursolan",
		},
		["valormok"] = {
			name = "Valormok",
			short = "Valormok es un puesto de la Horda en Azshara, situado en el noroeste, al norte del Campamento Haldarr. Los guerreros destacados allí soportan tiempos difíciles, pero se aferran a su esperanza.",
			full = "Valormok es un puesto de la Horda en Azshara, situado en el noroeste, al norte del Campamento Haldarr. Los guerreros destacados allí soportan tiempos difíciles, pero se aferran a su esperanza.\n\nEsa esperanza fue traicionada desde dentro. Belgrom Destrozarroca había enviado a la magus Rimtori, una elfa de sangre, con una compañía de guerreros orcos a buscar riquezas y artefactos poderosos en la región. Rimtori encontró lo que buscaba y, en lugar de compartir el hallazgo, se volvió contra los guerreros que la habían escoltado, los mató y se quedó con el botín. Ag'tor Puñosangre, que dirige el campamento, no dejará sin respuesta la matanza. Busca guerreros que venguen a sus caídos y el orgullo herido de Destrozarroca, y que vean muerta a la magus Rimtori en su campamento cercano.",
			source = "https://warcraft.wiki.gg/wiki/Valormok",
		},
	},
	-- Frondavil: 18 subzones
	[1448] = {
		["bloodvenom falls"] = {
			name = "Cascadas del Veneno",
			short = "Las Cascadas del Veneno caen desde las alturas de Frondavil, con sus aguas contaminadas desde el nacimiento.",
			full = "Las Cascadas del Veneno caen desde las alturas de Frondavil, con sus aguas contaminadas desde el nacimiento. De aquí nace el Río del Veneno, que lleva la corrupción hacia abajo hasta desembocar en Costa Oscura como el enfermo Río Culebra.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Falls",
		},
		["bloodvenom post"] = {
			name = "Puesto del Veneno",
			short = "El Puesto del Veneno se alza en los altos acantilados sobre Costa Oscura, donde el Río del Veneno atraviesa Frondavil.",
			full = "El Puesto del Veneno se alza en los altos acantilados sobre Costa Oscura, donde el Río del Veneno atraviesa Frondavil. Su arquitectura y los tauren que lo custodian lo señalan como una fundación tauren, un pequeño punto de apoyo de la Horda que vigila la costa de abajo.\n\nSe llega a él por un sendero oscuro que sigue la orilla sur del río hacia el oeste desde el camino de piedra que atraviesa Frondavil, rodeando la ladera hasta el propio puesto.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Post",
		},
		["bloodvenom river"] = {
			name = "Río del Veneno",
			short = "El Río del Veneno corre negro por Frondavil, y su corrupción se extiende más allá de la región hasta reaparecer como el Río Culebra en Costa Oscura.",
			full = "El Río del Veneno corre negro por Frondavil, y su corrupción se extiende más allá de la región hasta reaparecer como el Río Culebra en Costa Oscura. Cienos nocivos se arrastran por sus orillas, y la fauna cercana se ha vuelto venenosa. Nadie bebe de él, y nadie nada en él.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_River",
		},
		["deadwood village"] = {
			name = "Aldea Muertobosque",
			short = "Los fúrbolgs Muertobosque construyeron su aldea en el sur de Frondavil tras muros de gruesos troncos, con estructuras más sólidas levantadas en el interior.",
			full = "Los fúrbolgs Muertobosque construyeron su aldea en el sur de Frondavil tras muros de gruesos troncos, con estructuras más sólidas levantadas en el interior. Como sus parientes de todo el bosque corrompido, sucumbieron a la corrupción de Frondavil y se volvieron hostiles y retorcidos.",
			source = "https://warcraft.wiki.gg/wiki/Deadwood_Village",
		},
		["emerald sanctuary"] = {
			name = "Santuario Esmeralda",
			short = "El Santuario Esmeralda se alza en el sureste de Frondavil, un campamento de los druidas del Círculo Esmeralda. Desde aquí vigilan Jaedenar y trabajan para sofocar la corrupción demoníaca que se extiende desde allí antes de que consuma más tierra.",
			full = "El Santuario Esmeralda se alza en el sureste de Frondavil, un campamento de los druidas del Círculo Esmeralda. Desde aquí vigilan Jaedenar y trabajan para sofocar la corrupción demoníaca que se extiende desde allí antes de que consuma más tierra.",
			source = "https://warcraft.wiki.gg/wiki/Emerald_Sanctuary",
		},
		["felpaw village"] = {
			name = "Poblado Zarpavil",
			short = "El Poblado Zarpavil se alza en el extremo norte de Frondavil, cerca de la entrada al Bastión Fauces de Madera.",
			full = "El Poblado Zarpavil se alza en el extremo norte de Frondavil, cerca de la entrada al Bastión Fauces de Madera. Pertenece a los Muertobosque, fúrbolgs a los que la corrupción ha separado de sus parientes, y su corrupción aún marca el terreno que ocupan.",
			source = "https://warcraft.wiki.gg/wiki/Felpaw_Village",
		},
		["irontree cavern"] = {
			name = "Caverna de Troncoferro",
			short = "En lo profundo de la cueva ha echado raíces la madera retorcida de los Alabeo, que ha dado origen a trituradores y desolladores de musgo que acechan en la oscuridad en lugar de cualquier guardián vivo.",
			full = "En lo profundo de la cueva ha echado raíces la madera retorcida de los Alabeo, que ha dado origen a trituradores y desolladores de musgo que acechan en la oscuridad en lugar de cualquier guardián vivo.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Cavern",
		},
		["irontree woods"] = {
			name = "Bosque de Troncoferro",
			short = "El Bosque de Troncoferro fue en otro tiempo un claro apacible en el norte de Frondavil, antes de que la corrupción de la Legión Ardiente lo retorciera hasta convertirlo en otra cosa.",
			full = "El Bosque de Troncoferro fue en otro tiempo un claro apacible en el norte de Frondavil, antes de que la corrupción de la Legión Ardiente lo retorciera hasta convertirlo en otra cosa. Tres grandes ancestros de los elfos de la noche vivían aquí, árboles vivientes llamados Hastat, Stoma y Vartrus. La corrupción no los perdonó: los tres quedaron petrificados donde estaban y siguen sepultados en el bosque, muertos entre la plaga que los mató.\n\nSin embargo, algo se ha negado a seguir muerto. El agua de una poza de la luna vertida en el corazón del bosque dio origen a un retoño. Cuidado y crecido, floreció, y luego regresó a la tierra donde nació, arraigado entre los muertos petrificados, a la espera de alzarse como un ancestro en su lugar.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Woods",
		},
		["jadefire glen"] = {
			name = "Cañada Fuego de Jade",
			short = "En los bosques corrompidos del sur de Frondavil, la Cañada Fuego de Jade alberga un campamento de sátiros, criaturas demoníacas que han hecho suya la hondonada corrompida, prosperan en medio de su podredumbre y extienden aún más la corrupción entre los árboles que los rodean.",
			full = "En los bosques corrompidos del sur de Frondavil, la Cañada Fuego de Jade alberga un campamento de sátiros, criaturas demoníacas que han hecho suya la hondonada corrompida, prosperan en medio de su podredumbre y extienden aún más la corrupción entre los árboles que los rodean.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Glen",
		},
		["jadefire run"] = {
			name = "Camino Fuego de Jade",
			short = "En el norte de Frondavil se encuentra el Camino Fuego de Jade, hogar de los sátiros más poderosos de la región. Conviene tener cautela al acercarse.",
			full = "En el norte de Frondavil se encuentra el Camino Fuego de Jade, hogar de los sátiros más poderosos de la región. Conviene tener cautela al acercarse. Sus construcciones siguen un diseño demoníaco y no mortal.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Run",
		},
		["jaedenar"] = {
			name = "Jaedenar",
			short = "Jaedenar surge de una tierra que en otro tiempo perteneció a los elfos de la noche, con piedras más antiguas que la corrupción que ahora las reclama.",
			full = "Jaedenar surge de una tierra que en otro tiempo perteneció a los elfos de la noche, con piedras más antiguas que la corrupción que ahora las reclama. Bajo sus ruinas se encuentran dos túmulos druídicos, sagrados en otro tiempo, y es sobre estos cimientos profanados donde el Consejo de la Sombra construyó su dominio, dando al propio lugar su nombre en adoración a Kil'jaeden el Impostor.\n\nDespués de la Tercera Guerra, las ruinas pasaron a manos de lord Pesadilla y del Consejo de la Sombra que él dirigía. Brujos orcos y Renegados llenaron sus salones, y no llegaron solos: súcubos, manáfagos, guardias viles y sátiros se movían entre ellos. En su corazón se alza la Guarida Sombría, sede del poder del Consejo en Azeroth, y a su lado el Santuario del Impostor, levantado en nombre de Kil'jaeden.",
			source = "https://warcraft.wiki.gg/wiki/Jaedenar",
		},
		["morlosaran"] = {
			name = "Morlos'Aran",
			short = "Morlos'Aran fue en otro tiempo un gran asentamiento de los elfos de la noche, levantado antes de que el Gran Cataclismo desgarrara el mundo.",
			full = "Morlos'Aran fue en otro tiempo un gran asentamiento de los elfos de la noche, levantado antes de que el Gran Cataclismo desgarrara el mundo. Ahora yace en ruinas en el extremo sur de Frondavil, uno más entre varios lugares así, como Ameth'Aran, Bashal'Aran, Ordil'Aran y Tethris'Aran, todos ellos ciudades prósperas en otro tiempo y todos ahora solo piedra y recuerdo de una edad dorada perdida hace mucho.",
			source = "https://warcraft.wiki.gg/wiki/Morlos'Aran",
		},
		["ruins of constellas"] = {
			name = "Ruinas de Constellas",
			short = "Las columnas rotas de aquí pertenecieron en otro tiempo a un asentamiento de los elfos de la noche cerca del Monte Hyjal. En su centro todavía descansa una poza de la luna, pero ya no contiene una luz limpia.",
			full = "Las columnas rotas de aquí pertenecieron en otro tiempo a un asentamiento de los elfos de la noche cerca del Monte Hyjal. En su centro todavía descansa una poza de la luna, pero ya no contiene una luz limpia. La corrupción vil ha empapado sus aguas, y el sátiro Xavathras la cuida ahora en nombre de Xavaric, cultivando la corrupción como un jardín destinado a envenenar. Más adentro de las ruinas, un muro de fuego cierra el paso hasta él.\n\nLos parientes druidas no han dejado a los demonios sin oposición, y los han atacado en un esfuerzo por arrancar el lugar de lo vil que ha echado raíces en él.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Constellas",
		},
		["shadow hold"] = {
			name = "Guarida Sombría",
			short = "Bajo Jaedenar, en el oeste de Frondavil, se extiende un laberinto que en otro tiempo fue un túmulo de los elfos de la noche. El Consejo de la Sombra lo reclamó hace mucho, y ahora los brujos y sus familiares demoníacos recorren sus túneles.",
			full = "Bajo Jaedenar, en el oeste de Frondavil, se extiende un laberinto que en otro tiempo fue un túmulo de los elfos de la noche. El Consejo de la Sombra lo reclamó hace mucho, y ahora los brujos y sus familiares demoníacos recorren sus túneles. El príncipe sátiro Xavalis y el señor del terror lord Pesadilla habitan ambos en su interior.\n\nEl paladín Trey Forjaluz y la elfa de la noche Arko'narin Starshade se adentraron en Frondavil en busca de señales de la obra del Consejo de la Sombra. Los cultistas los capturaron a ambos y los enjaularon dentro de la Guarida Sombría. Trey murió allí torturado, y sus captores retorcieron y corrompieron su espíritu. Arko'narin sigue enjaulada en las profundidades, vigilada por sus torturadores, esperando un rescate que aún no ha llegado.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Hold",
		},
		["shatter scar vale"] = {
			name = "Cañada Gran Cicatriz",
			short = "La Cañada Gran Cicatriz es el lugar donde cayeron los infernales cuando la Legión Ardiente arrasó Frondavil durante la Tercera Guerra. Los cráteres que dejaron aún humean y marcan la tierra, y los demonios todavía vagan entre ellos.",
			full = "La Cañada Gran Cicatriz es el lugar donde cayeron los infernales cuando la Legión Ardiente arrasó Frondavil durante la Tercera Guerra. Los cráteres que dejaron aún humean y marcan la tierra, y los demonios todavía vagan entre ellos.",
			source = "https://warcraft.wiki.gg/wiki/Shatter_Scar_Vale",
		},
		["shrine of the deceiver"] = {
			name = "Santuario del Impostor",
			short = "El Santuario del Impostor, un túmulo corrompido en Jaedenar, en Frondavil, toma su nombre de Kil'jaeden, el Impostor, señor de la Legión Ardiente.",
			full = "El Santuario del Impostor, un túmulo corrompido en Jaedenar, en Frondavil, toma su nombre de Kil'jaeden, el Impostor, señor de la Legión Ardiente. Los brujos del Consejo de la Sombra llenan sus profundidades, lo que lo convierte en un lugar peligroso para quienes no estén preparados.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Deceiver",
		},
		["talonbranch glade"] = {
			name = "Claro Ramaespolón",
			short = "El Claro Ramaespolón se encuentra en el norte de Frondavil, al sur del Bastión Fauces de Madera, a lo largo del sendero que continúa hacia el Claro de la Luna y Cuna del Invierno.",
			full = "El Claro Ramaespolón se encuentra en el norte de Frondavil, al sur del Bastión Fauces de Madera, a lo largo del sendero que continúa hacia el Claro de la Luna y Cuna del Invierno.",
			source = "https://warcraft.wiki.gg/wiki/Talonbranch_Glade",
		},
		["timbermaw hold"] = {
			name = "Bastión Fauces de Madera",
			short = "El Bastión Fauces de Madera, en el noreste de Frondavil, es la capital de la tribu de fúrbolgs Fauces de Madera. Sus túneles abren un paso hasta el Claro de la Luna y Cuna del Invierno.",
			full = "El Bastión Fauces de Madera, en el noreste de Frondavil, es la capital de la tribu de fúrbolgs Fauces de Madera. Sus túneles abren un paso hasta el Claro de la Luna y Cuna del Invierno.\n\nCuando la corrupción de la Legión Ardiente se infiltró en los bosques sagrados de Kalimdor, los fúrbolgs cayeron bajo su influencia y se sumieron en la locura. Solo la tribu Fauces de Madera escapó de aquella oscuridad, refugiada en su bastión mientras el bosque que amaba se convertía en una perversión purulenta de sí mismo. Incluso mucho después de que cayera el líder de los demonios, la corrupción de los bosques permaneció.\n\nLos fúrbolgs del Bastión Fauces de Madera desconfían de todos los forasteros, temiendo que los confundan con sus parientes corrompidos y los ataquen nada más verlos. Sin embargo, saben que no pueden resistir solos, y quienes se ganan su confianza descubren que los Fauces de Madera valoran la amistad por encima de todo. Por encima de todo, solo desean poner fin al sufrimiento de sus hermanos corrompidos y encontrar algún remedio para la herida en que se ha convertido Frondavil.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Cráter de Un'Goro: 9 subzones
	[1449] = {
		["fire plume ridge"] = {
			name = "Cresta del Penacho en Llamas",
			short = "La Cresta del Penacho en Llamas se alza en el corazón del Cráter de Un'Goro, una montaña de roca calcinada donde la lava se desliza por las laderas y los elementales de fuego se agitan en el calor.",
			full = "La Cresta del Penacho en Llamas se alza en el corazón del Cráter de Un'Goro, una montaña de roca calcinada donde la lava se desliza por las laderas y los elementales de fuego se agitan en el calor. Vetas poco profundas de magma corren bajo el suelo del cráter y alimentan las pozas de vapor y los géiseres que silban por todo Un'Goro, de modo que toda la cuenca parece respirar del fuego de la montaña.\n\nDentro de una cueva en la cima habita Correfuego, el más fuerte de los elementales de fuego que rondan la cresta, amo del corazón ardiente de la montaña. Los espíritus de fuego que parpadean y danzan aquí hablan de siglos ardiendo, apagándose hasta quedar en brasas y volviendo a encenderse, una y otra vez, sin fin.\n\nNo todos los que llegan a la cresta logran dominarla. Un viajero llamado Ringo vino a explorar sus laderas y se perdió, y el agotamiento por el calor lo venció. Todavía puede encontrársele en la cueva del sur, pues nunca logró salir.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Plume_Ridge",
		},
		["fungal rock"] = {
			name = "Roca Fungal",
			short = "La Roca Fungal se abre en la pared noreste del Cráter de Un'Goro, una caverna donde los gorilas viven entre los hongos fantasma que crecen en su oscuridad.",
			full = "La Roca Fungal se abre en la pared noreste del Cráter de Un'Goro, una caverna donde los gorilas viven entre los hongos fantasma que crecen en su oscuridad. Afuera, un pequeño estanque se forma bajo una cascada, y allí se encuentra el simio mecánico de Karna Tripirrem, Memo 01.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Rock",
		},
		["golakka hot springs"] = {
			name = "Baños de Golakka",
			short = "El vapor se eleva sin cesar de los Baños de Golakka, donde el corazón volcánico del Cráter de Un'Goro desangra su calor en pozas y géiseres en el oeste del cráter.",
			full = "El vapor se eleva sin cesar de los Baños de Golakka, donde el corazón volcánico del Cráter de Un'Goro desangra su calor en pozas y géiseres en el oeste del cráter. Elementales de furia nacidos de ese vapor y ese fuego recorren las orillas, arrancados de la tierra por las mismas fuerzas que mantienen hirviendo los baños.\n\nKrakle vino aquí en una ocasión para averiguar qué unía los baños termales con los fuegos de la cercana Cresta del Penacho en Llamas, antes de que su búsqueda lo llevara a otra parte.",
			source = "https://warcraft.wiki.gg/wiki/Golakka_Hot_Springs",
		},
		["ironstone plateau"] = {
			name = "Meseta Roca de Hierro",
			short = "La roca desnuda asoma entre el verdor de Un'Goro a lo largo de su pared noreste. La Meseta Roca de Hierro está tranquila en comparación con el resto del cráter, y en gran parte libre de depredadores.",
			full = "La roca desnuda asoma entre el verdor de Un'Goro a lo largo de su pared noreste. La Meseta Roca de Hierro está tranquila en comparación con el resto del cráter, y en gran parte libre de depredadores. Aquí anidan pterrordáctilos jóvenes, y la quietud de la meseta la distingue del inquieto crecimiento de Un'Goro.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Plateau",
		},
		["lakkari tar pits"] = {
			name = "Fosas de Alquitrán Lakkari",
			short = "Los lagos negros al norte del Refugio de Marshal se asientan densos y malolientes entre el verdor de Un'Goro. Los huesos sobresalen de la superficie por centenares, restos de bestias que entraron esperando suelo firme y no lo encontraron.",
			full = "Los lagos negros al norte del Refugio de Marshal se asientan densos y malolientes entre el verdor de Un'Goro. Los huesos sobresalen de la superficie por centenares, restos de bestias que entraron esperando suelo firme y no lo encontraron. Los carroñeros aguardan en los bordes a que el alquitrán termine lo que empezó, mientras bestias de alquitrán han surgido de las propias fosas.",
			source = "https://warcraft.wiki.gg/wiki/Lakkari_Tar_Pits",
		},
		["marshals refuge"] = {
			name = "Refugio de Marshal",
			short = "El Refugio de Marshal se encuentra en el extremo norte del Cráter de Un'Goro, levantado por las Expediciones Marshal bajo el mando de Williden y Hol'anyee Marshal.",
			full = "El Refugio de Marshal se encuentra en el extremo norte del Cráter de Un'Goro, levantado por las Expediciones Marshal bajo el mando de Williden y Hol'anyee Marshal. Su incursión en el cráter no estaba preparada para lo que encontró; las bestias de Un'Goro resultaron demasiado salvajes, y los campamentos base de la expedición fueron arrasados uno tras otro. Lo que quedó de la compañía huyó a terrenos más altos y escapó hasta aquí, al borde del cráter.\n\nEl refugio es lo que surgió de aquella retirada, un punto de apoyo apenas conservado más que conquistado.",
			source = "https://warcraft.wiki.gg/wiki/Marshal's_Refuge",
		},
		["marshlands"] = {
			name = "Los Pantanales",
			short = "El pantano se extiende por el sureste del Cráter de Un'Goro, una amplia extensión baja de agua estancada y vegetación maloliente que recibe a la mayoría de quienes bajan por primera vez al cráter desde Tanaris, pues cualquier otro acceso es traicionero.",
			full = "El pantano se extiende por el sureste del Cráter de Un'Goro, una amplia extensión baja de agua estancada y vegetación maloliente que recibe a la mayoría de quienes bajan por primera vez al cráter desde Tanaris, pues cualquier otro acceso es traicionero. Los raptores se mueven entre los juncos en gran número, y algunos llevan veneno en la mordedura.\n\nAquí pueden encontrarse cristales de poder azules, y su presencia ha impregnado el propio pantano, filtrándose en los raptores que cazan por el terreno húmedo y dejando en ellos su huella.\n\nEn un montículo que se alza sobre el agua, Torwa Abrecaminos monta guardia, tras haber llegado al lugar en canoa desde otra parte del cráter.",
			source = "https://warcraft.wiki.gg/wiki/Marshlands",
		},
		["slithering scar"] = {
			name = "La Cicatriz Serpenteante",
			short = "La Cicatriz Serpenteante se extiende por el sur del Cráter de Un'Goro, una colmena de la secta Gorishi.",
			full = "La Cicatriz Serpenteante se extiende por el sur del Cráter de Un'Goro, una colmena de la secta Gorishi.\n\nLa colmena tuvo en otro tiempo una reina, invocada al perturbar el Cristal Silítido Gorishi de su interior.",
			source = "https://warcraft.wiki.gg/wiki/Slithering_Scar",
		},
		["terror run"] = {
			name = "Camino del Terror",
			short = "En el Camino del Terror, al oeste de la Cicatriz Serpenteante, crecen del suelo cristales rojos que no se encuentran en ningún otro lugar del Cráter de Un'Goro. Las bestias del lugar han absorbido su poder, y se les nota.",
			full = "En el Camino del Terror, al oeste de la Cicatriz Serpenteante, crecen del suelo cristales rojos que no se encuentran en ningún otro lugar del Cráter de Un'Goro. Las bestias del lugar han absorbido su poder, y se les nota.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Run",
		},
	},
	-- Claro de la Luna: 5 subzones
	[1450] = {
		["lake eluneara"] = {
			name = "Lago Elune'ara",
			short = "Agua cristalina llena el corazón del Claro de la Luna, quieta como el vidrio bajo los árboles. Bajo su superficie yace Omen, el semidiós enloquecido, derrotado hace largos siglos y nunca del todo desaparecido de estas profundidades.",
			full = "Agua cristalina llena el corazón del Claro de la Luna, quieta como el vidrio bajo los árboles. Bajo su superficie yace Omen, el semidiós enloquecido, derrotado hace largos siglos y nunca del todo desaparecido de estas profundidades. El lago lo mantiene inmóvil, un peso silencioso bajo el agua tranquila.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Elune'ara",
		},
		["nighthaven"] = {
			name = "Amparo de la Noche",
			short = "A orillas del Lago Elune'ara se alza Amparo de la Noche, una aldea de cantería de los elfos de la noche y pozas de la luna, hogar de los druidas del Círculo Cenarion.",
			full = "A orillas del Lago Elune'ara se alza Amparo de la Noche, una aldea de cantería de los elfos de la noche y pozas de la luna, hogar de los druidas del Círculo Cenarion. Es un lugar tranquilo y apartado, cerrado a la mayoría de los forasteros, y su gente está entregada al druidismo y al cuidado de la naturaleza.\n\nSolo una vez al año Amparo de la Noche abre sus puertas, cuando se celebra el Festival Lunar y se lanzan fuegos artificiales sobre el lago en homenaje al poder de Elune, dando la bienvenida a forasteros que de otro modo nunca serían bien recibidos aquí.\n\nPero la aldea ha visto noches más oscuras que cualquier festival. Fue aquí donde el guardián Remulos se enfrentó al dragón de la Pesadilla Eranikus, corrompido y vuelto contra la aldea. Las criaturas de la Pesadilla cayeron sobre Amparo de la Noche, amenazando con destruirla por completo, hasta que por fin llegó Tyrande Susurravientos e invocó la luz de Elune para limpiar al dragón de la corrupción que se había apoderado de él. Las pozas de la luna todavía arden con esa misma luz.",
			source = "https://warcraft.wiki.gg/wiki/Nighthaven",
		},
		["shrine of remulos"] = {
			name = "Santuario de Remulos",
			short = "En el oeste del Claro de la Luna se alza el Santuario de Remulos, levantado en honor al guardián que vela por ese lugar. En su interior habita el elfo de la noche Tajarri, que guía a los jóvenes druidas que buscan aprender la forma acuática.",
			full = "En el oeste del Claro de la Luna se alza el Santuario de Remulos, levantado en honor al guardián que vela por ese lugar. En su interior habita el elfo de la noche Tajarri, que guía a los jóvenes druidas que buscan aprender la forma acuática.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Remulos",
		},
		["stormrage barrow dens"] = {
			name = "Túmulo de Tempestira",
			short = "Bajo el tranquilo césped del Claro de la Luna se encuentran los túmulos, hundidos en una tierra que muchos druidas elfos de la noche nunca abandonan del todo, con sus cuerpos en reposo mientras sus espíritus vagan por el Sueño Esmeralda.",
			full = "Bajo el tranquilo césped del Claro de la Luna se encuentran los túmulos, hundidos en una tierra que muchos druidas elfos de la noche nunca abandonan del todo, con sus cuerpos en reposo mientras sus espíritus vagan por el Sueño Esmeralda.\n\nFue aquí donde durmió en otro tiempo Malfurion Tempestira, y por eso los túmulos llevan su nombre. Cuando Tichondrius y sus señores del terror llegaron en la Tercera Guerra, atacaron a Malfurion donde yacía y estuvieron a punto de destrozar su túmulo. Fue Tyrande Susurravientos quien lo despertó y lo llamó de vuelta al mundo para enfrentarse a Archimonde y a la Legión Ardiente.\n\nDespués, cuando el Círculo Cenarion habló de hacer crecer un segundo Árbol del Mundo, Malfurion regresó a los túmulos para meditar. Tyrande vino más tarde a buscarlo y encontró su cuerpo inmóvil, como dormido, sin manera de despertarlo. El Círculo consideró más prudente no moverlo: si su espíritu todavía vagaba por el Sueño buscando el camino de vuelta, necesitaría encontrar el cuerpo donde lo había dejado. Así que permaneció allí, vigilado por el Círculo Cenarion y la Hermandad de Elune, con su cuerpo inmóvil en el túmulo que lleva su nombre.",
			source = "https://warcraft.wiki.gg/wiki/Stormrage_Barrow_Dens",
		},
		["timbermaw hold"] = {
			name = "Bastión Fauces de Madera",
			short = "El Bastión Fauces de Madera se alza en el noreste de Frondavil, donde un túnel se abre paso hasta el Claro de la Luna y Cuna del Invierno. Es la capital de la tribu de fúrbolgs Fauces de Madera.",
			full = "El Bastión Fauces de Madera se alza en el noreste de Frondavil, donde un túnel se abre paso hasta el Claro de la Luna y Cuna del Invierno. Es la capital de la tribu de fúrbolgs Fauces de Madera.\n\nCuando la corrupción de la Legión Ardiente se infiltró en los bosques sagrados de Kalimdor, los fúrbolgs cayeron bajo su influencia. Solo la tribu Fauces de Madera escapó de aquella oscuridad, refugiada en su bastión mientras veía, impotente, cómo el bosque que amaba se retorcía hasta convertirse en una perversión purulenta de sí mismo. Incluso después de que se destruyera el origen de aquella corrupción, la contaminación de los bosques permaneció.\n\nAhora los Fauces de Madera desconfían de todos los forasteros, temiendo que los confundan con sus parientes corrompidos y los ataquen nada más verlos. Sin embargo, saben que no pueden resistir solos, y quienes se ganan su confianza descubren que los Fauces de Madera valoran la amistad por encima de todo. Su tradición chamánica perdura, rica en la confección de armaduras de piel y en antiguos conocimientos de sanación. Por encima de todo, la tribu anhela poner fin al sufrimiento de sus parientes corrompidos, para que el antiguo bosque pueda volver a resonar algún día con los cantos y las risas que ha perdido.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Silithus: 19 subzones
	[1451] = {
		["bones of grakkarond"] = {
			name = "Huesos de Grakkarond",
			short = "En el centro de Silithus yacen los enormes huesos del dragón Grakkarond, que cayó allí durante la guerra del Mar de Dunas.",
			full = "En el centro de Silithus yacen los enormes huesos del dragón Grakkarond, que cayó allí durante la guerra del Mar de Dunas.",
			source = "https://warcraft.wiki.gg/wiki/Bones_of_Grakkarond",
		},
		["bronzebeard encampment"] = {
			name = "Campamento Barbabronce",
			short = "El Campamento Barbabronce se encuentra en el sur de Silithus, al este del Muro del Escarabajo.",
			full = "El Campamento Barbabronce se encuentra en el sur de Silithus, al este del Muro del Escarabajo.",
			source = "https://warcraft.wiki.gg/wiki/Bronzebeard_Encampment",
		},
		["cenarion hold"] = {
			name = "Fuerte Cenarion",
			short = "El Fuerte Cenarion se alzó en Silithus después de la guerra del Mar de Dunas, construido por el Círculo Cenarion sobre un antiguo asentamiento de los elfos de la noche.",
			full = "El Fuerte Cenarion se alzó en Silithus después de la guerra del Mar de Dunas, construido por el Círculo Cenarion sobre un antiguo asentamiento de los elfos de la noche. Es uno de los grandes bastiones druidas de Kalimdor, solo igualado en tamaño por el propio Claro de la Luna, y su propósito es único: resistir frente a los enjambres de silítidos y vigilar lo que yace enterrado bajo las arenas, el dios antiguo aprisionado C'Thun, para que sus ejércitos no vuelvan a alzarse.\n\nEs un lugar duro y asediado para vivir. Los silítidos presionan constantemente contra sus muros, y la región que lo rodea se vuelve cada vez más hostil. Aun así, los mercaderes del fuerte mantienen abiertos sus puestos y comercian con quien haga la larga subida desde el Cráter de Un'Goro, pues el comercio escasea tan lejos de todo, y cada moneda cuenta.\n\nEl camino hasta él serpentea hacia el noroeste desde Un'Goro, pasando junto al Montón Musgoso, y sube por la pared de un acantilado empinado que zigzaguea sobre sí misma antes de abrirse a los páramos abrasadores de Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Hold",
		},
		["crystal vale"] = {
			name = "La Vega de Cristal",
			short = "En el extremo noroeste de Silithus se encuentra el Valle de Cristal, un valle entregado a elementales de tierra y aire.",
			full = "En el extremo noroeste de Silithus se encuentra el Valle de Cristal, un valle entregado a elementales de tierra y aire. El torio abunda bajo su piedra, pero el terreno pertenece ante todo a los espíritus que se agitan allí, inquietos y antiguos. El alto señor Demitrian tiene un campamento dentro del valle.\n\nEs aquí donde puede invocarse a Thunderaan, el Hijo del Viento, y atarlo de nuevo a la hoja que lleva su furia, una obra de tormenta y voluntad que pocos se atreven a intentar y menos aún logran completar.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Vale",
		},
		["hiveashi"] = {
			name = "Colmen'Ashi",
			short = "Colmen'Ashi se encuentra en el norte de Silithus, y su prole de silítidos se extiende hasta infestar El Pilar de la Ascensión, más allá de sus límites.",
			full = "Colmen'Ashi se encuentra en el norte de Silithus, y su prole de silítidos se extiende hasta infestar El Pilar de la Ascensión, más allá de sus límites.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Ashi",
		},
		["hiveregal"] = {
			name = "Colmen'Regal",
			short = "En el sur de Silithus, los montículos de Colmen'Regal surgen de la arena, hogar de los silítidos, con túneles y quitina abundantes entre el polvo.",
			full = "En el sur de Silithus, los montículos de Colmen'Regal surgen de la arena, hogar de los silítidos, con túneles y quitina abundantes entre el polvo.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Regal",
		},
		["hivezora"] = {
			name = "Colmen'Zora",
			short = "Colmen'Zora es un nido de silítidos excavado en las arenas del oeste de Silithus.",
			full = "Colmen'Zora es un nido de silítidos excavado en las arenas del oeste de Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Zora",
		},
		["ortells hideout"] = {
			name = "Guarida de Ortell",
			short = "En el sureste de Silithus, una pequeña cueva se abre en las laderas, hogar de un ermitaño llamado Ortell.",
			full = "En el sureste de Silithus, una pequeña cueva se abre en las laderas, hogar de un ermitaño llamado Ortell.",
			source = "https://warcraft.wiki.gg/wiki/Ortell's_Hideout",
		},
		["ravaged twilight camp"] = {
			name = "Campamento Crepúsculo Devastado",
			short = "En el Valle de Cristal, en el noroeste de Silithus, se alza un campamento del Martillo Crepuscular, reclamado por el alto señor Demitrian.",
			full = "En el Valle de Cristal, en el noroeste de Silithus, se alza un campamento del Martillo Crepuscular, reclamado por el alto señor Demitrian.\n\nAquí permanece Demitrian, defendiendo este terreno para el culto.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Twilight_Camp",
		},
		["scarab dais"] = {
			name = "Estrado del Escarabajo",
			short = "El gong del Escarabajo se alza en el Estrado del Escarabajo, al noroeste del Muro del Escarabajo, a las puertas de Ahn'Qiraj, en el sur de Silithus.",
			full = "El gong del Escarabajo se alza en el Estrado del Escarabajo, al noroeste del Muro del Escarabajo, a las puertas de Ahn'Qiraj, en el sur de Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Dais",
		},
		["scarab wall"] = {
			name = "El Muro del Escarabajo",
			short = "El Muro del Escarabajo se extiende a lo largo del límite sur de Silithus y separa el desierto de la ciudad en ruinas de Ahn'Qiraj que hay al otro lado.",
			full = "El Muro del Escarabajo se extiende a lo largo del límite sur de Silithus y separa el desierto de la ciudad en ruinas de Ahn'Qiraj que hay al otro lado. Se levantó de la propia arena al final de la guerra del Mar de Dunas, y su mole de arenisca se eleva al menos treinta metros hacia el cielo. Por encima de esa altura, donde la piedra ya no podía subir más, el Vuelo Bronce tejió su magia en una barrera muchas veces más alta aún.\n\nQuienes lo crearon, elfos de la noche y dragones bronce juntos, lo llamaron Irana'ethil, Escudo contra la Sombra. El nombre dice claramente para qué servía: C'Thun y sus proles de silítidos quedaron sellados dentro de Ahn'Qiraj, y el muro se alzaba entre aquel horror y el resto del mundo.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Wall",
		},
		["southwind village"] = {
			name = "Aldea del Viento del Sur",
			short = "La Aldea del Viento del Sur fue en otro tiempo un puesto de los elfos de la noche en Silithus. No sobrevivió a la guerra del Mar de Dunas.",
			full = "La Aldea del Viento del Sur fue en otro tiempo un puesto de los elfos de la noche en Silithus. No sobrevivió a la guerra del Mar de Dunas.\n\nCuando los qiraji se alzaron en sus multitudes de enjambre, Valstann Corzocelada, hijo de Fandral Corzocelada, condujo a un destacamento del ejército de los elfos de la noche para defender la aldea. Sus tropas fueron masacradas allí mismo, y el propio Valstann fue capturado con vida por el general Rajaxx mientras la aldea que había sido enviado a defender quedaba destrozada a sus espaldas.\n\nLo que dejaron atrás los qiraji no ha permanecido vacío. Los espíritus de los druidas y las centinelas que cayeron en la masacre permanecen entre los restos, vagando sin propósito, atados al lugar de su muerte, siguiendo a la Sombra de Ambermoon. La Aldea del Viento del Sur no sigue en pie como una ruina tranquila, sino como un terreno embrujado, con sus muertos todavía sin haber terminado con ella.",
			source = "https://warcraft.wiki.gg/wiki/Southwind_Village",
		},
		["staghelm point"] = {
			name = "Punta de Corzocelada",
			short = "Una torre de los elfos de la noche coronaba en otro tiempo un pico del noreste de Silithus. Aquí Ralo'shan la Vigía Eterna mantiene su puesto, mientras un draco bronce de la prole de Nozdormu vuela en círculos en el cielo sobre ella.",
			full = "Una torre de los elfos de la noche coronaba en otro tiempo un pico del noreste de Silithus. Aquí Ralo'shan la Vigía Eterna mantiene su puesto, mientras un draco bronce de la prole de Nozdormu vuela en círculos en el cielo sobre ella. Camino abajo desde la torre se encuentra el Paseo Crepúsculo, una cueva que da refugio a cultistas del Martillo Crepuscular, con un pequeño campamento en su entrada, una amenaza con la que la vigía debe lidiar.",
			source = "https://warcraft.wiki.gg/wiki/Staghelm_Point",
		},
		["swarming pillar"] = {
			name = "El Pilar de la Ascensión",
			short = "El Pilar de la Ascensión se alza al sur del Fuerte Cenarion, un pico acribillado de túneles de silítidos, con sus laderas nunca quietas.",
			full = "El Pilar de la Ascensión se alza al sur del Fuerte Cenarion, un pico acribillado de túneles de silítidos, con sus laderas nunca quietas. Una nube de pequeños silítidos rodea la piedra a todas horas, una nube viviente que le dio su nombre al pilar, y bajo la arena, a sus pies, se encuentra una de las cámaras de la colmena, la mayor de los muchos nidos que horadan como un panal el suelo de Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Swarming_Pillar",
		},
		["twilight base camp"] = {
			name = "Campamento Crepúsculo",
			short = "El Campamento Crepúsculo es uno de los cuatro campamentos que el culto del Martillo Crepuscular ha levantado en los páramos de Silithus, un punto de apoyo para quienes sirven a la llegada de los dioses antiguos entre el polvo y la ruina de aquella tierra arrasada.",
			full = "El Campamento Crepúsculo es uno de los cuatro campamentos que el culto del Martillo Crepuscular ha levantado en los páramos de Silithus, un punto de apoyo para quienes sirven a la llegada de los dioses antiguos entre el polvo y la ruina de aquella tierra arrasada.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Base_Camp",
		},
		["twilight outpost"] = {
			name = "Avanzada Crepúsculo",
			short = "La Avanzada Crepúsculo se encuentra en el extremo suroeste de Silithus, cerca del Muro del Escarabajo, al oeste del Campamento Barbabronce. La ocupa el culto del Martillo Crepuscular.",
			full = "La Avanzada Crepúsculo se encuentra en el extremo suroeste de Silithus, cerca del Muro del Escarabajo, al oeste del Campamento Barbabronce. La ocupa el culto del Martillo Crepuscular.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Outpost",
		},
		["twilight post"] = {
			name = "Puesto Crepúsculo",
			short = "El Puesto Crepúsculo se encuentra en el noroeste de Silithus, al oeste del Fuerte Cenarion y al noroeste del Campamento Crepúsculo, un punto de apoyo reclamado por el Martillo Crepuscular en aquella tierra arrasada y azotada por el limo.",
			full = "El Puesto Crepúsculo se encuentra en el noroeste de Silithus, al oeste del Fuerte Cenarion y al noroeste del Campamento Crepúsculo, un punto de apoyo reclamado por el Martillo Crepuscular en aquella tierra arrasada y azotada por el limo.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Post",
		},
		["twilights run"] = {
			name = "Paseo Crepúsculo",
			short = "El Paseo Crepúsculo se oculta en la roca, en la base de la Punta de Corzocelada, en el norte de Silithus.",
			full = "El Paseo Crepúsculo se oculta en la roca, en la base de la Punta de Corzocelada, en el norte de Silithus. La boca de su cueva no deja adivinar lo que llena la oscuridad de más allá: cámara tras cámara entregadas al culto del Martillo Crepuscular, que ha hecho suya esta cavidad en la montaña, profunda e invisible, mientras el viento del desierto azota la piedra sobre ellos.",
			source = "https://warcraft.wiki.gg/wiki/Twilight's_Run",
		},
		["valors rest"] = {
			name = "Sosiego del Valor",
			short = "El Sosiego del Valor es un pequeño campamento en el límite de Silithus, al que se llega por el sendero que sube desde la esquina noroeste del Cráter de Un'Goro: el primer terreno que pisa un viajero al subir hacia las arenas.",
			full = "El Sosiego del Valor es un pequeño campamento en el límite de Silithus, al que se llega por el sendero que sube desde la esquina noroeste del Cráter de Un'Goro: el primer terreno que pisa un viajero al subir hacia las arenas.\n\nEl campamento lo cuidan miembros del Círculo Cenarion, que comparten el terreno con una infestación de insectos que resulta inquietantemente familiar. Tanto la Alianza como la Horda se refugian aquí de paso, y en su límite se alzan tumbas silenciosas.",
			source = "https://warcraft.wiki.gg/wiki/Valor's_Rest",
		},
	},
	-- Cuna del Invierno: 18 subzones
	[1452] = {
		["banthallow barrow den"] = {
			name = "Túmulo de Ban'Thallow",
			short = "Detrás de la Aldea Estrella Fugaz, en Cuna del Invierno, se encuentra el Túmulo de Ban'Thallow, un laberinto de túneles que guarda reliquias benditas muy apreciadas por la aldea.",
			full = "Detrás de la Aldea Estrella Fugaz, en Cuna del Invierno, se encuentra el Túmulo de Ban'Thallow, un laberinto de túneles que guarda reliquias benditas muy apreciadas por la aldea.",
			source = "https://warcraft.wiki.gg/wiki/Ban'Thallow_Barrow_Den",
		},
		["darkwhisper gorge"] = {
			name = "Garganta Negro Rumor",
			short = "La Garganta Negro Rumor se encuentra en el sur de Cuna del Invierno.",
			full = "La Garganta Negro Rumor se encuentra en el sur de Cuna del Invierno.\n\nCuando el ejército de la Legión Ardiente se estrelló contra el Monte Hyjal en la Tercera Guerra y Archimonde cayó, los demonios que sobrevivieron no desaparecieron del mundo. Huyeron a la Garganta Negro Rumor y se refugiaron allí, restos de una hueste que estuvo a punto de destruir el mundo, abandonados a pudrirse en la oscuridad.",
			source = "https://warcraft.wiki.gg/wiki/Darkwhisper_Gorge",
		},
		["dun mandarr"] = {
			name = "Dun Mandarr",
			short = "Dun Mandarr se encuentra cerca de una caverna helada en el sureste de Cuna del Invierno, y su nombre delata manos enanas. Ahora feroces lechúcicos lunares invaden el campamento, y poco más queda de quienes lo levantaron.",
			full = "Dun Mandarr se encuentra cerca de una caverna helada en el sureste de Cuna del Invierno, y su nombre delata manos enanas. Ahora feroces lechúcicos lunares invaden el campamento, y poco más queda de quienes lo levantaron.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Mandarr",
		},
		["everlook"] = {
			name = "Vista Eterna",
			short = "Vista Eterna se alza donde se cruzan las rutas comerciales de Cuna del Invierno, un puesto goblin del Cártel Bonvapor, con su laboratorio escondido entre los edificios.",
			full = "Vista Eterna se alza donde se cruzan las rutas comerciales de Cuna del Invierno, un puesto goblin del Cártel Bonvapor, con su laboratorio escondido entre los edificios.\n\nEl Alba Argenta envió aquí a Gregor Petragris para que defendiera sus intereses ante el gobierno local del Cártel.",
			source = "https://warcraft.wiki.gg/wiki/Everlook",
		},
		["frostfire hot springs"] = {
			name = "Baños de Fuego de Escarcha",
			short = "El vapor se eleva de una cadena de pozas en el extremo occidental de Cuna del Invierno, con agua demasiado caliente para la tierra helada que la rodea. Nadie ha explicado por qué los baños arden bajo la nieve y el hielo.",
			full = "El vapor se eleva de una cadena de pozas en el extremo occidental de Cuna del Invierno, con agua demasiado caliente para la tierra helada que la rodea. Nadie ha explicado por qué los baños arden bajo la nieve y el hielo. Donova Cubilnevado, que acampa cerca, se pregunta si alguna corrupción demoníaca que se filtra hacia el norte desde la Garganta Negro Rumor habrá llegado hasta aquí para calentar la piedra.\n\nLa poza más cercana al Bastión Fauces de Madera nunca se ha librado del dominio de la tribu Nevada. Todavía la ocupan, y los fúrbolgs no están dispuestos a compartir el calor que han reclamado.",
			source = "https://warcraft.wiki.gg/wiki/Frostfire_Hot_Springs",
		},
		["frostsaber rock"] = {
			name = "Roca Sable de Hielo",
			short = "En lo alto de la Roca Sable de Hielo se encuentra Rivern Ventogélido, guardián del vínculo entre los sables de hielo y quienes quieren montarlos.",
			full = "En lo alto de la Roca Sable de Hielo se encuentra Rivern Ventogélido, guardián del vínculo entre los sables de hielo y quienes quieren montarlos. Enseña a los amigos de la Alianza que se lo ganan a domar y montar a los grandes felinos blancos que merodean por la piedra helada de abajo.",
			source = "https://warcraft.wiki.gg/wiki/Frostsaber_Rock",
		},
		["frostwhisper gorge"] = {
			name = "Cañón Levescarcha",
			short = "El Cañón Levescarcha atraviesa el sur de Cuna del Invierno, con su fondo y sus crestas salpicados de ruinas de los elfos de la noche. Entre estas viejas piedras habitan los gigantes Machacahielo y sus enormes preservadores.",
			full = "El Cañón Levescarcha atraviesa el sur de Cuna del Invierno, con su fondo y sus crestas salpicados de ruinas de los elfos de la noche. Entre estas viejas piedras habitan los gigantes Machacahielo y sus enormes preservadores.",
			source = "https://warcraft.wiki.gg/wiki/Frostwhisper_Gorge",
		},
		["hidden grove"] = {
			name = "La Arboleda Oculta",
			short = "La Arboleda Oculta se hunde dentro de un cráter en Cuna del Invierno, cercada por todos lados por acantilados escarpados.",
			full = "La Arboleda Oculta se hunde dentro de un cráter en Cuna del Invierno, cercada por todos lados por acantilados escarpados. Solo una cueva, excavada en la cresta sureste, ofrece un paso, y bajar desde las alturas es un camino que pocos se atreverían a tomar.\n\nEn otro tiempo esta hondonada no albergaba nada más temible que liebres blancas, que prosperaban sin que nadie las molestara en su refugio. Eso ha cambiado desde entonces. Ahora los lechúcicos lunares reclaman la arboleda, hostiles con cualquiera que entre, y su presencia ha sellado el lugar con tanta seguridad como sus acantilados.",
			source = "https://warcraft.wiki.gg/wiki/Hidden_Grove",
		},
		["ice thistle hills"] = {
			name = "Colinas Cardo Nevado",
			short = "Las Colinas Cardo Nevado se alzan al sureste de Vista Eterna, hogar de los yetis Cardo Nevado, que tienen su guarida en una cueva que sube por la ladera y recorren las pendientes que la rodean.",
			full = "Las Colinas Cardo Nevado se alzan al sureste de Vista Eterna, hogar de los yetis Cardo Nevado, que tienen su guarida en una cueva que sube por la ladera y recorren las pendientes que la rodean. Su espeso pelaje y sus cuernos pálidos son muy apreciados por quienes desafían el frío para conseguirlos.\n\nLa hierba gélida crece por las laderas abiertas, y dentro de la cueva hay vetas de torio que atraviesan la roca. Lo más raro de todo: justo en el borde de la cueva, se dice que a veces florece un loto negro, frágil y extraño en el territorio de los yetis.",
			source = "https://warcraft.wiki.gg/wiki/Ice_Thistle_Hills",
		},
		["lake keltheril"] = {
			name = "Lago Kel'Theril",
			short = "Las aguas heladas del Lago Kel'Theril descansan quietas en el corazón de Cuna del Invierno, rodeadas por las ruinas que comparten su nombre.",
			full = "Las aguas heladas del Lago Kel'Theril descansan quietas en el corazón de Cuna del Invierno, rodeadas por las ruinas que comparten su nombre. Las ruinas son antigua obra de los Altonato, y quienes habitaron allí no se marcharon cuando cayeron sus salones. Sus espíritus todavía permanecen, atormentados, vagando sobre el hielo y la piedra rota.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Kel'Theril",
		},
		["mazthoril"] = {
			name = "Mazthoril",
			short = "En lo profundo del hielo de Cuna del Invierno, cerca del Lago Kel'Theril, la caverna de Mazthoril se abre bajo la tierra, fría, vasta y cargada de magia.",
			full = "En lo profundo del hielo de Cuna del Invierno, cerca del Lago Kel'Theril, la caverna de Mazthoril se abre bajo la tierra, fría, vasta y cargada de magia. Aquí habita una prole de dragones azules leales a Malygos, y aquí su matriarca mantiene su vigilia solitaria.\n\nHaleh rara vez adopta una forma que el mundo llamaría verdadera, y solo se muestra como una alta elfa de pie en el punto más alto de la caverna, al que se llega a través de una runa de paso grabada en el suelo, muy abajo. Pocos que no sean de su propia especie llegan a ver su rostro.\n\nA su alrededor ha dispuesto una guardia digna de su vida retirada. Cuatro poderosos dracos responden solo ante ella. Spellmaw recorre un circuito lento e ininterrumpido por un tercio de las zonas bajas de Cuna del Invierno, mientras Manaclaw y Scryer vigilan las runas al fondo de la caverna como centinelas ante una puerta cerrada.",
			source = "https://warcraft.wiki.gg/wiki/Mazthoril",
		},
		["moon horror den"] = {
			name = "Cubil del Horror de la Luna",
			short = "A poca distancia al noreste de las puertas de Vista Eterna, el terreno se eleva hacia una pequeña cueva conocida como el Cubil del Horror de la Luna, hogar de feroces lechúcicos enfurecidos.",
			full = "A poca distancia al noreste de las puertas de Vista Eterna, el terreno se eleva hacia una pequeña cueva conocida como el Cubil del Horror de la Luna, hogar de feroces lechúcicos enfurecidos. Una montaña se interpone entre el cubil y el Poblado Nevada, al sur, por muy cerca que parezcan ambos lugares, de modo que no hay ningún camino directo entre ellos, solo un largo rodeo alrededor de las alturas.",
			source = "https://warcraft.wiki.gg/wiki/Moon_Horror_Den",
		},
		["owl wing thicket"] = {
			name = "Matorral del Ala del Búho",
			short = "Las cuevas del Matorral del Ala del Búho atraviesan el sur de Cuna del Invierno, hogar de lechúcicos enloquecidos, tocados por la luna y furiosos.",
			full = "Las cuevas del Matorral del Ala del Búho atraviesan el sur de Cuna del Invierno, hogar de lechúcicos enloquecidos, tocados por la luna y furiosos. Se dice que los antiguos Guardianes de Elune cuentan aquí cómo llegaron al mundo los primeros lechúcicos lunares, un relato que conserva Ranshalla.",
			source = "https://warcraft.wiki.gg/wiki/Owl_Wing_Thicket",
		},
		["ruins of keltheril"] = {
			name = "Las Ruinas de Kel'Theril",
			short = "Las Ruinas de Kel'Theril yacen destrozadas en las orillas del lago que lleva su nombre, todo lo que queda de una gran ciudad de los elfos de la noche.",
			full = "Las Ruinas de Kel'Theril yacen destrozadas en las orillas del lago que lleva su nombre, todo lo que queda de una gran ciudad de los elfos de la noche. Cayó durante el Gran Cataclismo, cuando el propio mundo se desgarró, y nunca volvió a levantarse.\n\nLo que permanece allí ahora es un dolor que no descansa. Los Altonato que murieron cuando cayó Kel'Theril no siguieron su camino; sus espíritus permanecen entre las columnas caídas de las ruinas del norte, atormentados, incapaces de soltar lo que perdieron. Fantasmas de altos elfos rondan la sección oriental, entre ellos forestales traicionados y un archimago.\n\nUn cristal llamado Zin-Malor está ligado a la caída de este lugar, unido a una destrucción que se tragó aquí a generación tras generación de elfos. Esa historia pertenece a la propia Kel'Theril, a la piedra caída y a los fantasmas que todavía caminan entre ella.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Kel'Theril",
		},
		["starfall village"] = {
			name = "Aldea Estrella Fugaz",
			short = "La Aldea Estrella Fugaz se alza a lo largo del camino que atraviesa Cuna del Invierno, el único lugar de aquella tierra fría donde la Alianza mantiene un punto de apoyo.",
			full = "La Aldea Estrella Fugaz se alza a lo largo del camino que atraviesa Cuna del Invierno, el único lugar de aquella tierra fría donde la Alianza mantiene un punto de apoyo. Una cabaña de los elfos de la noche y una casa más pequeña forman el asentamiento, y cerca se encuentra el Túmulo de Ban'Thallow, hundido en la tierra como los montículos funerarios de los que toma su nombre.",
			source = "https://warcraft.wiki.gg/wiki/Starfall_Village",
		},
		["timbermaw hold"] = {
			name = "Bastión Fauces de Madera",
			short = "El Bastión Fauces de Madera se encuentra en los túneles del norte de Frondavil, el paso que se abre al Claro de la Luna y a Cuna del Invierno, y es el último bastión de la tribu de fúrbolgs Fauces de Madera.",
			full = "El Bastión Fauces de Madera se encuentra en los túneles del norte de Frondavil, el paso que se abre al Claro de la Luna y a Cuna del Invierno, y es el último bastión de la tribu de fúrbolgs Fauces de Madera.\n\nCuando la corrupción de la Legión Ardiente se infiltró en los bosques sagrados de Kalimdor, los fúrbolgs de aquella tierra cayeron bajo ella, retorcidos hasta volverse salvajes y crueles. Solo la tribu Fauces de Madera escapó de ese destino, aferrada a sus túneles mientras el bosque que amaba se convertía a su alrededor en una perversión purulenta de sí mismo. Incluso después de que se destruyera el origen de la corrupción, la contaminación de los bosques no desapareció.\n\nLos Fauces de Madera siguen desconfiando de todos los forasteros, temiendo que los confundan con sus parientes corrompidos y los abatan antes de que puedan demostrar lo contrario. Sin embargo, saben que no pueden resistir solos, y con quienes se ganan su confianza son generosos: se aferran a los antiguos caminos chamánicos y comparten libremente los conocimientos de sanación que conservan. Lo que más desean es poner fin al sufrimiento de sus hermanos corrompidos y encontrar un remedio para las heridas que ha sufrido Frondavil.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
		["timbermaw post"] = {
			name = "Puesto de los Fauces de Madera",
			short = "El Puesto de los Fauces de Madera conserva un nombre que ya no le corresponde.",
			full = "El Puesto de los Fauces de Madera conserva un nombre que ya no le corresponde. El campamento perteneció en otro tiempo a la tribu Fauces de Madera, pero ahora responde ante los fúrbolgs Nevada corrompidos, que lo ocupan por completo, al sureste de los Baños de Fuego de Escarcha y al oeste del Lago Kel'Theril.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Post",
		},
		["winterfall village"] = {
			name = "Poblado Nevada",
			short = "El Poblado Nevada trepa por las laderas orientales de Cuna del Invierno, cerca de Vista Eterna, y sus fúrbolgs están corrompidos desde hace mucho. En su cima hay una pequeña cueva, sede del Gran Jefe Nevada, que gobierna el asentamiento desde allí.",
			full = "El Poblado Nevada trepa por las laderas orientales de Cuna del Invierno, cerca de Vista Eterna, y sus fúrbolgs están corrompidos desde hace mucho. En su cima hay una pequeña cueva, sede del Gran Jefe Nevada, que gobierna el asentamiento desde allí.",
			source = "https://warcraft.wiki.gg/wiki/Winterfall_Village",
		},
	},
	-- Ciudad de Ventormenta: 3 subzones
	[1453] = {
		["champions hall"] = {
			name = "Sala de los Campeones",
			short = "En el sur del Casco Antiguo de la Ciudad de Ventormenta se alza la Sala de los Campeones, donde se alojan los oficiales de la Alianza, apartados dentro de la vieja ciudad como corresponde a su rango.",
			full = "En el sur del Casco Antiguo de la Ciudad de Ventormenta se alza la Sala de los Campeones, donde se alojan los oficiales de la Alianza, apartados dentro de la vieja ciudad como corresponde a su rango.",
			source = "https://warcraft.wiki.gg/wiki/Champions'_Hall",
		},
		["deeprun tram"] = {
			name = "Tranvía Subterráneo",
			short = "El rey Magni Barbabronce no construyó el Tranvía Subterráneo por comodidad.",
			full = "El rey Magni Barbabronce no construyó el Tranvía Subterráneo por comodidad. En los años posteriores a la Segunda Guerra, mientras Ventormenta se esforzaba por reconstruirse de sus ruinas, a Magni le impacientaba la lentitud con que la ayuda de Forjaz llegaba a sus aliados humanos, y le inquietaba la lentitud con que los soldados enanos podrían llegar hasta ellos si volvía la guerra. Recurrió al Manitas Mayor Gelbin Mekkatorque, el ingeniero más estimado de Azeroth, y le encomendó el problema. La respuesta de Mekkatorque fue un ferrocarril tendido bajo la propia tierra, que unía directamente ambas capitales.\n\nLos constructores se toparon con un lago subterráneo en el trayecto del túnel, y no lo rodearon. El tranvía todavía lo atraviesa, con sus vías cerradas pasando por debajo del agua en lugar de a su lado.\n\nLos gnomos atienden el tranvía a diario y mantienen sus dos convoyes de tres vagones circulando rápidos y sin tropiezos entre Forjaz y Ventormenta, gratis para todos los que cruzan los andenes subterráneos.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["valley of heroes"] = {
			name = "Valle de los Héroes",
			short = "Un puente de piedra clara lleva a todo viajero sobre el foso que hay ante la puerta sur de Ventormenta, hasta un valle verde flanqueado por estatuas levantadas tanto por el dolor como por la gloria.",
			full = "Un puente de piedra clara lleva a todo viajero sobre el foso que hay ante la puerta sur de Ventormenta, hasta un valle verde flanqueado por estatuas levantadas tanto por el dolor como por la gloria.\n\nDespués de la Segunda Guerra, cuando Ventormenta se reconstruyó de sus ruinas, la ciudad honró a quienes dirigieron la Expedición de la Alianza a través del Portal Oscuro para sellarlo desde el otro lado. Kurdran Martillo Salvaje y el archimago Khadgar se alzan a la izquierda del camino; el comandante de fuerzas Danath Aterratrols y la capitana forestal Alleria Brisaveloz, a la derecha; y al final del camino, donde se bifurca para entrar en la ciudad propiamente dicha, se alza el general Turalyon, que los dirigió a todos. Ninguno de los cinco regresó jamás.\n\nAños después, Arator, el hijo de Alleria y Turalyon, fue llevado a una ceremonia en el valle, a hombros de un Caballero de la Mano de Plata. Alzó la vista hacia la imagen de piedra de su madre, un rostro del que no guardaba recuerdo. Algo de ella llegó hasta él allí, pues el niño sonrió y tendió la mano hacia la estatua. Volvería una y otra vez a medida que crecía, para detenerse ante su rostro y saber, sin recordarla, que ella lo había amado.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Heroes",
		},
	},
	-- Orgrimmar: 2 subzones
	[1454] = {
		["hall of legends"] = {
			name = "Sala de las Leyendas",
			short = "La Sala de las Leyendas se alza en el Valle de la Fuerza, en Orgrimmar: el cuartel donde los oficiales de la Horda celebran sus consejos.",
			full = "La Sala de las Leyendas se alza en el Valle de la Fuerza, en Orgrimmar: el cuartel donde los oficiales de la Horda celebran sus consejos.\n\nEn su centro hay una mesa cubierta de mapas de Azeroth.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Legends",
		},
		["ragefire chasm"] = {
			name = "Sima Ígnea",
			short = "Bajo Orgrimmar, la tierra se abre en una sima ardiente, con sus túneles ahogados en lava y humo. Los troggs han empezado a subir desde las profundidades por aquí, un clan al que la Horda llegó a llamar los troggs de la Sima Ígnea.",
			full = "Bajo Orgrimmar, la tierra se abre en una sima ardiente, con sus túneles ahogados en lava y humo. Los troggs han empezado a subir desde las profundidades por aquí, un clan al que la Horda llegó a llamar los troggs de la Sima Ígnea. Magatha la Vidente, de los tauren, intentó hacer las paces con ellos, con la esperanza de apartarlos de la ciudad de arriba. Solo encontró hostilidad. Quedó claro que estas criaturas no tenían ningún interés en la diplomacia y que, si no se las detenía, podrían arrollar por completo a la Horda.\n\nPeor aún, la conspiración llegaba hasta la propia Orgrimmar. Neeru Hojafuego, que ocultaba su verdadera lealtad como líder del Filo Ardiente, atrajo a la sima a los propios seguidores leales de Thrall y se los entregó a una secta de cultistas oscuros que se refugiaba allí, tanto para deshacerse de ellos como para comprobar si podía confiar en los cultistas. Thrall sabe de la traición más de lo que deja ver, pero los líderes de los cultistas todavía ocupan las cavernas que han reclamado como propias.",
			source = "https://warcraft.wiki.gg/wiki/Ragefire_Chasm",
		},
	},
	-- Forjaz: 2 subzones
	[1455] = {
		["deeprun tram"] = {
			name = "Tranvía Subterráneo",
			short = "El rey Magni Barbabronce no construyó el Tranvía Subterráneo por comodidad.",
			full = "El rey Magni Barbabronce no construyó el Tranvía Subterráneo por comodidad. En los años posteriores a la Segunda Guerra, mientras Ventormenta se esforzaba por reconstruirse de sus ruinas, a Magni le impacientaba la lentitud con que la ayuda de Forjaz llegaba a sus aliados humanos, y le inquietaba la lentitud con que los soldados enanos podrían llegar hasta ellos si volvía la guerra. Recurrió al Manitas Mayor Gelbin Mekkatorque, el ingeniero más estimado de Azeroth, y le encomendó el problema. La respuesta de Mekkatorque fue un ferrocarril tendido bajo la propia tierra, que unía directamente ambas capitales.\n\nLos constructores se toparon con un lago subterráneo en el trayecto del túnel, y no lo rodearon. El tranvía todavía lo atraviesa, con sus vías cerradas pasando por debajo del agua en lugar de a su lado.\n\nLos gnomos atienden el tranvía a diario y mantienen sus dos convoyes de tres vagones circulando rápidos y sin tropiezos entre Forjaz y Ventormenta, gratis para todos los que cruzan los andenes subterráneos.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["gates of ironforge"] = {
			name = "Puertas de Forjaz",
			short = "Las Puertas de Forjaz se alzan donde la gran rampa de Dun Morogh sube al encuentro de la montaña, visibles a kilómetros de distancia sobre la nieve mucho antes de que un viajero llegue a ellas.",
			full = "Las Puertas de Forjaz se alzan donde la gran rampa de Dun Morogh sube al encuentro de la montaña, visibles a kilómetros de distancia sobre la nieve mucho antes de que un viajero llegue a ellas. Son el umbral entre las tierras enanas abiertas y la propia Forjaz.\n\nAl cruzarlas, uno queda bajo la mirada de una enorme estatua erigida en honor al gran rey Modimus Yunquemar, colocada para vigilar justo detrás de la entrada, de modo que nadie entre en la ciudad sin pasar antes bajo sus ojos.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
	},
	-- Cima del Trueno: 4 subzones
	[1456] = {
		["elder rise"] = {
			name = "Alto de los Ancestros",
			short = "El Alto de los Ancestros se alza al este de la meseta central, y se llega a él por puentes de cuerda desde la meseta alta y la meseta media.",
			full = "El Alto de los Ancestros se alza al este de la meseta central, y se llega a él por puentes de cuerda desde la meseta alta y la meseta media. Aquí tiene su hogar el Círculo Cenarion, donde se reúnen los druidas y sacerdotes tauren, y aquí reside el archidruida Hamuul Tótem de Runa. El Consejo de Ancestros también ejerce aquí su gobierno.\n\nEntre los dos puentes se alza una choza reclamada por Magatha Tótem Siniestro, líder de la tribu Tótem Siniestro.",
			source = "https://warcraft.wiki.gg/wiki/Elder_Rise",
		},
		["hunter rise"] = {
			name = "Alto de los Cazadores",
			short = "La meseta sur de Cima del Trueno pertenece a quienes luchan y a quienes cazan.",
			full = "La meseta sur de Cima del Trueno pertenece a quienes luchan y a quienes cazan. Aquí se alza la Sala de los Cazadores, donde los tauren adiestran a sus guerreros y cazadores, y donde tramperos, rastreadores y curtidores ejercen sus oficios. Los puentes de cuerda unen la meseta con los caminos de arriba y de abajo y la integran en el resto de la cima.",
			source = "https://warcraft.wiki.gg/wiki/Hunter_Rise",
		},
		["pools of vision"] = {
			name = "Pozas de las Visiones",
			short = "Bajo la cima del Alto de los Espíritus, un túnel se abre a unas aguas oscuras y quietas conocidas como los Estanques de la Visión.",
			full = "Bajo la cima del Alto de los Espíritus, un túnel se abre a unas aguas oscuras y quietas conocidas como los Estanques de la Visión. Los Renegados mantienen aquí un punto de apoyo, en lo profundo del territorio tauren, un centro para sus magos y sacerdotes, con una emisaria de los Rapiñadores Renegados que busca reclutas para la batalla entre los estanques.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Vision",
		},
		["spirit rise"] = {
			name = "Alto de los Espíritus",
			short = "El Alto de los Espíritus se alza al noroeste de la meseta central, dedicado al estudio chamánico entre los tauren. La tribu Cazacielo tiene aquí su influencia.",
			full = "El Alto de los Espíritus se alza al noroeste de la meseta central, dedicado al estudio chamánico entre los tauren. La tribu Cazacielo tiene aquí su influencia. Bajo la superficie de la meseta se encuentran los Estanques de la Visión, con sus aguas calentadas por vapor oculto. Los puentes de cuerda bajan hasta las mesetas baja y media y unen las alturas entre sí.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Rise",
		},
	},
	-- Darnassus: 5 subzones
	[1457] = {
		["cenarion enclave"] = {
			name = "Enclave Cenarion",
			short = "El Enclave Cenarion se encuentra en el noroeste de Darnassus, una arboleda circular donde robles y fresnos se alzan más altos que los salones de piedra del resto de la ciudad.",
			full = "El Enclave Cenarion se encuentra en el noroeste de Darnassus, una arboleda circular donde robles y fresnos se alzan más altos que los salones de piedra del resto de la ciudad. Cada árbol de aquí lleva runas que no están talladas, sino que han crecido de la corteza viva, y los lugares de reunión de la arboleda están hechos de madera y piedra trabajadas juntas, como si se hubieran hecho crecer en lugar de construirse.\n\nEste ha sido siempre la sede de los druidas de la ciudad, del mismo modo que el Templo de la Luna es la sede de sus sacerdotes. El archidruida Fandral Corzocelada los dirige desde las ramas del Enclave, y la mayor de sus estructuras vivientes, que se alza en el corazón de la arboleda, es su propia residencia.\n\nLa arboleda sigue sirviendo a la orden que se reúne bajo ella: los druidas vienen aquí a aprender los antiguos caminos, los cazadores se entrenan en su árbol más oriental, y al pie del gran árbol del Enclave se puede aprender a montar los sables de la noche que llevan a los jinetes de Darnassus por las tierras salvajes. Bajo tierra, oculta dentro de la rama más occidental, una discreta hermandad de pícaros tiene sus aposentos, que solo conocen quienes ya saben dónde buscar.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Enclave",
		},
		["craftsmens terrace"] = {
			name = "Bancal del Artesano",
			short = "El Bancal del Artesano se encuentra en el norte de Darnassus, dedicado al comercio y no a la guerra ni al culto. Aquí los artesanos de la ciudad tienen sus tiendas, y los viajeros cansados pueden refugiarse en una de las posadas de Darnassus.",
			full = "El Bancal del Artesano se encuentra en el norte de Darnassus, dedicado al comercio y no a la guerra ni al culto. Aquí los artesanos de la ciudad tienen sus tiendas, y los viajeros cansados pueden refugiarse en una de las posadas de Darnassus. También se alza aquí una embajada de El Alba Argenta, una presencia extranjera a la que se ha concedido un lugar dentro de la ciudad élfica.\n\nEl bancal limita con el Bancal del Guerrero al sur y con el Enclave Cenarion al oeste.",
			source = "https://warcraft.wiki.gg/wiki/Craftsmen's_Terrace",
		},
		["temple gardens"] = {
			name = "Los Jardines del Templo",
			short = "En el corazón de Darnassus se encuentran los Jardines del Templo, una amplia extensión de agua, pasarelas y pequeñas islas que toman su nombre del gran Templo de la Luna que se alza justo al sur.",
			full = "En el corazón de Darnassus se encuentran los Jardines del Templo, una amplia extensión de agua, pasarelas y pequeñas islas que toman su nombre del gran Templo de la Luna que se alza justo al sur. Los puentes se extienden en todas direcciones y unen el Enclave Cenarion al norte, los bancales del Artesano, del Guerrero y de los Mercaderes al este, y el Templo de la Luna al sur, de modo que todos los caminos de la ciudad parecen confluir aquí.\n\nLa isla más grande alberga el banco de la ciudad, y un portal en el extremo occidental de los jardines ofrece paso hasta la Aldea Rut'theran, al pie del Árbol del Mundo, lo que convierte este tranquilo centro de agua y piedra también en el umbral entre Darnassus y el mundo exterior.",
			source = "https://warcraft.wiki.gg/wiki/Temple_Gardens",
		},
		["tradesmens terrace"] = {
			name = "Bancal de los Mercaderes",
			short = "El Bancal de los Mercaderes se encuentra en el sur de Darnassus, donde los tenderos tienen sus puestos y los comerciantes se reúnen para regatear, lo que lo convierte en el corazón del comercio de toda la ciudad.",
			full = "El Bancal de los Mercaderes se encuentra en el sur de Darnassus, donde los tenderos tienen sus puestos y los comerciantes se reúnen para regatear, lo que lo convierte en el corazón del comercio de toda la ciudad. Por el norte se abre al Bancal del Guerrero, y al oeste los senderos llevan hacia el Templo de la Luna y los Jardines del Templo.\n\nSus edificios han crecido de la madera, a la manera de los elfos de la noche, ligeros y elegantes.",
			source = "https://warcraft.wiki.gg/wiki/Tradesmen's_Terrace",
		},
		["warriors terrace"] = {
			name = "Bancal del Guerrero",
			short = "El Bancal del Guerrero alberga la puerta oriental de Darnassus, donde la ciudad se abre a las tierras salvajes de Teldrassil.",
			full = "El Bancal del Guerrero alberga la puerta oriental de Darnassus, donde la ciudad se abre a las tierras salvajes de Teldrassil. Aquí las centinelas tienen su terreno, y cualquier elfo de la noche que quiera tomar las armas al servicio de la ciudad viene a este bancal para hacerlo, practicando en los campos de tiro y en los terrenos de duelo hasta que su habilidad está lista para la guerra.\n\nJinetes sobre sables de la noche vigilan las puertas, y el bancal se alza como el escudo de la ciudad contra cualquier violencia que pueda subir por el camino desde el bosque.\n\nLimita con el Bancal del Artesano al norte, el Bancal de los Mercaderes al sur y los Jardines del Templo al oeste, de modo que un guerrero que se entrena aquí está al alcance de la voz de los artesanos, los mercaderes y los sacerdotes de la ciudad por igual.",
			source = "https://warcraft.wiki.gg/wiki/Warrior's_Terrace",
		},
	},
	-- Entrañas: 1 subzones
	[1458] = {
		["ruins of lordaeron"] = {
			name = "Ruinas de Lordaeron",
			short = "Sobre la ciudad sepultada, el palacio de Lordaeron sigue en pie, con sus salones abiertos al cielo y sus jardines en ruinas. Aquí murió el gran reino de la Alianza, y aquí sus fantasmas nunca se han ido del todo.",
			full = "Sobre la ciudad sepultada, el palacio de Lordaeron sigue en pie, con sus salones abiertos al cielo y sus jardines en ruinas. Aquí murió el gran reino de la Alianza, y aquí sus fantasmas nunca se han ido del todo.\n\nFue Arthas Menethil quien le puso fin. El príncipe regresó a casa al frente de un ejército alzado contra su propio pueblo, recibido a través de estas puertas con campanas y vítores antes de que nadie comprendiera en qué se había convertido. Encontró a su padre, el rey Terenas, esperándolo en la sala del trono, y lo mató allí mismo. De pie sobre el cuerpo, pronunció palabras que aún resuenan en esa sala para quien se detenga en ella: que el reino caería, y que de sus cenizas surgiría un nuevo orden que sacudiría el mundo. No fue una amenaza vana. En cuestión de días, la ciudad y su gente fueron masacradas, y Lordaeron pasó a pertenecer a la Plaga.\n\nSe dice que quien recorre aún el patio puede oír lo que la piedra recuerda: voces apagadas, el tañido de las campanas de bienvenida, un murmullo en la sala del trono que nunca termina de apagarse. Quienes pueden ver más allá del velo dicen que los ciudadanos de Lordaeron aún caminan por allí, sin saber que su reino ya no existe.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
	},
}

SpokenZones:RegisterLoreData("esMX", "subzones", subzones)
